export type WordCard = { id: string; word: string; pair: string; meaning: string; origin: string; originQuery: string; page: number };

export const WORDS: WordCard[] = [{"id":"p02r01a","word":"encomiums","pair":"tributes","meaning":"赞美","origin":"Encomiums 意思是“赞美”，是因为它原本就指公开颂扬某人的赞歌或颂词。单数 encomium 来自希腊语 enkōmion：en- 表示“在……之中”，kōmos 指宴饮游行，早期是宴会上赞颂英雄的诗歌。由“赞歌”扩大为任何高度赞扬的话，所以复数 encomiums 就是“赞美之词”。","originQuery":"encomium","page":1},{"id":"p02r01b","word":"tributes","pair":"encomiums","meaning":"赞美","origin":"Tributes 意思是“赞美”，是因为 tribute 从“应当交付的贡品”发展成了“表示敬意而献上的东西”。它来自拉丁语 tributum“摊派物、贡税”，与 tribus“部族”有关。后来，人们把献给某人的礼物、言辞或作品也称为 tribute，于是复数 tributes 可指一连串致敬或赞美。","originQuery":"tribute","page":1},{"id":"p02r02a","word":"hamstring","pair":"impair","meaning":"削弱","origin":"Hamstring 意思是“削弱”，是因为 hamstring 本指膝后控制腿部活动的肌腱。ham 是“大腿后部”，string 是“筋、弦”；割断这条筋会使人或动物无法正常行走。这个具体动作后来被比喻为使某人失去行动能力或严重受限，因此有“使受制、削弱”的意思。","originQuery":"hamstring","page":1},{"id":"p02r02b","word":"impair","pair":"hamstring","meaning":"削弱","origin":"Impair 意思是“削弱”，是因为它的历史核心就是“使变得更坏”。它经古法语 empeirier 进入英语，最终来自晚期拉丁语 impeiorare，其中 peior 表示“更坏的”。某种能力、价值或状况被“弄得更坏”，自然就是受到损害、减弱；相关词 impaired 表示“受损的”。","originQuery":"impair","page":1},{"id":"p02r03a","word":"minimal","pair":"trifling","meaning":"微不足道","origin":"Minimal 意思是“微不足道”，是因为它表示“小到最低限度”。它来自拉丁语 minimus“最小的、最少的”，与 minimum“最低限度”同源，-al 构成形容词。由“数量或程度最小”可进一步表示“小得几乎不重要”，所以在语境中常译为“极少的、微不足道的”。","originQuery":"minimal","page":1},{"id":"p02r03b","word":"trifling","pair":"minimal","meaning":"微不足道","origin":"Trifling 意思是“微不足道”，是因为 trifle 很早就表示“琐碎小事、无价值之物”。trifle 经古法语 trufle 进入英语，早期还带有“戏弄、胡闹”的意味；-ing 使它成为形容词，表示“像小玩意一样不值得认真看待的”。于是 trifling 就有“琐碎的、无足轻重的”之意。","originQuery":"trifle","page":1},{"id":"p02r04a","word":"acerbic","pair":"vitriolic","meaning":"尖刻","origin":"Acerbic 意思是“尖刻”，是因为它先形容味道“酸涩、苦而刺激”，后来转用于言辞。它来自拉丁语 acerbus“未熟的、酸涩的、严厉的”，与表示“尖锐”的词根有关。说话像酸味刺激舌头一样令人难受，便是“辛辣、尖刻”；相关词 acerbity 指“尖刻、酸涩”。","originQuery":"acerbic","page":1},{"id":"p02r04b","word":"vitriolic","pair":"acerbic","meaning":"尖刻","origin":"Vitriolic 意思是“尖刻”，是因为 vitriol 原指腐蚀性很强的硫酸盐，后来尤其让人联想到硫酸。该词经法语来自拉丁语 vitriolum“玻璃状物质”，因晶体外观似玻璃而得名。言语若像强酸一样灼伤、腐蚀别人，就被称为 vitriolic，即“刻薄恶毒的、尖刻的”。","originQuery":"vitriolic","page":1},{"id":"p02r05a","word":"speculative","pair":"conjectural","meaning":"推测的","origin":"Speculative 意思是“推测的”，是因为它来自“观察、思考”而不是已经证实的事实。其核心是拉丁语 speculari“察看、审视”，与 specere“看”有关；-ive 表示具有某种性质。由仔细观察进入理论思考，再指根据有限线索提出可能性，所以 speculative 表示“推测性的”。","originQuery":"speculative","page":1},{"id":"p02r05b","word":"conjectural","pair":"speculative","meaning":"推测的","origin":"Conjectural 意思是“推测的”，是因为 conjecture 的原始图景是“把线索合在一起，形成判断”。它来自拉丁语 conicere：con- 表示“共同、一起”，iacere 表示“投掷”，可以理解为“把各种迹象投到一起”。这种判断尚未得到证明，因此 conjectural 就表示“依据猜想的、推测性的”。","originQuery":"conjectural","page":1},{"id":"p02r06a","word":"stymied","pair":"neutralized","meaning":"受阻","origin":"Stymied 意思是“受阻”，是因为 stymie 原是高尔夫术语：一名球员的球挡在另一人的球与球洞之间，使对方难以进洞。这个苏格兰词的更早来源并不确定。由球路被挡住，词义自然扩大为计划或行动“遭到阻碍、陷入困境”，所以 stymied 表示“受阻的”。","originQuery":"stymie","page":1},{"id":"p02r06b","word":"neutralized","pair":"stymied","meaning":"受阻","origin":"Neutralized 在这里意思是“受阻、失去作用”，是因为 neutralize 表示“使变成中性或无效”。neutral 来自拉丁语 neutralis，与 neuter“二者皆非”有关；-ize 表示“使成为”。把一种力量变成“不站任何一边”的状态，就是抵消其效力，因此 neutralized 可指“被抵消、被压制”。","originQuery":"neutralize","page":1},{"id":"p02r07a","word":"cheerless","pair":"gloomy","meaning":"阴郁","origin":"Cheerless 意思是“阴郁”，是因为它由 cheer“愉快、振奋”与 -less“没有……”直接构成，即“没有欢乐的”。cheer 早期曾指“脸、表情”，后来由人的面容发展为内在心情和鼓舞。缺少这种明快精神的气氛或人，就显得冷清、忧郁，因此是“阴郁的”。","originQuery":"cheerless","page":1},{"id":"p02r07b","word":"gloomy","pair":"cheerless","meaning":"阴郁","origin":"Gloomy 意思是“阴郁”，是因为 gloom 的核心是“昏暗、幽暗”。gloom 的更早来源并不十分确定，中古英语相关形式可指阴沉的神情或黑暗；-y 表示“充满……的”。由光线昏暗自然引申到气氛沉重、心情忧郁，所以 gloomy 既可指“昏暗的”，也可指“阴郁的”。","originQuery":"gloomy","page":1},{"id":"p02r08a","word":"scarcity","pair":"want","meaning":"缺乏","origin":"Scarcity 意思是“缺乏”，是因为它表示 scarce“稀少、不足”的状态。scarce 经古法语进入英语，可能源于晚期拉丁语中表示“挑选、稀疏”的词；-ity 把性质变成名词。东西稀少到不能满足需要，就形成“短缺”，因此 scarcity 是“稀缺、缺乏”。","originQuery":"scarcity","page":1},{"id":"p02r08b","word":"want","pair":"scarcity","meaning":"缺乏","origin":"Want 意思是“缺乏”，是因为它较早的核心义并非“想要”，而是“没有、欠缺”。它与古诺斯语 vanta“缺少”有关。人通常会想得到自己没有的东西，于是“缺少某物”后来又发展出“想要某物”；在名词或正式用法中，want 仍保留“缺乏、匮乏”的原始方向。","originQuery":"want","page":1},{"id":"p02r09a","word":"inviolable","pair":"sacrosanct","meaning":"不可侵犯的","origin":"Inviolable 意思是“不可侵犯的”，是因为它由否定前缀 in-“不”、violable“可被侵犯的”构成。violable 来自拉丁语 violare“伤害、亵渎、侵犯”，-able 表示“能够被……”。合起来就是“不能被伤害或违犯的”，因此可形容权利、原则或圣物神圣不可侵犯。","originQuery":"inviolable","page":1},{"id":"p02r09b","word":"sacrosanct","pair":"inviolable","meaning":"不可侵犯的","origin":"Sacrosanct 意思是“不可侵犯的”，是因为拉丁语 sacrosanctus 本就表示“以宗教制裁保护、神圣不可触犯的”。它结合 sacer“神圣的”与 sanctus“被规定为神圣的”。原先多用于受宗教保护的人或事，后来泛指任何被视为绝对不能批评、改变或侵犯的事物。","originQuery":"sacrosanct","page":1},{"id":"p02r10a","word":"wealth","pair":"profusion","meaning":"大量，丰富","origin":"Wealth 在这里意思是“大量、丰富”，是因为它最初表示“良好、幸福的状态”，后来特别指物质上的富足。它由中古英语 wele“福祉、财富”加名词后缀 -th 形成，与 well“良好地”同源。拥有充足资源就是处于良好状态，因此 wealth 可由“财富”泛指“大量、丰富”。","originQuery":"wealth","page":1},{"id":"p02r10b","word":"profusion","pair":"wealth","meaning":"大量，丰富","origin":"Profusion 意思是“大量、丰富”，是因为它的字面图景是“向外倾倒”。它来自拉丁语 profundere“倾泻、挥霍”，由 pro-“向前、向外”和 fundere“倒、流”构成；-ion 表示过程或结果。东西多得像不断倾泻出来，便形成“丰盛、大量”，所以 profusion 表示“丰富、充沛”。","originQuery":"profusion","page":1},{"id":"p03r01a","word":"clandestine","pair":"surreptitious","meaning":"秘密的","origin":"Clandestine 意思是“秘密的”，是因为它从拉丁语 clandestinus“隐蔽的、秘密的”直接继承了这个核心含义。该拉丁词可能与 clam“暗中、不公开地”有关，但更深的构词关系并不完全确定。凡是刻意避开公众视线进行的活动，都可称为 clandestine。","originQuery":"clandestine","page":2},{"id":"p03r01b","word":"surreptitious","pair":"clandestine","meaning":"秘密的","origin":"Surreptitious 意思是“秘密的”，是因为它源自拉丁语 surrepticius“偷偷取得的”。该词与 surripere“暗中夺走”有关：sub-“在下、暗中”在 r 前同化为 sur-，rapere 表示“抓走”。由“偷偷拿走”扩展为“偷偷进行”，于是表示“秘密的、鬼鬼祟祟的”。","originQuery":"surreptitious","page":2},{"id":"p03r02a","word":"anathema","pair":"repellent","meaning":"令人厌恶的","origin":"Anathema 在这里表示“令人厌恶的事物”，是因为它曾指被宗教正式诅咒、逐出的人或物。它经拉丁语来自希腊语 anathema，原可指“献置之物”，在《圣经》和教会用语中转为“受诅咒者”。由“必须排斥的对象”进一步变成“极其讨厌、完全不能接受的事物”。","originQuery":"anathema","page":2},{"id":"p03r02b","word":"repellent","pair":"anathema","meaning":"令人厌恶的","origin":"Repellent 意思是“令人厌恶的”，是因为它的核心动作是“把人推开”。它来自拉丁语 repellere：re-“向后”，pellere“推动、驱赶”；-ent 表示具有这种作用。能在物理上把东西排斥开的东西是 repellent，令人心理上想远离的事物也就成了“讨厌的、令人反感的”。","originQuery":"repellent","page":2},{"id":"p03r03a","word":"trivial","pair":"ephemera","meaning":"琐碎无关紧要的事物","origin":"Trivial 意思是“琐碎、无关紧要的”，是因为它原来形容“三岔路口随处可见的东西”。拉丁语 trivialis 来自 trivium“三路交会处”，由 tri-“三”与 via“道路”构成。路口上的事物普通、人人可见，由“寻常”逐渐带上“不重要、琐碎”的含义。","originQuery":"trivial","page":2},{"id":"p03r03b","word":"ephemera","pair":"trivial","meaning":"琐碎无关紧要的事物","origin":"Ephemera 意思是“短暂而不重要的事物”，是因为其核心是“只维持一天”。它来自希腊语 ephēmeros，由 epi“在……期间”和 hēmera“一天”构成，早期用于一日热和蜉蝣。后来泛指寿命很短的印刷品或物件；短暂、易丢弃的性质又使它常带有“琐碎资料”的意味。","originQuery":"ephemera","page":2},{"id":"p03r04a","word":"trepidation","pair":"misgivings","meaning":"不安","origin":"Trepidation 意思是“不安”，是因为它原本描写惊恐时身体发抖、慌乱的状态。它来自拉丁语 trepidatio“惊慌、颤抖”，其动词 trepidare 表示“慌张、发抖”。身体因恐惧而颤动，转而表示内心忐忑，因此 trepidation 就是“惶恐、不安”。","originQuery":"trepidation","page":2},{"id":"p03r04b","word":"misgivings","pair":"trepidation","meaning":"不安","origin":"Misgivings 意思是“不安、疑虑”，是因为 misgive 曾表示“使人产生怀疑或忧惧”。mis- 常含“错误、不利”，give 是“给予”；这里不能机械理解为“给错”，而可理解为内心向自己发出不好的预感。由这种不祥感觉形成名词 misgiving，复数常指对某事能否妥当的疑虑。","originQuery":"misgiving","page":2},{"id":"p03r05a","word":"unassuming","pair":"modest","meaning":"谦逊","origin":"Unassuming 意思是“谦逊”，是因为它表示“不摆出自以为了不起的姿态”。un-“不”，assuming 来自 assume“自取、摆出”，而 assume 最终来自拉丁语 ad-“向”与 sumere“拿取”。这里的 assuming 指“自负、摆架子”，加上 un- 后就是“不自命不凡的”，因而译为“谦逊的”。","originQuery":"unassuming","page":2},{"id":"p03r05b","word":"modest","pair":"unassuming","meaning":"谦逊","origin":"Modest 意思是“谦逊”，是因为其拉丁语根义强调“守住适当分寸”。它来自 modestus“有节制的、端庄的”，与 modus“尺度、限度”有关。一个人不过分夸耀自己、言行保持合宜尺度，就显得谦虚，因此 modest 由“有分寸”发展为“谦逊的”。","originQuery":"modest","page":2},{"id":"p03r06a","word":"reveal","pair":"manifest","meaning":"显现","origin":"Reveal 意思是“显现”，是因为它的字面动作是“揭开遮盖”。它经古法语 reveler 来自拉丁语 revelare，由 re-“反向、去除”与 velum“帘幕、面纱”相关的成分构成。把面纱揭掉，原先隐藏的东西就显现出来，因此 reveal 表示“揭示、使显现”。","originQuery":"reveal","page":2},{"id":"p03r06b","word":"manifest","pair":"reveal","meaning":"显现","origin":"Manifest 意思是“显现”，是因为拉丁语 manifestus 表示“明显的、可直接察觉的”。这个词的更早构成有争议，常被联系到 manus“手”和表示“抓住”的成分，即“明显得仿佛能用手抓到”。由“清楚可见”形成形容词“明显的”，作动词时就是“显示、显现”。","originQuery":"manifest","page":2},{"id":"p03r07a","word":"cede","pair":"relinquish","meaning":"放弃","origin":"Cede 意思是“放弃”，是因为它来自拉丁语 cedere“走开、让路、退让”。当一个人从原有位置退开，就是把空间让给别人；这个动作进一步用于权利或领土，表示“让出、割让”。因此 cede 强调把原先拥有或主张的东西交给另一方。","originQuery":"cede","page":2},{"id":"p03r07b","word":"relinquish","pair":"cede","meaning":"放弃","origin":"Relinquish 意思是“放弃”，是因为它的拉丁语核心是“留下在后面”。它来自 relinquere，由 re-“向后”与 linquere“离开、留下”构成。把某物留在身后、不再掌握，便是放手或抛弃，因此 relinquish 表示“放弃权利、控制或主张”；相关词 relic 也与“留下之物”有关。","originQuery":"relinquish","page":2},{"id":"p03r08a","word":"proclivity toward","pair":"predilection","meaning":"倾向，偏好","origin":"Proclivity toward 意思是“对……有倾向、偏好”，是因为 proclivity 原本描写向前下方倾斜的坡势。它来自拉丁语 proclivis：pro-“向前”，clivus“斜坡”。物体会顺坡自然滑向某处，这个图景被用于人的性情，表示不经强迫就容易朝某种行为或选择发展。","originQuery":"proclivity","page":2},{"id":"p03r08b","word":"predilection","pair":"proclivity toward","meaning":"倾向，偏好","origin":"Predilection 意思是“倾向、偏好”，是因为它的构词核心是“比其他对象更先喜欢”。它经法语来自拉丁语 praediligere：prae-“在前、优先”，diligere“珍视、喜爱”。先把某一对象挑出来喜爱，就是对它有特别偏好，所以 predilection 指预先存在或格外明显的喜好。","originQuery":"predilection","page":2},{"id":"p03r09a","word":"perceptive","pair":"discerning","meaning":"有洞察力的","origin":"Perceptive 意思是“有洞察力的”，是因为 perceive 的核心是“彻底抓住、领会”。它来自拉丁语 percipere：per-“完全”，capere“抓取”；-ive 表示具有这种能力。由感官接收信息进一步发展为头脑准确把握细节，所以 perceptive 形容人观察敏锐、能看出别人忽略之处。","originQuery":"perceptive","page":2},{"id":"p03r09b","word":"discerning","pair":"perceptive","meaning":"有洞察力的","origin":"Discerning 意思是“有洞察力的”，是因为 discern 原本表示“把不同事物分开辨认”。它来自拉丁语 discernere：dis-“分开”，cernere“筛分、辨别”。能从相似或混杂的信息中分清差别，就具有良好判断力，因此 discerning 表示“眼光敏锐、善于辨别的”；名词是 discernment。","originQuery":"discerning","page":2},{"id":"p03r10a","word":"altruism","pair":"benevolence","meaning":"无私，利他","origin":"Altruism 意思是“无私、利他”，是因为这个词的核心直接指向“他人”。它由法语 altruisme 进入英语，altrui 意为“别人的、他人的”，最终与拉丁语 alter“另一个”同源。把关注点从自己转向他人的利益，就是利他主义，因此 altruism 表示“为他人着想的原则或行为”。","originQuery":"altruism","page":2},{"id":"p03r10b","word":"benevolence","pair":"altruism","meaning":"无私，利他","origin":"Benevolence 意思是“善意、利他”，是因为其拉丁语构词就是“希望别人好”。它来自 benevolentia，其中 bene 表示“好、善”，velle 表示“希望、愿意”。对他人怀有“愿其安好”的心意，会表现为仁慈和帮助，因此 benevolence 指“善意、仁爱”；相关词 benevolent 是“仁慈的”。","originQuery":"benevolence","page":2},{"id":"p04r01a","word":"appropriate","pair":"borrow","meaning":"挪用","origin":"Appropriate 在这里意思是“挪用”，是因为它作动词时原本表示“把某物变成自己的”。它来自晚期拉丁语 appropriare，由 ad-“向、归于”与 proprius“自己的”构成。把本不属于自己的钱物据为己有，就从中性的“拨作专用”变成贬义的“擅自占用、挪用”。","originQuery":"appropriate","page":3},{"id":"p04r01b","word":"borrow","pair":"appropriate","meaning":"挪用","origin":"Borrow 在这里译为“挪用”，是因为它的核心是“暂时取得并承诺归还”。它来自古英语 borgian，与 borg“抵押、保证”有关：借取者以归还承诺作保证。borrow 本身通常是中性的“借用”，但若未经允许借取资金或物品，语境中便可带有委婉的“挪用”意味。","originQuery":"borrow","page":3},{"id":"p04r02a","word":"bypass","pair":"circumvent","meaning":"避开","origin":"Bypass 意思是“避开”，是因为它由 by“在旁边、经过旁路”与 pass“通过”构成。它先指为绕过拥堵地点而修建的旁路，后来成为动词，表示不经过正常路线而从旁通过。由绕开地点进一步引申为绕过程序、障碍或某个人，因此就是“避开、绕过”。","originQuery":"bypass","page":3},{"id":"p04r02b","word":"circumvent","pair":"bypass","meaning":"避开","origin":"Circumvent 意思是“避开”，是因为它的拉丁语字面图景是“绕到四周”。它来自 circumvenire：circum-“环绕”，venire“来、走近”。原先可指包围或从四面设法制伏某人，后来重点转到用计谋绕过障碍、规则，所以现代常表示“规避、绕开”。","originQuery":"circumvent","page":3},{"id":"p04r03a","word":"proliferate","pair":"abound","meaning":"大量存在","origin":"Proliferate 意思是“大量存在、激增”，是因为它原本表示“繁殖后代”。词中 proles 是拉丁语“后代”，-fer 来自 ferre“携带、产生”，合起来是“产生后代”。生物不断繁殖会使数量迅速增加，这个含义又扩展到观点、机构等事物的大量涌现。","originQuery":"proliferate","page":3},{"id":"p04r03b","word":"abound","pair":"proliferate","meaning":"大量存在","origin":"Abound 意思是“大量存在”，是因为它的核心图景是“多到溢出来”。它经古法语 abonder 来自拉丁语 abundare，与 unda“波浪、水”有关；ab- 在这里有“从……涌出”的感觉。水满而外溢象征数量充裕，因此 abound 表示某物“充满、富于、大量存在”。","originQuery":"abound","page":3},{"id":"p04r04a","word":"checking","pair":"stemming","meaning":"抑制","origin":"Checking 意思是“抑制”，是因为 check 从国际象棋中的“将军”发展出“阻止行动”。该词经古法语 eschec，最终与波斯语 shāh“国王”有关；棋王受到威胁时，对手必须停下原计划应对。由这种被迫止步的局面，check 逐渐表示“制止、控制”，checking 即“正在抑制”。","originQuery":"check","page":3},{"id":"p04r04b","word":"stemming","pair":"checking","meaning":"抑制","origin":"Stemming 意思是“抑制”，是因为动词 stem 曾用于“顶着水流使船停住或前进”。它可能来自 stem“船艏、船首”，与表示植物“茎”的同形词来源有所区别。船首迎流阻挡水势的图景，后来扩展为“阻住某物的发展或流动”，因此 stem the spread 就是“遏制蔓延”。","originQuery":"stem","page":3},{"id":"p04r05a","word":"waning","pair":"ebbing","meaning":"衰退","origin":"Waning 意思是“衰退”，是因为 wane 最典型地描写满月之后月面逐渐变小。它来自古英语 wanian“减少、衰弱”，与表示“缺少”的 wan- 成分有关。月光由盛转弱的周期成为一般比喻，任何力量、影响或数量逐渐减少，都可以说 is waning，即“正在衰退”。","originQuery":"waning","page":3},{"id":"p04r05b","word":"ebbing","pair":"waning","meaning":"衰退","origin":"Ebbing 意思是“衰退”，是因为 ebb 原指潮水退去。它来自古英语 ebba“退潮”，与日耳曼语中“离开、退去”的概念相关。水位从高处不断下降的可见过程，后来被比喻性地用于精力、声望或势力的减弱，所以 ebbing 就是“正在消退、衰退”。","originQuery":"ebb","page":3},{"id":"p04r06a","word":"engenders","pair":"induces","meaning":"引起","origin":"Engenders 意思是“引起”，是因为 engender 原本表示“生育、产生”。它经古法语 engendrer 来自拉丁语 ingenerare，由 in-“进入、使成”与 genus“种类、出生”相关的 generare“产生”构成。由产生生命扩展到产生结果或情绪，因此 A engenders B 就是“A 引起、造成 B”。","originQuery":"engender","page":3},{"id":"p04r06b","word":"induces","pair":"engenders","meaning":"引起","origin":"Induces 意思是“引起”，是因为 induce 的拉丁语字面义是“引入、带进”。它来自 inducere：in-“进入”，ducere“引导、带领”。把某人引入一种行动，便是劝使；把事物带入某种状态，便是导致。因此 induces 在因果语境中表示“促成、引起”。","originQuery":"induce","page":3},{"id":"p04r07a","word":"inert","pair":"passive","meaning":"无活力的","origin":"Inert 意思是“无活力的”，是因为拉丁语 iners 直指“没有技艺、不能行动”。它由否定前缀 in-“无”与 ars“技艺、能力”相关的成分构成，早期可形容懒散或无能。后来物理学用 inert 表示不自行改变运动状态，由“不行动”自然得到“迟钝、无活力的”。","originQuery":"inert","page":3},{"id":"p04r07b","word":"passive","pair":"inert","meaning":"无活力的","origin":"Passive 意思是“无活力的、被动的”，是因为它原来表示“承受作用，而不主动施加作用”。它来自拉丁语 passivus，与 pati“承受、遭受”有关。只接受外力、自己不采取行动，就显得消极而缺少活力，因此 passive 与 active“主动的”相对。","originQuery":"passive","page":3},{"id":"p04r08a","word":"undergirded","pair":"dependent","meaning":"以为基础","origin":"Undergirded 意思是“以……为基础、受到支撑”，是因为 undergird 的构词图景是“从下面束紧”。under 表示“在下方”，gird 表示“束住、围住”。从下方绑紧结构可以托住并加固它，于是这个具体动作引申为给思想、制度等提供基础；undergirded 表示“由……支撑”。","originQuery":"undergird","page":3},{"id":"p04r08b","word":"dependent","pair":"undergirded","meaning":"以为基础","origin":"Dependent 在这里与“以……为基础”相连，是因为 depend 的字面图景是“悬挂在某物之下”。它来自拉丁语 dependere：de-“从……向下”，pendere“悬挂”。悬着的东西必须靠上方支点维持，因此 depend on 发展为“依靠、取决于”，dependent 就是“依赖某基础而存在的”。","originQuery":"dependent","page":3},{"id":"p04r09a","word":"rigorous","pair":"faithful","meaning":"严谨的","origin":"Rigorous 意思是“严谨的”，是因为它的词源核心是“僵硬、严格”。它来自拉丁语 rigor“僵硬、严厉”，与 rigere“变硬、僵直”有关，-ous 表示具有这种性质。规则若像硬物一样不容弯曲，就是严格的；方法若严格遵守标准，便是周密、严谨的。","originQuery":"rigorous","page":3},{"id":"p04r09b","word":"faithful","pair":"rigorous","meaning":"严谨的","origin":"Faithful 在这里意思是“严谨、忠实的”，是因为它表示“忠于原物或事实”。它由 faith“信实、忠诚”与 -ful“充满……的”构成；faith 最终来自拉丁语 fides“信任、忠诚”。从对人忠诚发展到对文本、数据或方法不歪曲，faithful 就可表示“准确可靠、严格如实的”。","originQuery":"faithful","page":3},{"id":"p04r10a","word":"flexibility","pair":"malleability","meaning":"灵活性","origin":"Flexibility 意思是“灵活性”，是因为它的词根核心是“弯曲”。flexible 来自拉丁语 flexibilis“可弯的”，其中 flectere 表示“弯、转”；-ity 表示性质。能弯曲而不折断的物体具有柔韧性，这一特点转用于计划或思维，就成为能随情况调整的“灵活性”。","originQuery":"flexibility","page":3},{"id":"p04r10b","word":"malleability","pair":"flexibility","meaning":"灵活性","origin":"Malleability 意思是“灵活性、可塑性”，是因为 malleable 原指金属能被锤打成形。它来自中世纪拉丁语 malleabilis，与 malleus“锤子”有关；-ity 表示性质。金属受力后能改变形状而不破裂，后来这一物理性质被比喻为思想或安排容易调整，所以有“可塑性、灵活性”。","originQuery":"malleability","page":3},{"id":"p05r01a","word":"ubiquitous","pair":"omnipresent","meaning":"无处不在","origin":"Ubiquitous 意思是“无处不在”，是因为它来自拉丁语 ubique“到处、在每个地方”。ubique 由 ubi“哪里”与表示普遍性的 -que 组成，后来形成 ubiquity“无所不在”和形容词 ubiquitous。某物若在每个地方都能遇见，自然就是“无处不在的”。","originQuery":"ubiquitous","page":4},{"id":"p05r01b","word":"omnipresent","pair":"ubiquitous","meaning":"无处不在","origin":"Omnipresent 意思是“无处不在”，是因为它由拉丁语 omni-“全部、每一处”和 present“在场的”构成。present 最终含有“在面前”的概念。若在所有地方都处于“在场”状态，就是无所不在；相关词 omniscient 表示“无所不知的”，其中 omni- 同样表示“全”。","originQuery":"omnipresent","page":4},{"id":"p05r02a","word":"unfounded","pair":"baseless","meaning":"毫无根据","origin":"Unfounded 意思是“毫无根据”，是因为它表示“没有 foundation（基础）的”。un-“没有、不”，founded 来自 found“建立、奠基”；这里的 found 与 foundation 同源，而不是 find 的过去式。论点若没有事实作为地基，就站不住脚，因此 unfounded 表示“无事实依据的”。","originQuery":"unfounded","page":4},{"id":"p05r02b","word":"baseless","pair":"unfounded","meaning":"毫无根据","origin":"Baseless 意思是“毫无根据”，是因为它由 base“底座、基础”与 -less“没有……”直接构成。base 最终来自希腊语 basis“脚步、基座”。建筑没有底座无法站稳，同样，主张没有证据也不能成立；因此 baseless 就是“无基础的、没有根据的”。","originQuery":"baseless","page":4},{"id":"p05r03a","word":"essential","pair":"indispensable","meaning":"必不可少的","origin":"Essential 意思是“必不可少的”，是因为它最初表示“属于事物本质的”。它来自晚期拉丁语 essentialis，核心 essentia 意为“存在、本质”，与拉丁语 esse“是、存在”有关。若某部分构成事物之所以为该事物的本质，缺少它就无法成立，于是 essential 发展为“不可缺少的”。","originQuery":"essential","page":4},{"id":"p05r03b","word":"indispensable","pair":"essential","meaning":"必不可少的","origin":"Indispensable 意思是“必不可少的”，是因为它表示“不能被免除的”。in-“不”，dispensable“可以省去的”，而 dispense 来自拉丁语 dispensare“分配、安排”，后来有“免除义务”之意。某项要求若不能获得豁免，就必须保留，因此 indispensable 表示“不可省略、不可或缺的”。","originQuery":"indispensable","page":4},{"id":"p05r04a","word":"belies","pair":"masks","meaning":"掩饰","origin":"Belies 意思是“掩饰、给人错误印象”，是因为 belie 原本就是“用谎言欺骗”。它来自古英语 beleogan，由强化性的 be- 与 leogan“说谎”构成。若外表“说了谎”，它就没有显露真实情况，反而掩盖或否定事实；因此 an appearance belies the truth 表示“外表掩盖了真相”。","originQuery":"belie","page":4},{"id":"p05r04b","word":"masks","pair":"belies","meaning":"掩饰","origin":"Masks 意思是“掩饰”，是因为 mask 原指遮住脸的面具。它经法语 masque、意大利语 maschera 进入英语，更早来源并不确定。戴上面具会隐藏真实面孔，所以 mask 很自然地成为动词，表示用外表、行为或说法遮住真实情感和事实，即“掩饰”。","originQuery":"mask","page":4},{"id":"p05r05a","word":"fluid","pair":"unstable","meaning":"不稳定的","origin":"Fluid 在这里意思是“不稳定的、易变的”，是因为它的本义是“流动的”。它来自拉丁语 fluidus，与 fluere“流动”有关。液体没有固定形状，会随容器和外力不断改变；这个物理特征被用于局势、身份或计划，就表示尚未定型、随时可能变化。","originQuery":"fluid","page":4},{"id":"p05r05b","word":"unstable","pair":"fluid","meaning":"不稳定的","origin":"Unstable 意思是“不稳定的”，是因为它由 un-“不”与 stable“稳固的”构成。stable 来自拉丁语 stabilis，与 stare“站立”有关，核心图景是“能够站住”。加上否定前缀后，就是不能稳稳站住、容易摇动或改变，因此可形容物体、局势或情绪不稳定。","originQuery":"unstable","page":4},{"id":"p05r06a","word":"truculent","pair":"pugnacious","meaning":"好斗的","origin":"Truculent 意思是“好斗的”，是因为拉丁语 truculentus 原本形容“凶猛、野蛮、残酷”。它与 trux“凶狠的、可怕的”有关。由外表或性情凶悍，进一步指随时准备攻击、挑衅他人，因此英语中的 truculent 常表示“气势汹汹、好斗的”。","originQuery":"truculent","page":4},{"id":"p05r06b","word":"pugnacious","pair":"truculent","meaning":"好斗的","origin":"Pugnacious 意思是“好斗的”，是因为它直接来自拉丁语 pugnax“爱打斗的”，核心动词 pugnare 是“打架、战斗”。-acious 表示具有明显倾向。一个人总倾向于进入争斗，就不仅是勇敢，而是动辄挑衅、喜欢争吵，因此 pugnacious 带有“好斗”的意味；相关词 pugnacity 指“好斗性”。","originQuery":"pugnacious","page":4},{"id":"p05r07a","word":"deferential","pair":"respectful","meaning":"恭敬的","origin":"Deferential 意思是“恭敬的”，是因为它来自 deference“顺从、尊重”，而 deference 与 defer“遵从某人的判断”有关。defer 经法语可追溯到拉丁语 deferre“带下、交付”，由 de- 与 ferre“携带”构成。把决定权交给别人，就是尊重其地位，所以 deferential 表示“恭敬顺从的”。","originQuery":"deferential","page":4},{"id":"p05r07b","word":"respectful","pair":"deferential","meaning":"恭敬的","origin":"Respectful 意思是“恭敬的”，是因为 respect 的词源图景是“回头再看、认真看待”。它来自拉丁语 respicere：re-“回、再”，specere“看”；-ful 表示具有这种态度。愿意认真看待他人的身份、感受和权利，就会表现出尊重，因此 respectful 是“表示敬意的、恭敬的”。","originQuery":"respectful","page":4},{"id":"p05r08a","word":"imperceptible","pair":"indiscernible","meaning":"难以察觉的","origin":"Imperceptible 意思是“难以察觉的”，是因为它由 im-“不”与 perceptible“能够被感知的”构成。perceptible 来自拉丁语 percipere“完全抓取、领会”，-ible 表示“能够被……”。小到感官或头脑无法“抓住”的变化，就难以察觉，因此是 imperceptible。","originQuery":"imperceptible","page":4},{"id":"p05r08b","word":"indiscernible","pair":"imperceptible","meaning":"难以察觉的","origin":"Indiscernible 意思是“难以察觉的”，是因为它表示“无法分辨出来”。in-“不”，discern“辨别”，-ible“能够被……”；discern 又来自拉丁语 discernere，含“分开、筛分”之意。若两个事物相似到不能分开辨认，或信号弱到看不出，就称为 indiscernible。","originQuery":"indiscernible","page":4},{"id":"p05r09a","word":"counterpart","pair":"correlative","meaning":"对应物","origin":"Counterpart 意思是“对应物”，是因为它原指契约中与另一份相配的副本。它经法语 contrepartie 形成，counter-“相对、对应”，part“部分、份”。两份文件分属双方却内容相应，由此扩大为两个体系中地位、作用相当的人或物，所以 counterpart 就是“对应的人或事物”。","originQuery":"counterpart","page":4},{"id":"p05r09b","word":"correlative","pair":"counterpart","meaning":"对应物","origin":"Correlative 意思是“对应物”，是因为它表示“与另一事物相互关联并成对存在”。co-/cor-“共同、相互”，relative 来自 relate“联系”；拉丁语 correlativus 已有“彼此相关”的意思。一个概念只有参照另一个概念才成立，如 cause 与 effect，二者便互为 correlative，即“相关对应项”。","originQuery":"correlative","page":4},{"id":"p05r10a","word":"cerebral","pair":"dispassionate","meaning":"理性的","origin":"Cerebral 在这里意思是“理性的、重思考的”，是因为它原本表示“与大脑有关的”。它来自拉丁语 cerebrum“大脑”，-al 表示“属于……的”。大脑被视为思考和分析的中心，因此 cerebral 从医学上的“脑部的”引申为“诉诸理智而非情感的”，有时也指过分学院化。","originQuery":"cerebral","page":4},{"id":"p05r10b","word":"dispassionate","pair":"cerebral","meaning":"理性的","origin":"Dispassionate 意思是“理性的、不带感情的”，是因为它表示“不受 passion 支配”。dis- 在这里有“去除、没有”的作用，passion 来自拉丁语 pati“承受、感受”，后来指强烈感情。把强烈情绪拿开后，判断就较为冷静客观，因此 dispassionate 并非“毫无兴趣”，而是“不偏不倚的”。","originQuery":"dispassionate","page":4},{"id":"p06r01a","word":"nuanced","pair":"subtle","meaning":"细微的","origin":"Nuanced 意思是“细微的”，是因为 nuance 原指颜色、音调中很轻的层次差别。它来自法语 nuance“色调、阴影”，与 nuer“给颜色分出层次”有关；-ed 表示带有这种层次。由难以一眼察觉的色差，词义扩展到观点、感情中的细微区别，因此 nuanced 表示“有细腻层次的”。","originQuery":"nuanced","page":5},{"id":"p06r01b","word":"subtle","pair":"nuanced","meaning":"细微的","origin":"Subtle 意思是“细微的”，是因为它的历史图景与“织得很细、很精巧”有关。它经古法语 sotil 来自拉丁语 subtilis，大致由 sub-“在下”与 tela“织物、网”相关成分形成，原指精细织造。由质地细密发展为差别不明显、需要敏锐感知，所以表示“微妙的、细微的”。","originQuery":"subtle","page":5},{"id":"p06r02a","word":"euphoria","pair":"jubilation","meaning":"极度欢喜","origin":"Euphoria 意思是“极度欢喜”，是因为它最初表示身体“状态良好、容易承受”。它来自希腊语 euphoria：eu-“好、良好”，pherein“承受、携带”。医学上曾指病人感觉舒适、能安然承受病情；这种强烈的良好感受后来转为精神上的异常愉悦，即“欣快、极度欢喜”。","originQuery":"euphoria","page":5},{"id":"p06r02b","word":"jubilation","pair":"euphoria","meaning":"极度欢喜","origin":"Jubilation 意思是“极度欢喜”，是因为它的词源核心是“欢呼喊叫”。它来自拉丁语 iubilatio“欢呼”，动词 iubilare 表示因喜悦而高声呼喊；-ation 表示行为或状态。喜悦强烈到忍不住欢呼，便不只是一般高兴，而是“欢欣鼓舞、极度欢喜”。","originQuery":"jubilation","page":5},{"id":"p06r03a","word":"insightful","pair":"discriminating","meaning":"有洞察力的","origin":"Insightful 意思是“有洞察力的”，是因为 insight 的字面构词可理解为“看进事物内部”。in 表示“向内”，sight 表示“看见、视野”，-ful 表示“富有……的”。能越过表面看到内在原因和联系，就是有 insight；因此 insightful 形容观点或人“有深刻洞察力的”。","originQuery":"insightful","page":5},{"id":"p06r03b","word":"discriminating","pair":"insightful","meaning":"有洞察力的","origin":"Discriminating 意思是“有洞察力的”，是因为 discriminate 的原义是“辨出差别”。它来自拉丁语 discriminare“区分”，核心 discrimen 指“分界、区别”。能在相近事物中作出细致判断，就说明眼光敏锐；因此在这一褒义用法中，discriminating 是“有鉴别力的”，并非“歧视的”。","originQuery":"discriminating","page":5},{"id":"p06r04a","word":"basic","pair":"crude","meaning":"简单朴素","origin":"Basic 意思是“简单朴素”，是因为它首先表示“构成基础的”。base 经法语进入英语，最终与希腊语 basis“基座、基础”有关，-ic 构成形容词。基础层面的东西通常只保留不可缺少的部分，不加复杂装饰，因此 basic 可从“基本的”进一步表示“简单、朴素的”。","originQuery":"basic","page":5},{"id":"p06r04b","word":"crude","pair":"basic","meaning":"简单朴素","origin":"Crude 意思是“简单粗糙”，是因为拉丁语 crudus 原本表示“生的、未熟的”。食物未经烹制，材料未经加工，都处于原始状态；由“生的”扩展为“不精制、不成熟”。因此 crude 可形容做法或器物简陋粗糙，也可形容言行缺少修饰、显得粗俗。","originQuery":"crude","page":5},{"id":"p06r05a","word":"unique","pair":"characteristic","meaning":"独有的典型的","origin":"Unique 意思是“独有的”，是因为它来自拉丁语 unicus“唯一的、独一的”，核心 unus 就是“一”。最初它严格表示同类中只有一个，后来口语中也常加强为“非常独特”。某种特征若只属于一个对象，便同时成为它最鲜明的特点，所以语境中可与“独有的、特有的”相连。","originQuery":"unique","page":5},{"id":"p06r05b","word":"characteristic","pair":"unique","meaning":"独有的典型的","origin":"Characteristic 意思是“独有的、典型的”，是因为 character 原指刻下的标记。它最终来自希腊语 kharaktēr“刻痕、印记”，与“刻、雕”有关；-istic 表示具有某种性质。能像印记一样识别某人或某类事物的特征，就是 characteristic，因此可指“特有的、典型的”。","originQuery":"characteristic","page":5},{"id":"p06r06a","word":"fabulous","pair":"legendary","meaning":"极好的令人惊叹的","origin":"Fabulous 意思是“极好的、令人惊叹的”，是因为它原来表示“存在于传奇故事中的”。它来自拉丁语 fabulosus，核心 fabula 是“故事、寓言”。传奇中的事物往往夸张得难以置信，于是 fabulous 先有“虚构、惊人”的意味，后来在口语中转为强烈赞叹：“好得像传奇一样”。","originQuery":"fabulous","page":5},{"id":"p06r06b","word":"legendary","pair":"fabulous","meaning":"极好的令人惊叹的","origin":"Legendary 意思是“极好的、令人惊叹的”，是因为 legend 原指值得传诵的圣徒故事或传说。legend 来自拉丁语 legenda“应当阅读的事”，是 legere“阅读”的动名词形式。能进入传说、被世代讲述的人或成就必然非同寻常，所以 legendary 又表示“传奇般卓越的”。","originQuery":"legendary","page":5},{"id":"p06r07a","word":"tempered","pair":"modulated","meaning":"缓和的","origin":"Tempered 意思是“缓和的”，是因为 temper 的早期核心是“按适当比例调和”。它来自拉丁语 temperare“混合、节制、使适中”。把过强的材料掺合调整，会降低其强度；同样，情绪、言辞或政策被 tempered，就是被约束、调到不过度的程度，因此译为“缓和的”。","originQuery":"tempered","page":5},{"id":"p06r07b","word":"modulated","pair":"tempered","meaning":"缓和的","origin":"Modulated 意思是“缓和、调整过的”，是因为 modulate 的核心是“按尺度调节”。它来自拉丁语 modulari“测量、调音”，与 modulus“小尺度”和 modus“尺度”有关。声音按一定幅度改变叫调制；更广泛地，把语气或力度调到适当程度，也就是“调节、缓和”。","originQuery":"modulate","page":5},{"id":"p06r08a","word":"hodgepodge","pair":"patchwork","meaning":"大杂烩","origin":"Hodgepodge 意思是“大杂烩”，是因为它原来就是把多种材料煮在一起的杂烩汤。它由中古英语 hotchpotch 等形式演变而来，源头是古法语 hochepot，含“摇动锅中食物”的图景。各种不相干的东西混到一锅，后来便比喻杂乱拼合的集合。","originQuery":"hodgepodge","page":5},{"id":"p06r08b","word":"patchwork","pair":"hodgepodge","meaning":"大杂烩","origin":"Patchwork 意思是“大杂烩”，是因为它由 patch“补丁、碎片”和 work“制品”构成，最初指把不同布片缝在一起的拼布。各种颜色、来源的碎片虽组成整体，却未必协调；这个形象后来用于制度、文章等，表示由零散部分拼凑成的杂乱组合。","originQuery":"patchwork","page":5},{"id":"p06r09a","word":"benign","pair":"innocuous","meaning":"无害的","origin":"Benign 意思是“无害的”，是因为它的拉丁语来源 benignus 表示“和善、仁慈”。该词通常被认为与 bene“好”和表示“出生、种类”的成分有关，可理解为“性情良善”。良善的事物不会造成伤害，于是医学中 benign 与 malignant“恶性的”相对，表示“良性、无害的”。","originQuery":"benign","page":5},{"id":"p06r09b","word":"innocuous","pair":"benign","meaning":"无害的","origin":"Innocuous 意思是“无害的”，是因为拉丁语 innocuus 的构词就是“不伤害”。in-“不”，nocuus 来自 nocere“伤害”；-ous 表示具有某种性质。合起来是“不会造成伤害的”，所以既可形容物质安全无害，也可形容言行温和、不冒犯人；同源词 noxious 表示“有害的”。","originQuery":"innocuous","page":5},{"id":"p06r10a","word":"encyclopedic","pair":"exhaustive","meaning":"全面的","origin":"Encyclopedic 意思是“全面的”，是因为它表示“像百科全书一样涵盖广泛”。encyclopedia 最终源自希腊语 enkyklios paideia，大意是“完整一圈的教育、全面教育”；-ic 构成形容词。知识若覆盖一个主题的各个方面，就像百科全书，因此是“广博、全面的”。","originQuery":"encyclopedic","page":5},{"id":"p06r10b","word":"exhaustive","pair":"encyclopedic","meaning":"全面的","origin":"Exhaustive 意思是“全面的”，是因为它表示把一个主题“穷尽到没有遗漏”。exhaust 来自拉丁语 exhaurire，由 ex-“向外、彻底”与 haurire“汲取”构成，原图景是把容器里的水全部舀空。调查若把所有可能性都取尽，便是 exhaustive，即“彻底而全面的”。","originQuery":"exhaustive","page":5},{"id":"p07r01a","word":"futility","pair":"pointlessness","meaning":"无用","origin":"Futility 意思是“无用”，是因为它来自拉丁语 futilis“徒劳、无价值的”。这个拉丁词可能原指“容易漏出的”，让人联想到盛不住东西的容器，但具体词源并不完全确定。无论怎样努力都留不住成果，便是徒劳；加 -ity 后，futility 表示“无效、无意义的状态”。","originQuery":"futility","page":6},{"id":"p07r01b","word":"pointlessness","pair":"futility","meaning":"无用","origin":"Pointlessness 意思是“无用、无意义”，是因为它由 point“要点、目的”、-less“没有”与 -ness“状态”构成。这里的 point 不是单指尖端，而是事情所指向的目标或意义。一个行动没有要达到的点，就没有目的和作用，因此 pointlessness 就是“毫无意义、徒劳无用”。","originQuery":"pointless","page":6},{"id":"p07r02a","word":"novel","pair":"original","meaning":"新颖","origin":"Novel 意思是“新颖”，是因为它来自拉丁语 novellus“新的、年轻的”，而 novellus 是 novus“新”的指小形式。经古法语进入英语后，它先作形容词表示“新近出现的、前所未有的”。由于不落旧套的东西会给人新鲜感，novel 便表示“新颖的”。","originQuery":"novel","page":6},{"id":"p07r02b","word":"original","pair":"novel","meaning":"新颖","origin":"Original 意思是“新颖”，是因为它首先表示“属于起源、最初产生的”。它来自拉丁语 originalis，核心 origo 是“开端、来源”。不是复制别人，而是从自己这里首次产生的想法，就是“原创的”；原创内容通常前所未见，因此 original 进一步带有“新颖、独创”的意味。","originQuery":"original","page":6},{"id":"p07r03a","word":"dwindling","pair":"contracting","meaning":"逐渐减少","origin":"Dwindling 意思是“逐渐减少”，是因为 dwindle 从很早的“消瘦、衰弱、消失”发展而来。它与古英语 dwinan“逐渐消逝”有关，并带有反复、渐进的形式特征。事物不是突然消失，而是一点点变小、变少，所以 dwindling 特别强调持续缩减的过程。","originQuery":"dwindle","page":6},{"id":"p07r03b","word":"contracting","pair":"dwindling","meaning":"逐渐减少","origin":"Contracting 意思是“逐渐减少、收缩”，是因为 contract 的拉丁语字面义是“拉到一起”。它来自 contrahere：con-“共同、一起”，trahere“拉”。把分散的部分拉紧，整体范围就缩小；因此 contract 作动词可指肌肉、经济或数量收缩，contracting 即“正在缩减”。","originQuery":"contract","page":6},{"id":"p07r04a","word":"gradual","pair":"imperceptible","meaning":"逐渐的，难以察觉的","origin":"Gradual 意思是“逐渐的”，是因为它的核心是“一步、一级”。它来自拉丁语 gradus“步伐、台阶、等级”，-al 表示相关性质。沿台阶前进不是一下跳到终点，而是一级一级变化；因此 gradual 表示缓慢分阶段发生，也常因每一步很小而难以察觉。","originQuery":"gradual","page":6},{"id":"p07r04b","word":"imperceptible","pair":"gradual","meaning":"逐渐的，难以察觉的","origin":"Imperceptible 意思是“难以察觉的”，是因为它由否定前缀 im-“不”和 perceptible“可感知的”构成。perceive 最终来自拉丁语 percipere“完整地抓住、领会”，-ible 表示“能被……”。变化若细小到感官无法抓住，就是 imperceptible；因此它也常与 gradual 搭配。","originQuery":"imperceptible","page":6},{"id":"p07r05a","word":"respite","pair":"break","meaning":"短暂的休息","origin":"Respite 意思是“短暂的休息”，是因为它最初指法律或行动上的“延期、暂缓”。它经古法语 respit 来自拉丁语 respectus“回看、考虑”，含有停下来重新考虑的意味。惩罚或困难暂时延期，人便获得一段喘息时间，于是 respite 发展为“暂时缓解、短暂休息”。","originQuery":"respite","page":6},{"id":"p07r05b","word":"break","pair":"respite","meaning":"短暂的休息","origin":"Break 意思是“短暂的休息”，是因为它原本表示“打断、折断”。它来自古英语 brecan“破开”。工作或连续活动被暂时打断，就形成一段空隙，让人休息；因此 take a break 是“休息一下”。这里的“休息”保留了从连续过程中断开的形象。","originQuery":"break","page":6},{"id":"p07r06a","word":"neglected","pair":"forsaken","meaning":"被忽视的","origin":"Neglected 意思是“被忽视的”，是因为 neglect 的拉丁语核心是“不去挑选、不加理会”。它来自 neglegere“忽略”，通常分析为否定成分 nec- 与 legere“选择、收集”。没有被选来关注和照管的事物会逐渐被遗忘，因此 neglected 表示“无人注意或照料的”。","originQuery":"neglected","page":6},{"id":"p07r06b","word":"forsaken","pair":"neglected","meaning":"被忽视的","origin":"Forsaken 意思是“被忽视、遗弃的”，是因为它是 forsake“抛弃”的过去分词。forsake 来自古英语 forsacan“拒绝、放弃”，其中 for- 有完全、彻底的作用，sacan 与“争辩、否认”有关。被彻底拒绝、不再照管的人或地方，就是 forsaken，因此常带荒凉孤独感。","originQuery":"forsaken","page":6},{"id":"p07r07a","word":"contentious","pair":"fraught","meaning":"充满争议的","origin":"Contentious 意思是“充满争议的”，是因为它来自拉丁语 contentio“争斗、辩论”。其动词 contendere 由 con-“共同、相对”与 tendere“拉伸、用力”构成，可理解为双方朝相反方向较劲。容易引起这种争夺或争论的问题，就是 contentious，即“有争议的”。","originQuery":"contentious","page":6},{"id":"p07r07b","word":"fraught","pair":"contentious","meaning":"充满争议的","origin":"Fraught 意思是“充满……的”，是因为它原本表示船只“装满货物”。它与 freight“货物、运费”同源，经中古荷兰语或低地德语进入英语。船舱被货物塞满的图景后来用于抽象事物；fraught with controversy 就是“装满争议”，因而表示“充满争议、问题重重”。","originQuery":"fraught","page":6},{"id":"p07r08a","word":"bias","pair":"orientation","meaning":"倾向","origin":"Bias 意思是“倾向”，是因为它原先表示一条斜线或斜向。它经法语 biais“斜面、斜角”进入英语，裁布中的 on the bias 至今仍指斜裁。事物一旦向某侧倾斜，就不会保持中正；这个空间图景转用于判断，便成为偏向某一方的“倾向、偏见”。","originQuery":"bias","page":6},{"id":"p07r08b","word":"orientation","pair":"bias","meaning":"倾向","origin":"Orientation 意思是“倾向、取向”，是因为 orient 原指确定相对于东方的位置。orient 来自拉丁语 oriens“升起的太阳、东方”，与 oriri“升起”有关。知道东方就能确定方向；由空间定向扩展到思想、兴趣朝向何处，orientation 便表示“方向、取向或倾向”。","originQuery":"orientation","page":6},{"id":"p07r09a","word":"cursory","pair":"perfunctory","meaning":"草率的，敷衍的","origin":"Cursory 意思是“草率的”，是因为它的核心图景是“跑着匆匆经过”。它来自晚期拉丁语 cursorius“奔跑的”，核心 currere 是“跑”。检查若像跑过一样迅速，只触及表面而未停下来细看，就会粗略不充分，因此 cursory 表示“匆忙而草率的”。","originQuery":"cursory","page":6},{"id":"p07r09b","word":"perfunctory","pair":"cursory","meaning":"草率的，敷衍的","origin":"Perfunctory 意思是“草率、敷衍的”，是因为它原本表示“把职责做完了事”。它来自拉丁语 perfungi：per-“完成、经历到底”，fungi“履行”。重点逐渐从“完成”转到“只求完成”，即机械履行而不投入关心，所以 perfunctory 指形式上做了、实际上很敷衍。","originQuery":"perfunctory","page":6},{"id":"p07r10a","word":"untethered","pair":"divorced","meaning":"脱离，分离","origin":"Untethered 意思是“脱离、无拘束的”，是因为 tether 是拴住动物、限制活动范围的绳索。un- 表示“解除、没有”，-ed 表示所处状态。把拴绳解开，动物就离开固定点自由移动；因此 untethered 可从物理上的“未拴住”比喻思想、价格等脱离原有约束。","originQuery":"untethered","page":6},{"id":"p07r10b","word":"divorced","pair":"untethered","meaning":"脱离，分离","origin":"Divorced 意思是“脱离、分离”，是因为 divorce 的拉丁语核心是“转向不同道路”。它来自 divortium“分离”，与 divertere 有关：di-/dis-“分开”，vertere“转向”。两个人各自转向不同方向，就是婚姻解除；后来 divorced from 可泛指某事与现实、传统或另一事物脱离。","originQuery":"divorce","page":6},{"id":"p08r01a","word":"abstracted","pair":"divorced","meaning":"脱离","origin":"Abstracted 意思是“脱离”，是因为 abstract 的拉丁语字面义就是“拉开、抽走”。它来自 abstrahere：abs-“离开”，trahere“拉”；abstracted 是其过去分词形式。某物从原处被拉开，就是被抽离；人的注意力若像被拉走，则表示心不在焉。两种用法都保留“脱离”的核心。","originQuery":"abstracted","page":7},{"id":"p08r01b","word":"divorced","pair":"abstracted","meaning":"脱离","origin":"Divorced 意思是“脱离”，是因为 divorce 的词源图景是“各自转向不同方向”。它来自拉丁语 divortium，与 divertere“分开转向”有关，其中 dis-“分开”，vertere“转”。原指夫妻分道扬镳，后来 divorced from 泛指概念、政策等与现实或原有联系相分离。","originQuery":"divorce","page":7},{"id":"p08r02a","word":"average","pair":"undistinguished","meaning":"普通的","origin":"Average 意思是“普通的”，是因为它从“按份分摊损失”发展为“取共同的中间数”。该词经法语 avarie 等形式进入英语，早期用于海运损失及其分担。把总量平均分给各方，就得到平均值；位于平均水平的事物不突出，于是 average 又表示“平常、普通的”。","originQuery":"average","page":7},{"id":"p08r02b","word":"undistinguished","pair":"average","meaning":"普通的","origin":"Undistinguished 意思是“普通的”，是因为它表示“没有可使其区别出来的特点”。un-“不”，distinguished“杰出、显著的”；distinguish 来自拉丁语 distinguere“分开、标记差别”。若一个人或事物无法从同类中被辨认出来，就不突出，因此是“平凡、普通的”。","originQuery":"undistinguished","page":7},{"id":"p08r03a","word":"extolled","pair":"acclaimed","meaning":"赞扬","origin":"Extolled 意思是“受到赞扬”，是因为 extoll 的拉丁语字面义是“高高举起”。它来自 extollere：ex- 在这里有“向上”的意味，tollere“举起”。在言辞中把某人的地位或优点抬高，就是热烈赞颂；因此 extol 表示“高度赞扬”，extolled 是其过去式或过去分词。","originQuery":"extoll","page":7},{"id":"p08r03b","word":"acclaimed","pair":"extolled","meaning":"赞扬","origin":"Acclaimed 意思是“受到赞扬”，是因为 acclaim 的核心是“向某人大声呼喊”。它来自拉丁语 acclamare：ad-“向”，clamare“喊叫”；ad- 在 c 前同化为 ac-。群众以呼声欢迎、赞许某人，便是公开称赞，所以 acclaimed 表示“广受赞誉的”；相关词 exclaim 也含 clamare。","originQuery":"acclaim","page":7},{"id":"p08r04a","word":"imperceptible","pair":"trivial","meaning":"微不足道","origin":"Imperceptible 在这里表示“微不足道、几乎察觉不到”，是因为它由 im-“不”和 perceptible“可感知的”构成。perceive 最终来自拉丁语 percipere“完全抓住、领会”。数量或变化小到感官无法抓住，便近乎可以忽略，因此由“难以察觉”自然连接到“微小得不重要”。","originQuery":"imperceptible","page":7},{"id":"p08r04b","word":"trivial","pair":"imperceptible","meaning":"微不足道","origin":"Trivial 意思是“微不足道”，是因为拉丁语 trivialis 原指三岔路口的、随处可见的事物。它来自 trivium，由 tri-“三”与 via“路”构成。人人在公共路口都能遇见的东西显得寻常、不特别；由“普通”进一步贬化为“琐碎、无足轻重”。","originQuery":"trivial","page":7},{"id":"p08r05a","word":"ineptitude","pair":"maladroitness","meaning":"笨拙","origin":"Ineptitude 意思是“笨拙、无能”，是因为 inept 表示“不合适、不称职”。它来自拉丁语 ineptus：in-“不”，aptus“合适、胜任”；-itude 表示状态。一个人的能力或做法总与任务不相配，就会表现得笨拙无能，因此 ineptitude 指“缺乏技能或判断力”。","originQuery":"ineptitude","page":7},{"id":"p08r05b","word":"maladroitness","pair":"ineptitude","meaning":"笨拙","origin":"Maladroitness 意思是“笨拙”，是因为法语 maladroit 的构词就是“做得不灵巧”。mal 表示“坏、糟糕地”，adroit 表示“熟练、灵巧”；-ness 把性质变成名词。行动缺乏灵巧和分寸，就显得手脚笨拙或处事不圆熟，因此 maladroitness 指“笨拙、不机敏”。","originQuery":"maladroit","page":7},{"id":"p08r06a","word":"thwarted","pair":"frustrated","meaning":"受挫的","origin":"Thwarted 意思是“受挫的”，是因为 thwart 的原始方向是“横着、横跨”。它来自古诺斯语 þvert“横向地”，与 across 的概念相近。某物横在前进路线上，就会挡住行动；因此 thwart 成为动词，表示“阻挠、使计划失败”，thwarted 便是“被阻止、受挫的”。","originQuery":"thwart","page":7},{"id":"p08r06b","word":"frustrated","pair":"thwarted","meaning":"受挫的","origin":"Frustrated 意思是“受挫的”，是因为 frustrate 的核心是“使努力落空”。它来自拉丁语 frustrari“使失望、欺骗”，与 frustra“徒劳地”有关。目标没有实现，付出的努力变成徒劳，便产生受阻和沮丧感；所以 frustrated 既可指计划“受挫”，也可指人“感到沮丧”。","originQuery":"frustrated","page":7},{"id":"p08r07a","word":"stilted","pair":"wooden","meaning":"不自然的生硬的","origin":"Stilted 意思是“不自然、生硬的”，是因为它原指“架在高跷上的”。stilt 是把人或物抬高的长脚支架；stilted 最初描述被高跷托起。走高跷的姿势高而僵硬，不像自然步态，于是这个形象用于语言或举止，表示刻意抬高、拘谨生硬。","originQuery":"stilted","page":7},{"id":"p08r07b","word":"wooden","pair":"stilted","meaning":"不自然的生硬的","origin":"Wooden 意思是“不自然、生硬的”，是因为它本义是“木头制成的”。wood 加 -en 构成材料形容词。木头坚硬、缺少肌肉般的灵活与表情，因此 wooden 被比喻用于动作、表演或语气，表示像木偶一样僵直、没有生气，也就是“生硬、不自然的”。","originQuery":"wooden","page":7},{"id":"p08r08a","word":"occult","pair":"arcane","meaning":"深奥难懂","origin":"Occult 意思是“深奥难懂”，是因为它原本表示“被遮住、隐藏的”。它来自拉丁语 occultus，是 occulere“隐藏”的过去分词，与 ob-“在前、遮挡”及 celare“藏匿”相关。知识若只对少数人开放、藏在表象之后，就显得神秘难解，因此 occult 又指秘术或深奥事物。","originQuery":"occult","page":7},{"id":"p08r08b","word":"arcane","pair":"occult","meaning":"深奥难懂","origin":"Arcane 意思是“深奥难懂”，是因为拉丁语 arcanus 表示“秘密的、隐藏的”。它来自 arca“箱子、柜子”：锁在箱中的东西不会公开示人。由“被收藏的秘密”发展到只有少数专家掌握的知识，arcane 因而表示“神秘的、晦涩难懂的”；相关词 arcanum 指“秘密”。","originQuery":"arcane","page":7},{"id":"p08r09a","word":"buoyed","pair":"sustained","meaning":"支持","origin":"Buoyed 意思是“受到支持”，是因为 buoy 原指漂在水面、标示航道的浮标。它经古法语 buie 或中古荷兰语 boeye 进入英语，更早可能与“信标、信号”有关。浮标能漂浮并托住物体，于是 buoy 成为“使浮起、支撑”的动词，进一步也表示在精神上鼓舞。","originQuery":"buoy","page":7},{"id":"p08r09b","word":"sustained","pair":"buoyed","meaning":"支持","origin":"Sustained 意思是“受到支持”，是因为 sustain 的拉丁语字面义是“从下面托住”。它来自 sustinere：sus- 是 sub-“在下”的变体，tenere“抓住、保持”。从下方撑住可防止坠落，由此扩展为维持生命、论点或行动；sustained 因而表示“被支撑、得以维持的”。","originQuery":"sustain","page":7},{"id":"p08r10a","word":"prolix","pair":"verbose","meaning":"冗长","origin":"Prolix 意思是“冗长”，是因为拉丁语 prolixus 原本表示“向前延伸、拉得很长”。它与 pro-“向前”及 liquere“流动”相关，可理解为内容不断向前流出。篇章若延伸过久、用了超过需要的文字，就成为 prolix，即“啰嗦冗长的”。","originQuery":"prolix","page":7},{"id":"p08r10b","word":"verbose","pair":"prolix","meaning":"冗长","origin":"Verbose 意思是“冗长”，是因为它的拉丁语构词就是“充满词语”。它来自 verbosus，核心 verbum 是“词、言语”，-osus 表示“充满……的”。表达若堆满过多词语，信息没有相应增加，就显得啰嗦，因此 verbose 表示“多言而冗长的”；名词 verbosity 指“冗长”。","originQuery":"verbose","page":7},{"id":"p09r01a","word":"unstinting","pair":"generous","meaning":"慷慨大方","origin":"Unstinting 意思是“慷慨大方”，是因为 stint 表示“限制数量、节省使用”，un- 则表示“不”。stint 的更早来源可能与“使变钝、缩短”有关，但并不完全确定。给予时不设限额、不吝惜，就是 unstinting，因此常形容赞扬、支持或帮助“毫无保留的”。","originQuery":"unstinting","page":8},{"id":"p09r01b","word":"generous","pair":"unstinting","meaning":"慷慨大方","origin":"Generous 意思是“慷慨大方”，是因为它最初指“出身高贵、具有贵族品格”。它来自拉丁语 generosus，核心 genus 是“出身、种类”。传统观念把宽宏、勇敢视为高贵品格，于是词义从“贵族的”转为“胸襟宽大”，最后特别指愿意多给、不吝啬。","originQuery":"generous","page":8},{"id":"p09r02a","word":"fundamentally miscellaneous","pair":"thoroughly eclectic","meaning":"多种多样的","origin":"Fundamentally miscellaneous 意思是“根本上多种多样”，关键在 miscellaneous。miscellaneous 来自拉丁语 miscellus“混合的”，与 miscere“混合”有关；fundamentally 则来自 fundamentum“基础”，表示“从根本性质上”。合起来就是其基础构成并非单一，而是许多不同种类混合在一起。","originQuery":"fundamentally","page":8},{"id":"p09r02b","word":"thoroughly eclectic","pair":"fundamentally miscellaneous","meaning":"多种多样的","origin":"Thoroughly eclectic 意思是“彻底地多种多样”，是因为 eclectic 的核心是“从各处挑选”。它来自希腊语 eklegein：ek-“从……中”，legein“选择、收集”。不拘一个流派，而从许多来源选取成分，就会形成多样混合；thoroughly 加强这种程度，表示“非常兼收并蓄”。","originQuery":"thorough","page":8},{"id":"p09r03a","word":"thorough","pair":"exhaustive","meaning":"全面的","origin":"Thorough 意思是“全面的”，是因为它与 through“穿过、从头到尾”同源，来自古英语 þurh。原先两者只是同一词的不同形式；后来 thorough 专门作形容词。检查若从一端贯穿到另一端，各部分都不遗漏，就是“彻底的、全面的”。","originQuery":"thorough","page":8},{"id":"p09r03b","word":"exhaustive","pair":"thorough","meaning":"全面的","origin":"Exhaustive 意思是“全面的”，是因为 exhaust 的原始图景是“把容器完全舀空”。它来自拉丁语 exhaurire：ex-“向外、彻底”，haurire“汲取”。研究若把资料和可能性全部取尽，不留下遗漏，就叫 exhaustive，因此不是“令人疲惫的”，而是“穷尽一切的、全面的”。","originQuery":"exhaustive","page":8},{"id":"p09r04a","word":"insular","pair":"parochial","meaning":"狭隘","origin":"Insular 意思是“狭隘”，是因为它原本表示“岛屿的”。它来自拉丁语 insula“岛”，-ar 表示“与……有关”。岛屿与外界隔绝的地理形象被用于人的眼界或群体态度，表示只关心自己一小片范围、不接纳外来观点，因此 insular 可译为“闭塞、狭隘的”。","originQuery":"insular","page":8},{"id":"p09r04b","word":"parochial","pair":"insular","meaning":"狭隘","origin":"Parochial 意思是“狭隘”，是因为它最初表示“只属于一个教区的”。它来自晚期拉丁语 parochialis，核心 paroecia 是“教区”。眼光若只停留在本地教区、不看更广阔世界，就显得地方性强而见识有限，于是 parochial 从“教区的”引申为“目光狭隘的”。","originQuery":"parochial","page":8},{"id":"p09r05a","word":"disparaged","pair":"dismissed","meaning":"贬低","origin":"Disparaged 意思是“贬低”，是因为 disparage 的早期含义是“降低等级，使不相配”。它来自古法语 desparagier，其中 des-“去除、降低”，parage 与“身份、同等地位”有关。把某人从同等地位往下压，就是损害其声望；因此 disparage 发展为“轻视、贬低”。","originQuery":"disparage","page":8},{"id":"p09r05b","word":"dismissed","pair":"disparaged","meaning":"贬低","origin":"Dismissed 在这里意思是“贬低、不予重视”，是因为 dismiss 的拉丁语字面义是“把人送走”。它来自 dimittere：dis-“分开、离开”，mittere“送”。由让人离场发展为拒绝考虑某个观点；如果不经认真评价便把它“打发走”，就是认为它不值得重视，因此带有贬低意味。","originQuery":"dismiss","page":8},{"id":"p09r06a","word":"paucity","pair":"dearth","meaning":"缺乏","origin":"Paucity 意思是“缺乏”，是因为它来自拉丁语 paucitas“数量少”，核心 paucus 就是“少数、很少”。-ity 表示状态或性质。某种资源只有少量，低于实际需要时，就构成短缺；因此 paucity 常用于正式语体，表示“少量、缺乏”，如 a paucity of evidence。","originQuery":"paucity","page":8},{"id":"p09r06b","word":"dearth","pair":"paucity","meaning":"缺乏","origin":"Dearth 意思是“缺乏”，是因为它最早与“昂贵”有关。它来自古英语 dēore“珍贵、价格高”，也就是现代 dear 的一个来源；-th 构成状态名词。东西供应稀少时价格会上涨，于是“昂贵的状态”逐渐转指造成昂贵的“短缺、匮乏”。","originQuery":"dearth","page":8},{"id":"p09r07a","word":"bolstering","pair":"buttressing","meaning":"支持","origin":"Bolstering 意思是“支持”，是因为 bolster 原指用来托住头部或身体的长枕、垫枕。它来自古英语 bolster，和“鼓起、膨胀”的概念有关。垫枕从下面把身体撑起，于是 bolster 成为动词，表示加强论点、信心或力量；bolstering 即“正在支撑、增强”。","originQuery":"bolster","page":8},{"id":"p09r07b","word":"buttressing","pair":"bolstering","meaning":"支持","origin":"Buttressing 意思是“支持”，是因为 buttress 本指从外侧撑住墙体的扶壁。它经古法语进入英语，早期尤指教堂建筑的支撑结构。扶壁防止高墙倾倒，这一具体功能后来被用于证据、资源或理由，表示给某事增加支撑；buttressing 即“加固、支持”。","originQuery":"buttress","page":8},{"id":"p09r08a","word":"lull","pair":"respite","meaning":"短暂的平静或休息","origin":"Lull 意思是“短暂的平静或休息”，是因为它原先表示用轻柔、重复的声音哄人安静或入睡。这个词可能带有模拟摇篮曲声音的性质，与 lullaby 相关。喧闹或活动暂时被安抚下来，就出现一段安静期，因此 a lull 是风暴、争论或工作中的“短暂平息”。","originQuery":"lull","page":8},{"id":"p09r08b","word":"respite","pair":"lull","meaning":"短暂的平静或休息","origin":"Respite 意思是“短暂的平静或休息”，是因为它原先指惩罚、义务或行动的“延期”。它经古法语 respit 来自拉丁语 respectus“回看、考虑”。事情暂停，让人有时间重新考虑，也让压力暂时解除；因此 respite 发展为困难中的“喘息、短暂休息”。","originQuery":"respite","page":8},{"id":"p09r09a","word":"predilection","pair":"proclivity","meaning":"偏好","origin":"Predilection 意思是“偏好”，是因为它的构词核心是“在其他对象之前先喜欢”。它来自拉丁语 praediligere：prae-“在前、优先”，diligere“珍视、喜爱”。把某个选择预先置于其他选择之上，就是对它有特别偏爱，因此 predilection 指较固定的偏好。","originQuery":"predilection","page":8},{"id":"p09r09b","word":"proclivity","pair":"predilection","meaning":"偏好","origin":"Proclivity 意思是“偏好、倾向”，是因为它原本表示向前倾斜的坡势。拉丁语 proclivis 由 pro-“向前”与 clivus“斜坡”构成。物体会顺坡自然滑向一个方向，这个图景转用于人的性情，表示无需外力就容易选择某种行为或爱好。","originQuery":"proclivity","page":8},{"id":"p09r10a","word":"stubborn","pair":"intractable","meaning":"顽固的","origin":"Stubborn 意思是“顽固的”，是因为它自中古英语起就形容难以移动、难以说服的状态。其更早来源不确定，因此不宜强行拆成现代词根。词义由物体“坚硬、不肯动”平行扩展到人的态度“不肯改变”，于是表示“固执、顽强难对付的”。","originQuery":"stubborn","page":8},{"id":"p09r10b","word":"intractable","pair":"stubborn","meaning":"顽固的","origin":"Intractable 意思是“顽固、难以处理的”，是因为它表示“无法被拉着走或摆弄”。它来自拉丁语 intractabilis：in-“不”，tractare“处理、操弄”，后者与 trahere“拉”有关；-able 表示“可……的”。不能被引导或处理的人、问题，就顽固难办。","originQuery":"intractable","page":8},{"id":"p10r01a","word":"familiar","pair":"recognizable","meaning":"熟悉的","origin":"Familiar 意思是“熟悉的”，是因为它最初表示“属于家中、与一家人亲近的”。它来自拉丁语 familiaris，核心 familia 是“家庭、家中成员”。家里的人和事由于长期相处而非常了解，因此 familiar 从“家庭的、亲密的”发展为“经常见到并认得的、熟悉的”。","originQuery":"familiar","page":9},{"id":"p10r01b","word":"recognizable","pair":"familiar","meaning":"熟悉的","origin":"Recognizable 意思是“熟悉、可认出的”，是因为 recognize 的拉丁语核心是“再次知道”。它来自 recognoscere：re-“再次”，cognoscere“认识、知道”；-able 表示“能够被……”。眼前事物若能与记忆中的形象重新对应，就可以认出来，因此 recognizable 表示“可识别的、看起来熟悉的”。","originQuery":"recognizable","page":9},{"id":"p10r02a","word":"mixed","pair":"inconsistent","meaning":"不一致的","origin":"Mixed 意思是“不一致的”，是因为 mix 表示把不同成分混合在一起。它经中古英语形式来自拉丁语 miscere“混合”；mixed 是过去分词。若评价、信号或结果中同时包含相反或不同成分，整体就不能指向一个统一结论，因此 mixed 可表示“好坏参半、不一致的”。","originQuery":"mixed","page":9},{"id":"p10r02b","word":"inconsistent","pair":"mixed","meaning":"不一致的","origin":"Inconsistent 意思是“不一致的”，是因为它由 in-“不”和 consistent“一致、前后相符的”构成。consistent 来自拉丁语 consistere“共同站立、保持”，其中 con-“共同”，sistere“站住”。各部分若不能一起站稳、彼此配合，就前后矛盾，因此是 inconsistent。","originQuery":"inconsistent","page":9},{"id":"p10r03a","word":"conceded","pair":"acknowledged","meaning":"承认","origin":"Conceded 意思是“承认”，是因为 concede 的核心是“让步、把立场让出去”。它来自拉丁语 concedere：con-“完全、共同”，cedere“退让、离开”。争论中退让一步，就是接受对方某点成立；因此 concede 由“让出”发展为“勉强承认”，conceded 是其过去式。","originQuery":"concede","page":9},{"id":"p10r03b","word":"acknowledged","pair":"conceded","meaning":"承认","origin":"Acknowledged 意思是“承认”，是因为 acknowledge 的历史核心是“认出并表示知道”。它由中古英语 aknow“承认、认出”与表示动作的成分形成，aknow 又与古英语 oncnāwan“认出”有关。把某事实辨认出来并公开表示接受，就是“承认”；acknowledged 也可表示“公认的”。","originQuery":"acknowledge","page":9},{"id":"p10r04a","word":"belie","pair":"mask","meaning":"掩饰","origin":"Belie 意思是“掩饰、给人错误印象”，是因为它来自古英语 beleogan“用谎言欺骗”，由 be- 与 leogan“说谎”构成。若外表像在“说谎”，它呈现的样子就与真相不符，从而遮住真实情况。因此 belie 常表示“掩盖真相”或“证明某种表象不真实”。","originQuery":"belie","page":9},{"id":"p10r04b","word":"mask","pair":"belie","meaning":"掩饰","origin":"Mask 意思是“掩饰”，是因为 mask 最初就是遮住脸、隐藏身份的面具。它经法语 masque 和意大利语 maschera 进入英语，更早来源尚不确定。戴面具使真实面孔不可见，于是 mask 成为动词，泛指用表象遮住情绪、动机或问题，也就是“掩饰”。","originQuery":"mask","page":9},{"id":"p10r05a","word":"awkward","pair":"ungainly","meaning":"笨拙的","origin":"Awkward 意思是“笨拙的”，是因为它原本带有“方向不对、反手而行”的感觉。中古英语 awk 表示“反向、错误”，-ward 表示“朝向”。朝不顺手的方向动作，自然显得不灵便；这个空间与动作上的“不对劲”后来扩展到社交场面，表示尴尬、不自然。","originQuery":"awkward","page":9},{"id":"p10r05b","word":"ungainly","pair":"awkward","meaning":"笨拙的","origin":"Ungainly 意思是“笨拙的”，是因为它由 un-“不”和古义 gainly“合适、灵巧”构成。gainly 与古诺斯语 gegn“直、合适”相关，不能按现代 gain“获得”来拆。动作若不合适、不便利，就显得难看而笨拙，因此 ungainly 形容体态或动作不协调。","originQuery":"ungainly","page":9},{"id":"p10r06a","word":"unalloyed","pair":"unqualified","meaning":"纯粹的","origin":"Unalloyed 意思是“纯粹的”，是因为 alloy 指加入金属中的合金成分或混合物，un- 表示“没有”。金属未经掺合，就保持纯度；因此 unalloyed 的字面概念是“没有掺入其他成分的”。后来它也形容抽象感情毫无杂质，如 unalloyed joy“纯粹的喜悦”。","originQuery":"unalloyed","page":9},{"id":"p10r06b","word":"unqualified","pair":"unalloyed","meaning":"纯粹的","origin":"Unqualified 在这里意思是“纯粹、毫无保留的”，是因为 qualify 可表示给陈述加上限制条件，un- 表示“没有”。qualified praise 是有所保留、附带条件的赞扬；去掉限制后，unqualified 就是完全彻底的。注意它在另一语境也可表示“没有资格的”，需由上下文判断。","originQuery":"unqualified","page":9},{"id":"p10r07a","word":"discordance","pair":"contention","meaning":"不一致","origin":"Discordance 意思是“不一致”，是因为其拉丁语构词表示“心或声音分开”。它来自 discordare，dis-“分离、不一致”，cor/cord-“心”；-ance 表示状态。人心不合会产生争执，声音不合会产生不和谐，因此 discordance 泛指意见、数据或音调之间的不协调。","originQuery":"discordance","page":9},{"id":"p10r07b","word":"contention","pair":"discordance","meaning":"不一致","origin":"Contention 意思是“不一致、争论”，是因为它原先描写双方用力争夺。它来自拉丁语 contendere：con-“共同、相对”，tendere“拉伸、用力”。两方各自用力坚持不同立场，就形成争执；因此 contention 可指激烈争论，也可指争论中提出的主张。","originQuery":"contention","page":9},{"id":"p10r08a","word":"immaterial","pair":"inconsequential","meaning":"不重要的","origin":"Immaterial 意思是“不重要的”，是因为它先表示“不由物质构成”。im-“不”，material 来自拉丁语 materia“材料、物质”。不具有实体的东西被视为无形；法律和论证中，与核心事实没有实质关系的内容也像“没有分量”，于是 immaterial 进一步表示“无关紧要的”。","originQuery":"immaterial","page":9},{"id":"p10r08b","word":"inconsequential","pair":"immaterial","meaning":"不重要的","origin":"Inconsequential 意思是“不重要的”，是因为它表示“不会带来重要后果”。in-“不”，consequential 来自 consequence“结果、后果”；consequence 又源于拉丁语 consequi“随后发生”。一件事若没有值得关注的后续影响，就无足轻重，因此 inconsequential 是“不重要的、微不足道的”。","originQuery":"inconsequential","page":9},{"id":"p10r09a","word":"denounces","pair":"lambasts","meaning":"严厉批评","origin":"Denounces 意思是“严厉批评”，是因为 denounce 原本表示公开宣布，尤其是正式宣布罪责。它来自拉丁语 denuntiare：de- 有强调作用，nuntiare“报告、宣布”。公开指出某人错误并加以谴责，比普通批评更强烈，因此 denounce 发展为“公开斥责、谴责”。","originQuery":"denounce","page":9},{"id":"p10r09b","word":"lambasts","pair":"denounces","meaning":"严厉批评","origin":"Lambasts 意思是“严厉批评”，是因为 lambast 原先表示“狠打、痛打”，后来转为言语攻击。该词来源并不确定，通常认为可能结合了 lam“打”和 baste“痛打”，但这不是完全确定的历史构词。批评若像一顿痛打般猛烈，就是 lambast，即“痛斥”。","originQuery":"lambasts","page":9},{"id":"p10r10a","word":"derision","pair":"ridicule","meaning":"嘲笑","origin":"Derision 意思是“嘲笑”，是因为它的词源核心就是“带着贬低意味地笑”。它来自拉丁语 deridere“嘲笑”：de- 可含“向下、贬低”，ridere 是“笑”；-ion 表示行为。可以理解为“把别人往下压着笑”，于是形成轻蔑的嘲弄；同源词有 deride、derisive。","originQuery":"derision","page":9},{"id":"p10r10b","word":"ridicule","pair":"derision","meaning":"嘲笑","origin":"Ridicule 意思是“嘲笑”，是因为它来自拉丁语 ridiculus“可笑的”，核心 ridere 表示“笑”。先把某人或某事视为荒唐可笑，再以言语使其成为笑柄，就从形容“可笑”发展为动词“嘲弄”。相关词 ridiculous 是“荒谬可笑的”。","originQuery":"ridicule","page":9},{"id":"p11r01a","word":"unprepossessing","pair":"unremarkable","meaning":"不起眼的","origin":"Unprepossessing 意思是“不起眼的”，是因为 prepossessing 表示“第一眼就能赢得好感的”，un- 表示“不”。prepossess 原意是“预先占据”，由 pre-“预先”与 possess“占有”构成；能预先占据别人好感的外表就是迷人的。不能产生这种第一印象，便是相貌平常、不引人注意。","originQuery":"unprepossessing","page":10},{"id":"p11r01b","word":"unremarkable","pair":"unprepossessing","meaning":"不起眼的","origin":"Unremarkable 意思是“不起眼的”，是因为它由 un-“不”和 remarkable“值得注意的”构成。remark 原指再次注意、作出评论，与 re-“再”和 mark“标记、注意”有关；-able 表示“值得、能够”。某物没有值得特别标出的特点，就普通得不会引人评论，因此是 unremarkable。","originQuery":"unremarkable","page":10},{"id":"p11r02a","word":"exacerbated","pair":"aggravated","meaning":"加剧","origin":"Exacerbated 意思是“加剧”，是因为 exacerbate 的拉丁语核心是“使变得更尖锐、更刺激”。它来自 exacerbare，核心 acerbus 表示“苦涩、严厉”。疼痛或矛盾像酸涩刺激一样变得更强，就叫 exacerbate；exacerbated 表示问题已被“恶化、加剧”。","originQuery":"exacerbate","page":10},{"id":"p11r02b","word":"aggravated","pair":"exacerbated","meaning":"加剧","origin":"Aggravated 意思是“加剧”，是因为 aggravate 的字面义是“使更沉重”。它来自拉丁语 aggravare：ad-“使、向”，gravis“重的”；ad- 在 g 前同化为 ag-。给问题增加重量，就是使负担或严重程度上升，因此 aggravated 表示“加重、恶化了的”；同源词 gravity 也有“重”的核心。","originQuery":"aggravated","page":10},{"id":"p11r03a","word":"superficial","pair":"sketchy","meaning":"肤浅的","origin":"Superficial 意思是“肤浅的”，是因为它原本表示“只在表面上的”。它来自拉丁语 superficialis，核心 superficies 由 super-“在上面”与 facies“表面、外观”构成。观察若只停留在外层，没有深入内部原因，就显得浅薄，因此 superficial 从“表面的”引申为“肤浅的”。","originQuery":"superficial","page":10},{"id":"p11r03b","word":"sketchy","pair":"superficial","meaning":"肤浅的","origin":"Sketchy 意思是“肤浅、不充分的”，是因为 sketch 原指只勾出轮廓的速写，-y 表示具有这种性质。速写提供大致形状，却缺少完整细节；因此 sketchy 用于说明、计划或知识时，表示只有粗略轮廓、内容单薄。后来它还可指情况“可疑、不可靠”，需按语境理解。","originQuery":"sketchy","page":10},{"id":"p11r04a","word":"acerbic","pair":"harsh","meaning":"尖刻的","origin":"Acerbic 意思是“尖刻的”，是因为它先形容味道“酸涩、苦而刺激”。它来自拉丁语 acerbus“未熟的、酸涩的、严厉的”，与“尖锐”概念相关。言辞若像酸味一样刺激、令人难受，就会显得辛辣刻薄，因此 acerbic 由味觉转为性格和语言上的“尖刻”。","originQuery":"acerbic","page":10},{"id":"p11r04b","word":"harsh","pair":"acerbic","meaning":"尖刻的","origin":"Harsh 意思是“尖刻的”，是因为它原先形容触感粗糙、味道酸涩或声音刺耳。它可能来自斯堪的纳维亚或低地德语相关形式，更早来源并不确定。由感官上的不柔和，词义扩展到态度和言辞缺乏温和、令人受伤，因此表示“严厉、尖刻”。","originQuery":"harsh","page":10},{"id":"p11r05a","word":"determination","pair":"resolve","meaning":"决心","origin":"Determination 意思是“决心”，是因为 determine 的字面核心是“划定边界，使事情定下来”。它来自拉丁语 determinare：de-“完全”与 terminus“界限、终点”。当人把选择明确限定、不再摇摆，就形成坚定意志；因此 determination 由“作出确定”发展为“决心、毅力”。","originQuery":"determination","page":10},{"id":"p11r05b","word":"resolve","pair":"determination","meaning":"决心","origin":"Resolve 意思是“决心”，是因为它原先表示把复杂问题“分解、解开”，从而得出确定答案。它来自拉丁语 resolvere：re-“回、彻底”，solvere“松开、解决”。疑惑被解开后，意志也随之定下；因此 resolve 作动词可指“解决、决定”，作名词则是坚定的“决心”。","originQuery":"resolve","page":10},{"id":"p11r06a","word":"splendor","pair":"brilliance","meaning":"辉煌","origin":"Splendor 意思是“辉煌”，是因为它来自拉丁语 splendor“光辉、明亮”，核心 splendere 表示“闪耀”。强烈的光芒给人华美壮丽之感，于是词义从视觉亮度扩展到宏伟场面、显赫成就或荣耀。相关词 splendid 原指“灿烂的”，后来常表示“极好的”。","originQuery":"splendor","page":10},{"id":"p11r06b","word":"brilliance","pair":"splendor","meaning":"辉煌","origin":"Brilliance 意思是“辉煌”，是因为 brilliant 最初表示宝石或光线“闪耀的”。它经法语 brillant 进入英语，与 briller“发光”有关；-ance 表示状态。耀眼光芒带来灿烂华丽的印象，因此 brilliance 可指“光辉、辉煌”，又由头脑闪光引申为“才华卓越”。","originQuery":"brilliance","page":10},{"id":"p11r07a","word":"anathema","pair":"repellent","meaning":"令人厌恶的","origin":"Anathema 意思是“令人厌恶的事物”，是因为它曾指被宗教诅咒、逐出共同体的人或物。它经拉丁语来自希腊语 anathema，原可指被献置的东西，后来在教会语境中转为“受诅咒者”。必须彻底排斥的对象，便进一步成为“极其讨厌、绝不能接受的事物”。","originQuery":"anathema","page":10},{"id":"p11r07b","word":"repellent","pair":"anathema","meaning":"令人厌恶的","origin":"Repellent 意思是“令人厌恶的”，是因为它的拉丁语构词图景是“向后推开”。re-“向后”，pellere“推动、驱赶”，-ent 表示具有这种作用。能排斥水或昆虫的东西会把它们赶开；同样，让人心理上本能想远离的事物就是 repellent，即“令人反感的”。","originQuery":"repellent","page":10},{"id":"p11r08a","word":"ubiquitous","pair":"prevalent","meaning":"无处不在普遍存在","origin":"Ubiquitous 意思是“无处不在、普遍存在”，是因为它来自拉丁语 ubique“到处、在每个地方”。由 ubique 形成 ubiquity“无所不在”，再有形容词 ubiquitous。某种现象若无论走到哪里都能遇到，就不仅常见，而是仿佛遍布所有地方，因此译为“无处不在的”。","originQuery":"ubiquitous","page":10},{"id":"p11r08b","word":"prevalent","pair":"ubiquitous","meaning":"无处不在普遍存在","origin":"Prevalent 意思是“普遍存在的”，是因为 prevail 原本表示“力量更强、占上风”。它来自拉丁语 praevalere：prae-“在前、超过”，valere“强健、有力”。一种现象若强到占据主导地位，便会广泛流行；因此 prevalent 从“占优势的”发展为“盛行、普遍的”。","originQuery":"prevalent","page":10},{"id":"p11r09a","word":"democratic","pair":"egalitarian","meaning":"平等的","origin":"Democratic 在这里意思是“平等的”，是因为 democracy 的希腊语构词是“人民统治”。dēmos 表示“人民”，kratos 表示“力量、统治”，-ic 构成形容词。权力不专属于少数人，而由公民共同参与，核心便包含政治地位的平等；因此 democratic 也可泛指作风平等、不摆等级架子。","originQuery":"democratic","page":10},{"id":"p11r09b","word":"egalitarian","pair":"democratic","meaning":"平等的","origin":"Egalitarian 意思是“平等的”，是因为它直接来自法语 égalitaire“主张平等的”，核心 égal 是“相等”。这组词最终可追溯到拉丁语 aequalis“相等的”；-arian 表示相关立场或人。主张人人享有同等权利和机会，就是 egalitarian，因此可译为“平等主义的”。","originQuery":"egalitarian","page":10},{"id":"p11r10a","word":"malleable","pair":"plastic","meaning":"可塑的","origin":"Malleable 意思是“可塑的”，是因为它原本形容金属“可以用锤子敲打成形”。它来自中世纪拉丁语 malleabilis，核心 malleus 是“锤子”，-able 表示“能够被……”。受敲击能改变形状而不破裂，就是有延展性；后来也比喻思想或性格容易改变。","originQuery":"malleable","page":10},{"id":"p11r10b","word":"plastic","pair":"malleable","meaning":"可塑的","origin":"Plastic 意思是“可塑的”，是因为它在成为材料名称之前就表示“能够塑造成形”。它来自希腊语 plastikos“适合塑造的”，核心 plassein 是“塑形、成形”。能被外力改变形态的东西具有 plastic 性；后来这种性质给合成材料命名，也可比喻大脑或性格富于可塑性。","originQuery":"plastic","page":10},{"id":"p12r01a","word":"maverick","pair":"nonconformist","meaning":"特立独行者","origin":"Maverick 意思是“特立独行者”，是因为它原指没有烙上牧场主人标记的小牛。词来自得州牧场主 Samuel Maverick 的姓氏；他不按惯例给牛烙印，于是无主标记的牛被称为 maverick。由“不属于既定群体”引申为不随众、独立行事的人。","originQuery":"maverick","page":11},{"id":"p12r01b","word":"nonconformist","pair":"maverick","meaning":"特立独行者","origin":"Nonconformist 意思是“特立独行者”，是因为它由 non-“不”、conform“遵从一致”与 -ist“……的人”构成。conform 来自拉丁语 conformare“使具有相同形式”。不把自己塑造成与群体相同的样子、不遵守主流规范的人，就是 nonconformist，即“不从众者”。","originQuery":"nonconformist","page":11},{"id":"p12r02a","word":"unscrupulous","pair":"dishonest","meaning":"不诚实","origin":"Unscrupulous 意思是“不诚实、不择手段”，是因为 scruple 原指使良心不安的“小尖石”。它来自拉丁语 scrupulus“小尖石、疑虑”，可理解为鞋中小石般刺痛良心；scrupulous 是顾忌道德的。加 un- 后就是没有这种良心顾虑，因此会为目的不择手段。","originQuery":"unscrupulous","page":11},{"id":"p12r02b","word":"dishonest","pair":"unscrupulous","meaning":"不诚实","origin":"Dishonest 意思是“不诚实”，是因为它由 dis-“缺乏、相反”与 honest“正直的”构成。honest 最终来自拉丁语 honestus“受尊敬的、体面的”，与 honor“荣誉”同源。言行不符合值得尊敬的品格，便是欺骗、不诚实，因此 dishonest 与 honesty“诚实”直接相对。","originQuery":"dishonest","page":11},{"id":"p12r03a","word":"cynical","pair":"jaded","meaning":"愤世嫉俗的","origin":"Cynical 意思是“愤世嫉俗的”，是因为它来自希腊语 kynikos“像狗的”。古希腊犬儒学派蔑视财富和社会习俗，被称为“犬一般的人”；后来词义离开原学派，转为相信人多出于自私动机、对理想抱怀疑态度，因此形成现代的“愤世嫉俗”。","originQuery":"cynical","page":11},{"id":"p12r03b","word":"jaded","pair":"cynical","meaning":"愤世嫉俗的","origin":"Jaded 意思是“厌倦、愤世的”，是因为 jade 曾指一匹疲惫不堪、役使过度的马。把马骑到精疲力尽就是 to jade；jaded 因而先表示“疲惫的”。人经历太多刺激或失望后也会像老马一样麻木，对事物失去热情，于是发展出“厌倦、冷漠”的意味。","originQuery":"jaded","page":11},{"id":"p12r04a","word":"sympathetic","pair":"well-disposed","meaning":"赞同的","origin":"Sympathetic 意思是“赞同、同情的”，是因为 sympathy 的希腊语构词是“共同感受”。syn-“一起”，pathos“感受、遭遇”，合起来表示与别人感同身受。理解并共享对方的感受，通常会对其观点或处境持善意态度，因此 sympathetic 可由“有同情心的”扩展为“赞同、支持的”。","originQuery":"sympathetic","page":11},{"id":"p12r04b","word":"well-disposed","pair":"sympathetic","meaning":"赞同的","origin":"Well-disposed 意思是“赞同、抱有好感的”，是因为 disposed 可表示“具有某种心理倾向”，well 则把这种倾向定为善意。dispose 来自拉丁语 disponere“安排、放置”，由 dis-“分开”与 ponere“放置”构成。心态若被“安排”在友好方向，就是愿意接受、支持某人。","originQuery":"disposed","page":11},{"id":"p12r05a","word":"precarious","pair":"uncertain","meaning":"不确定的","origin":"Precarious 意思是“不确定、危险的”，是因为它最初指“靠请求才获得、可随时被收回的”。它来自拉丁语 precarius“经祈求取得的”，与 prex“祈祷、请求”有关。只凭他人恩准而拥有的东西没有保障，由“不稳固”进一步发展为“岌岌可危、不确定”。","originQuery":"precarious","page":11},{"id":"p12r05b","word":"uncertain","pair":"precarious","meaning":"不确定的","origin":"Uncertain 意思是“不确定的”，是因为它由 un-“不”和 certain“确定的”构成。certain 经法语来自拉丁语 certus“已决定的、可靠的”，与 discern 的“区分、决定”概念相关。事实若尚未定下或无法可靠知道，就是 uncertain，可指结果、信息或人的态度不确定。","originQuery":"uncertain","page":11},{"id":"p12r06a","word":"interwoven","pair":"integrated","meaning":"交织在一起","origin":"Interwoven 意思是“交织在一起”，是因为它由 inter-“在彼此之间”与 woven“编织”构成。woven 是 weave 的过去分词；织物由经纬线相互穿过而形成整体。不同主题、命运或因素若像线一样彼此穿插、难以分开，就称为 interwoven。","originQuery":"interwoven","page":11},{"id":"p12r06b","word":"integrated","pair":"interwoven","meaning":"交织在一起","origin":"Integrated 意思是“结合在一起”，是因为 integrate 的核心是“使恢复为完整整体”。它来自拉丁语 integrare，核心 integer 表示“完整、未触动的”。把原本分离的部分纳入同一系统，使其共同运作，就是 integration；integrated 因而表示“整合的、融为一体的”。","originQuery":"integrated","page":11},{"id":"p12r07a","word":"prejudicial","pair":"tendentious","meaning":"有偏见的","origin":"Prejudicial 在这里与“有偏见”相连，是因为 prejudice 的字面概念是“预先作出判断”。它来自拉丁语 praeiudicium：prae-“在前”，iudicium“判断”。没有充分了解事实便先下结论，容易形成偏见；prejudicial 更常严格表示“造成损害的”，具体含义需按语境区分。","originQuery":"prejudicial","page":11},{"id":"p12r07b","word":"tendentious","pair":"prejudicial","meaning":"有偏见的","origin":"Tendentious 意思是“有偏见的”，是因为它表示内容带有明显 tendency“倾向”，而不是中立呈现。它经德语 tendenziös 形成，根源与拉丁语 tendere“伸向、趋向”有关。论述若刻意朝某一立场推进，就带有导向性，因此 tendentious 指“倾向性强、偏颇的”。","originQuery":"tendentious","page":11},{"id":"p12r08a","word":"slippery","pair":"elusive","meaning":"难以捉摸","origin":"Slippery 意思是“难以捉摸”，是因为它本义是“容易滑走的”。它来自古英语 slipor“滑的”，与 slip“滑动、溜走”同族；-y 表示具有这种性质。光滑物体抓不牢，会从手中溜掉；这个形象用于问题、概念或人，便表示难以界定、难以抓住或不可信。","originQuery":"slippery","page":11},{"id":"p12r08b","word":"elusive","pair":"slippery","meaning":"难以捉摸","origin":"Elusive 意思是“难以捉摸”，是因为 elude 的拉丁语字面义是“玩弄着逃开”。它来自 eludere：e-/ex-“出去”，ludere“玩”；-ive 表示具有这种性质。目标仿佛在游戏中不断闪避，使人抓不到或理解不了，因此 elusive 表示“难以捕捉、难以理解的”。","originQuery":"elusive","page":11},{"id":"p12r09a","word":"restorative","pair":"tonic","meaning":"滋补的","origin":"Restorative 意思是“滋补、恢复健康的”，是因为 restore 表示“使重新站立、恢复原状”。它来自拉丁语 restaurare“重建、恢复”，含 re-“再次”的概念；-ative 表示具有作用。能让虚弱身体恢复力量的食物或药物，就是 restorative，因此可作形容词“滋补的”或名词“恢复剂”。","originQuery":"restorative","page":11},{"id":"p12r09b","word":"tonic","pair":"restorative","meaning":"滋补的","origin":"Tonic 意思是“滋补的”，是因为它原来与身体或肌肉的“张力”有关。它来自希腊语 tonikos“伸展、紧张的”，核心 tonos 是“拉紧、张力”。能提高身体张力和活力的药剂被称为 tonic，后来泛指使人恢复精神、强健身体的滋补品。","originQuery":"tonic","page":11},{"id":"p12r10a","word":"exhaustive","pair":"comprehensive","meaning":"详尽的","origin":"Exhaustive 意思是“详尽的”，是因为 exhaust 的字面图景是“把里面的东西彻底汲取出来”。它来自拉丁语 exhaurire：ex-“向外、彻底”，haurire“汲取”。讨论若把所有资料和可能性都取尽，不留遗漏，就达到 exhaustive 的程度，因此是“全面详尽的”。","originQuery":"exhaustive","page":11},{"id":"p12r10b","word":"comprehensive","pair":"exhaustive","meaning":"详尽的","origin":"Comprehensive 意思是“详尽、全面的”，是因为 comprehend 的拉丁语字面义是“共同抓住、全部包含”。它来自 comprehendere：com-“一起、完全”，prehendere“抓住”。能把主题的各个部分都纳入掌握范围，就是 comprehensive，因此既可指内容覆盖全面，也可指理解力广。","originQuery":"comprehensive","page":11},{"id":"p13r01a","word":"yield","pair":"engender","meaning":"产生","origin":"Yield 意思是“产生”，是因为它早期有“支付、交付应得之物”的意思。它来自古英语 gieldan“偿付、给予”，与 geld“钱、报酬”同源。土地把收成交给耕作者，投资把回报交给投资者，于是 yield 发展为“出产、产生”；作名词也可指产量或收益。","originQuery":"yield","page":12},{"id":"p13r01b","word":"engender","pair":"yield","meaning":"产生","origin":"Engender 意思是“产生”，是因为它原本表示“生育、使出生”。它经古法语 engendrer 来自拉丁语 ingenerare，与 genus“种类、出生”相关，en-/in- 表示“使进入某状态”。由产生生命扩大到产生思想、情绪或结果，因此 engender 就是“引起、造成”。","originQuery":"engender","page":12},{"id":"p13r02a","word":"robust","pair":"strong","meaning":"健壮","origin":"Robust 意思是“健壮”，是因为拉丁语 robustus 原指“像橡木一样坚硬强壮”。它来自 robur“橡木、力量”，可能与 ruber“红色”相关，因为某些橡木心材呈红色。橡木坚实耐久的形象转用于身体和系统，便表示强健、结实且不易损坏。","originQuery":"robust","page":12},{"id":"p13r02b","word":"strong","pair":"robust","meaning":"健壮","origin":"Strong 意思是“健壮”，是因为它从古英语 strang 起就表示“有力量、坚固”。该词属于日耳曼语族，与德语 streng 等相关。能承受压力、不易被破坏的人或物就是 strong；用于身体时强调肌肉和体质有力，因此自然对应“强壮、健壮”。","originQuery":"strong","page":12},{"id":"p13r03a","word":"persistence","pair":"survival","meaning":"坚持不懈","origin":"Persistence 意思是“坚持不懈”，是因为 persist 的拉丁语字面图景是“始终站住”。它来自 persistere：per-“一直、彻底”，sistere“站立、使停住”；-ence 表示状态。面对阻力仍站在原处、不放弃，就表现为持续努力，因此 persistence 是“坚持、持久性”。","originQuery":"persistence","page":12},{"id":"p13r03b","word":"survival","pair":"persistence","meaning":"坚持不懈","origin":"Survival 在这里与“坚持不懈”相连，是因为 survive 的字面义是“活过某个事件之后”。它来自拉丁语 supervivere：super-“超过、在……之后”，vivere“活”。经历困难仍继续存在，需要持续坚持；因此 survival 本义是“生存、幸存”，语境中可突出顽强维持下去的能力。","originQuery":"survival","page":12},{"id":"p13r04a","word":"intelligible","pair":"readable","meaning":"可理解的","origin":"Intelligible 意思是“可理解的”，是因为它来自拉丁语 intelligibilis“能够被认识的”。核心 intelligere 可理解为“在事物之间作选择、辨认”，由 inter-“在……之间”与 legere“选择、读”构成；-ible 表示“能够被……”。能被头脑辨认清楚的内容，就是可理解的。","originQuery":"intelligible","page":12},{"id":"p13r04b","word":"readable","pair":"intelligible","meaning":"可理解的","origin":"Readable 意思是“可理解的”，是因为它由 read“阅读”与 -able“能够被……”构成，字面是“能够读下去的”。文字不仅要看得清，还要在语言和结构上容易理解；因此 readable 除“字迹清楚”外，也常指文章通顺易懂、适合阅读。","originQuery":"readable","page":12},{"id":"p13r05a","word":"abused","pair":"misused","meaning":"误用","origin":"Abused 在这里意思是“被误用”，是因为 abuse 的拉丁语核心是“偏离正当用途地使用”。它来自 abuti：ab-“离开、偏离”，uti“使用”。使用方式离开正常界限，就成为滥用或误用；若对象是人，则可进一步表示虐待。abused 是其过去式或过去分词。","originQuery":"abuse","page":12},{"id":"p13r05b","word":"misused","pair":"abused","meaning":"误用","origin":"Misused 意思是“误用”，是因为它由 mis-“错误地、不当地”与 use“使用”构成。mis- 明确指出动作偏离正确方式，所以 misuse 不是普通使用，而是把词语、工具或权力用错地方或用得不当；misused 表示“被错误使用或滥用的”。","originQuery":"misuse","page":12},{"id":"p13r06a","word":"insufficient","pair":"meager","meaning":"不足","origin":"Insufficient 意思是“不足”，是因为它由 in-“不”和 sufficient“足够的”构成。sufficient 来自拉丁语 sufficere“供给到足够程度”，由 sub-“从下、达到”与 facere“做、提供”相关成分构成。所提供的数量若达不到需要，就是 insufficient，即“不充分、不足够”。","originQuery":"insufficient","page":12},{"id":"p13r06b","word":"meager","pair":"insufficient","meaning":"不足","origin":"Meager 意思是“不足、贫乏”，是因为它原本形容人或动物“瘦削、没有肉”。它经古法语 megre 来自拉丁语 macer“瘦的”。由身体缺少充足养分，词义扩展到食物、收入、证据等数量少得可怜，因此 meager 表示“微薄、贫乏的”。","originQuery":"meager","page":12},{"id":"p13r07a","word":"mockery","pair":"derision","meaning":"嘲笑","origin":"Mockery 意思是“嘲笑”，是因为它来自 mock“模仿并取笑”加名词后缀 -ery。mock 经古法语 moquer 进入英语，更早来源不确定。以夸张方式模仿某人的言行，会使其显得可笑，于是 mockery 表示“嘲弄”；也可指对理想标准的可笑仿制品。","originQuery":"mockery","page":12},{"id":"p13r07b","word":"derision","pair":"mockery","meaning":"嘲笑","origin":"Derision 意思是“嘲笑”，是因为其拉丁语核心是“带着贬低意味地笑”。它来自 deridere：de- 可含“向下、贬低”，ridere“笑”；-ion 表示行为。可以理解为把别人往下压着笑，由此形成轻蔑的嘲弄；同源词 deride 是“嘲弄”，derisive 是“嘲弄的”。","originQuery":"derision","page":12},{"id":"p13r08a","word":"anonymous","pair":"obscure","meaning":"不出名的","origin":"Anonymous 意思是“不出名的”，是因为它的希腊语构词就是“没有名字”。an-“没有”，onyma/onoma“名字”，-ous 构成形容词。没有署名的人或作品无法凭姓名被识别，因此 anonymous 首先是“匿名的”；一个人若不为公众所知，也可由此表示“籍籍无名的”。","originQuery":"anonymous","page":12},{"id":"p13r08b","word":"obscure","pair":"anonymous","meaning":"不出名的","origin":"Obscure 意思是“不出名的”，是因为它本义是“昏暗、被遮住而看不清”。它来自拉丁语 obscurus“黑暗的、隐蔽的”。处在暗处的事物不会引人注意，也不容易被认识；因此 obscure 从视觉上的“模糊”扩展为知识上的“晦涩”和名声上的“默默无闻”。","originQuery":"obscure","page":12},{"id":"p13r09a","word":"feigned","pair":"false","meaning":"虚假的","origin":"Feigned 意思是“虚假的”，是因为 feign 的拉丁语核心是“塑造、捏出一个形象”。它经古法语 feindre 来自拉丁语 fingere“塑造、虚构”，与 fiction 同源。人为塑造出的感情或借口并非自然真实，因此 feign 表示“假装”，feigned 就是“伪装的、虚假的”。","originQuery":"feign","page":12},{"id":"p13r09b","word":"false","pair":"feigned","meaning":"虚假的","origin":"False 意思是“虚假的”，是因为它从古法语 fals 和拉丁语 falsus 继承了“受骗、错误”的含义。falsus 是 fallere“欺骗、使误判”的过去分词。会把人引向错误判断的陈述或外表不符合事实，因此 false 表示“不真实的、伪造的”。","originQuery":"false","page":12},{"id":"p13r10a","word":"hierarchical","pair":"stratified","meaning":"分层的","origin":"Hierarchical 意思是“分层的”，是因为 hierarchy 原指教会中按神圣权力排列的等级。它最终来自希腊语 hieros“神圣的”与 arkhein“统治”，-ical 构成形容词。由宗教权力层级扩展到任何从上到下分级组织的体系，因此 hierarchical 就是“等级分层的”。","originQuery":"hierarchical","page":12},{"id":"p13r10b","word":"stratified","pair":"hierarchical","meaning":"分层的","origin":"Stratified 意思是“分层的”，是因为 stratum 在拉丁语中指“铺开的一层”，来自 sternere“铺展”。stratify 由 stratum 加表示“使成为”的 -fy 构成，即“使形成层次”。岩石、社会或数据若像铺叠的层一样按级别排列，就是 stratified。","originQuery":"stratify","page":12},{"id":"p14r01a","word":"meticulous","pair":"thorough","meaning":"一丝不苟","origin":"Meticulous 意思是“一丝不苟”，是因为它最初表示因害怕出错而过分小心。它来自拉丁语 meticulosus“胆怯、恐惧的”，核心 metus 是“恐惧”。害怕遗漏任何细节，会促使人反复检查；词义后来由贬义的“过分谨慎”转为褒义的“极其细致”。","originQuery":"meticulous","page":13},{"id":"p14r01b","word":"thorough","pair":"meticulous","meaning":"一丝不苟","origin":"Thorough 意思是“一丝不苟、彻底的”，是因为它与 through“穿过、从头到尾”同源，来自古英语 þurh。做事若从开头贯穿到结尾，每一处都检查，不留下空缺，就是 thorough。它强调覆盖完整，因此在形容工作态度时可译为“周密、一丝不苟”。","originQuery":"thorough","page":13},{"id":"p14r02a","word":"purposefulness","pair":"design","meaning":"有目的性","origin":"Purposefulness 意思是“有目的性”，是因为它由 purpose“目的”、-ful“具有……”和 -ness“状态”构成。purpose 经古法语来自拉丁语 proponere“提出、置于前面”。把目标摆在前方并让行动朝它推进，就显得有明确意图，因此 purposefulness 指“目标明确、行动有目的”。","originQuery":"purposeful","page":13},{"id":"p14r02b","word":"design","pair":"purposefulness","meaning":"有目的性","origin":"Design 意思是“有目的的安排”，是因为它的拉丁语核心是“标记出来、预先规划”。它来自 designare：de- 有强调作用，signare“作标记”，与 sign 同源。先在头脑或图纸上标出将要完成的结构，说明结果并非偶然，于是 design 可指“设计、意图、目的”。","originQuery":"design","page":13},{"id":"p14r03a","word":"underwritten","pair":"endorsed","meaning":"支持","origin":"Underwritten 意思是“受到支持、担保”，是因为 underwrite 的字面构词是“在下面签字”。早期承保人会在风险说明下方写上姓名和愿意承担的份额。签名意味着为交易提供财务保证，因此 underwrite 从“署名承保”扩展为资助、保证；underwritten 即“由……支持的”。","originQuery":"underwritten","page":13},{"id":"p14r03b","word":"endorsed","pair":"underwritten","meaning":"支持","origin":"Endorsed 意思是“支持”，是因为 endorse 原本表示“在文件背面书写”。它来自中世纪拉丁语 indorsare：in-“在……上”，dorsum“背部”。在票据背面签名意味着确认或转让，后来发展为公开认可某人或观点；因此 endorsed 表示“得到认可、支持的”。","originQuery":"endorse","page":13},{"id":"p14r04a","word":"itinerant","pair":"peripatetic","meaning":"四处游历的","origin":"Itinerant 意思是“四处游历的”，是因为它直接来自表示“旅行”的拉丁语。晚期拉丁语 itinerari 意为“旅行”，核心 iter、itineris 是“旅程、道路”；-ant 表示从事动作的人或性质。没有固定地点而沿路线不断移动的人，就是 itinerant，如巡回工人或游方传教者。","originQuery":"itinerant","page":13},{"id":"p14r04b","word":"peripatetic","pair":"itinerant","meaning":"四处游历的","origin":"Peripatetic 意思是“四处游历的”，是因为希腊语 peripatein 表示“来回行走”：peri-“周围”，patein“走”。该词先指亚里士多德的逍遥学派，传统上与边走边讲学联系。后来离开哲学专名，泛指从一地走到另一地、没有固定居所或工作地点。","originQuery":"peripatetic","page":13},{"id":"p14r05a","word":"spurious","pair":"specious","meaning":"虚假的","origin":"Spurious 意思是“虚假的”，是因为拉丁语 spurius 原本表示“非婚生的、血统不正的”。由无法证明正统来源，词义扩展到事物的出处或真实性可疑。一个论据、作品或关联若冒充真实却来路不正，就叫 spurious，即“伪造的、貌似真实的”。","originQuery":"spurious","page":13},{"id":"p14r05b","word":"specious","pair":"spurious","meaning":"虚假的","origin":"Specious 意思是“虚假的”，是因为它原本不是“假”，而是“外表好看”。它来自拉丁语 speciosus“美观的”，与 species“外观”和 specere“看”有关。某个论点表面漂亮、看似有理，却经不起细查，就会以外观欺骗判断，因此 specious 发展为“似是而非的”。","originQuery":"specious","page":13},{"id":"p14r06a","word":"dispassionately","pair":"analytically","meaning":"冷静客观地","origin":"Dispassionately 意思是“冷静客观地”，是因为 dispassionate 表示“不受强烈感情支配”。dis- 有去除之意，passion 来自拉丁语 pati“承受、感受”；-ly 构成副词。把愤怒、偏爱等情绪暂时放开后再判断，就是以不偏不倚的方式进行，因此是“冷静客观地”。","originQuery":"dispassionate","page":13},{"id":"p14r06b","word":"analytically","pair":"dispassionately","meaning":"冷静客观地","origin":"Analytically 意思是“冷静客观地分析”，是因为 analysis 的希腊语字面义是“拆开、解开”。ana-“向上、分开”，lysis 来自 lyein“松开”；analytic 表示把整体分成部分考察。按组成和逻辑逐项判断，而非凭情绪反应，就是 analytically 的思考方式。","originQuery":"analytical","page":13},{"id":"p14r07a","word":"obtrusive","pair":"conspicuous","meaning":"显眼","origin":"Obtrusive 意思是“显眼、扎眼的”，是因为 obtrude 的拉丁语字面义是“向前强推”。它来自 obtrudere：ob-“朝向、在前”，trudere“推、挤”；-ive 表示具有这种性质。某物强行挤进视线或注意力，令人无法忽略，就显得突兀、过分显眼。","originQuery":"obtrusive","page":13},{"id":"p14r07b","word":"conspicuous","pair":"obtrusive","meaning":"显眼","origin":"Conspicuous 意思是“显眼”，是因为它来自拉丁语 conspicuus“清楚可见的”，与 conspicere“注视”有关：con-“共同、完全”，specere“看”。能被众人清楚看见、一下吸引视线的事物，就是 conspicuous，因此表示“明显、引人注目的”。","originQuery":"conspicuous","page":13},{"id":"p14r08a","word":"sound","pair":"unassailable","meaning":"可靠的","origin":"Sound 意思是“可靠的”，这里并非“声音”那个来源，而与“健康、完整”有关。这个形容词来自古英语 sund“健全、没有损伤的”。物体结构完整就牢固，人的判断没有缺陷就可信；因此 sound 可由“健康完好”扩展为“稳妥、可靠”，如 sound evidence。","originQuery":"sound","page":13},{"id":"p14r08b","word":"unassailable","pair":"sound","meaning":"可靠的","origin":"Unassailable 意思是“可靠、无可反驳的”，是因为它由 un-“不能”、assail“攻击”与 -able“可被……”构成。assail 最终来自拉丁语 assilire“跃向、攻击”。论证若坚固到无法攻破，就没有明显漏洞，因此 unassailable 表示“无懈可击、非常可靠的”。","originQuery":"unassailable","page":13},{"id":"p14r09a","word":"timely","pair":"opportune","meaning":"适时的","origin":"Timely 意思是“适时的”，是因为它由 time“时间”与 -ly“具有……性质的”构成，古英语 tīmlīc 已有“适合某一时间”的含义。在正确时间发生的行动既不早也不晚，往往能发挥最大作用，因此 timely 表示“及时的、时机恰当的”。","originQuery":"timely","page":13},{"id":"p14r09b","word":"opportune","pair":"timely","meaning":"适时的","origin":"Opportune 意思是“适时的”，是因为拉丁语 opportunus 原指风把船“带向港口”的有利状况，通常与 ob-“朝向”及 portus“港口”联系。顺风恰好帮助船进港，就是合适的时机；因此 opportune 发展为“时机有利、恰到好处的”。","originQuery":"opportune","page":13},{"id":"p14r10a","word":"obviate","pair":"displace","meaning":"排除取代","origin":"Obviate 意思是“排除、使不再需要”，是因为它来自拉丁语 obviare“迎面遇上、阻挡”，核心 obvius 是“在路上的”：ob-“面对”，via“道路”。提前迎上并处理一个困难，就能防止它发生；因此 obviate 表示通过措施消除需要或避免问题。","originQuery":"obviate","page":13},{"id":"p14r10b","word":"displace","pair":"obviate","meaning":"排除取代","origin":"Displace 意思是“排除、取代”，是因为它由 dis-“离开、移开”与 place“位置”构成。把某人或某物从原来的位置移走，就会留下空位，常由另一对象占据；因此 displace 既可指“使离开原处”，也可指新技术或人“替代”旧者。","originQuery":"displace","page":13},{"id":"p15r01a","word":"applauded","pair":"extolled","meaning":"称赞","origin":"Applauded 意思是“受到称赞”，是因为 applaud 的拉丁语字面动作是“朝某人拍手”。它来自 applaudere：ad-“向”，plaudere“拍打、鼓掌”；ad- 在 p 前同化为 ap-。观众拍手表示赞许，于是 applaud 从具体的鼓掌扩展为公开赞扬，applauded 即“被称赞的”。","originQuery":"applaud","page":14},{"id":"p15r01b","word":"extolled","pair":"applauded","meaning":"称赞","origin":"Extolled 意思是“受到称赞”，是因为 extoll 的拉丁语字面义是“高高举起”。它来自 extollere，含 ex-“向上”与 tollere“举起”。在言辞中把某人的优点和地位抬高，就是高度赞颂；因此 extol 比普通 praise 语气更强，extolled 是“被盛赞的”。","originQuery":"extoll","page":14},{"id":"p15r02a","word":"irresolution","pair":"vacillation","meaning":"优柔寡断","origin":"Irresolution 意思是“优柔寡断”，是因为它由 ir-“不”和 resolution“坚定决定”构成。resolution 来自 resolve“解决、定下”，其拉丁语根义是“解开”。问题若始终未被解开，意志就无法确定；因此 irresolution 表示迟迟不能下决心、在选择间摇摆的状态。","originQuery":"irresolution","page":14},{"id":"p15r02b","word":"vacillation","pair":"irresolution","meaning":"优柔寡断","origin":"Vacillation 意思是“优柔寡断”，是因为拉丁语 vacillare 原本表示“来回摇晃、踉跄”。-ation 表示动作或状态。身体一会儿倒向这边、一会儿倒向那边，转用于意志就是在不同选择间反复摆动、不能定下，因此 vacillation 指“动摇、犹豫不决”。","originQuery":"vacillation","page":14},{"id":"p15r03a","word":"scolding","pair":"admonishment","meaning":"责备","origin":"Scolding 意思是“责备”，是因为 scold 自中古英语起就指爱争吵、用尖锐言语斥责的人或行为。旧说曾把它与古诺斯语 skald“诗人”相连，但这一词源并不可靠，具体来源仍不确定。现代核心很明确：以愤怒、持续的言语训斥某人，scolding 即这种责骂。","originQuery":"scold","page":14},{"id":"p15r03b","word":"admonishment","pair":"scolding","meaning":"责备","origin":"Admonishment 意思是“责备、告诫”，是因为 admonish 的拉丁语核心是“使人想起、提醒”。它来自 admonere：ad-“向、加强”，monere“提醒、警告”；-ment 表示行为或结果。提醒某人注意错误时常带警告和批评语气，于是 admonishment 表示旨在纠正行为的责备。","originQuery":"admonishment","page":14},{"id":"p15r04a","word":"perspicacity","pair":"discernment","meaning":"洞察力","origin":"Perspicacity 意思是“洞察力”，是因为它的拉丁语核心是“看穿”。它来自 perspicax“眼光锐利的”，与 perspicere 有关：per-“穿过、彻底”，specere“看”；-ity 表示能力。能穿过表象看清内部关系的人，便有敏锐理解力，因此 perspicacity 就是“洞察力”。","originQuery":"perspicacity","page":14},{"id":"p15r04b","word":"discernment","pair":"perspicacity","meaning":"洞察力","origin":"Discernment 意思是“洞察力”，是因为 discern 原本表示“把混杂事物分开辨认”。它来自拉丁语 discernere：dis-“分开”，cernere“筛分、辨别”；-ment 表示能力或结果。能看出细微差别并作出正确判断，就是 discernment，因此兼有“辨别力”和“洞察力”。","originQuery":"discernment","page":14},{"id":"p15r05a","word":"contradict","pair":"gainsay","meaning":"否认","origin":"Contradict 意思是“否认、反驳”，是因为它的拉丁语构词就是“说相反的话”。contra-“反对、相反”，dicere“说”。当一个陈述与另一个陈述正面相反时，它就在否认后者的真实性；因此 contradict 表示“反驳、与……矛盾”，相关词 contradiction 是“矛盾”。","originQuery":"contradict","page":14},{"id":"p15r05b","word":"gainsay","pair":"contradict","meaning":"否认","origin":"Gainsay 意思是“否认、反驳”，是因为它由中古英语 gain-“反对、相逆”与 say“说”构成，字面就是“说反对的话”。这里的 gain 与现代“获得”无关。对一个说法明确说“不”或提出相反意见，便是 gainsay，因此常用于正式语体表示“否认、质疑”。","originQuery":"gainsay","page":14},{"id":"p15r06a","word":"inertia","pair":"stasis","meaning":"惰性","origin":"Inertia 意思是“惰性”，是因为拉丁语 inertia 表示“无技能、无活动”。它由 in-“无”与 ars“技艺、能力”相关的 iners 形成。缺少主动能力就保持不动；物理学借此指物体维持原有运动状态的性质，日常语境再比喻人或制度不愿改变的“惰性”。","originQuery":"inertia","page":14},{"id":"p15r06b","word":"stasis","pair":"inertia","meaning":"惰性","origin":"Stasis 意思是“停滞、惰性”，是因为它来自希腊语 stasis“站立、静止”，核心 histanai 是“使站立”。事物停在原处而不继续变化，就进入 stasis。医学中可指体液停滞，社会或思想语境中则指缺乏运动和发展，因此与“惰性”相连。","originQuery":"stasis","page":14},{"id":"p15r07a","word":"extract","pair":"ferret out","meaning":"寻找","origin":"Extract 在这里与“寻找并取出”相连，是因为它的拉丁语字面义是“向外拉”。它来自 extrahere：ex-“向外”，trahere“拉”；extractus 是过去分词。先从大量材料中定位所需内容，再把它拉出来，就是提取；因此 extract 更准确的核心是“抽取”，而寻找常是这一过程的一部分。","originQuery":"extract","page":14},{"id":"p15r07b","word":"ferret out","pair":"extract","meaning":"寻找","origin":"Ferret out 意思是“搜寻并找出”，是因为 ferret 原指钻入洞穴追赶兔子的雪貂。该动物名经古法语 furet 来自晚期拉丁语 furittus，可能与 fur“贼”有关。雪貂能钻进隐蔽处把猎物赶出来，于是 ferret out 比喻仔细搜索并揭出隐藏的信息。","originQuery":"ferret","page":14},{"id":"p15r08a","word":"capriciousness","pair":"volatility","meaning":"反复无常","origin":"Capriciousness 意思是“反复无常”，是因为 caprice 表示突然冒出的念头或任性变化。它经法语 caprice 来自意大利语 capriccio，早期可指惊跳、寒颤，具体更早来源有争议。像身体突然一颤般毫无预兆地改变想法，就是 capricious；-ness 表示这种无常状态。","originQuery":"capricious","page":14},{"id":"p15r08b","word":"volatility","pair":"capriciousness","meaning":"反复无常","origin":"Volatility 意思是“反复无常”，是因为 volatile 原本表示“会飞、容易飞散”。它来自拉丁语 volatilis，核心 volare 是“飞”。容易飞走的物质不稳定、迅速蒸发；这一性质后来用于价格、情绪或局势，表示剧烈而难预测地变化，volatility 即“不稳定性”。","originQuery":"volatility","page":14},{"id":"p15r09a","word":"skirt","pair":"circumvent","meaning":"避开","origin":"Skirt 意思是“避开”，是因为 skirt 原指衣服的下摆或边缘，后来也表示某一区域的外围。它来自古诺斯语 skyrta“衬衣”。沿着某物边缘走，而不穿过中心，就是 to skirt；这个空间动作进一步比喻回避问题、不正面处理，因此表示“绕开、避开”。","originQuery":"skirt","page":14},{"id":"p15r09b","word":"circumvent","pair":"skirt","meaning":"避开","origin":"Circumvent 意思是“避开”，是因为它来自拉丁语 circumvenire“从四周走来、包围”：circum-“环绕”，venire“来”。原先有围住并智胜对方之意，后来重点转到用办法绕过障碍或规则。因此 circumvent 常含有策略性“规避”的意味。","originQuery":"circumvent","page":14},{"id":"p15r10a","word":"opprobrium","pair":"disdain","meaning":"蔑视","origin":"Opprobrium 意思是“蔑视、耻辱”，是因为拉丁语 opprobrium 指公开的责难和羞辱。它与 ob-“朝向”及 probrum“可耻之事、责骂”有关。把耻辱当面加到某人身上，会使其遭受公众轻蔑；因此 opprobrium 既可指严厉谴责，也可指由此带来的恶名。","originQuery":"opprobrium","page":14},{"id":"p15r10b","word":"disdain","pair":"opprobrium","meaning":"蔑视","origin":"Disdain 意思是“蔑视”，是因为它的历史核心是“认为不值得”。它经古法语 desdeignier 来自拉丁语 dedignari，核心 dignus 是“值得的”，否定成分表示“不认为有价值”。把某人看作不配得到尊重，就产生轻视态度，因此 disdain 表示“鄙视、不屑”。","originQuery":"disdain","page":14},{"id":"p16r01a","word":"broached","pair":"proposed","meaning":"提出","origin":"Broached 意思是“提出”，是因为 broach 原指用尖锐工具刺穿酒桶、打开酒液。它经古法语 broche“尖物、烤肉叉”进入英语。把封闭的桶开口，后来被比喻为把尚未谈论的话题打开，因此 to broach a subject 就是首次提出某事，broached 是其过去式。","originQuery":"broach","page":15},{"id":"p16r01b","word":"proposed","pair":"broached","meaning":"提出","origin":"Proposed 意思是“提出”，是因为 propose 的拉丁语构词就是“放到前面”。它经古法语 proposer，与拉丁语 proponere 有关：pro-“向前”，ponere“放置”。把一个计划或观点摆到众人面前供考虑，就是“提议、提出”；proposed 表示“已提出的、建议的”。","originQuery":"propose","page":15},{"id":"p16r02a","word":"antipathetic","pair":"inconsistent","meaning":"与不相容","origin":"Antipathetic 意思是“与……不相容、反感的”，是因为 antipathy 的希腊语构词是“相反的感受”。anti-“反对”，pathos“感受、遭遇”，-etic 构成形容词。两种性质彼此排斥，或一个人对某事有强烈反感，就可称为 antipathetic，因此含“不相容、抵触”。","originQuery":"antipathetic","page":15},{"id":"p16r02b","word":"inconsistent","pair":"antipathetic","meaning":"与不相容","origin":"Inconsistent 意思是“与……不相容”，是因为它由 in-“不”和 consistent“能共同成立的”构成。consistent 来自拉丁语 consistere“共同站立、保持”。两个说法若不能在逻辑上一起站住，彼此就矛盾、不相容；因此 inconsistent with 表示“与……不一致”。","originQuery":"inconsistent","page":15},{"id":"p16r03a","word":"lambasted","pair":"excoriated","meaning":"严厉批评","origin":"Lambasted 意思是“受到严厉批评”，是因为 lambast 原先表示“狠打、痛打”，后来转为猛烈的言语攻击。该词来源并不确定，通常认为可能受 lam“打”和 baste“痛打”影响，不宜视为确定构词。批评像一顿痛打般强烈，便是 lambast；lambasted 是其过去式。","originQuery":"lambaste","page":15},{"id":"p16r03b","word":"excoriated","pair":"lambasted","meaning":"严厉批评","origin":"Excoriated 意思是“受到严厉批评”，是因为 excoriate 的拉丁语字面义是“剥掉皮”。它来自 excoriare：ex-“去掉、向外”，corium“皮革、皮肤”。把人的皮剥下是极猛烈的伤害，这个形象转为言语上的严酷攻击，因此 excoriate 表示“痛斥、严厉批评”。","originQuery":"excoriate","page":15},{"id":"p16r04a","word":"homegrown","pair":"indigenous","meaning":"本土的","origin":"Homegrown 意思是“本土的”，是因为它由 home“本地、家乡”与 grown“生长出来的”构成，字面就是“在自家或本地种出来的”。词义从本地农产品扩展到本地培养的人才、思想或技术，强调不是从外地输入，因此表示“本土产生的”。","originQuery":"homegrown","page":15},{"id":"p16r04b","word":"indigenous","pair":"homegrown","meaning":"本土的","origin":"Indigenous 意思是“本土的”，是因为拉丁语 indigena 表示“在当地出生的人”。它通常分析为 indu“在……之内”与 gignere“生育、产生”相关成分。一个物种或群体若在某地自然产生、长期存在，而非后来引入，就是 indigenous，即“土生土长的、本土的”。","originQuery":"indigenous","page":15},{"id":"p16r05a","word":"unprecedented","pair":"novel","meaning":"前所未有的","origin":"Unprecedented 意思是“前所未有的”，是因为它由 un-“没有”和 precedent“先例”构成。precedent 来自拉丁语 praecedere“走在前面”，由 prae-“在前”与 cedere“走”组成。过去没有任何事情走在它前面作为先例，因此 unprecedented 就是“史无前例的”。","originQuery":"unprecedented","page":15},{"id":"p16r05b","word":"novel","pair":"unprecedented","meaning":"前所未有的","origin":"Novel 意思是“前所未有、新颖的”，是因为它来自拉丁语 novellus“新的、年轻的”，核心 novus 就是“新”。经古法语进入英语后，它形容新近出现、不同于旧有方式的事物。若一种方法此前从未出现，就同时具有 novel 的“新颖”和“前所未有”意味。","originQuery":"novel","page":15},{"id":"p16r06a","word":"supplemental","pair":"complementary","meaning":"补充的","origin":"Supplemental 意思是“补充的”，是因为 supplement 的拉丁语字面概念是“填满不足”。它来自 supplere“补足”：sub- 在 p 前同化为 sup-，plere“填满”；-ment 指补充物，-al 构成形容词。为已有内容加上缺少的部分，就是 supplemental。","originQuery":"supplemental","page":15},{"id":"p16r06b","word":"complementary","pair":"supplemental","meaning":"补充的","origin":"Complementary 意思是“补充的”，是因为 complement 原指“使整体完成的东西”。它来自拉丁语 complementum，核心 complere 是“填满、完成”：com-“完全”，plere“填”。两个部分各自补足对方的缺口，合起来成为完整整体，因此称为 complementary。不要与 complimentary“赞美的、免费的”混淆。","originQuery":"complementary","page":15},{"id":"p16r07a","word":"unexceptional","pair":"commonplace","meaning":"普通的","origin":"Unexceptional 意思是“普通的”，是因为它由 un-“不”和 exceptional“例外、出众的”构成。exception 最终来自拉丁语 excipere“取出、排除”；被从一般规则中取出的才是例外。没有被特别挑出来的事物就与多数同类一样，因此 unexceptional 表示“平常、不出众的”。","originQuery":"unexceptional","page":15},{"id":"p16r07b","word":"commonplace","pair":"unexceptional","meaning":"普通的","origin":"Commonplace 意思是“普通的”，是因为它原指众所周知、可通用的“共同论题”。该词仿自拉丁语 locus communis 和希腊语 koinos topos，字面都是“共同的地方”。人人都能想到、到处重复的说法缺少新意，于是 commonplace 发展为“平凡、司空见惯的”。","originQuery":"commonplace","page":15},{"id":"p16r08a","word":"demarcation","pair":"lines between","meaning":"界限","origin":"Demarcation 意思是“界限”，是因为 demarcate 表示“标出边界”。它经西班牙语 demarcar 进入英语，其中 de- 有明确划分的作用，marca 指“边界标记”，与 mark 相关；-ation 表示行为或结果。把两块区域分界线标清，所得结果就是 demarcation。","originQuery":"demarcation","page":15},{"id":"p16r08b","word":"lines between","pair":"demarcation","meaning":"界限","origin":"Lines between 意思是“……之间的界限”，是因为 line 原指拉紧的亚麻线或细绳。它来自拉丁语 linea“亚麻线”，与 linum“亚麻”有关。绷直的线可用来标记区域边缘，于是 line 从实体细线发展为抽象的分界；the line between A and B 就是两者界限。","originQuery":"lines","page":15},{"id":"p16r09a","word":"fanciful","pair":"chimerical","meaning":"异想天开的","origin":"Fanciful 意思是“异想天开的”，是因为 fancy 原本是 fantasy“想象”的缩短形式，-ful 表示“充满……的”。fantasy 来自希腊语 phantasia“显现、想象”。一个想法若主要由想象创造而非现实根据支撑，就显得奇异、不切实际，因此是 fanciful。","originQuery":"fanciful","page":15},{"id":"p16r09b","word":"chimerical","pair":"fanciful","meaning":"异想天开的","origin":"Chimerical 意思是“异想天开的”，是因为它来自 Chimera“奇美拉”。奇美拉是希腊神话中由狮、羊、蛇等部分组成的怪兽；这种拼合生物并不存在。于是 chimera 后来表示不现实的幻想，chimerical 就是“幻想的、荒诞而不切实际的”。","originQuery":"chimerical","page":15},{"id":"p16r10a","word":"intrinsic","pair":"inextricable","meaning":"本质的内在的","origin":"Intrinsic 意思是“本质的、内在的”，是因为它来自拉丁语 intrinsecus“在内侧、从内部”。核心 intra 表示“内部”。一种性质若不是外界附加，而是事物自身内部固有、构成本性的，就叫 intrinsic；它与 extrinsic“外在的、外加的”相对。","originQuery":"intrinsic","page":15},{"id":"p16r10b","word":"inextricable","pair":"intrinsic","meaning":"本质的内在的","origin":"Inextricable 的准确核心是“无法解开、无法分开的”，不是“本质的”。它来自拉丁语 inextricabilis：in-“不能”，extricare“解开纠缠”，后者与 tricae“纠葛、障碍”有关。线结缠得无法理清，便是 inextricable；抽象上指问题复杂难解或事物密不可分。","originQuery":"inextricable","page":15},{"id":"p17r01a","word":"enthralled","pair":"dazzled","meaning":"着迷于","origin":"Enthralled 意思是“着迷于”，是因为 enthrall 原本表示“使成为奴隶”。它由 en-“使进入”与 thrall“奴隶、受束缚者”构成，thrall 来自古诺斯语 þræll。一个人被某事吸引得仿佛失去自由、完全受其控制，就从实际奴役转成心理上的“迷住、吸引”。","originQuery":"enthrall","page":16},{"id":"p17r01b","word":"dazzled","pair":"enthralled","meaning":"着迷于","origin":"Dazzled 意思是“着迷、目眩”，是因为 dazzle 原指强光使人眼睛看不清。它可能来自中古英语 dasen“使昏迷、迷惑”，更早来源不确定。耀眼光芒会让人短暂失去判断，惊人魅力也能产生类似效果；因此 dazzled 可由“眼花”引申为“惊叹、着迷”。","originQuery":"dazzle","page":16},{"id":"p17r02a","word":"untenable","pair":"indefensible","meaning":"站不住脚的","origin":"Untenable 意思是“站不住脚的”，是因为它由 un-“不能”和 tenable“可守住、可维持的”构成。tenable 来自拉丁语 tenere“握住、保持”，-able 表示“能够被……”。一个阵地若守不住就必须放弃；同样，论点若无法抵御质疑，就不成立，因此是 untenable。","originQuery":"untenable","page":16},{"id":"p17r02b","word":"indefensible","pair":"untenable","meaning":"站不住脚的","origin":"Indefensible 意思是“站不住脚的”，是因为它由 in-“不能”和 defensible“可辩护的”构成。defend 来自拉丁语 defendere“挡开、保护”，-ible 表示“能够被……”。理由若无法挡住反驳、行为无法合理辩护，就像没有防线一样，因此是“无法辩解的”。","originQuery":"indefensible","page":16},{"id":"p17r03a","word":"plastic","pair":"pliable","meaning":"可塑的，适应性强的","origin":"Plastic 意思是“可塑、适应性强的”，是因为它在成为材料名称前就表示“能够被塑造成形”。它来自希腊语 plastikos，核心 plassein 是“塑造”。能随外力改变形态而不破坏，就具有可塑性；用于头脑、行为或制度时，便表示能适应新条件。","originQuery":"plastic","page":16},{"id":"p17r03b","word":"pliable","pair":"plastic","meaning":"可塑的，适应性强的","origin":"Pliable 意思是“可塑、适应性强的”，是因为它的核心动作是“折叠、弯曲”。它经古法语 ploiable 来自拉丁语 plicare“折、叠”，与 ply、apply 的部分词源相关；-able 表示“能够”。能弯而不断的材料容易塑形，这一性质转用于人或计划，就表示灵活易调整。","originQuery":"pliable","page":16},{"id":"p17r04a","word":"supplant","pair":"supersede","meaning":"取代","origin":"Supplant 意思是“取代”，是因为拉丁语 supplantare 原指“从下面绊倒”。它由 sub-“在下”与 planta“脚底”相关成分构成，sub- 在 p 前同化为 sup-。把对手绊倒后占据其位置，就是排挤替代；因此 supplant 带有新事物把旧事物赶走的意味。","originQuery":"supplant","page":16},{"id":"p17r04b","word":"supersede","pair":"supplant","meaning":"取代","origin":"Supersede 意思是“取代”，是因为它来自拉丁语 supersedere“坐在上方、停止”：super-“在上”，sedere“坐”。后来的事物居于旧事物之上，使旧者不再生效，于是词义发展为替代、废止。注意标准拼写是 supersede，不是常见误写 supercede。","originQuery":"supersede","page":16},{"id":"p17r05a","word":"private","pair":"insular","meaning":"孤立封闭","origin":"Private 意思是“孤立、封闭的”，是因为它来自拉丁语 privatus“从公共领域分离出来的”，核心 privare 表示“剥夺、使单独”。不属于公众共享范围的事物只供个人使用，于是 private 表示“私人的”；强调与外界隔开的场合，又可呈现封闭、不公开的意味。","originQuery":"private","page":16},{"id":"p17r05b","word":"insular","pair":"private","meaning":"孤立封闭","origin":"Insular 意思是“孤立封闭”，是因为它最初表示“岛屿的”。它来自拉丁语 insula“岛”，-ar 构成形容词。岛被水与大陆隔开，这个地理形象转用于群体或思想，便表示不与外界往来、只关心自身小范围，因此有“闭塞、狭隘”的含义。","originQuery":"insular","page":16},{"id":"p17r06a","word":"coherent","pair":"orderly","meaning":"连贯有序","origin":"Coherent 意思是“连贯有序”，是因为 cohere 的拉丁语字面义是“粘在一起”。它来自 cohaerere：co-“共同”，haerere“粘附”；-ent 表示状态。句子的各部分若像粘合成整体一样互相连接，逻辑就不会散乱，因此 coherent 表示“前后一致、连贯的”。","originQuery":"coherent","page":16},{"id":"p17r06b","word":"orderly","pair":"coherent","meaning":"连贯有序","origin":"Orderly 意思是“连贯有序”，是因为它由 order“次序、安排”与 -ly“具有……性质”构成。order 来自拉丁语 ordo“行列、等级”。事物按队列一样各居其位，就容易理解和管理；因此 orderly 形容安排整齐、过程有条理，而非杂乱无章。","originQuery":"orderly","page":16},{"id":"p17r07a","word":"manifest","pair":"self-evident","meaning":"不言自明","origin":"Manifest 意思是“不言自明”，是因为拉丁语 manifestus 表示“明显、可直接察觉的”。其更早构成有争议，常与 manus“手”和“抓住”相联系，可理解为清楚得仿佛能用手触到。事实若显而易见，无须再解释，因此 manifest 可译为“明显的、不言自明的”。","originQuery":"manifest","page":16},{"id":"p17r07b","word":"self-evident","pair":"manifest","meaning":"不言自明","origin":"Self-evident 意思是“不言自明”，是因为它由 self“自身”与 evident“清楚可见的”构成，即“凭自身就显出真实性”。evident 来自拉丁语 evidens，含 e-/ex-“向外”与 videre“看”。证据仿佛自己呈现在眼前，不依赖额外证明，所以是“不证自明的”。","originQuery":"evident","page":16},{"id":"p17r08a","word":"irascibility","pair":"exasperation","meaning":"易怒","origin":"Irascibility 意思是“易怒”，是因为 irascible 来自拉丁语 irasci“发怒”，而 ira 就是“愤怒”；-ibility 把这种倾向变成名词。一个人很容易进入愤怒状态、稍受刺激就发火，便具有 irascibility，因此它指“易怒的性情”。","originQuery":"irascibility","page":16},{"id":"p17r08b","word":"exasperation","pair":"irascibility","meaning":"易怒","origin":"Exasperation 意思是“恼怒、激怒状态”，是因为 exasperate 的拉丁语核心是“使变粗糙”。它来自 exasperare：ex- 有“使完全”之意，asper“粗糙、严厉”。反复刺激像把表面磨得更粗，令人越来越烦躁，因此 exasperation 是“恼怒、愤慨”，不是单纯的性格易怒。","originQuery":"exasperation","page":16},{"id":"p17r09a","word":"precarious","pair":"perilous","meaning":"危险的","origin":"Precarious 意思是“危险的”，是因为它最初指“靠请求获得、随时可被收回的”。它来自拉丁语 precarius，与 prex“祈求”有关。只凭他人恩准而存在的权利没有保障，处境很不稳定；由“不稳”进一步发展为容易失败或受伤的“危险、岌岌可危”。","originQuery":"precarious","page":16},{"id":"p17r09b","word":"perilous","pair":"precarious","meaning":"危险的","origin":"Perilous 意思是“危险的”，是因为它由 peril“危险”与 -ous“充满……的”构成。peril 经古法语 peril 来自拉丁语 periculum“试验、风险”。需要接受考验的处境可能带来伤害或失败，因此 peril 发展为危险；perilous 就是“充满危险的”。","originQuery":"perilous","page":16},{"id":"p17r10a","word":"augment","pair":"extend","meaning":"增加","origin":"Augment 意思是“增加”，是因为它来自拉丁语 augmentare“使增大”，核心 augere 就是“增长、使扩大”。同一词根也出现在 auction 的远源中，原含“增加出价”。给原有数量或力量再添一部分，使其变大，就是 augment，因此常用于正式语体表示“增强、扩充”。","originQuery":"augment","page":16},{"id":"p17r10b","word":"extend","pair":"augment","meaning":"增加","origin":"Extend 意思是“增加、扩展”，是因为它的拉丁语字面义是“向外拉长”。它来自 extendere：ex-“向外”，tendere“伸展”。物体被拉长会覆盖更大距离；时间、范围或能力也可用同一图景扩大，因此 extend 表示“延伸、延长”，在某些语境中即增加。","originQuery":"extend","page":16},{"id":"p18r01a","word":"rudimentary","pair":"sketchy","meaning":"粗略的","origin":"Rudimentary 意思是“粗略、初步的”，是因为 rudiment 原指学习或发展的最初阶段。它来自拉丁语 rudimentum“开端、初次尝试”，与 rudis“未经加工、生疏的”有关。处于起步阶段的东西尚未发展完整，只具基本轮廓，因此 rudimentary 可表示“初级的、粗略的”。","originQuery":"rudimentary","page":17},{"id":"p18r01b","word":"sketchy","pair":"rudimentary","meaning":"粗略的","origin":"Sketchy 意思是“粗略的”，是因为 sketch 原指快速勾出的素描轮廓，-y 表示具有这种性质。草图只抓住主要形状，省略大量细节；因此 sketchy 用于报告、计划或描述时，表示信息不完整、只是大概。它有时还引申为“不可靠、可疑”，需看语境。","originQuery":"sketchy","page":17},{"id":"p18r02a","word":"discerned","pair":"discovered","meaning":"被发现","origin":"Discerned 意思是“被发现、辨认出”，是因为 discern 的拉丁语核心是“分开辨别”。它来自 discernere：dis-“分开”，cernere“筛分、看清”。从混杂背景中把某个模式区分出来，就相当于察觉或发现它；discerned 因而表示“被看出、被识别”。","originQuery":"discern","page":17},{"id":"p18r02b","word":"discovered","pair":"discerned","meaning":"被发现","origin":"Discovered 意思是“被发现”，是因为 discover 的字面图景是“把覆盖物移开”。它经古法语 descovrir 来自晚期拉丁语 discooperire：dis-“去除”，cooperire“覆盖”。遮盖一旦揭开，原来隐藏的事物就显露出来，因此 discover 从“揭开”发展为“发现”。","originQuery":"discover","page":17},{"id":"p18r03a","word":"extirpated","pair":"eliminated","meaning":"根除","origin":"Extirpated 意思是“被根除”，是因为 extirpate 的拉丁语字面义就是“连根拔出”。它来自 exstirpare：ex-“向外、去除”，stirps“树干、根株”。植物连根拔掉便无法再生，这个动作转用于疾病、习俗或问题，表示彻底消灭；extirpated 是“已被根除的”。","originQuery":"extirpate","page":17},{"id":"p18r03b","word":"eliminated","pair":"extirpated","meaning":"根除","origin":"Eliminated 意思是“被根除、排除”，是因为 eliminate 的拉丁语核心是“赶出门槛”。它来自 eliminare，核心 limen 是“门槛”，e-/ex- 表示“向外”。把某物逐出门外，就是从范围中移除；后来词义扩大为删去、淘汰或彻底消除。","originQuery":"eliminate","page":17},{"id":"p18r04a","word":"anticipates","pair":"prefigures","meaning":"预示","origin":"Anticipates 意思是“预示”，是因为 anticipate 的拉丁语字面义是“提前取得”。它来自 anticipare：ante-“在前”，capere“拿、抓”。在事情到来前先抓住它，就是预先想到或行动；一个迹象若提前呈现后来的特征，也就“预示”将要发生的事。","originQuery":"anticipate","page":17},{"id":"p18r04b","word":"prefigures","pair":"anticipates","meaning":"预示","origin":"Prefigures 意思是“预示”，是因为 prefigure 的构词就是“预先呈现形象”。pre-“在前、预先”，figure 来自拉丁语 figura“形状、形象”。早期事件若先以某种形态展示后来事件的模式，就像提前画出轮廓，因此 prefigure 表示“预示、预兆”。","originQuery":"prefigure","page":17},{"id":"p18r05a","word":"unimpeachable","pair":"blameless","meaning":"无可指责的","origin":"Unimpeachable 意思是“无可指责的”，是因为它由 un-“不能”、impeach“质疑、控告”与 -able“可被……”构成。impeach 最终与晚期拉丁语 impedicare“缠住脚、阻碍”有关。品格或证据若找不到可攻击之处，就无法被控诉，因此是“无可非议、完全可靠的”。","originQuery":"unimpeachable","page":17},{"id":"p18r05b","word":"blameless","pair":"unimpeachable","meaning":"无可指责的","origin":"Blameless 意思是“无可指责的”，是因为它由 blame“责怪、过错”与 -less“没有……”直接构成。blame 经古法语 blasmer 来自拉丁语 blasphemare“责骂、亵渎”。一个人没有可归责的错误，就没有理由受到 blame，因此 blameless 表示“无过错的”。","originQuery":"blameless","page":17},{"id":"p18r06a","word":"prominence","pair":"salience","meaning":"显著性","origin":"Prominence 意思是“显著性”，是因为 prominent 的拉丁语图景是“向前突出”。它来自 prominere：pro-“向前”，minere“伸出、凸出”；-ence 表示状态。物体凸出于周围会首先进入视线，人物或议题在重要性上突出也同样引人注意，因此 prominence 指“显著、突出”。","originQuery":"prominence","page":17},{"id":"p18r06b","word":"salience","pair":"prominence","meaning":"显著性","origin":"Salience 意思是“显著性”，是因为 salient 的拉丁语核心是“跳出来”。它来自 salire“跳跃”，-ence 表示状态。某个特征仿佛从背景中跃出，最容易吸引注意，就具有 salience；因此该词表示信息或特征的“突出程度、显著性”。","originQuery":"salience","page":17},{"id":"p18r07a","word":"left","pair":"ceded","meaning":"让与","origin":"Left 在这里意思是“让与、留下”，来自 leave 的过去式，而不是“左边”的 left。leave 源自古英语 læfan“留下、遗留”。一个人离开时把财产留给别人，或主动让出某物，接受者就获得了它；因此 leave something to someone 可表示“把某物留给、交由”。","originQuery":"left","page":17},{"id":"p18r07b","word":"ceded","pair":"left","meaning":"让与","origin":"Ceded 意思是“让与”，是因为 cede 来自拉丁语 cedere“退让、让路”。一个人从位置退开，就把空间让给别人；用于权利、领土或控制权时，便是正式交出。ceded 是其过去式，表示某物已经被“割让、转让”。","originQuery":"cede","page":17},{"id":"p18r08a","word":"faultlessness","pair":"perfection","meaning":"完美","origin":"Faultlessness 意思是“完美”，是因为它由 fault“缺点、过错”、-less“没有”与 -ness“状态”构成，字面就是“没有缺陷的状态”。fault 经古法语 faute 来自拉丁语 fallere“失败、欺骗”相关形式。任何可挑出的错误都不存在，便达到无瑕、完美。","originQuery":"faultless","page":17},{"id":"p18r08b","word":"perfection","pair":"faultlessness","meaning":"完美","origin":"Perfection 意思是“完美”，是因为 perfect 的拉丁语字面义是“彻底做完”。它来自 perficere：per-“完全”，facere“做”；-ion 表示结果。事物被完成到无一处欠缺，就处于完整无瑕的状态，因此 perfection 从“完成”发展为“完美”。","originQuery":"perfection","page":17},{"id":"p18r09a","word":"confound","pair":"perplex","meaning":"使困惑","origin":"Confound 意思是“使困惑”，是因为它的拉丁语字面义是“把东西混在一起”。它来自 confundere：con-“共同、一起”，fundere“倒”。不同信息被倒进一处、界限混乱，人就无法分辨；因此 confound 由“混淆”发展为“使迷惑、使不知所措”。","originQuery":"confound","page":17},{"id":"p18r09b","word":"perplex","pair":"confound","meaning":"使困惑","origin":"Perplex 意思是“使困惑”，是因为拉丁语 perplexus 表示“彻底缠绕”。它由 per-“完全”与 plectere“编织、缠结”构成。线索像线团一样纠缠在一起，便难以理清；这个图景转用于头脑，就表示使人困惑、为难。","originQuery":"perplex","page":17},{"id":"p18r10a","word":"conform","pair":"square","meaning":"与……一致","origin":"Conform 意思是“与……一致”，是因为它的拉丁语字面义是“使具有同样形式”。它来自 conformare：con-“共同、相同”，forma“形状”。一个对象若改变自身形态以配合标准，就与标准相符；因此 conform to 表示“遵守、与……一致”。","originQuery":"conform","page":17},{"id":"p18r10b","word":"square","pair":"conform","meaning":"与……一致","origin":"Square 在这里意思是“与……一致”，是因为正方形的边角可用来检验物体是否端正。square 经古法语 esquire 来自通俗拉丁语 exquadra，与拉丁语 quattuor“四”相关。两项账目或说法若能“校成方正”、彼此吻合，就 square with，即“与……一致”。","originQuery":"square","page":17},{"id":"p19r01a","word":"intricate","pair":"convoluted","meaning":"复杂精细","origin":"Intricate 意思是“复杂精细”，是因为拉丁语 intricatus 表示“缠结在一起”。它来自 intricare“使纠缠”，与 tricae“纠葛、难题”有关。许多细线相互缠绕会形成难解而细密的结构；这个图景转用于设计、论证或情节，便表示细节众多、关系复杂。","originQuery":"intricate","page":18},{"id":"p19r01b","word":"convoluted","pair":"intricate","meaning":"复杂精细","origin":"Convoluted 意思是“复杂、盘绕的”，是因为它来自拉丁语 convolutus“卷在一起”。con-“共同、一起”，volvere“滚动、卷”；convoluted 是过去分词。多层东西卷叠在一起会难以理清，因此它从物理上的盘曲引申为思想、句子或过程过度复杂。","originQuery":"convoluted","page":18},{"id":"p19r02a","word":"brook","pair":"tolerate","meaning":"容忍","origin":"Brook 意思是“容忍”，这里是动词 brook，与名词“小溪”来源不同。动词来自古英语 brūcan“使用、享有、忍受”。能继续承受并与某事共处，就是容忍它；因此常见于否定结构 brook no opposition，表示“绝不容忍反对”。","originQuery":"brook","page":18},{"id":"p19r02b","word":"tolerate","pair":"brook","meaning":"容忍","origin":"Tolerate 意思是“容忍”，是因为它来自拉丁语 tolerare“承受、忍耐”，与表示“承担重量”的词根相关。面对不喜欢或困难的事仍把它承受下来，而不加阻止或反击，就是 tolerate。因此它既可指忍受痛苦，也可指允许不同意见存在。","originQuery":"tolerate","page":18},{"id":"p19r03a","word":"attenuating","pair":"dissipating","meaning":"减弱","origin":"Attenuating 意思是“减弱”，是因为 attenuate 的拉丁语字面义是“使变薄”。它来自 attenuare：ad-“使、向”，tenuis“薄的”；ad- 在 t 前同化为 at-。物体变薄，浓度或力量也随之降低，所以 attenuate 扩展为“削弱、稀释”，attenuating 即正在减弱。","originQuery":"attenuate","page":18},{"id":"p19r03b","word":"dissipating","pair":"attenuating","meaning":"减弱","origin":"Dissipating 意思是“减弱、消散”，是因为 dissipate 的拉丁语核心是“向四处分散”。它来自 dissipare：dis-“分开”，sipare 可能与“抛撒”有关。力量或云雾被散到各处后，局部浓度便降低直至消失，因此 dissipating 表示“正在消散、减弱”。","originQuery":"dissipate","page":18},{"id":"p19r04a","word":"senescence","pair":"decrepitude","meaning":"衰老","origin":"Senescence 意思是“衰老”，是因为它直接来自拉丁语 senescere“逐渐变老”。核心 senex 表示“老人”，-escence 表示“进入某种状态的过程”。年龄增长带来的机能退化就是 senescence，因此该词多用于生物学，强调衰老的过程而非单一时刻。","originQuery":"senescence","page":18},{"id":"p19r04b","word":"decrepitude","pair":"senescence","meaning":"衰老","origin":"Decrepitude 意思是“衰老、衰弱”，是因为它来自拉丁语 decrepitus“年老体弱的”。该词的更深来源不完全确定，古代解释曾把它与 crepare“发出裂响”联系，但不宜当作定论。核心语义一直是年老导致身体破败无力，因此表示衰老状态。","originQuery":"decrepitude","page":18},{"id":"p19r05a","word":"unconstrained","pair":"free","meaning":"不受限制","origin":"Unconstrained 意思是“不受限制”，是因为它由 un-“没有”与 constrained“被束缚的”构成。constrain 来自拉丁语 constringere“紧紧绑在一起”：con-“共同、加强”，stringere“拉紧、束住”。没有绳索般的规则或压力束缚，就能自由发展，因此是 unconstrained。","originQuery":"unconstrained","page":18},{"id":"p19r05b","word":"free","pair":"unconstrained","meaning":"不受限制","origin":"Free 意思是“不受限制”，是因为它从古英语 frēo 起就表示“不处于奴役中”。这个日耳曼词还与“亲爱、属于自己人”的概念相关：自由人是共同体的成员，不是被占有的奴隶。由没有人身束缚扩大到不受规则、障碍或费用限制，因此 free 有“自由的”。","originQuery":"free","page":18},{"id":"p19r06a","word":"coveted","pair":"enviable","meaning":"令人渴望的","origin":"Coveted 意思是“令人渴望的”，是因为 covet 表示强烈想拥有某物。它经古法语 coveitier 来自拉丁语 cupiditas“欲望”，与 cupid“爱神”及 cupere“渴望”同源。许多人争相想得到的对象便是 coveted，即“备受觊觎、令人渴望的”。","originQuery":"coveted","page":18},{"id":"p19r06b","word":"enviable","pair":"coveted","meaning":"令人渴望的","origin":"Enviable 意思是“令人渴望的”，是因为它表示“好到会引起别人 envy”。envy 经古法语 envie 来自拉丁语 invidia“嫉妒”，与 invidere“敌意地看”有关；-able 表示“足以引起”。某种处境优越到旁人羡慕，便是 enviable，即“令人羡慕、值得向往的”。","originQuery":"enviable","page":18},{"id":"p19r07a","word":"meager","pair":"paltry","meaning":"微不足道","origin":"Meager 意思是“微不足道、少得可怜”，是因为它原本形容“瘦得没有肉”。它经古法语 megre 来自拉丁语 macer“瘦的”。由身体缺少养分，词义扩展到收入、证据或成果数量贫乏；少到不足以产生分量，就显得微不足道。","originQuery":"meager","page":18},{"id":"p19r07b","word":"paltry","pair":"meager","meaning":"微不足道","origin":"Paltry 意思是“微不足道”，是因为它早期可指破烂、廉价而无价值的东西。该词可能与低地德语或荷兰语中表示“破布”的词有关，但具体来源不确定。由物品寒酸破旧，扩展到数量少、价值低或行为卑劣，因此常译为“微薄、可怜的”。","originQuery":"paltry","page":18},{"id":"p19r08a","word":"upheaval","pair":"convulsion","meaning":"剧变","origin":"Upheaval 意思是“剧变”，是因为它由 up“向上”与 heave“用力举起”相关形式构成，原指地面或物体被猛然抬起。大地被向上掀动会彻底改变原有形态；这个强烈图景转用于社会和生活，就表示秩序被打乱的大规模变动。","originQuery":"upheaval","page":18},{"id":"p19r08b","word":"convulsion","pair":"upheaval","meaning":"剧变","origin":"Convulsion 意思是“剧变”，是因为它原本指身体突然猛烈抽搐。它来自拉丁语 convellere“猛拉、撕扯”：con-“共同、强烈”，vellere“拉扯”；-ion 表示过程。社会若像身体痉挛一样被猛烈震动，就发生 convulsion，因此可指政治或经济剧变。","originQuery":"convulsion","page":18},{"id":"p19r09a","word":"puzzle","pair":"conundrum","meaning":"一个难题","origin":"Puzzle 意思是“难题”，是因为它先表示使人迷惑、陷入困境的状态或事物。该词在16世纪出现，更早来源不确定，可能与 pose“使困惑”有关，但无定论。凡是需要费力拼合线索、暂时找不到答案的问题，都可称为 a puzzle。","originQuery":"puzzle","page":18},{"id":"p19r09b","word":"conundrum","pair":"puzzle","meaning":"一个难题","origin":"Conundrum 意思是“难题”，是因为它从16世纪起就用于谜语、文字游戏和难解问题。旧词典有时给出伪拉丁形式，但其真正来源不明，因此不能按 con- 等现代成分强拆。由故意令人困惑的谜语，词义扩大为任何棘手、难以解决的问题。","originQuery":"conundrum","page":18},{"id":"p19r10a","word":"temperate","pair":"dispassionate","meaning":"克制的","origin":"Temperate 意思是“克制的”，是因为它来自拉丁语 temperatus“调节适度的”，核心 temperare 是“按比例混合、使适中”。不让欲望或情绪走向极端，而保持合宜尺度，就是 temperate；该词也用于气候，表示不过冷也不过热的“温和”。","originQuery":"temperate","page":18},{"id":"p19r10b","word":"dispassionate","pair":"temperate","meaning":"克制的","origin":"Dispassionate 意思是“克制、冷静的”，是因为它表示不受 passion“强烈感情”支配。dis- 有去除、离开之意，passion 最终与拉丁语 pati“承受、感受”有关。把强烈情绪从判断中拿开，就能保持客观，因此 dispassionate 指冷静而非冷漠。","originQuery":"dispassionate","page":18},{"id":"p20r01a","word":"honed","pair":"enhanced","meaning":"精炼完善","origin":"Honed 意思是“精炼完善”，是因为 hone 原指磨刀用的磨石，也可作动词“把刀刃磨利”。它来自古英语 hān“石头”，与古诺斯语 hein“磨石”相关。技能或论点经过反复打磨，会像刀刃一样更精确有效，因此 hone 引申为“磨炼、完善”。","originQuery":"hone","page":19},{"id":"p20r01b","word":"enhanced","pair":"honed","meaning":"精炼完善","origin":"Enhanced 意思是“改善、提高”，是因为 enhance 的历史核心是“抬高”。它经古法语 enhaucier 来自通俗拉丁语 *inaltiare，与 altus“高”有关。把事物往高处提升，就是增加其价值、质量或力量；因此 enhanced 表示“经过增强或改进的”。","originQuery":"enhance","page":19},{"id":"p20r02a","word":"shunning","pair":"eschewing","meaning":"刻意避开","origin":"Shunning 意思是“刻意避开”，是因为 shun 从古英语 scunian 起就有“躲开、避开”的含义，可能还与害怕或厌恶有关。它的更深来源并不确定。与偶然错过不同，shun 强调主动远离某人或某事，因此 shunning 是有意识地回避。","originQuery":"shun","page":19},{"id":"p20r02b","word":"eschewing","pair":"shunning","meaning":"刻意避开","origin":"Eschewing 意思是“刻意避开”，是因为 eschew 经古法语 eschiver 进入英语，早期就表示“躲避、远离”。其更早来源与日耳曼语中“害怕、避开”的词有关。因认为某物有害或不合原则而主动不用它，就是 eschew；eschewing 表示持续回避。","originQuery":"eschew","page":19},{"id":"p20r03a","word":"emendation","pair":"revision","meaning":"修订","origin":"Emendation 意思是“修订”，是因为 emend 的拉丁语字面概念是“去掉错误”。它来自 emendare，通常分析为 e-/ex-“去除”与 mendum“错误、缺陷”；-ation 表示动作或结果。把文本中的错处移除并改善内容，就是 emendation，尤用于校勘和文字修正。","originQuery":"emendation","page":19},{"id":"p20r03b","word":"revision","pair":"emendation","meaning":"修订","origin":"Revision 意思是“修订”，是因为 revise 的拉丁语字面义是“再次看”。它来自 revidere：re-“再”，videre“看”；-ion 表示过程。重新查看原稿时会发现错误并作修改，因此 revision 从“再检查”自然发展为“修订、修订稿”。","originQuery":"revision","page":19},{"id":"p20r04a","word":"wayward","pair":"errant","meaning":"任性的","origin":"Wayward 意思是“任性的”，是因为它在中古英语中带有“转离正路”的图景。其早期形式由表示“离开”的成分与 -ward“朝向”形成，不宜简单按现代 way 强拆。由方向上偏离应走的路，词义转为行为上不服管束、按自己性子行事。","originQuery":"wayward","page":19},{"id":"p20r04b","word":"errant","pair":"wayward","meaning":"任性的","origin":"Errant 意思是“任性、偏离正道的”，是因为它原本表示“游走、漫游”。它来自古法语 errant，是 errer“旅行、走错路”的现在分词，最终与拉丁语 errare“徘徊、犯错”有关。离开规定路线四处乱走，转用于行为便表示偏离规范、不受约束。","originQuery":"errant","page":19},{"id":"p20r05a","word":"unexceptional","pair":"nondescript","meaning":"平凡无奇","origin":"Unexceptional 意思是“平凡无奇”，是因为它由 un-“不”和 exceptional“例外、出众的”构成。exception 最终来自拉丁语 excipere“取出”；只有从一般同类中被特别挑出的才是例外。没有任何可使其例外的特点，就普通而不引人注意。","originQuery":"unexceptional","page":19},{"id":"p20r05b","word":"nondescript","pair":"unexceptional","meaning":"平凡无奇","origin":"Nondescript 意思是“平凡无奇”，是因为它原先指“无法归入已有描述或类别的”。它由 non-“不”与拉丁语 descriptus“被描述的”形成。后来重点转为外表没有鲜明特征，难以用一句话描述；因此 nondescript 常表示“毫不起眼、难以辨认的”。","originQuery":"nondescript","page":19},{"id":"p20r06a","word":"tantamount","pair":"synonymous","meaning":"等同于","origin":"Tantamount 意思是“等同于”，是因为它来自古法语短语 tant amonter“价值达到同样多”。tant 表示“这么多”，amonter 表示“总计、达到数额”。两件事在效果或价值上加总到相同程度，就彼此等同，因此 tantamount to 表示“实际上相当于”。","originQuery":"tantamount","page":19},{"id":"p20r06b","word":"synonymous","pair":"tantamount","meaning":"等同于","origin":"Synonymous 意思是“等同、同义的”，是因为 synonym 的希腊语构词是“共同名字”。syn-“共同、相同”，onyma/onoma“名字”；-ous 构成形容词。两个词若给同一概念起名，就是同义词；进一步说两件事 synonymous，表示它们意义或效果几乎等同。","originQuery":"synonymous","page":19},{"id":"p20r07a","word":"verbose","pair":"long-winded","meaning":"冗长啰嗦","origin":"Verbose 意思是“冗长啰嗦”，是因为拉丁语 verbosus 的构词就是“充满词语”。核心 verbum 表示“词、言语”，-osus 表示“多、充满”。表达中词很多却没有相应增加信息，就显得拖沓，因此 verbose 表示“多言而冗长的”。","originQuery":"verbose","page":19},{"id":"p20r07b","word":"long-winded","pair":"verbose","meaning":"冗长啰嗦","origin":"Long-winded 意思是“冗长啰嗦”，是因为它的字面图景是“气息很长”。wind 在旧用法中可指呼吸、气息；一个人仿佛一口气说个不停，就会说得过长。该复合词后来固定形容讲话或文章用词过多、迟迟不到重点。","originQuery":"long","page":19},{"id":"p20r08a","word":"painstakingly","pair":"meticulously","meaning":"一丝不苟地","origin":"Painstakingly 意思是“一丝不苟地”，是因为 painstaking 来自短语 take pains“费力、下苦功”，不是“制造痛苦”。pains 指付出的辛苦，taking 表示愿意承担；-ly 构成副词。肯为每个细节付出辛劳，做事自然格外仔细，因此是“一丝不苟地”。","originQuery":"painstaking","page":19},{"id":"p20r08b","word":"meticulously","pair":"painstakingly","meaning":"一丝不苟地","origin":"Meticulously 意思是“一丝不苟地”，是因为 meticulous 最初表示因害怕出错而过分小心。它来自拉丁语 meticulosus“胆怯的”，核心 metus 是“恐惧”；-ly 构成副词。小心到不放过任何细节，后来获得褒义，表示极其认真细致地。","originQuery":"meticulously","page":19},{"id":"p20r09a","word":"shrewd","pair":"canny","meaning":"精明","origin":"Shrewd 意思是“精明”，是因为它经历了从“恶毒、难对付”到“判断敏锐”的褒义化。它与 shrew“泼妇、鼩鼱”同族，中古英语早期可指邪恶或尖刻。一个难对付的人往往机警、善算计，于是词义逐渐转为有敏锐实际判断力的“精明”。","originQuery":"shrewd","page":19},{"id":"p20r09b","word":"canny","pair":"shrewd","meaning":"精明","origin":"Canny 意思是“精明”，是因为它来自苏格兰和英格兰北部用法，核心与 can“知道、会做”有关，早期有“懂得如何做、谨慎”的意思。知道分寸、善于处理实际事务的人显得机敏而可靠，因此 canny 发展为“精明谨慎的”，有时也含小心算计。","originQuery":"canny","page":19},{"id":"p20r10a","word":"pedigree","pair":"origin","meaning":"起源","origin":"Pedigree 意思是“起源、血统”，是因为它原指族谱图上像“鹤脚”的三叉标记。它来自法语 pied de grue“鹤的脚”，其中 pied 是“脚”，grue 是“鹤”。这种符号连接家族世代，后来整份家谱都称为 pedigree，于是表示血统和来源。","originQuery":"pedigree","page":19},{"id":"p20r10b","word":"origin","pair":"pedigree","meaning":"起源","origin":"Origin 意思是“起源”，是因为它来自拉丁语 origo“开端、来源”，与 oriri“升起、开始出现”有关。太阳从地平线升起是一天的开始，事物首次出现之处就是它的 origin；因此该词可指事件的开端、人的出身或某物的来源。","originQuery":"origin","page":19},{"id":"p21r01a","word":"distinct","pair":"idiosyncratic","meaning":"独特的","origin":"Distinct 意思是“独特、明显不同的”，是因为它来自拉丁语 distinctus“被分开、被标记的”。其动词 distinguere 含 dis-“分开”与 stinguere“刺、作标记”的概念。被清楚标出、与其他事物分开的对象具有自身特点，因此 distinct 表示“不同的、鲜明的”。","originQuery":"distinct","page":20},{"id":"p21r01b","word":"idiosyncratic","pair":"distinct","meaning":"独特的","origin":"Idiosyncratic 意思是“独特的”，是因为 idiosyncrasy 原指个人特有的体质或气质。它来自希腊语 idios“个人自己的”与 synkrasis“混合、性情”。每个人独有的“成分组合”会产生不同习惯和风格，因此 idiosyncratic 表示“个人特有、不同寻常的”。","originQuery":"idiosyncratic","page":20},{"id":"p21r02a","word":"purveyors","pair":"suppliers","meaning":"供应者","origin":"Purveyors 意思是“供应者”，是因为 purvey 原本表示预先备办、提供所需物资。它经古法语 porveoir 来自拉丁语 providere“预见、准备”：pro-“在前”，videre“看”。提前看见需要并备好货物的人，就是 purveyor；复数 purveyors 指供应商品、信息或观念的人。","originQuery":"purveyor","page":20},{"id":"p21r02b","word":"suppliers","pair":"purveyors","meaning":"供应者","origin":"Suppliers 意思是“供应者”，是因为 supply 的拉丁语核心是“把欠缺填满”。它经古法语 souploier 来自 supplere：sub- 在 p 前同化为 sup-，plere“填满”。为他人补上所需物资或服务，就是 supply；执行这一行为的人便是 supplier。","originQuery":"suppliers","page":20},{"id":"p21r03a","word":"inherent","pair":"intrinsic","meaning":"内在的","origin":"Inherent 意思是“内在的”，是因为 inhere 的拉丁语字面义是“粘在里面”。它来自 inhaerere：in-“在……内”，haerere“粘附”；-ent 表示状态。某种性质若紧密附着于事物本身，不能轻易分离，就不是外加的，而是 inherent，即“固有、内在的”。","originQuery":"inherent","page":20},{"id":"p21r03b","word":"intrinsic","pair":"inherent","meaning":"内在的","origin":"Intrinsic 意思是“内在的”，是因为它来自拉丁语 intrinsecus“在内部、从内侧”，核心 intra 表示“里面”。某种价值或性质若源自事物自身，而不是由环境、奖励或评价加上去，就是 intrinsic；它与 extrinsic“外在的”形成直接对照。","originQuery":"intrinsic","page":20},{"id":"p21r04a","word":"dampen","pair":"impede","meaning":"抑制","origin":"Dampen 意思是“抑制”，是因为它本来表示“弄湿、使潮湿”。damp 是“潮气、湿气”，-en 表示“使成为”。火焰或声音被湿气压低，会减弱而不再旺盛；这个物理效果转用于热情、希望或增长，就表示“使消沉、抑制”。","originQuery":"dampen","page":20},{"id":"p21r04b","word":"impede","pair":"dampen","meaning":"抑制","origin":"Impede 意思是“抑制、阻碍”，是因为拉丁语 impedire 原本表示“缠住脚”。它来自 in-“进入、使”与 pes/pedis“脚”相关成分。脚被束缚就无法顺利前进；因此 impede 从具体的绊脚扩展为使进程放慢或停止，即“妨碍、抑制”。","originQuery":"impede","page":20},{"id":"p21r05a","word":"fraud","pair":"duplicity","meaning":"欺骗","origin":"Fraud 意思是“欺骗”，是因为它从拉丁语 fraus、fraudis 起就表示“欺诈、诡计、损害”。该词更早来源不确定，不宜强行拆分。以虚假手段诱使别人交出财物或权利，就是 fraud；它既可指欺骗行为，也可指实施骗局的人。","originQuery":"fraud","page":20},{"id":"p21r05b","word":"duplicity","pair":"fraud","meaning":"欺骗","origin":"Duplicity 意思是“欺骗、口是心非”，是因为它的拉丁语核心是“双重”。它来自 duplicitas，核心 duplex“二重的”由 duo“二”与 plicare“折叠”相关成分构成。一个人表面一套、内心另一套，仿佛折成两层，因此 duplicity 表示“两面派、欺诈”。","originQuery":"duplicity","page":20},{"id":"p21r06a","word":"convey","pair":"impart","meaning":"传达","origin":"Convey 意思是“传达”，是因为它原本表示护送或把某物运到另一处。它经古法语 conveier、convoiier 进入英语，与 convoy“护送”同源。物品可以从甲地运到乙地，信息和感情也可以从一个人传到另一个人，因此 convey 发展为“表达、传达”。","originQuery":"convey","page":20},{"id":"p21r06b","word":"impart","pair":"convey","meaning":"传达","origin":"Impart 意思是“传达”，是因为它的拉丁语构词表示“分给一部分”。它来自 impartire：in-“进入、使”与 partire“分配”，核心 pars 是“部分”。把自己拥有的知识或消息分一份给别人，就是使对方也获得它，因此 impart 由“分配”发展为“告知、传授”。","originQuery":"impart","page":20},{"id":"p21r07a","word":"specious","pair":"deceptive","meaning":"似是而非的","origin":"Specious 意思是“似是而非的”，是因为它原本表示“外表漂亮”。它来自拉丁语 speciosus“美观的”，与 species“外观”和 specere“看”有关。一个论点看上去合理、很有吸引力，却隐藏逻辑错误，就会以外观欺骗判断，因此称为 specious。","originQuery":"specious","page":20},{"id":"p21r07b","word":"deceptive","pair":"specious","meaning":"似是而非的","origin":"Deceptive 意思是“似是而非、具有欺骗性的”，是因为 deceive 的拉丁语核心是“设陷阱抓住”。它来自 decipere：de- 与 capere“抓取”组合，表示诱骗、使落入圈套；-ive 表示具有这种作用。外观若引导人形成错误判断，就是 deceptive。","originQuery":"deceptive","page":20},{"id":"p21r08a","word":"fluid","pair":"mutable","meaning":"易变的","origin":"Fluid 意思是“易变的”，是因为它本义是“流动的”。它来自拉丁语 fluidus，与 fluere“流动”有关。液体没有固定形状，会随容器和外力改变；这个性质转用于局势、身份或计划，就表示尚未定型、可以迅速变化。","originQuery":"fluid","page":20},{"id":"p21r08b","word":"mutable","pair":"fluid","meaning":"易变的","origin":"Mutable 意思是“易变的”，是因为它来自拉丁语 mutabilis“能够改变的”，核心 mutare 表示“变化、更换”，-able 对应“可……的”。事物若没有固定不变的形式，容易从一种状态转到另一种，就是 mutable；反义词 immutable 是“不可改变的”。","originQuery":"mutable","page":20},{"id":"p21r09a","word":"splendor","pair":"sumptuousness","meaning":"奢华","origin":"Splendor 意思是“奢华”，是因为它本义是“耀眼的光辉”。它来自拉丁语 splendor“明亮、灿烂”，核心 splendere 是“闪耀”。富丽场面常以金光、珠宝和华丽装饰吸引目光，于是 splendor 从光亮扩展为壮丽、豪华的外观。","originQuery":"splendor","page":20},{"id":"p21r09b","word":"sumptuousness","pair":"splendor","meaning":"奢华","origin":"Sumptuousness 意思是“奢华”，是因为 sumptuous 的拉丁语核心与“花费”有关。它来自 sumptuosus“昂贵、铺张的”，核心 sumptus 是“费用、开支”；-ness 表示状态。需要大量花费才能形成的宴席或装饰通常华丽丰盛，因此 sumptuousness 就是“豪华、奢侈”。","originQuery":"sumptuous","page":20},{"id":"p22r01a","word":"overwhelming","pair":"irresistible","meaning":"无法抗拒的","origin":"Overwhelming 意思是“无法抗拒的”，是因为 overwhelm 原本表示把东西整个翻覆或淹没。over-“在上、彻底”，whelm 是“翻倒、覆盖”。巨浪从上方盖过船只，会使其完全失去抵抗能力；这个图景转用于力量、情绪或证据，就表示强大到压倒一切。","originQuery":"overwhelm","page":21},{"id":"p22r01b","word":"irresistible","pair":"overwhelming","meaning":"无法抗拒的","origin":"Irresistible 意思是“无法抗拒的”，是因为它由 ir-“不能”、resist“抵抗”与 -ible“可被……”构成。resist 来自拉丁语 resistere“站回来对抗”：re-“反向”，sistere“站立”。力量大到无法站住抵挡，或吸引力强到不能拒绝，就是 irresistible。","originQuery":"irresistible","page":21},{"id":"p22r02a","word":"saccharine","pair":"cloying","meaning":"过于甜腻","origin":"Saccharine 意思是“过于甜腻”，是因为它直接来自表示“糖”的词。它源于拉丁语 saccharum，经希腊语 sakkharon 可追溯到更东方的语言；-ine 构成形容词。由“含糖、甜的”进一步比喻言辞或感情甜得不自然，saccharine 因而常带贬义，表示“甜腻做作”。","originQuery":"saccharine","page":21},{"id":"p22r02b","word":"cloying","pair":"saccharine","meaning":"过于甜腻","origin":"Cloying 意思是“过于甜腻”，是因为 cloy 曾表示“用过量食物使人饱腻、厌烦”。它在中古英语中还可指堵塞或塞满，具体来源并不完全确定。甜食或情感一旦多到让人厌倦，就从愉快变成负担，因此 cloying 表示“甜得发腻、过分讨好”。","originQuery":"cloying","page":21},{"id":"p22r03a","word":"impatient","pair":"keen","meaning":"急切","origin":"Impatient 意思是“急切”，是因为它由 im-“不能”与 patient“耐心忍受的”构成。patient 来自拉丁语 pati“承受、忍耐”。一个人不能继续忍受等待，就急于立刻行动或得到结果；因此 impatient 既可表示“不耐烦”，也可在 impatient to do 中表示“迫切想做”。","originQuery":"impatient","page":21},{"id":"p22r03b","word":"keen","pair":"impatient","meaning":"急切","origin":"Keen 意思是“急切”，是因为它的早期核心是“锋利、勇猛、有力量”。它来自古英语 cēne“勇敢、强烈”，后来也形容刀刃锐利。欲望若像刀锋一样强而集中，就会表现为热切、迫切；因此 be keen to do 表示“急切想做”。","originQuery":"keen","page":21},{"id":"p22r04a","word":"essential","pair":"foundational","meaning":"基础的","origin":"Essential 意思是“基础的”，是因为它原本表示“属于事物本质的”。它来自晚期拉丁语 essentialis，核心 essentia“存在、本质”与 esse“是”有关。决定事物之所以成为它自己的要素最为根本，其他部分建立在其上，因此 essential 可指“根本的、必不可少的”。","originQuery":"essential","page":21},{"id":"p22r04b","word":"foundational","pair":"essential","meaning":"基础的","origin":"Foundational 意思是“基础的”，是因为它由 foundation“地基、基础”与 -al 构成。foundation 来自拉丁语 fundare“奠基”，核心 fundus 是“底部”。建筑的其余部分由地基承托，抽象体系也依靠基本原则建立，因此 foundational 表示“奠基性的、作为基础的”。","originQuery":"foundational","page":21},{"id":"p22r05a","word":"unassailable","pair":"airtight","meaning":"无懈可击","origin":"Unassailable 意思是“无懈可击”，是因为它由 un-“不能”、assail“攻击”与 -able“可被……”构成。assail 最终来自拉丁语 assilire“跃向、袭击”。论点或声誉若坚固到任何攻击都无法突破，就找不到漏洞，因此是“无可争辩、无懈可击的”。","originQuery":"unassailable","page":21},{"id":"p22r05b","word":"airtight","pair":"unassailable","meaning":"无懈可击","origin":"Airtight 意思是“无懈可击”，是因为它由 air“空气”与 tight“严密的”构成，字面是“连空气都透不过去”。容器没有缝隙就不会泄漏；论证若也找不到任何漏洞，就像密封容器一样，因此 airtight 可比喻“严密到无法反驳的”。","originQuery":"airtight","page":21},{"id":"p22r06a","word":"fictions","pair":"inventions","meaning":"虚构","origin":"Fictions 意思是“虚构”，是因为 fiction 的拉丁语核心是“塑造、捏造”。它来自 fictio，动词 fingere 表示“塑形、想象、编造”，与 feign 同源。作者在头脑中塑造不存在的人物和事件，便产生 fiction；在非文学语境中，它也可指人为编造的假象。","originQuery":"fiction","page":21},{"id":"p22r06b","word":"inventions","pair":"fictions","meaning":"虚构","origin":"Inventions 在这里意思是“虚构、编造物”，是因为 invent 的拉丁语字面义是“遇到、发现”。它来自 invenire：in-“进入、在……上”，venire“来”。头脑“找到”一个新构想就是发明；若找到的是为解释而造出的说法，invention 也可贬义表示“捏造、虚构”。","originQuery":"invention","page":21},{"id":"p22r07a","word":"reinforces","pair":"buttresses","meaning":"加强巩固","origin":"Reinforces 意思是“加强巩固”，是因为它由 re-“再次、进一步”与 inforce/enforce“使有力量”构成，核心 force 是“力量”。向已有结构再次加入力量或支援，就会使它更牢固；因此 reinforce 可用于建筑、军队、行为或观点，表示“强化”。","originQuery":"reinforce","page":21},{"id":"p22r07b","word":"buttresses","pair":"reinforces","meaning":"加强巩固","origin":"Buttresses 意思是“加强巩固”，是因为 buttress 原指支撑墙体的扶壁。它经古法语进入英语，尤其用于教堂外侧的承重结构。扶壁从旁边抵住墙，防止倾倒；因此 buttress 作动词时比喻用证据、资源或制度支撑并加强某物。","originQuery":"buttress","page":21},{"id":"p22r08a","word":"partitioning","pair":"segmenting","meaning":"分割","origin":"Partitioning 意思是“分割”，是因为 partition 来自拉丁语 partitio“划分、分配”，核心 partire 表示“分成部分”，与 part 同源。把一个整体划出若干独立部分，就是 partition；-ing 表示这一过程，因此可指空间、数据或资源的分区。","originQuery":"partition","page":21},{"id":"p22r08b","word":"segmenting","pair":"partitioning","meaning":"分割","origin":"Segmenting 意思是“分割”，是因为 segment 原指从整体上切下来的一段。它来自拉丁语 segmentum“切下的部分”，核心 secare 是“切”。把连续整体按边界切成若干段，就是 segment；segmenting 因而表示正在分段或划分。","originQuery":"segment","page":21},{"id":"p22r09a","word":"authoritative","pair":"definitive","meaning":"权威的","origin":"Authoritative 意思是“权威的”，是因为 authority 原指创始者或担保者所具有的分量。它来自拉丁语 auctoritas，核心 auctor“创始者、推动者”与 augere“使增长”有关。来自公认专家或正式权力的说法值得信赖和服从，因此称为 authoritative。","originQuery":"authoritative","page":21},{"id":"p22r09b","word":"definitive","pair":"authoritative","meaning":"权威的","origin":"Definitive 意思是“权威、定论性的”，是因为 define 的拉丁语字面义是“划定边界”。它来自 definire：de-“完全”，finis“界限、终点”；-ive 表示性质。一个答案若把问题边界彻底定清、不再留争议，就成为最终标准，因此 definitive 可指“最可靠、决定性的”。","originQuery":"definitive","page":21},{"id":"p23r01a","word":"influenced","pair":"informed","meaning":"受影响并被启发","origin":"Influenced 意思是“受影响并被启发”，是因为 influence 原指星辰之力“流入”人间。它来自拉丁语 influere“流入”：in-“进入”，fluere“流”。某种思想或人物的作用像水流进入他人头脑，改变其方向并激发创作，因此 influenced 表示“受到作用或启发”。","originQuery":"influence","page":22},{"id":"p23r01b","word":"informed","pair":"influenced","meaning":"受影响并被启发","origin":"Informed 在这里意思是“受影响、被赋予思想”，是因为 inform 的拉丁语字面义是“使具有形状”。它来自 informare：in-“进入、使”，forma“形状”。信息进入头脑会塑造认识；某种理念 inform a work，则从内部塑造其内容和风格。因此 informed by 可译为“受……影响或启发”。","originQuery":"informed","page":22},{"id":"p23r02a","word":"allied","pair":"conflated","meaning":"密切相关","origin":"Allied 意思是“密切相关”，是因为 ally 的拉丁语字面义是“绑在一起”。它经古法语 alier 来自 alligare：ad-“向”，ligare“捆绑”；ad- 在 l 前同化为 al-。被绑到同一阵线的双方就是盟友，概念或事物若联系紧密，也可称为 allied。","originQuery":"allied","page":22},{"id":"p23r02b","word":"conflated","pair":"allied","meaning":"密切相关","origin":"Conflated 更准确的意思是“被合并、混为一谈”，其拉丁语字面义是“一起吹铸”。它来自 conflare：con-“共同”，flare“吹”，原指把金属熔合或合成。两个原本不同的概念被并成一个，就 become conflated；这会使它们看似密切相关，却也可能造成混淆。","originQuery":"conflate","page":22},{"id":"p23r03a","word":"unprecedented","pair":"unique","meaning":"前所未有的","origin":"Unprecedented 意思是“前所未有的”，是因为它由 un-“没有”和 precedent“先例”构成。precedent 来自拉丁语 praecedere“走在前面”：prae-“在前”，cedere“走”。若过去没有任何事件走在它前面作为参照，它就没有先例，因此是“前所未有的”。","originQuery":"unprecedented","page":22},{"id":"p23r03b","word":"unique","pair":"unprecedented","meaning":"前所未有的","origin":"Unique 意思是“前所未有、独一无二的”，是因为它来自拉丁语 unicus“唯一的”，核心 unus 就是“一”。同类中只存在一个的事物没有可与之完全相比的旧例，因此 unique 首先表示“独特的”，语境中也可强调前所未见。","originQuery":"unique","page":22},{"id":"p23r04a","word":"abrogate","pair":"nullify","meaning":"废除","origin":"Abrogate 意思是“废除”，是因为拉丁语 abrogare 专指正式撤销法律。它由 ab-“离开、取消”与 rogare“提议、请求”构成；罗马法律中的 rogare 可指提案。把已经通过的法令反向取消，就是 abrogate，因此常用于废止法律、条约或权利。","originQuery":"abrogate","page":22},{"id":"p23r04b","word":"nullify","pair":"abrogate","meaning":"废除","origin":"Nullify 意思是“废除、使无效”，是因为它由 null“无、零”与 -ify“使成为”构成。null 来自拉丁语 nullus“一个也没有”，由 ne“不”与 ullus“任何一个”形成。把法律或效力变成“零”，就是取消其作用，因此 nullify 表示“使无效”。","originQuery":"nullify","page":22},{"id":"p23r05a","word":"distill","pair":"extract","meaning":"提炼","origin":"Distill 意思是“提炼”，是因为它原本描写液体一滴滴流下。它来自拉丁语 destillare：de-“向下”，stillare“滴落”，核心 stilla 是“水滴”。蒸馏时物质汽化后凝成滴液，从混合物中分离出精华；因此 distill 也比喻从复杂材料中提炼要点。","originQuery":"distill","page":22},{"id":"p23r05b","word":"extract","pair":"distill","meaning":"提炼","origin":"Extract 意思是“提炼、提取”，是因为它的拉丁语字面义是“向外拉”。它来自 extrahere：ex-“向外”，trahere“拉”。把有效成分从原料中拉出来，就是提取；把大量信息中的核心抽出来，也可称为 extract，因此与“提炼”相连。","originQuery":"extract","page":22},{"id":"p23r06a","word":"tedious","pair":"tiresome","meaning":"冗长乏味","origin":"Tedious 意思是“冗长乏味”，是因为它来自拉丁语 taediosus“令人厌烦的”，核心 taedium 是“厌倦、烦闷”。一项事情持续过久、重复而缺少变化，会令人产生这种厌倦，因此 tedious 常同时包含“耗时冗长”和“枯燥烦人”两层意思。","originQuery":"tedious","page":22},{"id":"p23r06b","word":"tiresome","pair":"tedious","meaning":"冗长乏味","origin":"Tiresome 意思是“冗长乏味”，是因为它由 tire“使疲倦、厌烦”与 -some“容易引起……”构成，字面就是“会使人疲倦的”。讲话或任务若拖得太长，让注意力耗尽，就会令人厌烦，因此 tiresome 表示“烦人的、令人疲惫的”。","originQuery":"tiresome","page":22},{"id":"p23r07a","word":"economy","pair":"concision","meaning":"简洁","origin":"Economy 意思是“简洁”，是因为它的核心是节约而有效地安排资源。它来自希腊语 oikonomia“家庭管理”：oikos“家”，nomos“管理、规则”。写作若像精打细算管理家庭一样，只用必要的词而不浪费，就具有 economy of expression，即“表达简洁”。","originQuery":"economy","page":22},{"id":"p23r07b","word":"concision","pair":"economy","meaning":"简洁","origin":"Concision 意思是“简洁”，是因为其拉丁语字面图景是“把多余部分切掉”。它来自 concidere“切除”：con- 有加强作用，caedere“切”；与 concise 同源。文章删去赘词后只保留核心，就变得短而有力，因此 concision 指“言简意赅”。","originQuery":"concision","page":22},{"id":"p23r08a","word":"antidote","pair":"corrective","meaning":"矫正手段","origin":"Antidote 意思是“矫正手段”，是因为它原指用来对抗毒物的药。它来自希腊语 antidoton“被给予来对抗之物”：anti-“对抗”，didonai“给予”。解毒剂抵消毒性、恢复正常；因此 antidote 后来比喻任何能抵消坏影响、纠正问题的方法。","originQuery":"antidote","page":22},{"id":"p23r08b","word":"corrective","pair":"antidote","meaning":"矫正手段","origin":"Corrective 意思是“矫正手段”，是因为 correct 的拉丁语字面义是“使直”。它来自 corrigere：com-“完全”，regere“引导、弄直”；-ive 表示具有作用。把偏离正轨的东西重新弄直，就是纠正，因此 a corrective 是能够修正错误或不平衡的措施。","originQuery":"corrective","page":22},{"id":"p23r09a","word":"capricious","pair":"cavalier","meaning":"反复无常的","origin":"Capricious 意思是“反复无常的”，是因为 caprice 指突然而任性的念头。它经法语来自意大利语 capriccio，早期可指惊跳或寒颤，更早来源有争议。想法像身体突然一颤般毫无预兆地改变，就显得任性难测，因此是 capricious。","originQuery":"capricious","page":22},{"id":"p23r09b","word":"cavalier","pair":"capricious","meaning":"反复无常的","origin":"Cavalier 在这里表示“漫不经心、任意的”，不严格等于“反复无常”。它来自意大利语 cavaliere“骑士、骑马者”，核心 cavallo“马”。骑士高高在上、姿态傲慢的刻板形象，使 cavalier 发展为“不把他人或后果当回事的”，从而显得随意轻率。","originQuery":"cavalier","page":22},{"id":"p23r10a","word":"nullified","pair":"vitiated","meaning":"使无效","origin":"Nullified 意思是“使无效”，是因为 nullify 的构词就是“使成为零”。null 来自拉丁语 nullus“一个也没有”，-ify 表示“使成为”；-ed 表示已完成。法律、合同或优势被变成没有效力的状态，就是 nullified，即“被取消、失效”。","originQuery":"nullify","page":22},{"id":"p23r10b","word":"vitiated","pair":"nullified","meaning":"使无效","origin":"Vitiated 意思是“使无效、损害”，是因为 vitiate 来自拉丁语 vitiare“使有缺陷、败坏”，核心 vitium 是“缺点、过错”。证据或协议一旦受到关键缺陷污染，就不再可靠或有效；因此 vitiated 表示“被破坏、因瑕疵而失效”。","originQuery":"vitiate","page":22},{"id":"p24r01a","word":"vitriol","pair":"obloquy","meaning":"尖刻反击","origin":"Vitriol 意思是“尖刻攻击”，是因为它原指具有强腐蚀性的硫酸盐，后来尤其让人联想到硫酸。该词来自拉丁语 vitriolum“玻璃状物质”，因晶体似玻璃得名。恶毒言辞仿佛强酸般灼伤他人，于是 vitriol 比喻“尖刻、刻毒的批评”。","originQuery":"vitriol","page":23},{"id":"p24r01b","word":"obloquy","pair":"vitriol","meaning":"尖刻反击","origin":"Obloquy 意思是“尖刻攻击、公开责难”，是因为它来自拉丁语 obloqui“反对着说”：ob-“反对、朝向”，loqui“说话”。众人以反对、辱骂的话攻击某人，会使其蒙受恶名；因此 obloquy 既指猛烈谴责，也指由此造成的公众羞辱。","originQuery":"obloquy","page":23},{"id":"p24r02a","word":"soberly","pair":"sensibly","meaning":"冷静理智地","origin":"Soberly 意思是“冷静理智地”，是因为 sober 最初表示“不醉、饮酒有节制”。它经古法语 sobre 来自拉丁语 sobrius“不醉的”。没有酒精扰乱判断，人的头脑清醒而庄重；-ly 构成副词，因此 soberly 表示以严肃、清醒、不夸张的方式。","originQuery":"soberly","page":23},{"id":"p24r02b","word":"sensibly","pair":"soberly","meaning":"冷静理智地","origin":"Sensibly 意思是“冷静理智地”，是因为 sensible 在这里表示“有良好判断力的”。它来自拉丁语 sensibilis“可感知的”，核心 sensus 是“感觉、判断”；-ly 构成副词。能依据现实感受和常识作判断，而不被冲动带走，就是 sensibly。","originQuery":"sensibly","page":23},{"id":"p24r03a","word":"anomalous","pair":"exceptional","meaning":"异常的","origin":"Anomalous 意思是“异常的”，是因为它来自希腊语 anomalos“不均匀、不规则”。an-“不”，homalos“平坦、均匀”；进入英语时 h 脱落在词形中。某个现象若不像周围事物那样平整一致，而是偏离正常模式，就是 anomalous，即“反常、异常的”。","originQuery":"anomalous","page":23},{"id":"p24r03b","word":"exceptional","pair":"anomalous","meaning":"异常的","origin":"Exceptional 在这里意思是“异常的”，是因为 exception 原指从一般规则中“取出来”的情况。它最终来自拉丁语 excipere：ex-“向外”，capere“拿取”；-al 构成形容词。被排除在常规模式之外的事物就是例外，因此 exceptional 可表示“异常的”，也可褒义表示“格外优秀”。","originQuery":"exceptional","page":23},{"id":"p24r04a","word":"disapprobation","pair":"censure","meaning":"批评指责","origin":"Disapprobation 意思是“批评指责”，是因为它表示“不赞许”。dis-“否定、相反”，approbation“认可、赞同”；approve 最终来自拉丁语 approbare“证明为好”。把“认为是好的”反转过来，就是认为错误并表示反对，因此 disapprobation 指正式或强烈的不赞成。","originQuery":"disapprobation","page":23},{"id":"p24r04b","word":"censure","pair":"disapprobation","meaning":"批评指责","origin":"Censure 意思是“批评指责”，是因为它来自拉丁语 censura“判断、审查”，核心 censere 是“评估、判定”。罗马监察官会审查行为并作出道德判断。判断某人有过错后公开谴责，便使 censure 从中性的“评判”发展为正式的严厉批评。","originQuery":"censure","page":23},{"id":"p24r05a","word":"placate","pair":"appease","meaning":"安抚","origin":"Placate 意思是“安抚”，是因为它来自拉丁语 placare“使平静、使和解”，与 placere“使高兴”相关。让愤怒者重新感到满意，情绪就会平息；因此 placate 表示通过让步、言语或行动消除怒气，恢复和平。","originQuery":"placate","page":23},{"id":"p24r05b","word":"appease","pair":"placate","meaning":"安抚","origin":"Appease 意思是“安抚”，是因为它的核心是“使恢复和平”。它经古法语 apaisier 进入英语，核心 pais“和平”来自拉丁语 pax、pacem。让愤怒或冲突进入平和状态，就是 appease，因此可指平息情绪，也可指以让步安抚对方。","originQuery":"appease","page":23},{"id":"p24r06a","word":"protean","pair":"versatile","meaning":"多才多艺","origin":"Protean 意思是“多才多艺、变化多端”，是因为它来自希腊神话海神 Proteus。Proteus 能不断改变形状以躲避追问，所以他的名字成为善变和多形的象征。一个人能灵活变换角色、展现多种能力，就可称为 protean。","originQuery":"protean","page":23},{"id":"p24r06b","word":"versatile","pair":"protean","meaning":"多才多艺","origin":"Versatile 意思是“多才多艺”，是因为拉丁语 versatilis 原指“能够转动、可朝不同方向转”。它来自 versare“反复转动”，与 vertere“转”有关。能迅速转向不同任务并适应多种用途的人，就不仅灵活，而且具备多方面才能，因此是 versatile。","originQuery":"versatile","page":23},{"id":"p24r07a","word":"origin","pair":"provenance","meaning":"起源","origin":"Origin 意思是“起源”，是因为它来自拉丁语 origo“开端、来源”，与 oriri“升起、开始出现”有关。太阳从地平线升起是一天的开始，事物首次出现之处就是它的 origin；因此该词可指事件的开端、人的出身或某物的来源。","originQuery":"origin","page":23},{"id":"p24r07b","word":"provenance","pair":"origin","meaning":"起源","origin":"Provenance 意思是“起源、出处”，是因为它来自法语 provenir“来自、产生于”，最终源于拉丁语 provenire：pro-“向前、出来”，venire“来”。追问一件物品从哪里“来到”现在的位置，就是追查其来源，因此 provenance 尤指艺术品、文献等的来历和所有权记录。","originQuery":"provenance","page":23},{"id":"p24r08a","word":"dearth","pair":"paucity","meaning":"缺乏","origin":"Dearth 意思是“缺乏”，是因为它最早与“昂贵”有关。它来自古英语 dēore“珍贵、价格高”，也就是现代 dear 的一个来源；-th 构成状态名词。东西供应稀少时价格会上涨，于是“昂贵的状态”逐渐转指造成昂贵的“短缺、匮乏”。","originQuery":"dearth","page":23},{"id":"p24r08b","word":"paucity","pair":"dearth","meaning":"缺乏","origin":"Paucity 意思是“缺乏”，是因为它来自拉丁语 paucitas“数量少”，核心 paucus 就是“少数、很少”。-ity 表示状态或性质。某种资源只有少量，低于实际需要时，就构成短缺；因此 paucity 常用于正式语体，表示“少量、缺乏”，如 a paucity of evidence。","originQuery":"paucity","page":23},{"id":"p24r09a","word":"respected","pair":"venerable","meaning":"值得尊敬的","origin":"Respected 意思是“值得尊敬、受到尊重的”，是因为 respect 的拉丁语字面义是“回头再看、认真看待”。它来自 respicere：re-“回、再”，specere“看”。愿意多看一眼并慎重考虑某人的价值，就是给予重视和敬意；respected 表示“受人尊重的”。","originQuery":"respect","page":23},{"id":"p24r09b","word":"venerable","pair":"respected","meaning":"值得尊敬的","origin":"Venerable 意思是“值得尊敬的”，是因为它来自拉丁语 venerabilis“值得崇敬的”，核心 venerari 表示“敬奉、崇敬”；-able 表示“值得被……”。因年资、品格或历史地位而应受到敬意的人或事物，就是 venerable，因此常带庄重而古老的色彩。","originQuery":"venerable","page":23},{"id":"p24r10a","word":"trivial","pair":"inconsequential","meaning":"不重要的","origin":"Trivial 意思是“不重要的”，是因为拉丁语 trivialis 原指三岔路口的、随处可见的事物。它来自 trivium：tri-“三”，via“道路”。公共路口上的话题人人都知道，显得寻常普通；由“普通”进一步贬化为“琐碎、无足轻重”。","originQuery":"trivial","page":23},{"id":"p24r10b","word":"inconsequential","pair":"trivial","meaning":"不重要的","origin":"Inconsequential 意思是“不重要的”，是因为它表示“不会带来重要后果”。in-“不”，consequential 来自 consequence“结果、后果”；consequence 又源于拉丁语 consequi“随后发生”。一件事若没有值得关注的后续影响，就无足轻重，因此 inconsequential 是“不重要的、微不足道的”。","originQuery":"inconsequential","page":23},{"id":"p25r01a","word":"baseless","pair":"untenable","meaning":"毫无根据","origin":"Baseless 意思是“毫无根据”，是因为它由 base“底座、基础”与 -less“没有……”直接构成。base 最终来自希腊语 basis“脚步、基座”。建筑没有底座无法站稳，同样，主张没有证据也不能成立；因此 baseless 就是“无基础的、没有根据的”。","originQuery":"baseless","page":24},{"id":"p25r01b","word":"untenable","pair":"baseless","meaning":"毫无根据","origin":"Untenable 意思是“毫无根据、站不住脚的”，是因为它由 un-“不能”和 tenable“可守住的”构成。tenable 来自拉丁语 tenere“握住、保持”，-able 表示“能够”。论点若无法守住、经不起证据检验，就不能成立，因此是 untenable。","originQuery":"untenable","page":24},{"id":"p25r02a","word":"restricted","pair":"circumscribed","meaning":"受限","origin":"Restricted 意思是“受限”，是因为 restrict 的拉丁语字面义是“紧紧绑住”。它来自 restringere：re-“向后、加强”，stringere“拉紧、束缚”。被绳索拉紧的物体不能自由活动；因此 restricted 可指范围、人数或行动受到规则约束。","originQuery":"restricted","page":24},{"id":"p25r02b","word":"circumscribed","pair":"restricted","meaning":"受限","origin":"Circumscribed 意思是“受限”，是因为 circumscribe 的拉丁语字面义是“在周围画线”。它来自 circumscribere：circum-“环绕”，scribere“写、画”。边界线画定后，活动只能留在线内；因此 circumscribed 表示“被限定在狭小范围内的”。","originQuery":"circumscribe","page":24},{"id":"p25r03a","word":"quixotic","pair":"idealistic","meaning":"不切实际","origin":"Quixotic 意思是“不切实际的”，是因为它来自小说人物 Don Quixote（堂吉诃德）。他以骑士理想解释现实，把风车当巨人，勇敢却脱离实际。于是 Quixote 的名字成为高尚但幻想化行动的象征，quixotic 表示“理想主义而不现实的”。","originQuery":"quixotic","page":24},{"id":"p25r03b","word":"idealistic","pair":"quixotic","meaning":"不切实际","origin":"Idealistic 意思是“不切实际的”，是因为 ideal 指头脑中的完美范型。它最终来自希腊语 idea“形态、观念”，-istic 表示相关倾向。按理想而非现实条件来设想事情，既可褒义表示有原则，也可能因忽略限制而成为“不切实际的”。","originQuery":"idealistic","page":24},{"id":"p25r04a","word":"asserts","pair":"maintains","meaning":"坚持","origin":"Asserts 意思是“坚持、断言”，是因为 assert 来自拉丁语 asserere“主张、认领”，由 ad-“向”与 serere“连接”相关成分构成。把某项权利牢牢归于自己，就是提出主张；在言语中坚定地把一句话作为事实提出，便是 assert。","originQuery":"assert","page":24},{"id":"p25r04b","word":"maintains","pair":"asserts","meaning":"坚持","origin":"Maintains 意思是“坚持”，是因为 maintain 的词源图景是“用手握住”。它经古法语 maintenir 来自拉丁语 manu tenere：manu“用手”，tenere“保持”。手中一直不松开，就是维持；用于观点时，maintain 表示持续主张、不因反对而放弃。","originQuery":"maintain","page":24},{"id":"p25r05a","word":"portend","pair":"predict","meaning":"预示","origin":"Portend 意思是“预示”，是因为它来自拉丁语 portendere“向前伸出、指出预兆”，通常分析为 por-/pro-“向前”与 tendere“伸展”。一个迹象仿佛伸到未来，指向尚未发生的事件，因此 portend 表示“预兆、预示”，常用于重大或不祥结果。","originQuery":"portend","page":24},{"id":"p25r05b","word":"predict","pair":"portend","meaning":"预示","origin":"Predict 意思是“预示、预测”，是因为它的拉丁语构词就是“预先说出”。它来自 praedicere：prae-“在前、预先”，dicere“说”。在事情发生前说出将来的结果，就是预测；若主语是一个迹象，它所“提前说出”的结果便是预示。","originQuery":"predict","page":24},{"id":"p25r06a","word":"sidestep","pair":"circumvent","meaning":"避开","origin":"Sidestep 意思是“避开”，是因为它由 side“侧面”与 step“迈步”构成，字面就是“向旁边迈一步”。身体侧移可以绕过迎面障碍；这个动作转用于谈话、责任或规则，便表示不正面应对，而是从旁绕开。","originQuery":"sidestep","page":24},{"id":"p25r06b","word":"circumvent","pair":"sidestep","meaning":"避开","origin":"Circumvent 意思是“避开”，是因为它来自拉丁语 circumvenire“从四周走来、包围”：circum-“环绕”，venire“来”。原先有围住并智胜对方之意，后来重点转到用办法绕过障碍或规则。因此 circumvent 常含有策略性“规避”的意味。","originQuery":"circumvent","page":24},{"id":"p25r07a","word":"heterogeneous","pair":"dissimilar","meaning":"不同种类的异质的","origin":"Heterogeneous 意思是“不同种类的、异质的”，是因为它来自希腊语 heterogenēs：heteros“另一个、不同”，genos“种类、出身”。一个整体若由不同来源或性质的成分组成，就不是均一的，因此是 heterogeneous；反义词 homogeneous 表示“同质的”。","originQuery":"heterogeneous","page":24},{"id":"p25r07b","word":"dissimilar","pair":"heterogeneous","meaning":"不同种类的异质的","origin":"Dissimilar 意思是“不同的”，是因为它由 dis-“不、分开”和 similar“相似的”构成。similar 来自拉丁语 similis“相像的”。加上否定成分后，就是外观、性质或种类不能彼此对应，因此 dissimilar 表示“不相似的”，但不一定强调混合成分。","originQuery":"dissimilar","page":24},{"id":"p25r08a","word":"visible","pair":"salient","meaning":"显而易见的","origin":"Visible 意思是“显而易见的”，是因为它来自拉丁语 visibilis“能够被看见的”，核心 videre 是“看”，-ible 表示“可被……”。能直接进入视线的事物无需推测；由视觉上的可见进一步扩展到事实或影响清楚明显，因此 visible 可译为“显而易见的”。","originQuery":"visible","page":24},{"id":"p25r08b","word":"salient","pair":"visible","meaning":"显而易见的","origin":"Salient 意思是“显而易见、突出的”，是因为它来自拉丁语 salire“跳”。salientem 原有“跳跃、凸出”的意思。某个特征仿佛从背景中跳出来，会立刻吸引注意，因此 salient 由物理上的突出发展为信息或特点上的“显著”。","originQuery":"salient","page":24},{"id":"p25r09a","word":"slighted","pair":"disparaged","meaning":"轻视","origin":"Slighted 意思是“受到轻视”，是因为 slight 作形容词表示“细小、微不足道”，作动词便是把某人看得很轻。该词来自古诺斯语 sléttr“平滑、简单”，语义后来转向轻微。认为某人不重要而忽略或怠慢他，就是 slight；slighted 表示“被轻慢”。","originQuery":"slight","page":24},{"id":"p25r09b","word":"disparaged","pair":"slighted","meaning":"轻视","origin":"Disparaged 意思是“受到轻视、贬低”，是因为 disparage 的早期含义是“降低等级”。它来自古法语 desparagier，其中 des-“降低、去除”，parage 与身份和同等地位有关。把某人从应有地位往下压，就是损害其声望，因此 disparaged 表示“被贬低”。","originQuery":"disparage","page":24},{"id":"p25r10a","word":"exactitude","pair":"meticulousness","meaning":"一丝不苟","origin":"Exactitude 意思是“一丝不苟、精确”，是因为 exact 来自拉丁语 exactus“彻底完成、精确的”。其动词 exigere 有“赶出、衡量、要求”的含义；-itude 表示状态。把标准执行到完全符合、分毫不差，就是 exactitude，因此强调严密准确。","originQuery":"exactitude","page":24},{"id":"p25r10b","word":"meticulousness","pair":"exactitude","meaning":"一丝不苟","origin":"Meticulousness 意思是“一丝不苟”，是因为 meticulous 最初表示因害怕出错而过分小心。它来自拉丁语 meticulosus“胆怯的”，核心 metus 是“恐惧”；-ness 表示性质。谨慎到逐一检查每个细节，后来成为褒义的极度认真。","originQuery":"meticulousness","page":24},{"id":"p26r01a","word":"quiescence","pair":"calm","meaning":"平静","origin":"Quiescence 意思是“平静”，是因为它来自拉丁语 quiescere“休息、静止”，核心 quies 是“安静、休息”；-ence 表示状态。活动暂时停止、没有扰动时，就进入 quiescence，因此该词常指一段静止或休眠状态。","originQuery":"quiescence","page":25},{"id":"p26r01b","word":"calm","pair":"quiescence","meaning":"平静","origin":"Calm 意思是“平静”，是因为它原先形容无风无浪的天气。它经法语 calme、意大利语 calma 进入英语，可能最终与希腊语 kauma“暑热”有关：炎热时海面常静止。由水面不受扰动，词义扩展到人的情绪安稳。","originQuery":"calm","page":25},{"id":"p26r02a","word":"beneficence","pair":"altruism","meaning":"利他主义","origin":"Beneficence 意思是“利他、行善”，是因为它的拉丁语构词就是“做好事”。bene-“好、善”，facere“做”，形成 beneficent“行善的”；-ence 表示性质或行为。主动为他人带来好处，就是 beneficence，因此比一般善意更强调实际的慷慨行动。","originQuery":"beneficence","page":25},{"id":"p26r02b","word":"altruism","pair":"beneficence","meaning":"利他主义","origin":"Altruism 意思是“利他主义”，是因为它的核心直接指向“他人”。它由法语 altruisme 进入英语，altrui 意为“他人的”，最终与拉丁语 alter“另一个”同源。把他人利益置于自身利益之前，便形成 altruism，即为别人着想的原则和行为。","originQuery":"altruism","page":25},{"id":"p26r03a","word":"extremist","pair":"zealot","meaning":"狂热分子","origin":"Extremist 意思是“狂热分子”，是因为它由 extreme“极端”与 -ist“持某种主张的人”构成。extreme 来自拉丁语 extremus“最外、最远的”。立场走到尺度最外端、不愿妥协的人就是 extremist；“狂热”是这种极端坚持常呈现的态度。","originQuery":"extremist","page":25},{"id":"p26r03b","word":"zealot","pair":"extremist","meaning":"狂热分子","origin":"Zealot 意思是“狂热分子”，是因为它来自希腊语 zēlōtēs“热烈追随者”，核心 zēlos 是“热情、竞争性热忱”。该词曾特指反抗罗马统治的犹太激进派，后来泛指对宗教或政治信念投入过度热情、排斥异议的人。","originQuery":"zealot","page":25},{"id":"p26r04a","word":"affable","pair":"easygoing","meaning":"亲切随和","origin":"Affable 意思是“亲切随和”，是因为拉丁语 affabilis 的字面概念是“可以与之交谈的”。它来自 affari“对某人说话”：ad-“向”，fari“说”；-able 表示“可以”。让人容易上前交谈、不摆架子的人，自然显得友善可亲。","originQuery":"affable","page":25},{"id":"p26r04b","word":"easygoing","pair":"affable","meaning":"亲切随和","origin":"Easygoing 意思是“亲切随和”，是因为它由 easy“轻松、不费力”与 going“相处、行事方式”构成。与这样的人相处无需紧张，他也不会因小事施压或动怒；因此该复合词表示性情放松、宽容好相处。","originQuery":"easygoing","page":25},{"id":"p26r05a","word":"inflammatory","pair":"provocative","meaning":"煽动性的","origin":"Inflammatory 意思是“煽动性的”，是因为 inflame 的拉丁语字面义是“点燃”。它来自 inflammare：in-“进入、使”，flamma“火焰”。言辞若像火种一样点燃愤怒和冲突，就具有煽动性；该词在医学中则保留“引起炎症”的本义。","originQuery":"inflammatory","page":25},{"id":"p26r05b","word":"provocative","pair":"inflammatory","meaning":"煽动性的","origin":"Provocative 意思是“煽动性的”，是因为 provoke 的拉丁语字面义是“向前叫出来”。它来自 provocare：pro-“向前”，vocare“呼喊、召唤”。把人叫出来迎战，就是挑衅；能激起强烈反应或冲突的言行，因此被称为 provocative。","originQuery":"provocative","page":25},{"id":"p26r06a","word":"heterogeneous","pair":"disparate","meaning":"多种多样的","origin":"heterogeneous 意思是“多种多样的”，是因为它来自希腊语 heterogenēs：heteros“另一个、不同”，genos“种类、出身”。一个整体若由不同来源或性质的成分组成，就不是均一的，因此是 heterogeneous；反义词 homogeneous 表示“同质的”。","originQuery":"heterogeneous","page":25},{"id":"p26r06b","word":"disparate","pair":"heterogeneous","meaning":"多种多样的","origin":"Disparate 意思是“多种多样、彼此不同”，是因为它来自拉丁语 disparatus“分开的”，核心 disparare 表示“使分离”，并与 par“相等”形成“不相等”的关系。各项若来源、性质都不相同，不能归为同类，就是 disparate。","originQuery":"disparate","page":25},{"id":"p26r07a","word":"intimidating","pair":"scary","meaning":"令人畏惧","origin":"Intimidating 意思是“令人畏惧”，是因为 intimidate 的核心来自拉丁语 timidus“胆怯、害怕的”。in- 在这里有“使进入某状态”的作用；使别人变得 timid，就是威吓。intimidating 因而形容人或事物气势强到令人生畏。","originQuery":"intimidate","page":25},{"id":"p26r07b","word":"scary","pair":"intimidating","meaning":"令人畏惧","origin":"Scary 意思是“令人畏惧”，是因为它由 scare“使受惊”与 -y 构成。scare 可能来自古诺斯语中表示“恐惧”的词，但具体路径并不完全确定。能触发惊吓反应、让人害怕的对象，就是 scary，即“可怕的”。","originQuery":"scary","page":25},{"id":"p26r08a","word":"hypotheses","pair":"preconceptions","meaning":"假设","origin":"Hypotheses 意思是“假设”，是因为单数 hypothesis 的希腊语字面义是“放在下面的东西”。hypo-“在下”，thesis“放置、命题”。一个尚待检验的判断先被放在论证底部作为出发点，因此成为“假设”；hypotheses 是其复数。","originQuery":"hypotheses","page":25},{"id":"p26r08b","word":"preconceptions","pair":"hypotheses","meaning":"假设","origin":"Preconceptions 意思是“预先设想、先入之见”，是因为它由 pre-“在前”与 conception“形成的观念”构成。人在接触事实之前就已形成的想法，会影响后续判断。因此它可充当未经验证的假设，但常比 hypothesis 多一层成见意味。","originQuery":"preconception","page":25},{"id":"p26r09a","word":"showy","pair":"meretricious","meaning":"华而不实","origin":"Showy 意思是“华而不实”，是因为它由 show“展示”与 -y 构成，原指特别适合展示、容易吸引目光。若外观只追求引人注意，却没有相应的内容或品质，“好展示”就转成贬义，因此 showy 表示“炫目的、浮华的”。","originQuery":"showy","page":25},{"id":"p26r09b","word":"meretricious","pair":"showy","meaning":"华而不实","origin":"Meretricious 意思是“华而不实”，是因为它来自拉丁语 meretricius“妓女的”，核心 meretrix 与 mereri“挣钱”有关。该词后来借用刻板印象，形容以艳丽外表招徕注意却缺乏真正价值的事物，因此表示“俗艳而虚假的”。","originQuery":"meretricious","page":25},{"id":"p26r10a","word":"waver","pair":"oscillate","meaning":"犹豫不决","origin":"Waver 意思是“犹豫不决”，是因为它原先表示来回摇摆、颤动。它与 wave“波动”在形式和概念上相近，来自日耳曼语中表示摆动的词。身体或物体不能稳定朝一个方向，转用于意志便是一会儿倾向这边、一会儿倾向那边。","originQuery":"waver","page":25},{"id":"p26r10b","word":"oscillate","pair":"waver","meaning":"犹豫不决","origin":"Oscillate 意思是“犹豫不决”，是因为它本义是像摆一样来回摆动。它来自拉丁语 oscillare“摆动”，与 oscillum“小面具、悬挂物”有关。位置在两端之间反复变化，转用于想法或选择，就表示摇摆不定。","originQuery":"oscillate","page":25},{"id":"p27r01a","word":"understandable","pair":"transparent","meaning":"易懂且清晰","origin":"Understandable 意思是“易懂且清晰”，是因为它由 understand“理解”与 -able“能够被……”构成。understand 来自古英语 understandan，原有“领会、理解”之义，不能机械解释成“站在下面”。能被头脑顺利把握的内容，就是 understandable。","originQuery":"understandable","page":26},{"id":"p27r01b","word":"transparent","pair":"understandable","meaning":"易懂且清晰","origin":"Transparent 意思是“易懂且清晰”，是因为它的拉丁语构词表示“让光穿过”。trans-“穿过”，parere“显现”；物体透光时，后面的东西清楚可见。这个视觉图景转用于语言或过程，便表示没有遮掩、容易理解。","originQuery":"transparent","page":26},{"id":"p27r02a","word":"endemic","pair":"native","meaning":"本地的","origin":"Endemic 意思是“本地的”，是因为它来自希腊语 endēmos“在本地人群中的”：en-“在……内”，dēmos“人民、地区”。某种疾病长期存在于特定地区，便是 endemic；后来也泛指某种现象为当地或某群体所固有。","originQuery":"endemic","page":26},{"id":"p27r02b","word":"native","pair":"endemic","meaning":"本地的","origin":"Native 意思是“本地的”，是因为它来自拉丁语 nativus“由出生而来的”，核心 nasci 是“出生”。在某地出生、自然生长的生物或人，不是后来从外部引入，因此 native 表示“本土的、土生的”。","originQuery":"native","page":26},{"id":"p27r03a","word":"flexible","pair":"supple","meaning":"灵活的","origin":"Flexible 意思是“灵活的”，是因为它来自拉丁语 flexibilis“可以弯曲的”，核心 flectere 是“弯、转”，-ible 表示“能够”。能弯而不断的材料容易改变形状；这一性质转用于计划和思维，就表示能随情况调整。","originQuery":"flexible","page":26},{"id":"p27r03b","word":"supple","pair":"flexible","meaning":"灵活的","origin":"Supple 意思是“灵活的”，是因为它经古法语 souple 来自拉丁语 supplex，早期有“弯曲、顺从”的意味。身体或材料容易弯曲就动作流畅，不僵硬；因此 supple 可指柔韧灵活，也可比喻思维适应性强。","originQuery":"supple","page":26},{"id":"p27r04a","word":"unfamiliarity","pair":"ignorance","meaning":"缺乏了解","origin":"Unfamiliarity 意思是“缺乏了解”，是因为它由 un-“不”、familiar“熟悉的”与 -ity“状态”构成。familiar 原本与 familia“家庭”有关；家中事物因长期接触而熟知。反过来，缺少接触和认识的状态就是 unfamiliarity。","originQuery":"unfamiliar","page":26},{"id":"p27r04b","word":"ignorance","pair":"unfamiliarity","meaning":"缺乏了解","origin":"Ignorance 意思是“缺乏了解”，是因为它来自拉丁语 ignorantia“不知道”，核心 ignorare 表示“不认识、不了解”。其中否定成分 in- 与 gnoscere“知道”相关。没有获得某方面知识，便处于 ignorance，即“无知、不了解”。","originQuery":"ignorance","page":26},{"id":"p27r05a","word":"anomalous","pair":"unusual","meaning":"异常的","origin":"anomalous 意思是“异常的”，是因为它来自希腊语 anomalos“不均匀、不规则”。an-“不”，homalos“平坦、均匀”；进入英语时 h 脱落在词形中。某个现象若不像周围事物那样平整一致，而是偏离正常模式，就是 anomalous，即“反常、异常的”。","originQuery":"anomalous","page":26},{"id":"p27r05b","word":"unusual","pair":"anomalous","meaning":"异常的","origin":"Unusual 意思是“异常的”，是因为它由 un-“不”和 usual“通常的”构成。usual 来自拉丁语 usus“使用、习惯”，与 use 同源。不是习惯中经常发生的事，就偏离常态，因此 unusual 表示“不寻常、异常的”。","originQuery":"unusual","page":26},{"id":"p27r06a","word":"unexampled","pair":"novel","meaning":"前所未有的","origin":"Unexampled 意思是“前所未有的”，是因为它由 un-“没有”与 example“例子、先例”构成，字面就是“找不到既有例子的”。example 来自拉丁语 exemplum“取出的样本”。过去没有样本可比，便是史无前例。","originQuery":"unexampled","page":26},{"id":"p27r06b","word":"novel","pair":"unexampled","meaning":"前所未有的","origin":"Novel 意思是“前所未有、新颖的”，是因为它来自拉丁语 novellus“新的、年轻的”，核心 novus 就是“新”。经古法语进入英语后，它形容新近出现、不同于旧有方式的事物。若一种方法此前从未出现，就同时具有 novel 的“新颖”和“前所未有”意味。","originQuery":"novel","page":26},{"id":"p27r07a","word":"outmoded","pair":"unfashionable","meaning":"过时的","origin":"Outmoded 意思是“过时的”，是因为它由 out-“超出、离开”与 mode“流行方式、样式”构成。mode 来自拉丁语 modus“尺度、方式”。一种做法若已经走出当前流行模式，不再适合时代，就成为 outmoded。","originQuery":"outmoded","page":26},{"id":"p27r07b","word":"unfashionable","pair":"outmoded","meaning":"过时的","origin":"Unfashionable 意思是“过时的”，是因为它由 un-“不”和 fashionable“符合流行样式的”构成。fashion 来自法语 façon“做法、样式”。一种衣着或观念若不再符合当下普遍采用的样式，就显得落伍，因此是 unfashionable。","originQuery":"unfashionable","page":26},{"id":"p27r08a","word":"decry","pair":"condemn","meaning":"谴责","origin":"Decry 意思是“谴责”，是因为它经法语 décrier 进入英语，早期表示公开喊叫、宣布贬低某物。cry 保留“大声说出”的核心，de- 带有降低、反对意味。公开高声宣称某事不好，就是严厉批评，因此 decry 表示“公开谴责”。","originQuery":"decry","page":26},{"id":"p27r08b","word":"condemn","pair":"decry","meaning":"谴责","origin":"Condemn 意思是“谴责”，是因为它来自拉丁语 condemnare“判定有罪、处罚”，由 con-“完全”与 damnare“定罪”构成。法官判定某人有罪，是最正式的否定评价；词义后来扩大为基于道德理由强烈批评。","originQuery":"condemn","page":26},{"id":"p27r09a","word":"conspicuous","pair":"prominent","meaning":"显眼","origin":"Conspicuous 意思是“显眼”，是因为它来自拉丁语 conspicuus“清楚可见的”，与 conspicere“注视”有关：con-“共同、完全”，specere“看”。能被众人清楚看见、一下吸引视线的事物，就是 conspicuous，因此表示“明显、引人注目的”。","originQuery":"conspicuous","page":26},{"id":"p27r09b","word":"prominent","pair":"conspicuous","meaning":"显眼","origin":"Prominent 意思是“显眼”，是因为它来自拉丁语 prominere“向前突出”：pro-“向前”，minere“伸出”。物体突出于周围表面时首先进入视线；人物或特点在重要性上突出也同样引人注意，因此 prominent 表示“显著、显眼的”。","originQuery":"prominent","page":26},{"id":"p27r10a","word":"trivial","pair":"inessential","meaning":"不重要的","origin":"trivial 意思是“不重要的”，是因为拉丁语 trivialis 原指三岔路口的、随处可见的事物。它来自 trivium，由 tri-“三”与 via“路”构成。人人在公共路口都能遇见的东西显得寻常、不特别；由“普通”进一步贬化为“琐碎、无足轻重”。","originQuery":"trivial","page":26},{"id":"p27r10b","word":"inessential","pair":"trivial","meaning":"不重要的","origin":"Inessential 意思是“不重要的”，是因为它由 in-“不”与 essential“本质的、必不可少的”构成。essential 来自拉丁语 essentia“存在、本质”。不构成事物本质、删掉也不影响核心的部分，就是 inessential，即“非必要、无关紧要的”。","originQuery":"inessential","page":26},{"id":"p28r01a","word":"eager","pair":"keen","meaning":"渴望的热切的","origin":"Eager 意思是“渴望、热切的”，是因为它早期有“尖锐、强烈”的含义。它经古法语 aigre 来自拉丁语 acer“尖、强烈”，与 acrid 等词相关。欲望若像尖锋一样强烈、迫切，就表现为 eager，即急于得到或做某事。","originQuery":"eager","page":27},{"id":"p28r01b","word":"keen","pair":"eager","meaning":"渴望的热切的","origin":"keen 意思是“渴望的热切的”，是因为它的早期核心是“锋利、勇猛、有力量”。它来自古英语 cēne“勇敢、强烈”，后来也形容刀刃锐利。欲望若像刀锋一样强而集中，就会表现为热切、迫切；因此 be keen to do 表示“急切想做”。","originQuery":"keen","page":27},{"id":"p28r02a","word":"denunciations","pair":"indictments","meaning":"谴责","origin":"Denunciations 意思是“谴责”，是因为 denounce 原本表示公开宣布，尤其是宣布罪责。它来自拉丁语 denuntiare：de- 加强语气，nuntiare“报告、宣布”。公开指出错误并严厉批评，就是 denunciation；复数表示多次或多项谴责。","originQuery":"denunciation","page":27},{"id":"p28r02b","word":"indictments","pair":"denunciations","meaning":"谴责","origin":"Indictments 意思是“谴责、控诉”，是因为 indictment 原指正式的刑事起诉。它经古法语 enditement 进入英语，核心与拉丁语 indicere“宣布、指控”有关。把罪名正式说出，就是起诉；后来也可泛指严厉揭露某事失败的控诉。","originQuery":"indictment","page":27},{"id":"p28r03a","word":"rudimentary","pair":"elemental","meaning":"基础的","origin":"rudimentary 意思是“基础的”，是因为 rudiment 原指学习或发展的最初阶段。它来自拉丁语 rudimentum“开端、初次尝试”，与 rudis“未经加工、生疏的”有关。处于起步阶段的东西尚未发展完整，只具基本轮廓，因此 rudimentary 可表示“初级的、粗略的”。","originQuery":"rudimentary","page":27},{"id":"p28r03b","word":"elemental","pair":"rudimentary","meaning":"基础的","origin":"Elemental 意思是“基础的”，是因为它来自 element“基本成分”加 -al。element 源于拉丁语 elementum“最初原理、组成要素”。复杂事物由这些最小要素构成，因此 elemental 可表示“基本的、根本的”，也可指自然元素般原始有力。","originQuery":"elemental","page":27},{"id":"p28r04a","word":"plethora","pair":"surfeit","meaning":"过量","origin":"Plethora 意思是“过量”，是因为它来自希腊语 plēthōrē“充满”，核心 plēthein 是“装满”。医学上它曾指体液或血液过多；后来泛指某物多到超过需要。因此 a plethora of 不是普通的“许多”，而常带“过多”的意味。","originQuery":"plethora","page":27},{"id":"p28r04b","word":"surfeit","pair":"plethora","meaning":"过量","origin":"Surfeit 意思是“过量”，是因为它来自古法语 sorfet“过度”，可分析为 sur-“超过”与 fait“做成的”。吃喝超过身体需要会造成饱胀不适，于是 surfeit 先指过量饮食，再泛指任何多到令人厌倦的东西。","originQuery":"surfeit","page":27},{"id":"p28r05a","word":"maturity","pair":"precociousness","meaning":"早熟","origin":"Maturity 在这里与“早熟”相连，是因为它表示达到成熟、完全发展的状态。它来自拉丁语 maturitas“成熟”，核心 maturus 是“成熟、适时的”。若人在通常年龄之前就达到这种状态，便表现为早熟；maturity 本身严格说是“成熟度”。","originQuery":"maturity","page":27},{"id":"p28r05b","word":"precociousness","pair":"maturity","meaning":"早熟","origin":"Precociousness 意思是“早熟”，是因为 precocious 的拉丁语字面义是“提前成熟”。它来自 praecox：prae-“在前、提前”，coquere“煮熟、使成熟”。果实比正常时间更早熟，转用于儿童就是智力或能力发展得异常早。","originQuery":"precocious","page":27},{"id":"p28r06a","word":"capricious","pair":"unpredictable","meaning":"反复无常","origin":"capricious 意思是“反复无常”，是因为 caprice 指突然而任性的念头。它经法语来自意大利语 capriccio，早期可指惊跳或寒颤，更早来源有争议。想法像身体突然一颤般毫无预兆地改变，就显得任性难测，因此是 capricious。","originQuery":"capricious","page":27},{"id":"p28r06b","word":"unpredictable","pair":"capricious","meaning":"反复无常","origin":"Unpredictable 意思是“反复无常、难以预测”，是因为它由 un-“不能”、predict“预先说出”与 -able 构成。predict 来自拉丁语 prae-“预先”加 dicere“说”。变化没有稳定规律，便无法事先说准，因此显得反复无常。","originQuery":"unpredictable","page":27},{"id":"p28r07a","word":"relic","pair":"vestige","meaning":"遗迹","origin":"Relic 意思是“遗迹”，是因为它来自拉丁语 reliquiae“留下来的东西”，核心 relinquere 表示“留下、离开”。早期尤指圣徒遗骨或遗物；后来泛指从过去保存到现在的物件、建筑或习俗，因此就是历史留下的“遗迹”。","originQuery":"relic","page":27},{"id":"p28r07b","word":"vestige","pair":"relic","meaning":"遗迹","origin":"Vestige 意思是“遗迹、残痕”，是因为它来自拉丁语 vestigium“脚印、踪迹”。脚已经离开，却在地面留下可追寻的印记；这个图景扩展到过去事物残存的微小证据，因此 vestige 常指“残余、遗迹”。","originQuery":"vestige","page":27},{"id":"p28r08a","word":"healthy","pair":"robust","meaning":"强健的","origin":"Healthy 意思是“强健的”，是因为 health 与 whole“完整”同源，核心概念是身体完整、没有损伤。health 加 -y 表示具有健康状态。身体各部分运作良好、能抵抗疾病，就显得强壮有活力，因此 healthy 可译为“健康强健的”。","originQuery":"healthy","page":27},{"id":"p28r08b","word":"robust","pair":"healthy","meaning":"强健的","origin":"robust 意思是“强健的”，是因为拉丁语 robustus 原指“像橡木一样坚硬强壮”。它来自 robur“橡木、力量”，可能与 ruber“红色”相关，因为某些橡木心材呈红色。橡木坚实耐久的形象转用于身体和系统，便表示强健、结实且不易损坏。","originQuery":"robust","page":27},{"id":"p28r09a","word":"flummoxed","pair":"confounded","meaning":"困惑","origin":"Flummoxed 意思是“困惑”，是因为 flummox 在19世纪初作为方言词进入书面英语，早期可指“弄乱、使失败”。其更早来源不明，不能可靠拆词。思路被彻底弄乱、无法决定下一步时，人就 flummoxed，即“不知所措”。","originQuery":"flummox","page":27},{"id":"p28r09b","word":"confounded","pair":"flummoxed","meaning":"困惑","origin":"Confounded 意思是“困惑”，是因为 confound 的拉丁语字面义是“倒在一起、混杂”。它来自 confundere：con-“一起”，fundere“倒”。信息混成一团就难以分辨，因此 confounded 由“被混乱”发展为“迷惑不解”。","originQuery":"confounded","page":27},{"id":"p28r10a","word":"cryptic","pair":"elusive","meaning":"难以理解的","origin":"Cryptic 意思是“难以理解的”，是因为它来自希腊语 kryptikos“隐藏的”，核心 kryptein 是“藏起来”，与 crypt“地下墓室”同源。信息若把真正含义藏在表面文字之后，就难以解读，因此 cryptic 表示“隐晦、费解的”。","originQuery":"cryptic","page":27},{"id":"p28r10b","word":"elusive","pair":"cryptic","meaning":"难以理解的","origin":"elusive 意思是“难以理解的”，是因为 elude 的拉丁语字面义是“玩弄着逃开”。它来自 eludere：e-/ex-“出去”，ludere“玩”；-ive 表示具有这种性质。目标仿佛在游戏中不断闪避，使人抓不到或理解不了，因此 elusive 表示“难以捕捉、难以理解的”。","originQuery":"elusive","page":27},{"id":"p29r01a","word":"captivated","pair":"enamored","meaning":"着迷于","origin":"Captivated 意思是“着迷于”，是因为 captivate 原本表示“俘虏、抓住”。它来自拉丁语 captivus“俘虏”，核心 capere 是“抓取”。某种魅力把人的注意力牢牢抓住，使其仿佛失去自由，于是 captivated 发展为“被迷住、深深吸引”。","originQuery":"captivate","page":28},{"id":"p29r01b","word":"enamored","pair":"captivated","meaning":"着迷于","origin":"Enamored 意思是“着迷于”，是因为 enamor 经古法语 enamourer 构成于 en-“使进入”与 amour“爱”。字面可以理解为“使陷入爱中”。对人或事产生强烈喜爱、注意力被吸引，便是 be enamored of/with。","originQuery":"enamored","page":28},{"id":"p29r02a","word":"canned","pair":"formulaic","meaning":"刻板的","origin":"Canned 意思是“刻板的”，是因为它原指被装进罐头、预先准备好的东西。录音技术出现后，canned 又指预先录制而非现场产生的声音。回答或笑声若早已制作好、每次原样取用，就缺少自然变化，因此表示“套用的、刻板的”。","originQuery":"canned","page":28},{"id":"p29r02b","word":"formulaic","pair":"canned","meaning":"刻板的","origin":"Formulaic 意思是“刻板的”，是因为它由 formula“固定公式、套式”与 -ic 构成。formula 是拉丁语 forma“形式”的指小词，原指小型范式。作品若机械套用固定模式，缺少原创变化，就显得公式化、刻板。","originQuery":"formulaic","page":28},{"id":"p29r03a","word":"objective","pair":"impartial","meaning":"客观公正","origin":"Objective 意思是“客观公正”，是因为 object 原指摆在面前、独立于观察者的对象。它来自拉丁语 obicere：ob-“在前”，iacere“投放”。判断若依据外在对象和事实，而非个人感情，就称为 objective，即“客观的”。","originQuery":"objective","page":28},{"id":"p29r03b","word":"impartial","pair":"objective","meaning":"客观公正","origin":"Impartial 意思是“客观公正”，是因为它由 im-“不”和 partial“偏向一部分的”构成。partial 来自 part“部分”。判断者若不只站在任何一部分或一方，而按同一标准对待各方，就没有偏袒，因此是 impartial。","originQuery":"impartial","page":28},{"id":"p29r04a","word":"unabated","pair":"undiminished","meaning":"未减弱的","origin":"Unabated 意思是“未减弱的”，是因为它由 un-“没有”与 abated“减弱、降低了的”构成。abate 经古法语 abatre，原有“打倒、降低”之意。强度没有被打下来，仍保持原来程度，因此称为 unabated。","originQuery":"unabated","page":28},{"id":"p29r04b","word":"undiminished","pair":"unabated","meaning":"未减弱的","origin":"Undiminished 意思是“未减弱的”，是因为它由 un-“没有”和 diminished“变小、减少了的”构成。diminish 来自拉丁语 diminuere“使变小”，与 minor“较小”相关。数量或力量没有变小，就仍然完整强盛，因此是 undiminished。","originQuery":"undiminished","page":28},{"id":"p29r05a","word":"deleterious","pair":"counterproductive","meaning":"有害的","origin":"Deleterious 意思是“有害的”，是因为它来自希腊语 dēlētērios“破坏性的”，核心 dēleisthai 表示“伤害、毁坏”。能损伤健康、环境或利益的因素会带来不良后果，因此称为 deleterious，语气比普通 harmful 更正式。","originQuery":"deleterious","page":28},{"id":"p29r05b","word":"counterproductive","pair":"deleterious","meaning":"有害的","origin":"Counterproductive 意思是“有害、适得其反的”，是因为它由 counter-“反向、对抗”与 productive“产生预期成果的”构成。一个措施不仅没产生目标结果，反而朝相反方向起作用，就会损害原目标，因此是 counterproductive。","originQuery":"counterproductive","page":28},{"id":"p29r06a","word":"trivial","pair":"insignificant","meaning":"微不足道","origin":"Trivial 意思是“微不足道”，是因为拉丁语 trivialis 原指三岔路口的、随处可见的事物。它来自 trivium，由 tri-“三”与 via“路”构成。人人在公共路口都能遇见的东西显得寻常、不特别；由“普通”进一步贬化为“琐碎、无足轻重”。","originQuery":"trivial","page":28},{"id":"p29r06b","word":"insignificant","pair":"trivial","meaning":"微不足道","origin":"Insignificant 意思是“微不足道”，是因为它由 in-“不”和 significant“有意义、有分量的”构成。significant 来自拉丁语 significare“表示”：signum“标记”加 facere“做”。小到不传达重要意义或不影响结果的事物，就是 insignificant。","originQuery":"insignificant","page":28},{"id":"p29r07a","word":"futile","pair":"fruitless","meaning":"无用的","origin":"Futile 意思是“无用的”，是因为它来自拉丁语 futilis“徒劳、无价值”。该词可能原指容易漏水、盛不住东西，但具体来源并不确定。努力若像倒进漏器一样不能留下成果，就是 futile，因此表示“无效、徒劳的”。","originQuery":"futile","page":28},{"id":"p29r07b","word":"fruitless","pair":"futile","meaning":"无用的","origin":"Fruitless 意思是“无用、无结果的”，是因为它由 fruit“果实、成果”和 -less“没有……”构成。植物不开花结果，投入便没有收获；这个自然图景转用于计划和努力，表示没有产生预期成果，因此是“徒劳的”。","originQuery":"fruitless","page":28},{"id":"p29r08a","word":"autonomy","pair":"independence","meaning":"自主独立","origin":"Autonomy 意思是“自主独立”，是因为它的希腊语构词就是“自己制定法律”。autos“自己”，nomos“法律、规则”。一个群体不受外部统治而按自己的规则行事，就拥有 autonomy；后来也泛指个人自我决定、不被控制的能力。","originQuery":"autonomy","page":28},{"id":"p29r08b","word":"independence","pair":"autonomy","meaning":"自主独立","origin":"Independence 意思是“自主独立”，是因为 depend 的字面图景是“悬挂在某物之下”，in- 表示“不”。depend 来自拉丁语 dependere：de-“向下”，pendere“悬挂”。不悬靠别的支点而存在，就是不依赖，因此能自主决定。","originQuery":"independence","page":28},{"id":"p29r09a","word":"allay","pair":"palliate","meaning":"减轻","origin":"Allay 意思是“减轻”，是因为它来自古英语 ālecgan“放下、使平静”，核心 lecgan 是“放置”。把激烈的恐惧、怀疑或疼痛放下来，强度就会降低；因此 allay 表示“缓和、减轻”，常用于情绪和担忧。","originQuery":"allay","page":28},{"id":"p29r09b","word":"palliate","pair":"allay","meaning":"减轻","origin":"Palliate 意思是“减轻”，是因为它的拉丁语字面义是“用斗篷遮盖”。它来自 palliare，核心 pallium“斗篷”。遮住症状并未消除病因，却能让痛苦暂时不明显；因此 palliate 表示缓解症状或减轻坏处，而非彻底治愈。","originQuery":"palliate","page":28},{"id":"p29r10a","word":"opprobrium","pair":"infamy","meaning":"羞耻","origin":"opprobrium 意思是“羞耻”，是因为拉丁语 opprobrium 指公开的责难和羞辱。它与 ob-“朝向”及 probrum“可耻之事、责骂”有关。把耻辱当面加到某人身上，会使其遭受公众轻蔑；因此 opprobrium 既可指严厉谴责，也可指由此带来的恶名。","originQuery":"opprobrium","page":28},{"id":"p29r10b","word":"infamy","pair":"opprobrium","meaning":"羞耻","origin":"Infamy 意思是“耻辱、恶名”，是因为它来自拉丁语 infamia“坏名声”：in-“否定、坏”，fama“名声、传闻”。一个人的恶行被众人传说，便获得不光彩的名声，因此 infamy 指因罪恶或丑闻而臭名昭著的状态。","originQuery":"infamy","page":28},{"id":"p30r01a","word":"acrimony","pair":"bitterness","meaning":"尖刻，敌意","origin":"Acrimony 意思是“尖刻、敌意”，是因为它原本表示味道的辛辣刺鼻。它来自拉丁语 acrimonia，核心 acer“尖锐”。言语若像辛辣味一样刺痛别人，就带有愤怒和敌意，因此 acrimony 由味觉上的刺激发展为关系中的尖刻。","originQuery":"acrimony","page":29},{"id":"p30r01b","word":"bitterness","pair":"acrimony","meaning":"尖刻，敌意","origin":"Bitterness 意思是“尖刻、敌意”，是因为 bitter 首先形容苦味。它来自古英语 biter“苦的、刺痛的”，与 bite“咬”相关。苦味令人不适，长期怨恨也像苦味留在心中；因此 bitterness 可指怨愤，并表现为尖刻言辞。","originQuery":"bitterness","page":29},{"id":"p30r02a","word":"imprecise","pair":"inexact","meaning":"不精确","origin":"Imprecise 意思是“不精确”，是因为它由 im-“不”和 precise“精确的”构成。precise 来自拉丁语 praecidere“预先切断”：prae-“在前”，caedere“切”。边界切得清楚才精确；界限不清、数值不准，就是 imprecise。","originQuery":"imprecise","page":29},{"id":"p30r02b","word":"inexact","pair":"imprecise","meaning":"不精确","origin":"Inexact 意思是“不精确”，是因为它由 in-“不”和 exact“准确的”构成。exact 来自拉丁语 exigere“衡量、要求”，其过去分词 exactus 有“彻底完成”的意味。没有达到严格测量标准，就存在偏差，因此是 inexact。","originQuery":"inexact","page":29},{"id":"p30r03a","word":"prudent","pair":"provident","meaning":"谨慎，有远见","origin":"Prudent 意思是“谨慎、有远见”，是因为它来自拉丁语 prudens，原是 providens“预见的”的缩合形式。能提前看到行动后果的人会权衡风险，不轻率决定；因此 prudent 把“预见”与“明智谨慎”连接起来。","originQuery":"prudent","page":29},{"id":"p30r03b","word":"provident","pair":"prudent","meaning":"谨慎，有远见","origin":"Provident 意思是“谨慎、有远见”，是因为 provide 的拉丁语字面义是“向前看”。它来自 providere：pro-“在前”，videre“看”。提前看见未来需要，就会预先储备、谨慎安排，因此 provident 表示“有先见之明、未雨绸缪的”。","originQuery":"provident","page":29},{"id":"p30r04a","word":"unfathomable","pair":"inscrutable","meaning":"高深莫测","origin":"Unfathomable 意思是“高深莫测”，是因为 fathom 原指用张开双臂的长度测量水深。un-“不能”，-able“能够被……”。深水若长线也量不到底，就是 unfathomable；这个图景转用于思想或动机，表示深到无法理解。","originQuery":"unfathomable","page":29},{"id":"p30r04b","word":"inscrutable","pair":"unfathomable","meaning":"高深莫测","origin":"Inscrutable 意思是“高深莫测”，是因为它来自拉丁语 inscrutabilis“无法探究的”。in-“不能”，scrutari“彻底搜索”，与 scruta“破布、杂物”有关。即使仔细翻查也找不到答案的事物，就是难以理解、不可测知的。","originQuery":"inscrutable","page":29},{"id":"p30r05a","word":"indiscernible","pair":"imperceptible","meaning":"难以察觉的","origin":"Indiscernible 意思是“难以察觉的”，是因为它表示“无法分辨出来”。in-“不”，discern“辨别”，-ible“能够被……”；discern 又来自拉丁语 discernere，含“分开、筛分”之意。若两个事物相似到不能分开辨认，或信号弱到看不出，就称为 indiscernible。","originQuery":"indiscernible","page":29},{"id":"p30r05b","word":"imperceptible","pair":"indiscernible","meaning":"难以察觉的","origin":"Imperceptible 意思是“难以察觉的”，是因为它由 im-“不”与 perceptible“能够被感知的”构成。perceptible 来自拉丁语 percipere“完全抓取、领会”，-ible 表示“能够被……”。小到感官或头脑无法“抓住”的变化，就难以察觉，因此是 imperceptible。","originQuery":"imperceptible","page":29},{"id":"p30r06a","word":"tributes","pair":"encomiums","meaning":"赞美","origin":"Tributes 意思是“赞美”，是因为 tribute 从“应当交付的贡品”发展成了“表示敬意而献上的东西”。它来自拉丁语 tributum“摊派物、贡税”，与 tribus“部族”有关。后来，人们把献给某人的礼物、言辞或作品也称为 tribute，于是复数 tributes 可指一连串致敬或赞美。","originQuery":"tribute","page":29},{"id":"p30r06b","word":"encomiums","pair":"tributes","meaning":"赞美","origin":"Encomiums 意思是“赞美”，是因为它原本就指公开颂扬某人的赞歌或颂词。单数 encomium 来自希腊语 enkōmion：en- 表示“在……之中”，kōmos 指宴饮游行，早期是宴会上赞颂英雄的诗歌。由“赞歌”扩大为任何高度赞扬的话，所以复数 encomiums 就是“赞美之词”。","originQuery":"encomium","page":29},{"id":"p30r07a","word":"charitable","pair":"forbearing","meaning":"宽容","origin":"Charitable 意思是“宽容”，是因为 charity 最初指基督教意义上的仁爱。它经古法语来自拉丁语 caritas“爱、珍贵”，核心 carus 是“亲爱的”。以善意看待别人，就会体谅其错误并作较宽厚解释，因此 charitable 可表示“宽容、不苛刻的”。","originQuery":"charitable","page":29},{"id":"p30r07b","word":"forbearing","pair":"charitable","meaning":"宽容","origin":"Forbearing 意思是“宽容”，是因为 forbear 来自古英语 forberan“忍住、克制”，其中 for- 有抑制作用，beran 是“承受”。面对冒犯仍承受下来、不立即报复，就是 forbear；forbearing 因此形容人耐心自制、能够宽容。","originQuery":"forbear","page":29},{"id":"p30r08a","word":"probity","pair":"integrity","meaning":"正直","origin":"Probity 意思是“正直”，是因为它来自拉丁语 probitas“善良、诚实”，核心 probus 表示“好、正直、经检验合格”。一个人的品格若经得起检验、符合道德标准，就值得信赖，因此 probity 指严格的诚实和正直。","originQuery":"probity","page":29},{"id":"p30r08b","word":"integrity","pair":"probity","meaning":"正直","origin":"Integrity 意思是“正直”，是因为它原本表示“完整、未受损”。它来自拉丁语 integritas，核心 integer 是“完整的”。品格完整的人不会因利益而裂成两套标准，言行保持一致；因此 integrity 从“完整性”发展为“诚实正直”。","originQuery":"integrity","page":29},{"id":"p30r09a","word":"advantageous","pair":"expedient","meaning":"有利的","origin":"Advantageous 意思是“有利的”，是因为 advantage 原指处在前面的位置。它经古法语 avantage 形成，与 avant“在前”有关；-ous 表示具有这种性质。位置领先会带来更好机会，因此 advantageous 表示能够给予优势、帮助成功的。","originQuery":"advantageous","page":29},{"id":"p30r09b","word":"expedient","pair":"advantageous","meaning":"有利的","origin":"Expedient 意思是“有利、合宜的”，是因为拉丁语 expedire 的字面图景是“把脚解开”。ex-“脱离”，pes/pedis“脚”。脚从束缚中解放后能顺利前进，因此 expedient 表示有助于达成目的的办法；有时暗含只顾眼前方便。","originQuery":"expedient","page":29},{"id":"p30r10a","word":"slanted","pair":"tendentious","meaning":"有偏见的","origin":"Slanted 意思是“有偏见的”，是因为 slant 本义是倾斜、偏向一侧。它可能来自斯堪的纳维亚或日耳曼语相关形式，更早来源不确定。报道若不像水平面那样中正，而朝某一立场倾斜，就不是客观呈现，因此是 slanted。","originQuery":"slant","page":29},{"id":"p30r10b","word":"tendentious","pair":"slanted","meaning":"有偏见的","origin":"Tendentious 意思是“有偏见的”，是因为它表示内容带有明显 tendency“倾向”，而不是中立呈现。它经德语 tendenziös 形成，根源与拉丁语 tendere“伸向、趋向”有关。论述若刻意朝某一立场推进，就带有导向性，因此 tendentious 指“倾向性强、偏颇的”。","originQuery":"tendentious","page":29},{"id":"p31r01a","word":"manifest","pair":"obvious","meaning":"显而易见","origin":"manifest 意思是“显而易见”，是因为拉丁语 manifestus 表示“明显、可直接察觉的”。其更早构成有争议，常与 manus“手”和“抓住”相联系，可理解为清楚得仿佛能用手触到。事实若显而易见，无须再解释，因此 manifest 可译为“明显的、不言自明的”。","originQuery":"manifest","page":30},{"id":"p31r01b","word":"obvious","pair":"manifest","meaning":"显而易见","origin":"Obvious 意思是“显而易见”，是因为拉丁语 obvius 的字面义是“在路上迎面而来”。ob-“朝向”，via“道路”。某物直接挡在眼前，根本无法错过，因此 obvious 从“迎面可见”发展为“不需解释也清楚的”。","originQuery":"obvious","page":30},{"id":"p31r02a","word":"questionable","pair":"dubious","meaning":"值得怀疑的","origin":"Questionable 意思是“值得怀疑的”，是因为它由 question“质问、疑问”与 -able“可以、值得被……”构成。一个说法若会引出合理质问，真实性或正当性就不稳固；因此 questionable 表示“可疑的”，有时也指品格不佳。","originQuery":"questionable","page":30},{"id":"p31r02b","word":"dubious","pair":"questionable","meaning":"值得怀疑的","origin":"Dubious 意思是“值得怀疑的”，是因为它来自拉丁语 dubius“摇摆、不确定”，与 duo“二”相关。面对两个方向而不能决定，就产生怀疑；因此 dubious 可形容证据不可靠，也可形容人心存疑虑。","originQuery":"dubious","page":30},{"id":"p31r03a","word":"atypical","pair":"idiosyncratic","meaning":"非典型的","origin":"Atypical 意思是“非典型的”，是因为它由希腊来源的否定前缀 a-“不”和 typical“典型的”构成。type 来自希腊语 typos“印记、模型”。不符合通常模型或代表性特征的事物，就是 atypical。","originQuery":"atypical","page":30},{"id":"p31r03b","word":"idiosyncratic","pair":"atypical","meaning":"非典型的","origin":"idiosyncratic 意思是“非典型的”，是因为 idiosyncrasy 原指个人特有的体质或气质。它来自希腊语 idios“个人自己的”与 synkrasis“混合、性情”。每个人独有的“成分组合”会产生不同习惯和风格，因此 idiosyncratic 表示“个人特有、不同寻常的”。","originQuery":"idiosyncratic","page":30},{"id":"p31r04a","word":"gainsaid","pair":"disputed","meaning":"否认","origin":"Gainsaid 意思是“否认”，是因为它是 gainsay 的过去式；gainsay 由中古英语 gain-“反对”和 say“说”构成，字面就是“说反对的话”。这里 gain 与现代“获得”无关。对一个主张说出相反意见，就是否认或反驳它。","originQuery":"gainsaid","page":30},{"id":"p31r04b","word":"disputed","pair":"gainsaid","meaning":"否认","origin":"Disputed 意思是“否认、质疑”，是因为 dispute 来自拉丁语 disputare“讨论、争论”，由 dis-“分开”与 putare“思考、计算”构成。双方把论点分开检验并提出反对，便不接受其真实性；因此 disputed 可表示“有争议、被质疑的”。","originQuery":"dispute","page":30},{"id":"p31r05a","word":"mainstream","pair":"conventional","meaning":"主流，传统","origin":"Mainstream 意思是“主流、传统”，是因为它由 main“主要的”与 stream“水流”构成。河流的主要水道承载最多水量；这个图景转用于社会意见和文化，表示多数人沿着的主要方向。长期占主导的主流也往往成为传统。","originQuery":"mainstream","page":30},{"id":"p31r05b","word":"conventional","pair":"mainstream","meaning":"主流，传统","origin":"Conventional 意思是“主流、传统的”，是因为 convention 原指人们聚到一起所达成的协议。它来自拉丁语 convenire“共同来到”：con-“共同”，venire“来”。大家共同接受并长期遵循的做法会成为社会惯例，因此 conventional 表示“依照惯例、传统而非创新的”。","originQuery":"conventional","page":30},{"id":"p31r06a","word":"inert","pair":"dormant","meaning":"惰性的","origin":"inert 意思是“惰性的”，是因为拉丁语 iners 直指“没有技艺、不能行动”。它由否定前缀 in-“无”与 ars“技艺、能力”相关的成分构成，早期可形容懒散或无能。后来物理学用 inert 表示不自行改变运动状态，由“不行动”自然得到“迟钝、无活力的”。","originQuery":"inert","page":30},{"id":"p31r06b","word":"dormant","pair":"inert","meaning":"惰性的","origin":"Dormant 意思是“惰性、休眠的”，是因为它来自古法语 dormant“睡着的”，核心拉丁语 dormire 就是“睡觉”。睡眠中的人暂时不活动，但仍保留醒来的可能；因此 dormant 可形容火山、种子或力量处于静止潜伏状态，而非彻底消失。","originQuery":"dormant","page":30},{"id":"p31r07a","word":"punctuated","pair":"intermittent","meaning":"间断的","origin":"Punctuated 意思是“间断的”，是因为 punctuate 的核心是用点把连续内容分开。它来自拉丁语 punctus“刺点、点”，与 pungere“刺”有关。标点在连续句流中插入停顿；因此 be punctuated by 表示一个过程不时被某些事件打断或穿插。","originQuery":"punctuate","page":30},{"id":"p31r07b","word":"intermittent","pair":"punctuated","meaning":"间断的","origin":"Intermittent 意思是“间断的”，是因为它来自拉丁语 intermittere“在中间放开、暂停”：inter-“在……之间”，mittere“放、送”。一个过程进行一段后停下，随后又恢复，中间留下空隙；因此 intermittent 表示时有时无、断断续续的。","originQuery":"intermittent","page":30},{"id":"p31r08a","word":"iconoclastic","pair":"subversive","meaning":"反传统","origin":"iconoclastic 意思是“反传统的”，是因为它最初指“破坏圣像”。它来自希腊语 eikon（形象、圣像）和 klastes（打破者）：敢打破宗教圣像的人，也就是在挑战当时的权威与正统。词义后来扩大为打破任何根深蒂固的观念或制度，因而表示“反传统的”。","originQuery":"iconoclastic","page":30},{"id":"p31r08b","word":"subversive","pair":"iconoclastic","meaning":"反传统","origin":"subversive 意思是“颠覆性的、反传统的”，是因为它的词源核心是“从下面翻转”。sub- 有“在下面”之意，vertere 在拉丁语中是“转、翻”。把一种秩序从根基处翻倒，就是破坏或颠覆现有制度；再引申为思想、艺术等对传统的挑战。同源词 subvert 即“颠覆”。","originQuery":"subversive","page":30},{"id":"p31r09a","word":"prudent","pair":"circumspect","meaning":"谨慎","origin":"prudent 意思是“谨慎的”，是因为它原本强调“提前看清”。它来自拉丁语 providere，由 pro-（向前）和 videre（看）组成，经语音变化成 prudent。能向前看，就能预见后果并在行动前权衡风险，所以词义从“有远见”发展为“审慎、谨慎”。相关词是 prudence（谨慎）。","originQuery":"prudent","page":30},{"id":"p31r09b","word":"circumspect","pair":"prudent","meaning":"谨慎","origin":"circumspect 意思是“谨慎的”，是因为它字面上是“向四周看”。circum- 表示“周围”，spect 来自拉丁语 specere（看）。行动前先环顾四周，意味着把各方面的情况和危险都纳入考量；因此它从具体的“四下观看”演变为“考虑周全、行事谨慎”。","originQuery":"circumspect","page":30},{"id":"p31r10a","word":"coercive","pair":"imperious","meaning":"强制的","origin":"coercive 意思是“强制的”，是因为它的历史核心是“限制、约束”。它来自拉丁语 coercere，大致由 co-（一起、完全）和 arcere（关起来、阻止）构成。先是把人约束在一定范围内，再引申为用压力迫使其服从，因而 coercive 表示借威胁或权力强制人的。","originQuery":"coercive","page":30},{"id":"p31r10b","word":"imperious","pair":"coercive","meaning":"强制的","origin":"imperious 意思是“专横的、命令式的”，是因为它来自拉丁语 imperium，即“命令权、统治权”。拥有 imperium 的人能发号施令，因此这个词最初可表示“具有最高权威的”；后来语气越来越负面，专指像统治者一样命令别人、不容质疑的态度。","originQuery":"imperious","page":30},{"id":"p32r01a","word":"anonymous","pair":"unrecognized","meaning":"不知名的","origin":"anonymous 意思是“不知名的”，是因为它的希腊语构词就是“没有名字”。an-“没有”，onyma/onoma“名字”，-ous 构成形容词。没有署名的人或作品无法凭姓名被识别，因此 anonymous 首先是“匿名的”；一个人若不为公众所知，也可由此表示“籍籍无名的”。","originQuery":"anonymous","page":31},{"id":"p32r01b","word":"unrecognized","pair":"anonymous","meaning":"不知名的","origin":"unrecognized 意思是“未被认出或不知名的”，是因为它表示“没有被再次辨认出来”。un- 表示否定，recognize 源自拉丁语 recognoscere：re- 有“再、重新”之意，cognoscere 表示“认知”。一个人或事物若未被人辨认、承认或注意，就会显得“不知名”。","originQuery":"unrecognized","page":31},{"id":"p32r02a","word":"contentious","pair":"controversial","meaning":"引起争议的","origin":"contentious 意思是“引起争议的”，是因为它来自拉丁语 contentio“争斗、辩论”。其动词 contendere 由 con-“共同、相对”与 tendere“拉伸、用力”构成，可理解为双方朝相反方向较劲。容易引起这种争夺或争论的问题，就是 contentious，即“有争议的”。","originQuery":"contentious","page":31},{"id":"p32r02b","word":"controversial","pair":"contentious","meaning":"引起争议的","origin":"controversial 意思是“引起争议的”，是因为它的词源画面是“向相反方向转”。contra- 在拉丁语中表示“相反、对着”，vertere 表示“转”。当人们的观点转向对立两方，就形成争论；所以 controversy 是“争议”，controversial 就是会使意见分裂的。","originQuery":"controversial","page":31},{"id":"p32r03a","word":"ubiquitous","pair":"pervasive","meaning":"无处不在","origin":"Ubiquitous 意思是“无处不在”，是因为它来自拉丁语 ubique“到处、在每个地方”。ubique 由 ubi“哪里”与表示普遍性的 -que 组成，后来形成 ubiquity“无所不在”和形容词 ubiquitous。某物若在每个地方都能遇见，自然就是“无处不在的”。","originQuery":"ubiquitous","page":31},{"id":"p32r03b","word":"pervasive","pair":"ubiquitous","meaning":"无处不在","origin":"pervasive 意思是“遍布的、无处不在的”，是因为它的词源核心是“穿过各处”。per- 表示“穿过、彻底”，vadere 在拉丁语中是“走、前进”。某种气味、思想或影响若一路渗透并进入所有地方，就会遍及整个环境；因而引申为“广泛存在的”。","originQuery":"pervasive","page":31},{"id":"p32r04a","word":"inferred","pair":"surmised","meaning":"推测","origin":"inferred 意思是“推测出的”，是因为 infer 的词源核心是“带入”。它来自拉丁语 inferre，in- 表示“入、向内”，ferre 表示“带、携带”。词义从把某事“带入”讨论或结果，发展为根据已知证据引入一个未明说的结论，也就是“推断、推测”。","originQuery":"infer","page":31},{"id":"p32r04b","word":"surmised","pair":"inferred","meaning":"推测","origin":"surmised 意思是“推测出的”，是因为 surmise 最初与“加在前事之上的判断”有关。它经古法语来自拉丁语 supermittere，super- 是“在上”，mittere 是“放、送”。中世纪时它曾指一项附加的指控，后来转为在证据不完全时加上的判断，即“猜测”。","originQuery":"surmise","page":31},{"id":"p32r05a","word":"fade","pair":"wane","meaning":"逐渐减弱","origin":"fade 意思是“逐渐减弱或消退”，是因为它最早表示“失去光泽、变得枯萎”。这个词经古法语传入英语，更远词源可能与“乏味、衰弱”有关。颜色失去鲜明是一个缓慢过程，因此词义扩展到声音、记忆、力量等慢慢变弱直至消失。","originQuery":"fade","page":31},{"id":"p32r05b","word":"wane","pair":"fade","meaning":"逐渐减弱","origin":"wane 意思是“逐渐减弱”，是因为它最典型的画面是月亮在满月后逐日“亏缺”。它来自古英语 wanian，表示“减少、衰退”，与 want 早期的“缺少”含义有关。由月轮一点点变小，很自然地引申为力量、兴趣、影响等持续下降。","originQuery":"wane","page":31},{"id":"p32r06a","word":"lay","pair":"avocational","meaning":"非职业的","origin":"lay 意思是“非职业的、外行的”，是因为它最初指“不属于神职人员的人”。它经古法语 lai 来自希腊语 laikos，意为“属于人民的”，laos 就是“人民”。在教会语境中，普通信徒不是专业神职者；这种对比后来扩展到任何领域，表示“非专业人士的”。","originQuery":"lay","page":31},{"id":"p32r06b","word":"avocational","pair":"lay","meaning":"非职业的","origin":"avocational 意思是“业余的、非职业的”，是因为 avocation 原指“把人从主要事务中叫开的事”。它来自拉丁语 avocare，a- 有“离开”之意，vocare 是“呼叫”。从本职工作旁边把人“叫走”的活动，通常就是兴趣或副业，因而形容非主业、业余性质的事。","originQuery":"avocational","page":31},{"id":"p32r07a","word":"substantiality","pair":"soundness","meaning":"坚实可靠","origin":"substantiality 意思是“实质性、坚实可靠”，是因为它的词根表示“站在下面支撑的东西”。sub- 是“在下”，stare 在拉丁语中是“站立”，substantia 因而指事物的根底、实体或本质。有足够“实体”就不是空洞虚弱的，所以 substantiality 可表示分量、牢靠性与实质。","originQuery":"substantial","page":31},{"id":"p32r07b","word":"soundness","pair":"substantiality","meaning":"坚实可靠","origin":"soundness 意思是“健全、坚实可靠”，是因为这里的 sound 最初表示“完好、健康”，与“声音”的 sound 词源不同。它来自古英语 sund，用于身体时是没有伤病，用于物体时是没有腐坏或裂缝。这种“无缺陷”的状态再引申为论证、判断或结构可靠。","originQuery":"soundness","page":31},{"id":"p32r08a","word":"recondite","pair":"esoteric","meaning":"深奥的","origin":"recondite 意思是“深奥的”，是因为它原本就有“藏起来的”之意。它来自拉丁语 recondere，re- 在此有“向后”的感觉，condere 表示“收藏、放置”。知识如果像被收藏在深处，就不是一眼能懂、普通人易于接触的；因此词义发展为“隐秘难懂的、深奥的”。","originQuery":"recondite","page":31},{"id":"p32r08b","word":"esoteric","pair":"recondite","meaning":"深奥的","origin":"esoteric 意思是“深奥难懂的”，是因为它最初指“传给内部人士的”知识。它来自希腊语 esoterikos，核心是 esotero（更内部）。只在小圈子内传授的学说，外人很难接触或理解；于是词义从“内传的”扩大为“仅少数专门人士懂的、深奥的”。","originQuery":"esoteric","page":31},{"id":"p32r09a","word":"swill","pair":"guzzle","meaning":"痛饮","origin":"swill 意思是“痛饮、大口灌下”，是因为它早期指“冲洗”以及用液体来回晃荡。它来自古英语 swillan，表示洗涤或漂洗。大量液体在容器中冲来荡去的画面，后来被用来形容人毫不节制地把酒或饮料灌进肚里，因而带有粗鲁、过量饮用的语气。","originQuery":"swill","page":31},{"id":"p32r09b","word":"guzzle","pair":"swill","meaning":"痛饮","origin":"guzzle 意思是“痛饮、狂饮”，是因为它从一开始就带有大口吞咽的动作感。该词在中古英语后期出现，可能是模仿吞饮时喉咙发出的声音，具体词源并不完全确定。它先指贪婪地喝，后也可扩展到大量消耗燃料等，核心都是“又快又多地吞下”。","originQuery":"guzzle","page":31},{"id":"p32r10a","word":"paragons","pair":"exemplars","meaning":"典范","origin":"paragons 意思是“典范、模范”，是因为 paragon 原本指用来检验贵金属纯度的“试金石”。它经法语来自意大利语 paragone，核心是“比较、测试”。能作为检验其他东西的标准，自身就被视为最优秀的尺度；因此词义发展为某种品质的完美典范。","originQuery":"paragon","page":31},{"id":"p32r10b","word":"exemplars","pair":"paragons","meaning":"典范","origin":"exemplars 意思是“典范、榜样”，是因为 exemplar 原指供人复制或仿照的“样本”。它来自拉丁语 exemplum（例子、样本），与 example 同源。一个样本如果值得别人照着做，就成了评判或行动的标准；所以词义从“可供复制的原型”发展为“值得效仿的典范”。","originQuery":"exemplar","page":31},{"id":"p33r01a","word":"ungainly","pair":"awkward","meaning":"笨拙的","origin":"Ungainly 意思是“笨拙的”，是因为它由 un-“不”和古义 gainly“合适、灵巧”构成。gainly 与古诺斯语 gegn“直、合适”相关，不能按现代 gain“获得”来拆。动作若不合适、不便利，就显得难看而笨拙，因此 ungainly 形容体态或动作不协调。","originQuery":"ungainly","page":32},{"id":"p33r01b","word":"awkward","pair":"ungainly","meaning":"笨拙的","origin":"Awkward 意思是“笨拙的”，是因为它原本带有“方向不对、反手而行”的感觉。中古英语 awk 表示“反向、错误”，-ward 表示“朝向”。朝不顺手的方向动作，自然显得不灵便；这个空间与动作上的“不对劲”后来扩展到社交场面，表示尴尬、不自然。","originQuery":"awkward","page":32},{"id":"p33r02a","word":"invention","pair":"contrivance","meaning":"创造力","origin":"invention 意思是“创造力”，是因为 invent 的拉丁语字面义是“遇到、发现”。它来自 invenire：in-“进入、在……上”，venire“来”。头脑“找到”一个新构想就是发明；若找到的是为解释而造出的说法，invention 也可贬义表示“捏造、虚构”。","originQuery":"invention","page":32},{"id":"p33r02b","word":"contrivance","pair":"invention","meaning":"创造力","origin":"contrivance 意思是“巧思、创制出的装置”，是因为 contrive 的早期核心是“找到、想出”。它经古法语可追溯到拉丁语 contropare，大致表示“找出、设想”。遇到问题后设法想出手段，既需要创造力，也会产生特别设计的机械或方法；因而它可指“巧妙的构思”或“发明的装置”。","originQuery":"contrivance","page":32},{"id":"p33r03a","word":"elisions","pair":"lacunae","meaning":"省略","origin":"elisions 意思是“省略”，是因为 elision 的词源核心是“把某物击出去”。它来自拉丁语 elidere，e- 表示“向外”，laedere 表示“撞击、伤害”。在发音中，一个音被“挤出”而不再读出，就是语音省略；后来这一概念也扩大到文字、叙事或内容的删去。","originQuery":"elision","page":32},{"id":"p33r03b","word":"lacunae","pair":"elisions","meaning":"省略","origin":"lacunae 意思是“空白、缺漏”，是因为 lacuna 在拉丁语中原指“池水、凹坑”。它与 lacus（湖）同源，lacunae 是其复数形式。一个表面上的凹坑是本应平整之处出现的空缺；这个空间画面后来被用于手稿、记录或知识中本应有内容却缺失的部分。","originQuery":"lacunae","page":32},{"id":"p33r04a","word":"itinerants","pair":"peripatetics","meaning":"流动的，巡游的","origin":"itinerants 意思是“流动的，巡游的”，是因为它直接来自表示“旅行”的拉丁语。晚期拉丁语 itinerari 意为“旅行”，核心 iter、itineris 是“旅程、道路”；-ant 表示从事动作的人或性质。没有固定地点而沿路线不断移动的人，就是 itinerant，如巡回工人或游方传教者。","originQuery":"itinerant","page":32},{"id":"p33r04b","word":"peripatetics","pair":"itinerants","meaning":"流动的，巡游的","origin":"peripatetics 意思是“流动的，巡游的”，是因为希腊语 peripatein 表示“来回行走”：peri-“周围”，patein“走”。该词先指亚里士多德的逍遥学派，传统上与边走边讲学联系。后来离开哲学专名，泛指从一地走到另一地、没有固定居所或工作地点。","originQuery":"peripatetic","page":32},{"id":"p33r05a","word":"unreceptive","pair":"inhospitable","meaning":"不接受的","origin":"unreceptive 意思是“不愿接受的”，是因为它直接否定了 receptive 所含的“能接住”。un- 表示“不”，receptive 来自拉丁语 recipere：re- 有“回、向后”之意，capere 是“取、拿”。能把外来之物接进来，就是愿意吸收意见或感受影响；加上 un- 后便表示拒绝、不开放。","originQuery":"unreceptive","page":32},{"id":"p33r05b","word":"inhospitable","pair":"unreceptive","meaning":"不接受的","origin":"inhospitable 意思是“不好客的、不适宜接纳的”，是因为它否定了 hospitable 的“待客友好”。in- 表示“不”，hospitable 的词根来自拉丁语 hospes，兼有“客人”和“主人”之意。不肯开门接待客人，就是不友好、不接纳；还可引申为环境恶劣，不适合生命居住。","originQuery":"inhospitable","page":32},{"id":"p33r06a","word":"eschew","pair":"forgo","meaning":"避开放弃","origin":"eschew 意思是“避开放弃”，是因为 eschew 经古法语 eschiver 进入英语，早期就表示“躲避、远离”。其更早来源与日耳曼语中“害怕、避开”的词有关。因认为某物有害或不合原则而主动不用它，就是 eschew；eschewing 表示持续回避。","originQuery":"eschew","page":32},{"id":"p33r06b","word":"forgo","pair":"eschew","meaning":"避开放弃","origin":"forgo 意思是“放弃、不取用”，是因为古英语前缀 for- 有“离开、彻底”的含义，go 就是“去”。这个词可以理解为让某物“彻底离去”，也就是不再保留或享用它。因此它常用于主动舍弃原本可以得到的权利、乐趣或机会。注意不要与 forego（在前面、先于）混淆。","originQuery":"forgo","page":32},{"id":"p33r07a","word":"marred","pair":"tainted","meaning":"受损的","origin":"marred 意思是“被损坏、被破坏美感的”，是因为 mar 在古英语中就表示“毁坏、损伤”。它来自古英语 merran，与阻碍、扰乱的概念有关。一个瑕疵会打断原本完整顺畅的状态，因而 mar 常不是指彻底摧毁，而是使外观、品质或经历因缺陷而受损。","originQuery":"mar","page":32},{"id":"p33r07b","word":"tainted","pair":"marred","meaning":"受损的","origin":"tainted 意思是“被污染、受损的”，是因为 taint 的历史含义是“着色、染上痕迹”。它是 attaint 的短形，经古法语与拉丁语 tangere（触碰）有关。某物被不好的东西碰及后留下颜色或污点，就不再纯净；因此它既可指食物、水的污染，也可指声誉、品质受损。","originQuery":"taint","page":32},{"id":"p33r08a","word":"judicious","pair":"sensible","meaning":"明智的","origin":"judicious 意思是“明智而审慎的”，是因为它的词根就是“判断”。它来自拉丁语 judicium（审判、判断），与 judge、judicial 同源。好的判官不能凭冲动决定，而要衡量证据并作出恰当选择；因此它从“关于判断的”发展为“判断力良好、处理得当的”。","originQuery":"judicious","page":32},{"id":"p33r08b","word":"sensible","pair":"judicious","meaning":"明智的","origin":"sensible 意思是“明智的、合理的”，是因为它原本表示“能感知的”。它来自拉丁语 sensibilis，词根 sentire 是“感觉、意识到”，与 sense 同源。一个人能对现实情况有正常感知，就会作出符合常识的选择；所以词义从“有感觉的”引申为“通情达理、明智”。","originQuery":"sensible","page":32},{"id":"p33r09a","word":"temper","pair":"neutralize","meaning":"缓和","origin":"temper 意思是“使缓和、使适度”，是因为它的词源核心是“按正确比例调和”。它来自拉丁语 temperare，表示混合、调节或节制。把过冷、过热或过强的东西加以调配，会使它回到合适程度；因而 temper 可表示削弱力量、缓和语气或节制情绪。","originQuery":"temper","page":32},{"id":"p33r09b","word":"neutralize","pair":"temper","meaning":"缓和","origin":"neutralize 意思是“缓和”，是因为 neutralize 表示“使变成中性或无效”。neutral 来自拉丁语 neutralis，与 neuter“二者皆非”有关；-ize 表示“使成为”。把一种力量变成“不站任何一边”的状态，就是抵消其效力，因此 neutralized 可指“被抵消、被压制”。","originQuery":"neutralize","page":32},{"id":"p33r10a","word":"sizable","pair":"substantial","meaning":"大量的，重大的","origin":"sizable 意思是“相当大的、数量可观的”，是因为它由 size（大小、尺寸）和 -able（可……的）构成。它早期可表示“有一定大小的”或“大小合适的”，但在比较中，特别值得提及尺寸，往往是因为它不小。因此现代常用来表示金额、数量或程度“颇大、可观”。","originQuery":"sizable","page":32},{"id":"p33r10b","word":"substantial","pair":"sizable","meaning":"大量的，重大的","origin":"substantial 意思是“大量的、重大的”，是因为它原本表示“具有真实实体的”。它来自拉丁语 substantia，sub- 是“在下”，stare 是“站立”，即支撑事物的实质。一个东西若有充分实体，就不是轻微或空洞的；因而词义扩展为数量很大、分量很重或内容充实。","originQuery":"substantial","page":32},{"id":"p34r01a","word":"choleric","pair":"irascible","meaning":"易怒的","origin":"choleric 意思是“易怒的”，是因为古代体液学说认为“黄胆汁”过多会使人暴躁。它来自希腊语 khole（胆汁），经拉丁语和法语进入英语。按当时的四体液理论，黄胆汁占优势的人性情火爆、容易发怒；虽然这一医学观念已过时，其性格含义保留了下来。","originQuery":"choleric","page":33},{"id":"p34r01b","word":"irascible","pair":"choleric","meaning":"易怒的","origin":"irascible 意思是“易怒的”，是因为它直接来自拉丁语中表示“发怒”的动词 irasci。这个词的重点不是一次具体的愤怒，而是“容易进入发怒状态”的性质。因而 irascible 专用来形容脾气急躁、稍受刺激就动怒的人。同源词 ire 表示“愤怒”。","originQuery":"irascible","page":33},{"id":"p34r02a","word":"patent","pair":"manifest","meaning":"明显的","origin":"patent 意思是“明显的”，是因为它原本表示“打开的、敞开的”。它来自拉丁语 patere，意为“开着、暴露在外”。东西若完全敞开在人眼前，就不需推理也能看清，所以词义发展为“显而易见的”。“专利”含义则来自 letters patent，即向公众敞开的官方文书。","originQuery":"patent","page":33},{"id":"p34r02b","word":"manifest","pair":"patent","meaning":"明显的","origin":"manifest 意思是“明显的”，是因为拉丁语 manifestus 表示“明显、可直接察觉的”。其更早构成有争议，常与 manus“手”和“抓住”相联系，可理解为清楚得仿佛能用手触到。事实若显而易见，无须再解释，因此 manifest 可译为“明显的、不言自明的”。","originQuery":"manifest","page":33},{"id":"p34r03a","word":"deftly","pair":"adroitly","meaning":"熟练地","origin":"deftly 意思是“熟练地、灵巧地”，是因为 deft 在古英语中原有“温和、合适”之意。它来自古英语 gedæfte，表示柔和、温顺或适宜。动作做得恰到好处，既不生硬也不笨拙，便给人技艺熟练、手法轻巧的感觉；因此 deft 逐渐专指巧妙有技巧，deftly 就是以这种方式行事。","originQuery":"deftly","page":33},{"id":"p34r03b","word":"adroitly","pair":"deftly","meaning":"熟练地","origin":"adroitly 意思是“熟练地、巧妙地”，是因为 adroit 在法语中字面上有“向右边”的意思。它来自法语 à droit，droit 表示“右、正确”。在传统观念中，右手是多数人更灵活、更擅长操作的手，所以“在右边”逐渐引申为手脚利落、处事机敏；adroitly 就是熟练灵巧地。","originQuery":"adroit","page":33},{"id":"p34r04a","word":"uncertain","pair":"tenuous","meaning":"不确定的","origin":"Uncertain 意思是“不确定的”，是因为它由 un-“不”和 certain“确定的”构成。certain 经法语来自拉丁语 certus“已决定的、可靠的”，与 discern 的“区分、决定”概念相关。事实若尚未定下或无法可靠知道，就是 uncertain，可指结果、信息或人的态度不确定。","originQuery":"uncertain","page":33},{"id":"p34r04b","word":"tenuous","pair":"uncertain","meaning":"不确定的","origin":"tenuous 意思是“薄弱的、不确定的”，是因为它的拉丁语根 tenuis 就是“细、薄”。一条线如果很细，就容易断；一层东西如果很薄，就缺少厚度和支撑。因此这个具体概念被用来形容证据、联系或论点“薄弱”，也就是牵强、不稳固或不确定。同源词 attenuate 意为“使变薄、减弱”。","originQuery":"tenuous","page":33},{"id":"p34r05a","word":"abundant","pair":"dominant","meaning":"丰富的","origin":"abundant 意思是“丰富的”，是因为它的词源画面是水多得“溢出河岸”。它来自拉丁语 abundare，ab- 表示“从……向外”，unda 是“波浪”。水量充沛到漫出边界，是“多得有余”的直观画面；因此词义从水势盛大扩展到资源、数量或品质充足而丰富。","originQuery":"abundant","page":33},{"id":"p34r05b","word":"dominant","pair":"abundant","meaning":"丰富的","origin":"dominant 意思是“占主导地位的”，是因为它的词根原指“主人、统治者”，并不是“丰富的”。它来自拉丁语 dominari（统治），词根 dominus 是“主人”。主人在家中掌控决定，因而 dominant 从“统治的”发展为某个因素、特征或群体比其他更强，占据支配位置。","originQuery":"dominant","page":33},{"id":"p34r06a","word":"brazen","pair":"barefaced","meaning":"厚颜无耻","origin":"brazen 意思是“厚颜无耻的”，是因为它原本表示“黄铜制的”。它由 brass（黄铜）的古形加形容词后缀 -en 构成。黄铜表面坚硬、闪亮，而且敲击时声音响亮；这种毫不遮掩、甚至刺眼刺耳的特性，后来被比喻为人做了不当之事仍公然无愧，即“厚颜无耻”。","originQuery":"brazen","page":33},{"id":"p34r06b","word":"barefaced","pair":"brazen","meaning":"厚颜无耻","origin":"barefaced 意思是“厚颜无耻的、公然的”，是因为它字面上就是“脸毫无遮掩”。bare 是“裸露的”，faced 表示“有……面孔的”。早期它可形容不戴面具、不留胡须等真正露出脸的状态；后来“不遮脸”变成道德比喻，指人做坏事时不知羞耻，连掩饰都不屑。","originQuery":"barefaced","page":33},{"id":"p34r07a","word":"disdain","pair":"scorn","meaning":"蔑视","origin":"Disdain 意思是“蔑视”，是因为它的历史核心是“认为不值得”。它经古法语 desdeignier 来自拉丁语 dedignari，核心 dignus 是“值得的”，否定成分表示“不认为有价值”。把某人看作不配得到尊重，就产生轻视态度，因此 disdain 表示“鄙视、不屑”。","originQuery":"disdain","page":33},{"id":"p34r07b","word":"scorn","pair":"disdain","meaning":"蔑视","origin":"scorn 意思是“鄙视、轻蔑”，是因为它早期就指对某人或某物的“嘲笑与鄙薄”。它经古法语 escarn 进入英语，更远词源不确定，可能与日耳曼语中的嘲弄观念有关。嘲笑别人的前提往往是认为对方不值得尊重；因此词义从外显的嘲弄动作，集中到内心的轻蔑和鄙视。","originQuery":"scorn","page":33},{"id":"p34r08a","word":"pacific","pair":"dovish","meaning":"温和，和平的","origin":"pacific 意思是“和平的、温和的”，是因为它的词源核心是“创造和平”。它来自拉丁语 pacificus，pax/pac- 表示“和平”，facere 表示“做、造成”。能“使和平”的人或行为会平息冲突，而不会挑起争斗；因而它既可表示倾向和平，也可表示性情平和。Pacific Ocean 是“太平洋”。","originQuery":"pacific","page":33},{"id":"p34r08b","word":"dovish","pair":"pacific","meaning":"温和，和平的","origin":"dovish 意思是“鸽派的、倾向和平的”，是因为 dove（鸽子）长期被视为和平与温和的象征，-ish 表示“具有……特征的”。在政治语境中，dove 与 hawk（鹰）相对：鹰象征强硬、好战，鸽子则象征协商、避免冲突。因此 dovish 形容主张温和政策或和平手段的态度。","originQuery":"dovish","page":33},{"id":"p34r09a","word":"paradigmatic","pair":"archetypal","meaning":"典型的","origin":"paradigmatic 意思是“典型的、范例性的”，是因为 paradigm 原本就是摆在人面前的“样例”。它来自希腊语 paradeigma，para- 有“在旁、对照”之意，deiknynai 是“展示”。把一个例子展示出来，是为了让其他事物与它对照；因而能清楚代表某一类型或模式的，就是 paradigmatic。","originQuery":"paradigmatic","page":33},{"id":"p34r09b","word":"archetypal","pair":"paradigmatic","meaning":"典型的","origin":"archetypal 意思是“原型的、最典型的”，是因为 archetype 字面上是“最初的模型”。它来自希腊语 arkhetypon，arkhe- 表示“开端、最初”，typos 表示“印痕、模型”。最早的模型是后续复制品的根本样式，所以 archetypal 不只是普通相似，而是将某类事物的核心特征表现得最完整。","originQuery":"archetypal","page":33},{"id":"p34r10a","word":"stringent","pair":"exacting","meaning":"严格的","origin":"stringent 意思是“严格的、紧缩的”，是因为它来自拉丁语 stringere，即“拉紧、束缚”。规则若像绳子一样拉得很紧，人的行动空间就很小，也容不得例外或马虎；因此这一物理上的“紧”引申为法规、条件、审查等严厉且要求高。同源词 constrict 意为“压紧、限制”。","originQuery":"stringent","page":33},{"id":"p34r10b","word":"exacting","pair":"stringent","meaning":"严格的","origin":"exacting 意思是“要求严格的”，是因为 exact 作动词时原有“强行索取”之意。它来自拉丁语 exigere，ex- 是“向外”，agere 是“驱使、推动”，可以理解为把应付之物“逼出来”。能不留余地要求别人交付费用、劳动或精力，就显得苛刻而难以满足；因而表示“高度苛求的”。","originQuery":"exacting","page":33},{"id":"p35r01a","word":"sustained","pair":"perpetuated","meaning":"持续的","origin":"sustained 意思是“持续的”，是因为 sustain 的拉丁语字面义是“从下面托住”。它来自 sustinere：sus- 是 sub-“在下”的变体，tenere“抓住、保持”。从下方撑住可防止坠落，由此扩展为维持生命、论点或行动；sustained 因而表示“被支撑、得以维持的”。","originQuery":"sustain","page":34},{"id":"p35r01b","word":"perpetuated","pair":"sustained","meaning":"持续的","origin":"perpetuated 意思是“使持续下去的”，是因为 perpetuate 的词根表示“连续不断”。它来自拉丁语 perpetuus，per- 有“彻底、始终”之意，petere 的相关形式有“向前去”的概念。一件事不停顿地一直向前延续，就变得长久；因而该词常指某种状态、传统或问题被人维持并延续。","originQuery":"perpetuate","page":34},{"id":"p35r02a","word":"transmit","pair":"propagate","meaning":"传播","origin":"transmit 意思是“传送、传播”，是因为它字面上表示“送过去”。trans- 在拉丁语中是“越过、到另一边”，mittere 是“送出”。把一件东西从这一端送到另一端，就是传递；所以它不仅可指信息和信号的传播，也可指疾病、能量或特征在不同个体间传递。","originQuery":"transmit","page":34},{"id":"p35r02b","word":"propagate","pair":"transmit","meaning":"传播","origin":"propagate 意思是“传播、扩散”，是因为它最初指植物通过插枝等方式“繁殖”。它来自拉丁语 propagare，与 propago（幼苗、插枝）有关。一根枝条长成新植株，数量增多并向外延展；这个生物学画面后来用于思想、信仰、信息等被复制并广泛传开。","originQuery":"propagate","page":34},{"id":"p35r03a","word":"bucolic","pair":"rustic","meaning":"乡村的","origin":"bucolic 意思是“乡村的、田园牧歌式的”，是因为它原本就是“牧牛人的”。它来自希腊语 boukolikos，bous 是“牛”，kolos 与“照看、牧放”有关。牧牛人的生活场景是草地、牛群与乡野，古典诗歌又常把这类生活理想化；因而它既表示乡村的，也常暗含宁静纯朴的田园情调。","originQuery":"bucolic","page":34},{"id":"p35r03b","word":"rustic","pair":"bucolic","meaning":"乡村的","origin":"rustic 意思是“乡村的、质朴的”，是因为它来自拉丁语 rusticus，词根 rus 就是“乡村、田野”。属于乡野的东西往往未经城市式的精细加工，呈现出天然、粗朴的外观；因此 rustic 从单纯的“乡村的”扩展为风格上的简朴、未雕饰，有时也带“乡下气、不文雅”的贬义。","originQuery":"rustic","page":34},{"id":"p35r04a","word":"paucity","pair":"scarcity","meaning":"缺乏","origin":"Paucity 意思是“缺乏”，是因为它来自拉丁语 paucitas“数量少”，核心 paucus 就是“少数、很少”。-ity 表示状态或性质。某种资源只有少量，低于实际需要时，就构成短缺；因此 paucity 常用于正式语体，表示“少量、缺乏”，如 a paucity of evidence。","originQuery":"paucity","page":34},{"id":"p35r04b","word":"scarcity","pair":"paucity","meaning":"缺乏","origin":"Scarcity 意思是“缺乏”，是因为它表示 scarce“稀少、不足”的状态。scarce 经古法语进入英语，可能源于晚期拉丁语中表示“挑选、稀疏”的词；-ity 把性质变成名词。东西稀少到不能满足需要，就形成“短缺”，因此 scarcity 是“稀缺、缺乏”。","originQuery":"scarcity","page":34},{"id":"p35r05a","word":"glut","pair":"surfeit","meaning":"过量","origin":"glut 意思是“过量、供过于求”，是因为它早期的核心是“吞咽得过多”。它经古法语 glotir 传入英语，可能与表示“喉咙”的词有关。一个人吃到再也咽不下，就是饱和过度；市场上若商品多到无法被消化，也像被“塞满”了。因而 glut 从过度进食引申为任何东西过剩。","originQuery":"glut","page":34},{"id":"p35r05b","word":"surfeit","pair":"glut","meaning":"过量","origin":"surfeit 意思是“过量、过度”，是因为它字面上就是“做得超出了”。它经古法语 surfait 进入英语，sur- 相当于 super-（超过），fait 是“做成的事”。当行为超出合理限度，就会变成过度；该词尤其曾指饮食过量导致的不适，后扩大为供应或享用多到厌腻的状态。","originQuery":"surfeit","page":34},{"id":"p35r06a","word":"indifference","pair":"apathy","meaning":"冷漠","origin":"indifference 意思是“冷漠、不关心”，是因为它原本表示“不加区别”。in- 在此是“不”，difference 来自拉丁语 differentia（差异）。当几种结果在一个人看来都没有差别，他就不会特别偏爱、反对或投入感情；因此词义从“无差别、不偏向”发展为对人或事毫不在意的冷漠。","originQuery":"indifference","page":34},{"id":"p35r06b","word":"apathy","pair":"indifference","meaning":"冷漠","origin":"apathy 意思是“冷漠、无动于衷”，是因为它字面上表示“没有感受”。它来自希腊语 apatheia，a- 表示“无、不”，pathos 表示“感受、情感”。这个词在古代哲学中曾指不受激情摆布的平静状态，未必是贬义；后来逐渐转为对本应引起反应的事缺乏兴趣与情感。","originQuery":"apathy","page":34},{"id":"p35r07a","word":"varied","pair":"diverse","meaning":"多样的","origin":"varied 意思是“多样的、各不相同的”，是因为 vary 的词源核心是“有不同斑纹或色彩”。它来自拉丁语 varius，表示多色的、斑驳的或不一的。一个表面上颜色与图案不断变化，便不会单调一致；因此词义从外观的斑驳扩展到种类、特征、内容等富于变化。","originQuery":"varied","page":34},{"id":"p35r07b","word":"diverse","pair":"varied","meaning":"多样的","origin":"diverse 意思是“多样的、彼此不同的”，是因为它的词源画面是“转向不同方向”。它来自拉丁语 diversus，di-/dis- 表示“分开”，vertere 表示“转”。若各个事物分别向不同方向转去，它们就会相互分离、不再一致；因而引申为群体内包含多种不同类型或背景。","originQuery":"diverse","page":34},{"id":"p35r08a","word":"itinerant","pair":"peripatetic","meaning":"巡游的","origin":"itinerant 意思是“巡游的”，是因为它直接来自表示“旅行”的拉丁语。晚期拉丁语 itinerari 意为“旅行”，核心 iter、itineris 是“旅程、道路”；-ant 表示从事动作的人或性质。没有固定地点而沿路线不断移动的人，就是 itinerant，如巡回工人或游方传教者。","originQuery":"itinerant","page":34},{"id":"p35r08b","word":"peripatetic","pair":"itinerant","meaning":"巡游的","origin":"peripatetic 意思是“巡游的”，是因为希腊语 peripatein 表示“来回行走”：peri-“周围”，patein“走”。该词先指亚里士多德的逍遥学派，传统上与边走边讲学联系。后来离开哲学专名，泛指从一地走到另一地、没有固定居所或工作地点。","originQuery":"peripatetic","page":34},{"id":"p35r09a","word":"supplemented","pair":"augmented","meaning":"补充完善","origin":"supplemented 意思是“被补充、得到完善”，是因为 supplement 原指“用来填满缺口的东西”。它来自拉丁语 supplementum，sup-/sub- 有“从下补上”的感觉，plere 是“填满”。原有内容不足时，再加入某物把缺口填满，整体就更完整；因而表示额外增加内容以弥补不足。","originQuery":"supplement","page":34},{"id":"p35r09b","word":"augmented","pair":"supplemented","meaning":"补充完善","origin":"augmented 意思是“被扩充、增强”，是因为 augment 的拉丁语根 augere 就是“使增长、使扩大”。它不只表示随意加上一件东西，而是让原有整体在数量、尺寸、力量或价值上真正变大。因此 augmented 表示经过添加后更充足、更强或更完善。同源词 auction 的早期含义也与“增加”有关。","originQuery":"augmented","page":34},{"id":"p35r10a","word":"impeding","pair":"hampering","meaning":"阻碍","origin":"impeding 意思是“阻碍”，是因为拉丁语 impedire 原本表示“缠住脚”。它来自 in-“进入、使”与 pes/pedis“脚”相关成分。脚被束缚就无法顺利前进；因此 impede 从具体的绊脚扩展为使进程放慢或停止，即“妨碍、抑制”。","originQuery":"impede","page":34},{"id":"p35r10b","word":"hampering","pair":"impeding","meaning":"阻碍","origin":"hampering 意思是“正在阻碍、妨碍”，是因为 hamper 作动词时早期指“捆绑、使无法自由活动”。这一动词可能来自一个表示脚链或束缚物的日耳曼语词源，具体演变并不完全确定。人的手脚一旦被绳索缠住，行动就会变慢甚至停下；因而引申为任何使进展受限的阻碍。","originQuery":"hamper","page":34},{"id":"p36r01a","word":"realism","pair":"verisimilitude","meaning":"逼真","origin":"realism 意思是“现实主义、逼真”，是因为它强调事物“如其真实存在那样”被呈现。real 经法语来自拉丁语 realis，词根 res 是“事物、实体”，-ism 表示一种主张或方式。艺术若不理想化或粉饰对象，而是忠实呈现其实际样貌，就会给人与现实高度一致的“逼真”感。","originQuery":"realism","page":35},{"id":"p36r01b","word":"verisimilitude","pair":"realism","meaning":"逼真","origin":"verisimilitude 意思是“逼真、似真性”，是因为它的拉丁语成分直接表示“与真实相似”。veri- 来自 verus（真实的），similitude 来自 similitudo（相似）。一个虚构人物或场景未必真的存在，但只要它的细节和因果看起来像真实世界，就具有“似真性”，从而显得逼真可信。","originQuery":"verisimilitude","page":35},{"id":"p36r02a","word":"unwarranted","pair":"groundless","meaning":"无根据的","origin":"unwarranted 意思是“无根据的、未获正当理由的”，是因为 warrant 原指能够保证或授权某事的凭据，un- 表示否定。warrant 经古法语来自日耳曼语源，核心是“保护、担保”。一个判断若有证据为它担保，就站得住；反之，unwarranted 就是没有事实、权限或情势为它提供正当支持。","originQuery":"unwarranted","page":35},{"id":"p36r02b","word":"groundless","pair":"unwarranted","meaning":"无根据的","origin":"groundless 意思是“无根据的”，是因为它字面上就是“没有地基”。ground 除了“地面”，还可比喻支撑一个主张的事实或理由，-less 表示“缺少”。建筑没有地基就无法站稳，论断没有证据也同样经不起质疑；因此 groundless 形容推测、恐惧或指控缺乏可信支撑。","originQuery":"groundless","page":35},{"id":"p36r03a","word":"irrelevant","pair":"extraneous","meaning":"无关的","origin":"irrelevant 意思是“无关的”，是因为它否定了 relevant 的“对当前事项有分量”。ir- 是 in-（不）在 r 前的变体，relevant 经法语与拉丁语 relevare（抬起、减轻）有关。relevant 的现代含义可以理解为足以影响当前判断的信息；加上否定前缀后，就是对讨论的问题不起作用、没有关联。","originQuery":"irrelevant","page":35},{"id":"p36r03b","word":"extraneous","pair":"irrelevant","meaning":"无关的","origin":"extraneous 意思是“外来的、无关的”，是因为它的拉丁语根 extra 就是“在外面”。它来自 extraneus，原指属于外部或来自外部的东西，与 strange、stranger 有较远的同源关系。某个因素如果在主体的边界之外，就不属于它的必要组成部分；因此词义从“外部的”发展为“多余的、与主题无关的”。","originQuery":"extraneous","page":35},{"id":"p36r04a","word":"rapacious","pair":"avaricious","meaning":"贪婪的","origin":"rapacious 意思是“贪婪的、贪得无厌的”，是因为它的词根表示“抢走、掠夺”，现有中文“贪婪的”显然是误写。它来自拉丁语 rapax，词根 rapere 是“抓走、劫掠”。一个人不是满足于已有之物，而是不断从别人手中抢取，就体现出强烈而侵略性的贪婪。同源词 raptor 原指掠食者。","originQuery":"rapacious","page":35},{"id":"p36r04b","word":"avaricious","pair":"rapacious","meaning":"贪婪的","origin":"avaricious 意思是“贪婪的、贪财的”，是因为它直接来自表示“贪求财物”的拉丁语词族，现有中文“贪婪的”是误写。它来自 avaritia（贪婪），其动词 avare 大致表示“渴望、贪求”。当对金钱和占有的渴望永远无法满足，人就会不断囤积和索取；因而该词专指对财富过分渴求。","originQuery":"avaricious","page":35},{"id":"p36r05a","word":"riddle","pair":"conundrum","meaning":"难题","origin":"riddle 意思是“谜题、难解之事”，是因为它在古英语中就指需要猜解的“疑问”，现有中文“难题”显然是误写。它来自古英语 rædels，词根 rædan 表示“建议、解读、猜出”，与 read 同源。谜面给出线索，解题者必须解读它们才能猜出答案；因此它也引申为任何令人费解的问题。","originQuery":"riddle","page":35},{"id":"p36r05b","word":"conundrum","pair":"riddle","meaning":"难题","origin":"conundrum 意思是“难题”，是因为它从16世纪起就用于谜语、文字游戏和难解问题。旧词典有时给出伪拉丁形式，但其真正来源不明，因此不能按 con- 等现代成分强拆。由故意令人困惑的谜语，词义扩大为任何棘手、难以解决的问题。","originQuery":"conundrum","page":35},{"id":"p36r06a","word":"original","pair":"novel","meaning":"原创的","origin":"original 意思是“原创的”，是因为它首先表示“属于起源、最初产生的”。它来自拉丁语 originalis，核心 origo 是“开端、来源”。不是复制别人，而是从自己这里首次产生的想法，就是“原创的”；原创内容通常前所未见，因此 original 进一步带有“新颖、独创”的意味。","originQuery":"original","page":35},{"id":"p36r06b","word":"novel","pair":"original","meaning":"原创的","origin":"novel 意思是“原创的”，是因为它来自拉丁语 novellus“新的、年轻的”，核心 novus 就是“新”。经古法语进入英语后，它形容新近出现、不同于旧有方式的事物。若一种方法此前从未出现，就同时具有 novel 的“新颖”和“前所未有”意味。","originQuery":"novel","page":35},{"id":"p36r07a","word":"gratify","pair":"please","meaning":"使满足","origin":"gratify 意思是“使满足、使高兴”，是因为它原本表示“使人心存感激或感到愉快”。它来自拉丁语 gratificari，gratus 是“令人愉快的、受感激的”，facere 是“使成为”。为人提供他想要的东西，就使他愉快并感到愿望已实现；因此现代含义集中于满足欲望或取悦某人。","originQuery":"gratify","page":35},{"id":"p36r07b","word":"please","pair":"gratify","meaning":"使满足","origin":"please 意思是“使满足、使愉快”，是因为它来自拉丁语 placere，本义就是“令人感到好、使人喜欢”。某件事若符合一个人的心意，他会感到舒适、满意；所以 please 既可指给人带来快乐，也可指满足其愿望。礼貌用语 please 则由“如果这能使你高兴”这类表达简化而来。","originQuery":"please","page":35},{"id":"p36r08a","word":"cumbersome","pair":"unwieldy","meaning":"笨重的","origin":"cumbersome 意思是“笨重的、难处理的”，是因为 cumber 原指“阻塞、给人增加负担”。它经古法语 encombrer 进入英语，与障碍物和阻碍的概念有关，-some 表示“容易导致……的”。一件东西若又大又重，会挡路并成为搬运者的负担；因此它也可形容程序、制度等复杂累赘。","originQuery":"cumbersome","page":35},{"id":"p36r08b","word":"unwieldy","pair":"cumbersome","meaning":"笨重的","origin":"unwieldy 意思是“笨重难以操控的”，是因为它字面上表示“无法熟练驾驭的”。un- 是“不”，wield 来自古英语 wealdan，表示“掌控、支配”，-y 构成形容词。武器或工具如果太大、太重，手就无法灵活驾驭；因而该词既可形容物体笨重，也可形容组织或系统庞大难管。","originQuery":"unwieldy","page":35},{"id":"p36r09a","word":"spurring","pair":"fostering","meaning":"促进","origin":"spurring 意思是“正在促进、激励”，是因为 spur 原指骑马者靴后用来催马前进的“马刺”。它来自古英语 spura/spora。骑手用马刺触及马的侧腹，会使马加速或开始行动；这个具体的推进动作后来变成比喻，指某种刺激促使人、经济或进程更快向前发展。","originQuery":"spur","page":35},{"id":"p36r09b","word":"fostering","pair":"spurring","meaning":"促进","origin":"fostering 意思是“正在促进、培育”，是因为 foster 最初指“用食物养大、抚育”。它来自古英语 fostrian，与 food 所属的“食物、喂养”词族有关。给幼小生命提供食物和照料，会帮助它成长；因此词义从具体的养育扩展到为想法、能力、关系或进步创造有利条件。","originQuery":"foster","page":35},{"id":"p37r01a","word":"decay","pair":"deterioration","meaning":"衰退","origin":"decay 意思是“腐烂、衰退”，是因为它的词源核心是“向下落”。它经古法语 decaïr 来自拉丁语 decadere，de- 表示“向下、离开”，cadere 是“落下”。一个事物从原有的完好状态不断“往下掉”，会失去结构、力量或活力；因而既可指物质腐坏，也可指制度、道德或经济衰退。","originQuery":"decay","page":36},{"id":"p37r01b","word":"deterioration","pair":"decay","meaning":"衰退","origin":"deterioration 意思是“恶化、衰退”，是因为它的拉丁语根 deterior 就是“更差的”。deteriorare 表示“使变得更差”，英语加上表过程或结果的 -ation。这个词强调的不是单纯的差，而是从较好状态向较差状态持续变化；因此可指健康、质量、关系或局势逐步恶化。","originQuery":"deterioration","page":36},{"id":"p37r02a","word":"dangerous","pair":"perilous","meaning":"危险的","origin":"dangerous 意思是“危险的”，是因为 danger 早期与“处在某人的支配下”有关。它经古法语 dangier 进入英语，曾指权力、统治或任人处置的状态。若落入有能力伤害你的人手中，就处于可能遭受损害的境地；因此 danger 逐渐从“受他人支配”发展为“危险”，dangerous 即可能带来伤害的。","originQuery":"dangerous","page":36},{"id":"p37r02b","word":"perilous","pair":"dangerous","meaning":"危险的","origin":"Perilous 意思是“危险的”，是因为它由 peril“危险”与 -ous“充满……的”构成。peril 经古法语 peril 来自拉丁语 periculum“试验、风险”。需要接受考验的处境可能带来伤害或失败，因此 peril 发展为危险；perilous 就是“充满危险的”。","originQuery":"perilous","page":36},{"id":"p37r03a","word":"relished","pair":"delighted","meaning":"享受","origin":"relished 意思是“享受、津津有味地品味”，是因为 relish 原本指食物留下的“味道、风味”。它经古法语与“留下”有关，可理解为品尝后留在口中的滋味。人若认真品味并喜爱这种滋味，就是在充分享受食物；因此词义扩展到对任何经历感到强烈乐趣。","originQuery":"relish","page":36},{"id":"p37r03b","word":"delighted","pair":"relished","meaning":"享受","origin":"delighted 意思是“感到愉快、非常享受”，是因为 delight 的拉丁语根 delectare 就是“使高兴、给人乐趣”。它经古法语进入英语，与 delectable（美味可口的、令人愉快的）同源。某件事不只让人一般满意，而是带来强烈的乐趣和喜悦，人就处于 delighted 的状态，即感到欣喜并享受其中。","originQuery":"delight","page":36},{"id":"p37r04a","word":"respite","pair":"relief","meaning":"短暂的休息或缓解","origin":"respite 意思是“短暂的休息或缓解”，是因为它原先指惩罚、义务或行动的“延期”。它经古法语 respit 来自拉丁语 respectus“回看、考虑”。事情暂停，让人有时间重新考虑，也让压力暂时解除；因此 respite 发展为困难中的“喘息、短暂休息”。","originQuery":"respite","page":36},{"id":"p37r04b","word":"relief","pair":"respite","meaning":"短暂的休息或缓解","origin":"relief 意思是“缓解、解脱”，是因为它的词源核心是“把人重新抬起”。它经法语与拉丁语 relevare 有关，re- 是“再、向上”，levare 是“举起、使变轻”。痛苦、压力或负担像重物一样把人压低；当这份重量被移开，人便能抬起身来，因而感到缓解和轻松。","originQuery":"relief","page":36},{"id":"p37r05a","word":"lugubrious","pair":"gloomy","meaning":"悲伤的","origin":"lugubrious 意思是“悲伤的、哀戚的”，是因为它直接来自拉丁语 lugubris，意为“哀悼的”。这个拉丁词与 lugere（哀哭、悼念）有关。在丧事中哀哭所呈现的是持久、沉重而明显的悲伤；因此 lugubrious 不只表示普通难过，还常形容神情、声音或气氛像在哀悼般忧郁沉重。","originQuery":"lugubrious","page":36},{"id":"p37r05b","word":"gloomy","pair":"lugubrious","meaning":"悲伤的","origin":"gloomy 意思是“悲伤的”，是因为 gloom 的核心是“昏暗、幽暗”。gloom 的更早来源并不十分确定，中古英语相关形式可指阴沉的神情或黑暗；-y 表示“充满……的”。由光线昏暗自然引申到气氛沉重、心情忧郁，所以 gloomy 既可指“昏暗的”，也可指“阴郁的”。","originQuery":"gloomy","page":36},{"id":"p37r06a","word":"deflate","pair":"soothe","meaning":"缓和","origin":"deflate 意思是“放气、压低，从而使缓和”，是因为它字面上是“把吹进去的气放掉”。de- 表示去除或向下，flate 来自拉丁语 flare（吹）的过去分词 flatus。充气物放掉空气后会缩小，原有的张力也随之降低；因此它也比喻打击人的自信、降低过热情绪或使紧张局势缓和。","originQuery":"deflate","page":36},{"id":"p37r06b","word":"soothe","pair":"deflate","meaning":"缓和","origin":"soothe 意思是“抚慰、缓和”，是因为它早期表示“证实某人说的是真话”，后来转为用迎合的话使人高兴。它来自古英语 sothian，词根 soð 是“真实”，与 soothsayer 中的 sooth 同源。肯定对方、说他爱听的话，能平息焦虑或怒气；因此词义逐渐集中为使情绪、疼痛或刺激变得平和。","originQuery":"soothe","page":36},{"id":"p37r07a","word":"harmless","pair":"innocuous","meaning":"无害的","origin":"harmless 意思是“无害的”，是因为它由 harm（伤害、损害）和 -less（没有、缺少）直接构成。harm 来自古英语 hearm，可指身体伤害、痛苦或不幸。一个东西若不会带来这些损害，就不必防范或害怕；因此 harmless 既可形容物质或动物不会伤人，也可形容玩笑、错误等没有严重后果。","originQuery":"harmless","page":36},{"id":"p37r07b","word":"innocuous","pair":"harmless","meaning":"无害的","origin":"Innocuous 意思是“无害的”，是因为拉丁语 innocuus 的构词就是“不伤害”。in-“不”，nocuus 来自 nocere“伤害”；-ous 表示具有某种性质。合起来是“不会造成伤害的”，所以既可形容物质安全无害，也可形容言行温和、不冒犯人；同源词 noxious 表示“有害的”。","originQuery":"innocuous","page":36},{"id":"p37r08a","word":"preachy","pair":"sanctimonious","meaning":"说教的，自以为是的","origin":"preachy 意思是“说教味的、自以为是地训人的”，是因为它由 preach（讲道、宣讲）加 -y 构成。preach 经古法语来自拉丁语 praedicare，原指在人前公开宣告，后尤指宗教讲道。讲道者通常从道德高处告诉听众应该怎样做；当普通言论过分采用这种口吻，就显得爱训诫人、说教味过重。","originQuery":"preachy","page":36},{"id":"p37r08b","word":"sanctimonious","pair":"preachy","meaning":"说教的，自以为是的","origin":"sanctimonious 意思是“假装道德高尚的、自以为是的”，是因为它原本表示“神圣、虔敬的”，后来语气变为讽刺。它来自拉丁语 sanctimonia（圣洁），词根 sanctus 是“神圣的”。真正的虔敬本是褒义，但若一个人过分展示自己的“圣洁”并审判别人，就会显得虚伪而自鸣得意。","originQuery":"sanctimonious","page":36},{"id":"p37r09a","word":"malodorous","pair":"noisome","meaning":"恶臭的","origin":"malodorous 意思是“恶臭的”，是因为它几乎就是“具有坏气味的”直接组合。mal- 来自拉丁语 malus，表示“坏的”，odor 是“气味”，-ous 表示“具有……性质的”。因此 malodorous 先表示散发令人不快气味的；由于坏名声也像恶臭一样使人躲避，它偶尔还可比喻令人厌恶或声名狼藉。","originQuery":"malodorous","page":36},{"id":"p37r09b","word":"noisome","pair":"malodorous","meaning":"恶臭的","origin":"noisome 意思是“恶臭的、令人反感的”，是因为这里的 noi- 与“伤害、烦扰”有关，并不是 noise（噪声）加 -some。它来自中古英语 noy（伤害、烦恼），与 annoy 同源，-some 表示“导致……的”。能使人受害或恶心的东西会令人厌恶，词义后来尤其集中到难闻、有害的气味。","originQuery":"noisome","page":36},{"id":"p37r10a","word":"shrieking","pair":"caterwauling","meaning":"尖叫","origin":"shrieking 意思是“正在尖叫”，是因为 shriek 本身就是模仿高亢、刺耳叫声的词。它在中古英语中以 schriken 等形式出现，具体词源不完全确定，但和其他表示尖锐声响的日耳曼语词有关。词的发音本身就给人急促尖锐的感觉，因而用来表示由恐惧、痛苦或兴奋引发的高声尖叫。","originQuery":"shriek","page":36},{"id":"p37r10b","word":"caterwauling","pair":"shrieking","meaning":"尖叫","origin":"caterwauling 意思是“正在发出猫叫般的尖厉哀号”，是因为 caterwaul 最初就是对猫发情时刺耳叫声的描写。它的前半与 cat（猫）有关，后半可能受 waul（哀号）这类拟声词影响，具体构成并不完全确定。由猫拖长而凄厉的叫声，它引申为人或声音难听地尖叫、哭嚎或吵嚷。","originQuery":"caterwaul","page":36},{"id":"p38r01a","word":"defied","pair":"disregarded","meaning":"无视","origin":"defied 意思是“公然违抗、无视”，是因为 defy 早期表示“弃绝信义、向对方正式挑战”。它经古法语 desfier 进入英语，des- 表示取消或离开，fi 与拉丁语 fides（信任、信义）有关。收回对某人的信义，等于不再承认他的权威并愿意与之对抗；因而发展为不服从命令、规则或威胁。","originQuery":"defy","page":37},{"id":"p38r01b","word":"disregarded","pair":"defied","meaning":"无视","origin":"disregarded 意思是“被无视、未加理会”，是因为 disregard 表示把“注意与尊重”去掉。dis- 表示否定或离开，regard 经古法语与 garder（观看、留意、保护）有关。对一件事“看在眼里”，就是将它纳入考虑并给予重视；加上 dis- 后，就是刻意不看、不顾及，从而表示无视建议、规则或他人需求。","originQuery":"disregard","page":37},{"id":"p38r02a","word":"somnolent","pair":"lethargic","meaning":"昏昏欲睡的","origin":"somnolent 意思是“昏昏欲睡的”，是因为它的拉丁语根 somnus 就是“睡眠”，现有中文“昏昏欲睡的”显然是误写。它来自拉丁语 somnolentus，表示困倦、爱睡的，与 insomnia（失眠）中的 somn- 同源。人如果被睡意占据，就会眼皮沉重、反应迟钝；因而 somnolent 既形容人想睡，也可形容场所沉静得令人发困。","originQuery":"somnolent","page":37},{"id":"p38r02b","word":"lethargic","pair":"somnolent","meaning":"昏昏欲睡的","origin":"lethargic 意思是“昏昏欲睡、无精打采的”，是因为 lethargy 在古代原指一种使人沉睡与健忘的病态，现有中文“昏昏欲睡的”是误写。它来自希腊语 lethargia，lethe 是“忘却”，argos 有“不活动的”之意。病人因沉睡而不动、意识迟钝；因此词义扩大为任何精神不振、缺乏活力的状态。","originQuery":"lethargic","page":37},{"id":"p38r03a","word":"averted","pair":"forestalled","meaning":"阻止","origin":"averted 意思是“被阻止、被避免”，是因为 avert 字面上是“转到别处”。a- 来自拉丁语 ab-，表示“离开”，vertere 表示“转”。把眼睛转开，就是不再面向原来的对象；把危险的走向转开，则能使它不落到人身上。因此词义从“使转向”发展为及时阻止灾难、风险或不良结果发生。","originQuery":"avert","page":37},{"id":"p38r03b","word":"forestalled","pair":"averted","meaning":"阻止","origin":"forestalled 意思是“被预先阻止”，是因为 forestall 原本指“在某人到达市场摊位之前截住他”。fore- 是“在前”，stall 在这里指售货摊位。中世纪商贩若在货物进市场前就抢先买下，会妨碍正常交易；因此词义从“半路截买”扩大为抢在某件事发生前采取行动，使其无法发生。","originQuery":"forestall","page":37},{"id":"p38r04a","word":"evasive","pair":"elusive","meaning":"难以捉摸","origin":"evasive 意思是“逃避的、难以捉摸的”，是因为 evade 的词源核心是“走到外面去”。e-/ex- 表示“向外”，vadere 在拉丁语中是“走、前进”。面对追捕时走出对方的控制范围，就是逃脱；面对问题时把话题引向别处，就是回避回答。因此 evasive 形容人、话语或动作总在躲避，让人难以抓住要点。","originQuery":"evasive","page":37},{"id":"p38r04b","word":"elusive","pair":"evasive","meaning":"难以捉摸","origin":"Elusive 意思是“难以捉摸”，是因为 elude 的拉丁语字面义是“玩弄着逃开”。它来自 eludere：e-/ex-“出去”，ludere“玩”；-ive 表示具有这种性质。目标仿佛在游戏中不断闪避，使人抓不到或理解不了，因此 elusive 表示“难以捕捉、难以理解的”。","originQuery":"elusive","page":37},{"id":"p38r05a","word":"expel","pair":"oust","meaning":"驱逐","origin":"expel 意思是“驱逐、排出”，是因为它字面上是“向外推”。ex- 在拉丁语中表示“出、向外”，pellere 表示“推、驱赶”。从一个团体或地方里把人强行推到外面，就是驱逐；身体或设备把气体、液体向外推，就是排出。因此 expel 始终带有使某物离开内部或原有位置的强制感。","originQuery":"expel","page":37},{"id":"p38r05b","word":"oust","pair":"expel","meaning":"驱逐","origin":"oust 意思是“驱逐、夺去位置”，是因为它最初是法律用语，表示把某人从财产或权利中“移出”。它经古法语 oster 来自拉丁语 obstare，ob- 是“对着、挡在前面”，stare 是“站立”。通过法律或力量让人不能再站在原有位置，就是把他排除出去；因而后来广泛用于赶下台或逐出场所。","originQuery":"oust","page":37},{"id":"p38r06a","word":"diffuse","pair":"spread","meaning":"扩散","origin":"diffuse 意思是“扩散、使散开”，是因为它的词源核心是“向各方倾注”。dif- 是 dis- 在 f 前的变体，表示“分开、向各处”，fundere 在拉丁语中是“倾倒、流出”。液体被向四周泼开，就不再集中于一点；因而这个画面扩展到气体、光线、思想或信息向广大范围传播。","originQuery":"diffuse","page":37},{"id":"p38r06b","word":"spread","pair":"diffuse","meaning":"扩散","origin":"spread 意思是“扩散、展开”，是因为它在古英语中就表示把某物“铺开、张开”。它来自古英语 sprædan，核心画面是使原本集中或折叠的东西占据更大面积。把布展开、把食物涂开，都会使它从一处延伸到多处；因此词义自然扩展为疾病、消息、火势等在更广范围传开。","originQuery":"spread","page":37},{"id":"p38r07a","word":"momentary","pair":"evanescent","meaning":"短暂的","origin":"momentary 意思是“短暂的、片刻的”，是因为 moment 原本指很小的“动量、移动”，后来才成为极短的时间单位。它来自拉丁语 momentum，词根 movere 是“移动”。一个微小动作发生所需的时间很短，moment 因而逐渐表示“一瞬”；加上 -ary 后，momentary 就是仅持续一瞬、很快会过去的。","originQuery":"momentary","page":37},{"id":"p38r07b","word":"evanescent","pair":"momentary","meaning":"短暂的","origin":"evanescent 意思是“转瞬即逝的、短暂的”，是因为它的拉丁语根表示“渐渐消失出去”。e-/ex- 表示“向外、离开”，vanescere 表示“消散、消失”，与 vanish 有关。像雾气或微光那样刚出现就慢慢散去，留存的时间自然很短；因而该词常形容美感、情绪或现象美丽却无法持久。","originQuery":"evanescent","page":37},{"id":"p38r08a","word":"irregularities","pair":"anomalies","meaning":"异常","origin":"irregularities 意思是“不规则现象、异常”，是因为 irregularity 表示偏离了“规则”的状态。ir- 是 in-（不）在 r 前的变体，regular 来自拉丁语 regula（直尺、规则），-ity 表示状态。直尺能画出整齐的直线，规则则让事物按统一模式运行；若不符合这一模式，就成为值得注意的异常或偏差。","originQuery":"irregularity","page":37},{"id":"p38r08b","word":"anomalies","pair":"irregularities","meaning":"异常","origin":"anomalies 意思是“异常、反常事物”，是因为 anomaly 在希腊语中就表示“不均匀、不平整”。它来自 anomalia，an- 表示“不”，homalos 表示“平坦、均匀”。一个表面若大部分都平整，突然出现的凸起或凹陷就格外显眼；因此词义从形状不齐，扩展为偏离常态、规律或预期的现象。","originQuery":"anomaly","page":37},{"id":"p38r09a","word":"ambiguous","pair":"mute","meaning":"模糊不清","origin":"Ambiguous 意思是“模糊不清”，是因为它的词源核心是“向两边游移”。拉丁语 ambiguus 来自 ambi-（两边、周围）和 agere（驱动、行动），原指摇摆不定或可朝两个方向理解。由“无法确定往哪边走”发展为“有两种解释、界限不清”，因此表示含混、有歧义。","originQuery":"ambiguous","page":37},{"id":"p38r09b","word":"mute","pair":"ambiguous","meaning":"模糊不清","origin":"Mute 意思是“模糊不清”，是因为它最初表示“不能说话、没有声音”。它经古法语 muet 来自拉丁语 mutus（哑的、沉默的）。当声音被压低或信息没有明确表达时，内容就像“说不出来”一样难以辨清，于是可引申为无声的、弱化的或不鲜明的；此处取“不明确”的语境义。","originQuery":"mute","page":37},{"id":"p38r10a","word":"dismiss","pair":"ignore","meaning":"忽视","origin":"dismiss 意思是“忽视”，是因为 dismiss 的拉丁语字面义是“把人送走”。它来自 dimittere：dis-“分开、离开”，mittere“送”。由让人离场发展为拒绝考虑某个观点；如果不经认真评价便把它“打发走”，就是认为它不值得重视，因此带有贬低意味。","originQuery":"dismiss","page":37},{"id":"p38r10b","word":"ignore","pair":"dismiss","meaning":"忽视","origin":"Ignore 意思是“忽视”，是因为它的词源核心是“不知道、不去认识”。它来自拉丁语 ignorare（不知道、不了解），与 ignarus（无知的）有关。语义从“没有意识到某事”发展为“即使注意到也当作不知道”，也就是有意不理会，因此形成今天“忽略、忽视”的意思。","originQuery":"ignore","page":37},{"id":"p39r01a","word":"belying","pair":"contradicting","meaning":"与……相矛盾","origin":"Belying 意思是“与……相矛盾”，是因为 belie 原本表示“用谎言欺骗或给人假象”。它来自古英语 beleogan：be- 有加强作用，leogan 是“说谎”。若表面现象“欺骗”了真实情况，就说明表象与事实不一致；因此 belying 常指某种表现掩盖、歪曲或反驳了背后的事实。","originQuery":"belying","page":38},{"id":"p39r01b","word":"contradicting","pair":"belying","meaning":"与……相矛盾","origin":"contradicting 意思是“与……相矛盾”，是因为它的拉丁语构词就是“说相反的话”。contra-“反对、相反”，dicere“说”。当一个陈述与另一个陈述正面相反时，它就在否认后者的真实性；因此 contradict 表示“反驳、与……矛盾”，相关词 contradiction 是“矛盾”。","originQuery":"contradict","page":38},{"id":"p39r02a","word":"proclivity","pair":"affinity","meaning":"倾向于","origin":"proclivity 意思是“倾向于”，是因为它原本表示向前倾斜的坡势。拉丁语 proclivis 由 pro-“向前”与 clivus“斜坡”构成。物体会顺坡自然滑向一个方向，这个图景转用于人的性情，表示无需外力就容易选择某种行为或爱好。","originQuery":"proclivity","page":38},{"id":"p39r02b","word":"affinity","pair":"proclivity","meaning":"倾向于","origin":"Affinity 意思是“倾向于”，是因为它最初表示“因接近而形成的亲属或联系”。它经古法语来自拉丁语 affinitas，词根 finis 是“边界”，ad- 表示“向、邻近”，字面概念是“边界相接”。由邻接关系发展为相似、亲和，再引申为对某事天然有吸引力或倾向。","originQuery":"affinity","page":38},{"id":"p39r03a","word":"learned","pair":"erudite","meaning":"博学的","origin":"Learned 意思是“博学的”，是因为它直接来自 learn（学习）加表示结果状态的 -ed，即“经过学习、已获得知识的”。learn 源自古英语 leornian（学习、求知）。语义从一般的“学会了”进一步专指因长期研习而知识丰富，所以作形容词时常读作两个音节，表示“有学问的、博学的”。","originQuery":"learned","page":38},{"id":"p39r03b","word":"erudite","pair":"learned","meaning":"博学的","origin":"Erudite 意思是“博学的”，是因为它的拉丁语原义是“从粗野无知中教化出来”。拉丁语 erudire 由 e-/ex-（脱离）和 rudis（粗糙的、未经训练的）构成，eruditus 即“受过教导的”。从“摆脱未经训练状态”发展为“学识深厚”，因此表示博学而有修养。","originQuery":"erudite","page":38},{"id":"p39r04a","word":"inaccessible","pair":"insurmountable","meaning":"无法达到的","origin":"Inaccessible 意思是“无法达到的”，是因为它就是“不能接近”。in- 表否定，accessible 来自拉丁语 accedere（走近），其中 ad- 是“向”，cedere 是“走、让步”。字面概念是“没有可走近的途径”，先用于地点难以进入，后来也用于目标、人物或知识难以触及。相关词 access 即“进入、接近”。","originQuery":"inaccessible","page":38},{"id":"p39r04b","word":"insurmountable","pair":"inaccessible","meaning":"无法达到的","origin":"Insurmountable 意思是“无法达到的”，是因为它表示“不能越到上面去”。in- 表否定，surmount 经法语来自 sur-（在上、越过）与 monter（登上）。原始画面是无法翻越一道障碍，随后从空间上的“越不过去”引申为困难无法克服、目标无法实现，因此表示不可逾越的。","originQuery":"insurmountable","page":38},{"id":"p39r05a","word":"scarcely","pair":"hardly","meaning":"几乎不","origin":"Scarcely 意思是“几乎不”，是因为 scarce 的核心概念是“稀少、不足”。scarce 经古法语进入英语，表示数量少、供应不足；加副词后缀 -ly 后，scarcely 原可理解为“以极少的程度”。“程度少到接近没有”便自然发展为“几乎不、勉强才”，如 scarcely visible 即“几乎看不见”。","originQuery":"scarce","page":38},{"id":"p39r05b","word":"hardly","pair":"scarcely","meaning":"几乎不","origin":"Hardly 意思是“几乎不”，是因为它由 hard（困难地、费力地）加 -ly 构成。古英语 heardlice 原表示“严厉地、费力地”，后来“费很大力才做到”逐渐被理解为“勉强做到”。当某事只是勉强成立，就接近于没有发生，因此 hardly 形成了“几乎不”的现代常用义。","originQuery":"hardly","page":38},{"id":"p39r06a","word":"obtain","pair":"glean","meaning":"获取","origin":"Obtain 意思是“获取”，是因为它的词源核心是“牢牢掌握”。它经法语来自拉丁语 obtinere，由 ob-（朝向、对着）和 tenere（握住、保持）构成，可理解为“把东西握到手并保有”。语义从“占有、维持住”发展为通过努力取得某物，因此表示获得、取得。相关词 retain 也含 tenere 的“握住”概念。","originQuery":"obtain","page":38},{"id":"p39r06b","word":"glean","pair":"obtain","meaning":"获取","origin":"Glean 意思是“获取”，是因为它原指收割后在田里一点点捡拾遗落的谷穗。它经古法语 glener 进入英语。由“从剩余作物中逐一收集”引申为从许多零散来源慢慢搜集信息、知识或线索，所以 glean 并非泛指轻易得到，而强调细致挑取、汇集而获得。","originQuery":"glean","page":38},{"id":"p39r07a","word":"panacea","pair":"remedy","meaning":"万能药","origin":"Panacea 意思是“万能药”，是因为它的希腊语词源字面就是“治愈一切”。pan- 表示“全部”，akos 表示“治疗、疗法”，希腊语 panakeia 还是神话中掌管治愈者的名字。这个词先指能治所有疾病的药，后来也比喻能解决一切问题的办法；通常暗含这种方案未必真实存在。","originQuery":"panacea","page":38},{"id":"p39r07b","word":"remedy","pair":"panacea","meaning":"万能药","origin":"Remedy 意思是“万能药”，是因为它的核心意思是“重新使好转的办法”。它经古法语来自拉丁语 remedium，re- 有“恢复、重新”之意，mederi 表示“医治”。原指治疗疾病、纠正伤害的方法，后来泛指补救问题的措施。在“能解决所有问题”的语境中，remedy 可被理解为万能疗法，但本身通常只表示“补救办法”。","originQuery":"remedy","page":38},{"id":"p39r08a","word":"fairness","pair":"objectivity","meaning":"公正","origin":"Fairness 意思是“公正”，是因为 fair 从“美好、合宜”逐渐发展出“不偏不倚”的意思。fair 源自古英语 fæger，早期指美丽、令人愉快；合乎理想、令人满意的做法又被视为合理正当。加名词后缀 -ness 后，fairness 就表示公平对待各方的状态，即公正、公平。","originQuery":"fairness","page":38},{"id":"p39r08b","word":"objectivity","pair":"fairness","meaning":"公正","origin":"Objectivity 意思是“公正”，是因为它要求判断朝向 object，也就是“对象、事实本身”，而非个人感受。object 经拉丁语 objectum，原指“被放在面前的东西”；-ivity 构成性质名词。由“以外在对象为依据”发展为不受个人偏好左右，因此 objectivity 表示客观性，并可带出公正、不偏颇。","originQuery":"objectivity","page":38},{"id":"p39r09a","word":"short-lived","pair":"ephemeral","meaning":"短暂的","origin":"Short-lived 意思是“短暂的”，是因为它是 short（短的）与 lived（有某种寿命的）的透明复合词，字面概念就是“生命或持续时间很短”。这里 lived 不是简单指“曾生活过”，而表示“具有……寿命”。它先用于寿命短的人或生物，也自然扩展到计划、潮流或成功等很快结束的事物。","originQuery":"short","page":38},{"id":"p39r09b","word":"ephemeral","pair":"short-lived","meaning":"短暂的","origin":"Ephemeral 意思是“短暂的”，是因为它的希腊语词源表示“只持续一天”。epi- 有“在……期间”之意，hemera 是“日、一天”，ephemeros 即“一日之久的”。这个词曾用于一天即退的热病和寿命极短的生物，后来泛化为任何转瞬即逝、维持时间很短的事物。相关词 ephemera 指短命或易逝之物。","originQuery":"ephemeral","page":38},{"id":"p39r10a","word":"secure","pair":"earn","meaning":"获得","origin":"Secure 意思是“获得”，是因为它从“使某物安全、确定归己”发展为“设法取得”。它来自拉丁语 securus，由 se-（没有、脱离）和 cura（忧虑、照料）构成，原义是“无忧的、安全的”。把机会或资源弄到手并确保不失去，就是 secure something，因此可表示成功获得、争取到。","originQuery":"secure","page":38},{"id":"p39r10b","word":"earn","pair":"secure","meaning":"获得","origin":"Earn 意思是“获得”，是因为它在古英语中就表示“通过劳动取得”。古英语 earnian 有“做工、凭劳动赢得回报”的意思，可能与收获劳动相关。语义始终强调付出与所得之间的关系：先是挣得工资或收益，后来也可指凭行为赢得尊重、资格或结果，因此是“努力后获得”。","originQuery":"earn","page":38},{"id":"p40r01a","word":"generating","pair":"originating","meaning":"产生","origin":"Generating 意思是“产生”，是因为 generate 的词源核心是“生育、使出生”。它来自拉丁语 generare（生育、创造），与 genus（种类、家族）同源；-ing 表示正在进行的动作。语义从生命的繁衍扩展到让能量、想法、收益等出现，因此 generating 就是使某物形成或产生。相关词 generation 是“一代；产生”。","originQuery":"generate","page":39},{"id":"p40r01b","word":"originating","pair":"generating","meaning":"产生","origin":"Originating 意思是“产生”，是因为 originate 表示“从源头开始、使之有起点”。它由 origin（起源）加动词后缀 -ate 构成；origin 来自拉丁语 oriri（升起、出现）。语义由事物“开始出现”扩展为某人或某处“发起、创生”某物，因此 originating 可表示正在产生或起源于。","originQuery":"originate","page":39},{"id":"p40r02a","word":"mitigated","pair":"abated","meaning":"减轻","origin":"Mitigated 意思是“减轻”，是因为 mitigate 的拉丁语核心是“使柔和”。它来自 mitigare，通常分析为 mitis（温和的、柔软的）加 agere（使、做）。原指把严厉或粗暴的东西变温和，后来用于疼痛、损害、处罚或严重程度被降低，因此 mitigated 表示已经缓和、减轻。","originQuery":"mitigate","page":39},{"id":"p40r02b","word":"abated","pair":"mitigated","meaning":"减轻","origin":"Abated 意思是“减轻”，是因为 abate 原本有“打倒、压低”的动作感。它经古法语 abatre 进入英语，a- 源自拉丁语 ad-，batre 是“击打”。从把某物打下去，发展为使力量、强度或数量下降；于是风势、疼痛、骚乱等变弱都可说 abate，abated 即“已经减弱、缓和”。","originQuery":"abate","page":39},{"id":"p40r03a","word":"self-interest","pair":"opportunism","meaning":"自私自利","origin":"Self-interest 意思是“自私自利”，是因为它直接表示“个人自身的利益”。self 是“自己”，interest 在这里不是“兴趣”，而是利害、权益；它源于拉丁语 interesse，原义是“处在其中、关系到”。当行动主要由与自己切身相关的利益驱动时，就是 self-interest；语境较负面时便译为自私自利。","originQuery":"interest","page":39},{"id":"p40r03b","word":"opportunism","pair":"self-interest","meaning":"自私自利","origin":"Opportunism 意思是“自私自利”，是因为它指为了眼前利益随时利用机会、调整立场。opportune 源自拉丁语 opportunus，原与“顺风驶向港口”有关，后来表示时机有利；-ism 表示一种做法或倾向。由“把握有利时机”发展为“不顾原则地逐利”，因此常含投机、自利的贬义。","originQuery":"opportunism","page":39},{"id":"p40r04a","word":"resonates","pair":"rings true","meaning":"引起共鸣","origin":"Resonates 意思是“引起共鸣”，是因为 resonate 的字面核心是“再次发声、回响”。它来自拉丁语 resonare：re- 表示“再次、回返”，sonare 表示“发声”。声音在空间中得到回应就是回响；思想或感情若在他人心中得到相似回应，也像声音被重新振起，因此引申为引起情感或观念上的共鸣。","originQuery":"resonate","page":39},{"id":"p40r04b","word":"rings true","pair":"resonates","meaning":"引起共鸣","origin":"Rings true 意思是“引起共鸣”，是因为这个短语来自凭声音判断材质真假的经验。ring 在此是“发出清脆声响”，并非“圆环”；物体受敲击若声音纯正，就显得真实可靠。后来一句话或观点若“听起来是真的”，便说 it rings true；它进一步表示与人的经验相合、让人产生认同感。","originQuery":"ring","page":39},{"id":"p40r05a","word":"proscriptive","pair":"exacting","meaning":"严格的","origin":"Proscriptive 意思是“严格的”，是因为它来自 proscribe（正式禁止、排斥）。proscribe 源于拉丁语 proscribere，由 pro-（在前、公开）和 scribere（写）构成，原指公开张榜宣布某人被放逐或财产被没收。由“公开列入禁令”发展为严厉禁止，因此 proscriptive 指设下禁令、限制性很强的。","originQuery":"proscriptive","page":39},{"id":"p40r05b","word":"exacting","pair":"proscriptive","meaning":"严格的","origin":"Exacting 意思是“严格的”，是因为 exact 作动词原指“强行索取、要求做到”。它来自拉丁语 exigere，由 ex-（出）和 agere（驱动）构成，原始概念是“把要求逼出来、彻底完成”。一个 exacting 标准或任务会索取大量精力并要求精确达标，因此表示要求苛刻、严格的。","originQuery":"exacting","page":39},{"id":"p40r06a","word":"simple","pair":"ingenuous","meaning":"纯朴","origin":"Simple 意思是“纯朴”，是因为它的拉丁语祖先 simplex 表示“单一、不复合”。simplex 通常与 sem-（一）和表示折叠的词根相关，可理解为“只折一次、单层的”。从结构不复杂发展为未经修饰、没有机巧，再用于人的性格时便表示朴素、率真；在不同语境中也可表示简单甚至天真。","originQuery":"simple","page":39},{"id":"p40r06b","word":"ingenuous","pair":"simple","meaning":"纯朴","origin":"Ingenuous 意思是“纯朴”，是因为它最初描述“出身自由、具有自由人应有品格的人”。它来自拉丁语 ingenuus（天生的、自由出生的），与 gignere（生育）有关。自由人被理想化为坦率、高尚、不受奴性束缚，语义遂转向真诚、不做作，因此表示纯朴坦率。不要与 ingenious（有巧思的）混淆。","originQuery":"ingenuous","page":39},{"id":"p40r07a","word":"cure-all","pair":"panacea","meaning":"万能药","origin":"Cure-all 意思是“万能药”，是因为它由 cure（治愈、疗法）和 all（一切）直接复合而成，字面就是“能治好一切的东西”。cure 经法语来自拉丁语 cura（照料、治疗）。这个词既可指号称能治百病的药，也常比喻可解决所有难题的方案，并往往带有对“万能解决办法”的怀疑意味。","originQuery":"all","page":39},{"id":"p40r07b","word":"panacea","pair":"cure-all","meaning":"万能药","origin":"Panacea 意思是“万能药”，是因为它来自希腊语 panakeia，字面核心就是“治愈一切”。pan- 表示“全部”，akos 表示“治疗、疗法”。它先指能医治所有疾病的神奇药物，后来扩大到政治、社会等领域，表示被认为能一次解决所有问题的办法；相关词 pan- 也见于 panorama、pandemic。","originQuery":"panacea","page":39},{"id":"p40r08a","word":"obscure","pair":"opaque","meaning":"晦涩难懂","origin":"obscure 意思是“晦涩难懂”，是因为它本义是“昏暗、被遮住而看不清”。它来自拉丁语 obscurus“黑暗的、隐蔽的”。处在暗处的事物不会引人注意，也不容易被认识；因此 obscure 从视觉上的“模糊”扩展为知识上的“晦涩”和名声上的“默默无闻”。","originQuery":"obscure","page":39},{"id":"p40r08b","word":"opaque","pair":"obscure","meaning":"晦涩难懂","origin":"Opaque 意思是“晦涩难懂”，是因为它最初表示“不透光、阴暗”。它经法语来自拉丁语 opacus（在阴影中的、昏暗的）。物体不让光穿过，人便看不清其内部；这种视觉上的阻隔后来比喻语言、论证或制度不透明，令人无法看懂，因此形成“晦涩难懂”的抽象义。反义词 transparent 也有同样的具象到抽象演变。","originQuery":"opaque","page":39},{"id":"p40r09a","word":"tenacity","pair":"resolve","meaning":"坚韧毅力","origin":"Tenacity 意思是“坚韧毅力”，是因为它的词根表示“紧紧抓住”。它来自拉丁语 tenacitas，源于 tenax（牢牢抓住的），背后是 tenere（握住、保持）。由物体黏附不松脱，引申为人在困难面前坚持目标、不肯放弃，因此表示顽强、韧性和持久毅力。相关词 tenacious 是“坚韧的”。","originQuery":"tenacity","page":39},{"id":"p40r09b","word":"resolve","pair":"tenacity","meaning":"坚韧毅力","origin":"resolve 意思是“坚韧毅力”，是因为它原先表示把复杂问题“分解、解开”，从而得出确定答案。它来自拉丁语 resolvere：re-“回、彻底”，solvere“松开、解决”。疑惑被解开后，意志也随之定下；因此 resolve 作动词可指“解决、决定”，作名词则是坚定的“决心”。","originQuery":"resolve","page":39},{"id":"p40r10a","word":"recycle","pair":"rehash","meaning":"重复利用","origin":"Recycle 意思是“重复利用”，是因为它由 re-（再次）和 cycle（循环）构成，字面概念是“让某物重新进入循环”。cycle 来自希腊语 kyklos（圆、轮）。物品完成一次使用后，若经过回收处理再次进入生产或使用周期，就不是终点而是回到循环中，因此 recycle 表示回收再利用。","originQuery":"recycle","page":39},{"id":"p40r10b","word":"rehash","pair":"recycle","meaning":"重复利用","origin":"Rehash 意思是“重复利用”，是因为它原指“把已有材料重新切碎、重新烹制”。re- 表示“再次”，hash 来自法语 hacher（切碎）。剩菜切碎后再做成一道菜，后来比喻把旧观点、旧内容稍作改动后重新端出来。因此它可表示重复利用，但常含“翻炒旧料、缺乏新意”的贬义。","originQuery":"rehash","page":39},{"id":"p41r01a","word":"civility","pair":"comity","meaning":"友好，和睦","origin":"Civility 意思是“友好、和睦”，是因为它的词源核心是“公民应有的礼貌行为”。它来自拉丁语 civilitas，源于 civis（公民）。能在共同体中与他人相处，需要遵守公共礼仪、克制敌意；于是“公民身份和治理”相关含义逐渐转为礼貌、文明交往，civility 因而表示彬彬有礼与和睦。","originQuery":"civility","page":40},{"id":"p41r01b","word":"comity","pair":"civility","meaning":"友好，和睦","origin":"Comity 意思是“友好、和睦”，是因为它来自拉丁语 comitas（礼貌、亲切），而 comis 表示友善、和蔼。这个词强调各方出于礼让与善意相处，而不是受到强制。在外交和法律语境中，comity 还指国家或机构彼此尊重对方规则的礼让原则，因此核心始终是友好合作、和睦相待。","originQuery":"comity","page":40},{"id":"p41r02a","word":"exiguous","pair":"tenuous","meaning":"稀少的微弱的","origin":"Exiguous 意思是“稀少的、微弱的”，是因为它的拉丁语原义是“精确称出后剩得很少”。它来自 exiguus（少量的、微小的），与 exigere（量出、要求）有关，由 ex-（出）和 agere（驱动）构成。语义重点落在数量或程度不足，因此可形容资源稀少、差别微小或证据薄弱。","originQuery":"exiguous","page":40},{"id":"p41r02b","word":"tenuous","pair":"exiguous","meaning":"稀少的微弱的","origin":"Tenuous 意思是“稀少的、微弱的”，是因为它来自拉丁语 tenuis（细的、薄的、纤弱的）。从线条或物质“很薄”自然发展为数量少、力量弱；再用于联系、论据时，表示薄弱到经不起推敲。因此 tenuous 可形容稀薄的空气、微弱的关系或牵强的论证。相关词 attenuate 是“使减弱”。","originQuery":"tenuous","page":40},{"id":"p41r03a","word":"totemic","pair":"emblematic","meaning":"象征性的","origin":"Totemic 意思是“象征性的”，是因为 totem 原指一个群体奉为祖先、守护者或身份标志的动物、植物等。该词经北美原住民奥吉布瓦语进入英语，后来加 -ic 构成形容词。图腾不仅是具体物件，更代表整个群体及其共同身份，于是 totemic 引申为具有强烈代表、象征意义的。","originQuery":"totemic","page":40},{"id":"p41r03b","word":"emblematic","pair":"totemic","meaning":"象征性的","origin":"Emblematic 意思是“象征性的”，是因为 emblem 本来就是承载某种含义的标志或图案。emblem 经拉丁语来自希腊语 emblēma，原指“嵌入或镶嵌进去的装饰物”，来自 emballein（嵌入）。装饰图案常被赋予特定观念，遂成为象征；加 -atic 后即表示“作为某事象征的、具有代表性的”。","originQuery":"emblematic","page":40},{"id":"p41r04a","word":"precarious","pair":"perilous","meaning":"危险的","origin":"Precarious 意思是“危险的”，是因为它最初指“靠请求获得、随时可被收回的”。它来自拉丁语 precarius，与 prex“祈求”有关。只凭他人恩准而存在的权利没有保障，处境很不稳定；由“不稳”进一步发展为容易失败或受伤的“危险、岌岌可危”。","originQuery":"precarious","page":40},{"id":"p41r04b","word":"perilous","pair":"precarious","meaning":"危险的","origin":"Perilous 意思是“危险的”，是因为它由 peril“危险”与 -ous“充满……的”构成。peril 经古法语 peril 来自拉丁语 periculum“试验、风险”。需要接受考验的处境可能带来伤害或失败，因此 peril 发展为危险；perilous 就是“充满危险的”。","originQuery":"perilous","page":40},{"id":"p41r05a","word":"aspersions","pair":"slurs","meaning":"诽谤","origin":"Aspersions 意思是“诽谤”，是因为它的字面来源是“把东西洒在上面”。拉丁语 aspergere 由 ad-（向）和 spargere（撒、散布）构成，aspersion 原指洒水，尤其是宗教仪式中的圣水。后来“向名誉上泼洒污物”成为比喻，cast aspersions 便指散布贬损性的怀疑或指控，也就是诽谤、中伤。","originQuery":"aspersion","page":40},{"id":"p41r05b","word":"slurs","pair":"aspersions","meaning":"诽谤","origin":"Slurs 意思是“诽谤”，是因为 slur 逐渐形成了“弄脏、贬损名声”的概念。其早期来源不完全确定，曾表示稀泥、污迹以及潦草带过；由“留下污点”引申为对名誉造成玷污，再具体指侮辱性称呼或贬损言论。因此 slurs 是带有歧视或侮辱色彩的中伤话语。","originQuery":"slur","page":40},{"id":"p41r06a","word":"fosters","pair":"adopts","meaning":"促进","origin":"Fosters 意思是“促进”，是因为 foster 的词源核心是“喂养、抚育”。它来自古英语 fostrian（养育、供给食物），与 food 的古老词根有关。幼儿或幼苗受到滋养便能成长，所以语义从实际抚养扩展为为想法、关系或发展提供有利条件；fosters 因而表示培育并促使某事增长。","originQuery":"foster","page":40},{"id":"p41r06b","word":"adopts","pair":"fosters","meaning":"促进","origin":"Adopts 意思是“促进”，是因为 adopt 原义是“主动选择并接纳为己有”。它来自拉丁语 adoptare，由 ad-（向）和 optare（选择、希望）构成，最典型的意义是收养。后来扩展为采纳方法、政策或观点；当一个做法被采纳并付诸实施时，它便能推动相应目标，因此此处可理解为通过采用某事来促进发展。","originQuery":"adopt","page":40},{"id":"p41r07a","word":"adept","pair":"proficient","meaning":"熟练于","origin":"Adept 意思是“熟练于”，是因为它的拉丁语原义是“已经达到、已经获得”。它来自 adeptus，是 adipisci（达到、取得）的过去分词。早期炼金术中 adept 指自称掌握炼金奥秘的人，后来泛指已经达到高水平、掌握某种技能的人。因此 be adept at 就是“在某方面很娴熟”。","originQuery":"adept","page":40},{"id":"p41r07b","word":"proficient","pair":"adept","meaning":"熟练于","origin":"Proficient 意思是“熟练于”，是因为它原本描述“不断向前进步的人”。它来自拉丁语 proficere，由 pro-（向前）和 facere（做）构成，proficientem 指取得进展的人。学习者持续向前并达到较高水平，便能熟练运用知识或技能，因此 proficient 表示精通的、熟练的。","originQuery":"proficient","page":40},{"id":"p41r08a","word":"tortuous","pair":"convoluted","meaning":"曲折复杂","origin":"Tortuous 意思是“曲折复杂”，是因为它的词根就是“扭转”。它来自拉丁语 tortuosus（多弯的），源于 torquere（扭、转），与 torsion 同源。道路不断扭转就是蜿蜒曲折；推理、程序或表达若像弯路一样绕来绕去，也会显得复杂难循，因此引申为曲折复杂。不要与 torturous（令人痛苦的）混淆。","originQuery":"tortuous","page":40},{"id":"p41r08b","word":"convoluted","pair":"tortuous","meaning":"曲折复杂","origin":"convoluted 意思是“曲折复杂”，是因为它来自拉丁语 convolutus“卷在一起”。con-“共同、一起”，volvere“滚动、卷”；convoluted 是过去分词。多层东西卷叠在一起会难以理清，因此它从物理上的盘曲引申为思想、句子或过程过度复杂。","originQuery":"convoluted","page":40},{"id":"p41r09a","word":"violates","pair":"contravenes","meaning":"违反","origin":"Violates 意思是“违反”，是因为 violate 原本表示“以暴力侵犯、破坏”。它来自拉丁语 violare（伤害、亵渎、强暴），与 vis（力量）相关。由侵犯人的身体或神圣事物，扩展到破坏法律、原则、边界或权利；因此 violates 指越过应受尊重的限制，也就是违背、违反。","originQuery":"violate","page":40},{"id":"p41r09b","word":"contravenes","pair":"violates","meaning":"违反","origin":"Contravenes 意思是“违反”，是因为它的拉丁语构词表示“迎面反向而来”。contra- 是“反对、相反”，venire 是“来”，晚期拉丁语 contravenire 即“与……相抵触”。行为若朝着规则规定的反方向进行，就与规则冲突，因此 contravene 专门表示违反法律、规定或原则。相关词 intervene 也含 venire 的“来”。","originQuery":"contravene","page":40},{"id":"p41r10a","word":"pressing","pair":"exigent","meaning":"紧急的","origin":"Pressing 意思是“紧急的”，是因为 press 的核心动作是“施压、紧逼”。它经法语来自拉丁语 pressare（压迫），背后是 premere（按压）。事情若像外力一样不断压迫人，迫使人立刻处理，就不仅重要而且刻不容缓；因此 pressing 从“施加压力的”发展为“迫切的、紧急的”。","originQuery":"pressing","page":40},{"id":"p41r10b","word":"exigent","pair":"pressing","meaning":"紧急的","origin":"Exigent 意思是“紧急的”，是因为它来自拉丁语 exigere（催逼、要求），由 ex-（出）和 agere（驱动）构成，可理解为“逼着把结果交出来”。能够强烈提出要求的情况会迫使人马上行动，所以 exigent 从“苛求的、迫切要求的”发展为形势紧迫、必须立即应对的。相关词 exigency 指紧急情况。","originQuery":"exigent","page":40},{"id":"p42r01a","word":"reluctant","pair":"unwilling","meaning":"不情愿的","origin":"Reluctant 意思是“不情愿的”，是因为它的拉丁语核心是“向后挣扎、抵抗”。reluctari 由 re-（向后、反对）和 luctari（搏斗、挣扎）构成。一个人若在行动前仿佛向后用力，不肯顺势前进，就表现出内心抗拒；因此 reluctant 表示勉强、不愿意。","originQuery":"reluctant","page":41},{"id":"p42r01b","word":"unwilling","pair":"reluctant","meaning":"不情愿的","origin":"Unwilling 意思是“不情愿的”，是因为它由否定前缀 un- 和 willing（愿意的）直接构成。will 源自古英语 willa，核心是意愿、愿望；willing 表示出于自己的意志准备去做。加上 un- 后便是否定这种意愿，即内心不想做、不是自愿的，所以表示不情愿。","originQuery":"unwilling","page":41},{"id":"p42r02a","word":"detect","pair":"discern","meaning":"察觉辨别","origin":"Detect 意思是“察觉、辨别”，是因为它的词源字面是“揭开覆盖物”。它来自拉丁语 detegere：de- 表示“去除”，tegere 表示“遮盖”，detectus 即“被揭露的”。把遮挡拿掉后，隐藏的事物便能被看见；语义因此从揭露秘密发展为发现微小迹象、察觉并辨认出来。","originQuery":"detect","page":41},{"id":"p42r02b","word":"discern","pair":"detect","meaning":"察觉辨别","origin":"discern 意思是“察觉辨别”，是因为 discern 的拉丁语核心是“分开辨别”。它来自 discernere：dis-“分开”，cernere“筛分、看清”。从混杂背景中把某个模式区分出来，就相当于察觉或发现它；discerned 因而表示“被看出、被识别”。","originQuery":"discern","page":41},{"id":"p42r03a","word":"circuitous","pair":"indirect","meaning":"迂回的","origin":"Circuitous 意思是“迂回的”，是因为它来自 circuit（环行、绕一圈）。circuit 源于拉丁语 circuitus，由 circum-（周围）和 ire（走）构成，字面概念是“绕着周围走”。路线不直达而绕圈就是迂回；说话或推理若不直接切入，也可称 circuitous，表示绕弯子的。","originQuery":"circuitous","page":41},{"id":"p42r03b","word":"indirect","pair":"circuitous","meaning":"迂回的","origin":"Indirect 意思是“迂回的”，是因为它就是“不直接”。in- 表否定，direct 来自拉丁语 dirigere（引直、指向），由 dis- 与 regere（引导、使直）构成。没有沿直线或明确方向到达，就要经过弯路或中间环节；因此 indirect 可指路线迂回，也可指表达含蓄、不正面。","originQuery":"indirect","page":41},{"id":"p42r04a","word":"dispel","pair":"dismiss","meaning":"消除","origin":"Dispel 意思是“消除”，是因为它的拉丁语字面概念是“向四处分开驱赶”。它来自 dispellere，由 dis-（分开、四散）和 pellere（推动、驱赶）构成。把云雾或人群驱散后，原来的聚集状态便消失；后来也用于恐惧、疑虑、误解等被清除，因此表示驱散、消除。相关词 repel 也含 pellere。","originQuery":"dispel","page":41},{"id":"p42r04b","word":"dismiss","pair":"dispel","meaning":"消除","origin":"dismiss 意思是“消除”，是因为 dismiss 的拉丁语字面义是“把人送走”。它来自 dimittere：dis-“分开、离开”，mittere“送”。由让人离场发展为拒绝考虑某个观点；如果不经认真评价便把它“打发走”，就是认为它不值得重视，因此带有贬低意味。","originQuery":"dismiss","page":41},{"id":"p42r05a","word":"formidable","pair":"daunting","meaning":"令人生畏的","origin":"Formidable 意思是“令人生畏的”，是因为它直接来自拉丁语 formidare（害怕）和 formido（恐惧）。-able 表示“能够使人……的”，所以早期核心就是“足以引起恐惧”。后来强大、艰巨或能力出众的事物都会让人不敢轻视，因此 formidable 可表示可怕的、难对付的，也可带敬畏意味。","originQuery":"formidable","page":41},{"id":"p42r05b","word":"daunting","pair":"formidable","meaning":"令人生畏的","origin":"Daunting 意思是“令人生畏的”，是因为 daunt 原指“制服、使胆怯”。它经古法语 danter 来自拉丁语 domitare（驯服、压服），与 domare（驯服）有关。能把人的勇气压下去的任务或局面，会让人感到畏缩、不敢着手；因此 daunting 表示令人望而生畏的。","originQuery":"daunt","page":41},{"id":"p42r06a","word":"inconstant","pair":"capricious","meaning":"反复无常","origin":"Inconstant 意思是“反复无常”，是因为它表示“不能稳定站住”。in- 表否定，constant 来自拉丁语 constans，源于 constare：con-（共同、稳固）加 stare（站立）。constant 是立场稳定、持续不变；加否定前缀后，就成为情绪、忠诚或行为无法保持稳定，因此表示易变、反复无常。","originQuery":"inconstant","page":41},{"id":"p42r06b","word":"capricious","pair":"inconstant","meaning":"反复无常","origin":"capricious 意思是“反复无常”，是因为 caprice 指突然而任性的念头。它经法语来自意大利语 capriccio，早期可指惊跳或寒颤，更早来源有争议。想法像身体突然一颤般毫无预兆地改变，就显得任性难测，因此是 capricious。","originQuery":"capricious","page":41},{"id":"p42r07a","word":"triumph","pair":"success","meaning":"胜利","origin":"Triumph 意思是“胜利”，是因为它原指古罗马为获胜将领举行的凯旋仪式。英语经古法语和拉丁语 triumphus 接受此词，其更早来源可能与希腊语庆典呼喊有关。由“庆祝军事胜利的盛大游行”转而指胜利本身，再扩展到任何重大成功，因此 triumph 带有战胜困难后扬眉吐气的意味。","originQuery":"triumph","page":41},{"id":"p42r07b","word":"success","pair":"triumph","meaning":"胜利","origin":"Success 意思是“胜利”，是因为它最初表示“随后发生的结果”。它来自拉丁语 successus，源于 succedere：sub-（从下、随后）加 cedere（前进、到来），即“接着到来”。早期 success 可指好坏任何结果，后来逐渐专指如愿的好结果，因此表示成功；在竞赛或斗争语境中就是胜利。","originQuery":"success","page":41},{"id":"p42r08a","word":"altruistic","pair":"benevolent","meaning":"无私仁慈","origin":"Altruistic 意思是“无私仁慈”，是因为它的构词核心是“他人”。altruism 由法国思想家孔德据法语 autrui（他人）创制，而 autrui 最终来自拉丁语 alter（另一个）。与只顾自己相对，把他人的福祉作为行动目标就是利他；加 -istic 后，altruistic 表示无私地关心、帮助别人的。","originQuery":"altruistic","page":41},{"id":"p42r08b","word":"benevolent","pair":"altruistic","meaning":"无私仁慈","origin":"Benevolent 意思是“无私仁慈”，是因为它的拉丁语构词就是“希望别人好”。bene 表示“好、良善地”，volent- 来自 velle（希望、愿意）；benevolens 即“怀有善意的”。从对他人抱有良好愿望，发展为主动关怀、慷慨相助，因此表示仁慈、善意的；相关词 benevolence 是“仁慈、善意”。","originQuery":"benevolent","page":41},{"id":"p42r09a","word":"favorable","pair":"auspicious","meaning":"有利的","origin":"Favorable 意思是“有利的”，是因为它来自 favor（赞同、善意支持）加 -able。favor 经法语来自拉丁语 favere（赞助、偏爱）。某人若受到支持，处境就更容易成功；天气、条件若像在“帮忙”，结果也会更顺利。因此 favorable 从“表示赞同的”扩展为有帮助、有利于成功的。","originQuery":"favorable","page":41},{"id":"p42r09b","word":"auspicious","pair":"favorable","meaning":"有利的","origin":"Auspicious 意思是“有利的”，是因为它最初与观察鸟兆、判断吉凶有关。拉丁语 auspicium 由 avis（鸟）和 specere（观看）构成；古罗马占卜者通过鸟的飞行判断行动是否受神意赞许。预兆良好便意味着时机有利，后来 auspicious 泛指吉利、预示成功或条件有利的。","originQuery":"auspicious","page":41},{"id":"p42r10a","word":"cursory","pair":"casual","meaning":"草率","origin":"cursory 意思是“草率”，是因为它的核心图景是“跑着匆匆经过”。它来自晚期拉丁语 cursorius“奔跑的”，核心 currere 是“跑”。检查若像跑过一样迅速，只触及表面而未停下来细看，就会粗略不充分，因此 cursory 表示“匆忙而草率的”。","originQuery":"cursory","page":41},{"id":"p42r10b","word":"casual","pair":"cursory","meaning":"草率","origin":"Casual 意思是“草率”，是因为它的词源核心是“偶然发生、没有预先安排”。它经法语来自拉丁语 casualis，源于 casus（落下、偶然事件）。随偶然而来、不经特别准备的事情往往显得随便；语义于是扩展为非正式、漫不经心。在负面语境中，casual 就可表示态度草率、不够认真。","originQuery":"casual","page":41},{"id":"p43r01a","word":"antagonistic","pair":"inimical","meaning":"敌对的","origin":"Antagonistic 意思是“敌对的”，是因为 antagonist 原指“在竞赛中与人对抗者”。它来自希腊语 antagonistes，由 anti-（反对、对面）和 agon（竞赛、斗争）构成。站在对面竞争的人就是对手；加 -ic 后，antagonistic 表示采取对抗立场、彼此冲突不相容，因此是敌对的。","originQuery":"antagonistic","page":42},{"id":"p43r01b","word":"inimical","pair":"antagonistic","meaning":"敌对的","origin":"Inimical 意思是“敌对的”，是因为它直接来自拉丁语 inimicus（敌人、不友好的）。in- 表否定，amicus 是“朋友”，所以核心概念就是“不是朋友”。由人与人之间的敌意，扩展为条件或事物对某目标有害、不利；因此 inimical to 既可表示敌视，也可表示与……相抵触、有害于。","originQuery":"inimical","page":42},{"id":"p43r02a","word":"kinfolk","pair":"relative","meaning":"亲属","origin":"Kinfolk 意思是“亲属”，是因为它由 kin（同族、亲属）和 folk（人们）直接复合，字面就是“同一家族的人”。kin 源自古英语 cynn（种族、家族），与 kind 有古老联系；folk 源自古英语 folc（民众）。两部分合起来专指由血缘或婚姻联系起来的家人、亲族。","originQuery":"kinfolk","page":42},{"id":"p43r02b","word":"relative","pair":"kinfolk","meaning":"亲属","origin":"Relative 意思是“亲属”，是因为它原本表示“与某人有关系的人”。它经法语来自拉丁语 relativus，源于 referre（带回、联系、涉及）。凡事物都可相对于另一个事物而存在；用于人际关系时，具有血缘或婚姻联系的人就是 a relative，因此形成“亲属”的名词义。","originQuery":"relative","page":42},{"id":"p43r03a","word":"heterogeneity","pair":"disparateness","meaning":"差异性","origin":"Heterogeneity 意思是“差异性”，是因为它的希腊语构词表示“由不同种类组成”。hetero- 是“不同、另一个”，genos 是“种类、族类”，-ity 构成性质名词。一个整体若包含来源、性质或类别不同的成分，就不是均一的；因此 heterogeneity 表示异质性、多样差异。反义词 homogeneity 以 homo- 表示“相同”。","originQuery":"heterogeneity","page":42},{"id":"p43r03b","word":"disparateness","pair":"heterogeneity","meaning":"差异性","origin":"Disparateness 意思是“差异性”，是因为 disparate 的拉丁语核心是“不相等、分离”。它来自 dispar，由 dis-（分开、不）和 par（相等）构成；-ness 表示状态。两个事物若“不相等且分开”，就缺少共同性、彼此迥异，因此 disparateness 表示显著不同、不相称的状态，也就是差异性。","originQuery":"disparate","page":42},{"id":"p43r04a","word":"perplexing","pair":"enigmatic","meaning":"令人困惑的","origin":"perplexing 意思是“令人困惑的”，是因为拉丁语 perplexus 表示“彻底缠绕”。它由 per-“完全”与 plectere“编织、缠结”构成。线索像线团一样纠缠在一起，便难以理清；这个图景转用于头脑，就表示使人困惑、为难。","originQuery":"perplex","page":42},{"id":"p43r04b","word":"enigmatic","pair":"perplexing","meaning":"令人困惑的","origin":"Enigmatic 意思是“令人困惑的”，是因为它来自 enigma（谜语、难解之物）。enigma 经拉丁语来自希腊语 ainigma，源于 ainissesthai（用暗示或谜语说话）。话若只给隐晦线索而不直说，听者就难以理解；加 -atic 后，enigmatic 表示像谜一样神秘费解、令人困惑的。","originQuery":"enigmatic","page":42},{"id":"p43r05a","word":"quiescent","pair":"abeyant","meaning":"静止的，暂缓的","origin":"Quiescent 意思是“静止的、暂缓的”，是因为它来自拉丁语 quiescere（安静下来、休息），词根 quies 表示“休息、宁静”。-cent 带有处于某状态的意味。事物停止活动但未必永久终止，就是处在休眠或静止期；因此 quiescent 常指暂时不活跃、沉寂而可能再次启动。相关词 quiet 与之同源。","originQuery":"quiescent","page":42},{"id":"p43r05b","word":"abeyant","pair":"quiescent","meaning":"静止的，暂缓的","origin":"Abeyant 意思是“静止的、暂缓的”，是因为它来自 abeyance，即“等待中的悬置状态”。abeyance 经古法语 abeance 进入英语，源于表示张口期待、盼望的词。权利若暂时无人行使，仿佛在等待归属确定，便处于 abeyance；由此 abeyant 表示暂缓生效、暂时搁置而非彻底取消。","originQuery":"abeyant","page":42},{"id":"p43r06a","word":"laconic","pair":"taciturn","meaning":"言简意赅","origin":"Laconic 意思是“言简意赅”，是因为它原指古希腊拉科尼亚人的说话风格。Laconia 是斯巴达所在地区，斯巴达人以语言简短、克制著称；希腊语 Lakonikos 即“拉科尼亚的”。地区特征后来成为一般形容词，专指用极少的话表达明确意思，因此表示简洁而不啰嗦。","originQuery":"laconic","page":42},{"id":"p43r06b","word":"taciturn","pair":"laconic","meaning":"言简意赅","origin":"Taciturn 意思是“言简意赅”，是因为它的拉丁语核心是“沉默”。它来自 taciturnus（少言的），源于 tacere（保持沉默），与 tacit（心照不宣的）同源。一个人习惯沉默，就只说必要的话，因此语境中可体现言语简少；不过它更准确地强调“沉默寡言”，不一定表示表达特别精炼。","originQuery":"taciturn","page":42},{"id":"p43r07a","word":"inaccessible","pair":"opaque","meaning":"难以理解","origin":"Inaccessible 意思是“难以理解”，是因为它的本义是“无法接近”。in- 表否定，accessible 源于拉丁语 accedere（走近），其中 ad- 是“向”，cedere 是“走”。抽象思想若让读者找不到进入的路径，就像地点无法抵达一样；因此 inaccessible 从空间上的难接近，引申为内容艰深、难以理解。","originQuery":"inaccessible","page":42},{"id":"p43r07b","word":"opaque","pair":"inaccessible","meaning":"难以理解","origin":"Opaque 意思是“难以理解”，是因为它最初表示“不透光、看不穿”。它经法语来自拉丁语 opacus（阴暗、在阴影中的）。物体阻挡光线时，人无法看清里面；语言、论证或制度若阻挡理解，也仿佛不透明。因此 opaque 可从视觉上的不透光引申为含义晦涩、难以理解。","originQuery":"opaque","page":42},{"id":"p43r08a","word":"hailed","pair":"acclaimed","meaning":"受到赞扬","origin":"Hailed 意思是“受到赞扬”，是因为 hail 作动词原本是“高声招呼、向人致意”。这个用法来自中古英语的问候语，和表示健康、安好的古英语词有关，与“冰雹”的 hail 来源不同。人们以欢呼迎接某人，往往同时表达认可和敬意；因此 be hailed as 发展为“被誉为、受到公开赞扬”。","originQuery":"hail","page":42},{"id":"p43r08b","word":"acclaimed","pair":"hailed","meaning":"受到赞扬","origin":"acclaimed 意思是“受到赞扬”，是因为 acclaim 的核心是“向某人大声呼喊”。它来自拉丁语 acclamare：ad-“向”，clamare“喊叫”；ad- 在 c 前同化为 ac-。群众以呼声欢迎、赞许某人，便是公开称赞，所以 acclaimed 表示“广受赞誉的”；相关词 exclaim 也含 clamare。","originQuery":"acclaim","page":42},{"id":"p43r09a","word":"demanded","pair":"exacted","meaning":"要求","origin":"Demanded 意思是“要求”，是因为 demand 原指正式交托请求，后来加强为“坚持索取”。它经古法语 demander 来自拉丁语 demandare，由 de-（强调、完全）和 mandare（委托、命令）构成。提出的请求若带有权利或权威，不容拒绝，就成为强烈要求；demanded 即“明确要求了”。","originQuery":"demand","page":42},{"id":"p43r09b","word":"exacted","pair":"demanded","meaning":"要求","origin":"Exacted 意思是“要求”，是因为 exact 作动词的词源概念是“逼着交出来”。它来自拉丁语 exigere，由 ex-（出）和 agere（驱动）构成，原指强行索取、彻底执行。权力方迫使对方缴纳钱财或履行义务，就是 exact something from someone；因此 exacted 表示强求、索取，而不仅是形容词“精确的”。","originQuery":"exact","page":42},{"id":"p43r10a","word":"polymathic","pair":"encyclopedic","meaning":"博学的","origin":"Polymathic 意思是“博学的”，是因为它的希腊语构词表示“学过很多”。poly- 是“多”，mathēs、manthanein 与“学习”有关；polymath 指在多个领域都有知识的人。加 -ic 后，polymathic 就表示跨越许多学科、知识面广的，因此比一般 learned 更强调多领域的广博。","originQuery":"polymathic","page":42},{"id":"p43r10b","word":"encyclopedic","pair":"polymathic","meaning":"博学的","origin":"encyclopedic 意思是“博学的”，是因为它表示“像百科全书一样涵盖广泛”。encyclopedia 最终源自希腊语 enkyklios paideia，大意是“完整一圈的教育、全面教育”；-ic 构成形容词。知识若覆盖一个主题的各个方面，就像百科全书，因此是“广博、全面的”。","originQuery":"encyclopedic","page":42},{"id":"p44r01a","word":"controversial","pair":"provocative","meaning":"引起争议的","origin":"Controversial 意思是“引起争议的”，是因为 controversy 的拉丁语核心是“转向相反方向”。controversia 来自 contra-（反对）和 vertere（转动），字面概念是意见彼此对着转。各方立场相反便会发生争论；加 -ial 后，controversial 表示容易让人分成对立阵营、引发争论的。","originQuery":"controversial","page":43},{"id":"p44r01b","word":"provocative","pair":"controversial","meaning":"引起争议的","origin":"provocative 意思是“引起争议的”，是因为 provoke 的拉丁语字面义是“向前叫出来”。它来自 provocare：pro-“向前”，vocare“呼喊、召唤”。把人叫出来迎战，就是挑衅；能激起强烈反应或冲突的言行，因此被称为 provocative。","originQuery":"provocative","page":43},{"id":"p44r02a","word":"eclipse","pair":"outdo","meaning":"使黯然失色","origin":"Eclipse 意思是“使黯然失色”，是因为它本来指日食或月食造成的光被遮蔽。它经拉丁语来自希腊语 ekleipsis，源于 ekleipein（离开、未出现），由 ek-（离开）和 leipein（留下、缺失）构成。当天体的光仿佛消失，其他事物也可因更耀眼者出现而失去光彩，因此引申为使黯然失色。","originQuery":"eclipse","page":43},{"id":"p44r02b","word":"outdo","pair":"eclipse","meaning":"使黯然失色","origin":"Outdo 意思是“使黯然失色”，是因为它由 out-（超过、胜过）和 do（做）直接构成，字面概念是“做得比别人更好”。当一个人的表现超过另一个人，后者就显得不那么突出；因此 outdo 表示胜过、超越，在比较光彩或成就的语境中便可译为“使……黯然失色”。","originQuery":"outdo","page":43},{"id":"p44r03a","word":"perennial","pair":"long-standing","meaning":"长期的","origin":"Perennial 意思是“长期的”，是因为它的拉丁语字面概念是“贯穿全年”。perennis 由 per-（贯穿）和 annus（年）构成，最初用于多年生、四季存活的植物。由“一年又一年持续”扩展到问题、话题或现象长期反复存在，因此 perennial 表示持久的、长期不断的。相关词 annual 也含 annus。","originQuery":"perennial","page":43},{"id":"p44r03b","word":"long-standing","pair":"perennial","meaning":"长期的","origin":"Long-standing 意思是“长期的”，是因为它直接描绘某事“站立了很久”。long 表示时间长，standing 表示持续存在、保持地位。一个制度、关系或问题经过多年仍然“站着”没有消失，就具有长久历史；因此 long-standing 表示存在已久、长期形成的，而不是指人长时间站立。","originQuery":"standing","page":43},{"id":"p44r04a","word":"uncertainty","pair":"instability","meaning":"不确定性","origin":"Uncertainty 意思是“不确定性”，是因为它由 un-（不）和 certainty（确定状态）构成。certain 经法语来自拉丁语 certus（确定的、已决定的），-ty 构成抽象名词。当前提、结果或判断没有被确定下来，就存在多种可能，无法有把握；因此 uncertainty 表示不确定、疑惑或难以预测的状态。","originQuery":"uncertainty","page":43},{"id":"p44r04b","word":"instability","pair":"uncertainty","meaning":"不确定性","origin":"Instability 意思是“不确定性”，是因为它的词源字面是“不能稳稳站住的状态”。in- 表否定，stability 来自拉丁语 stabilis（稳定的），词根 stare 是“站立”。基础若站不稳，就容易变化或倒下；由物理不稳扩展到局势、情绪、制度难以维持，因此带来不可预测性，也就是不稳定与不确定。","originQuery":"instability","page":43},{"id":"p44r05a","word":"reprehensible","pair":"deplorable","meaning":"应受谴责的","origin":"Reprehensible 意思是“应受谴责的”，是因为它来自拉丁语 reprehendere（责备、抓住过错）。该词由 re-（向后、强调）和 prehendere（抓住）构成，可理解为“抓住问题并加以责斥”。-ible 表示“可以被……的”，所以 reprehensible 就是行为坏到可以、也应该受到责备。相关词 reprehend 是“斥责”。","originQuery":"reprehensible","page":43},{"id":"p44r05b","word":"deplorable","pair":"reprehensible","meaning":"应受谴责的","origin":"Deplorable 意思是“应受谴责的”，是因为 deplore 原本表示“为某事深深哀叹”。它来自拉丁语 deplorare，由 de-（加强）和 plorare（哭喊、哀号）构成。某种状况坏到令人悲叹，便是 deplorable；后来这个评价进一步带上道德否定，指糟糕、可耻到应受谴责的。","originQuery":"deplorable","page":43},{"id":"p44r06a","word":"supported","pair":"championed","meaning":"支持","origin":"Supported 意思是“支持”，是因为 support 的拉丁语字面概念是“从下方托起”。它经古法语来自 supportare，由 sub-（在下）和 portare（承载、携带）构成。托住物体能防止它倒下，后来便引申为给人、主张或事业提供力量、资源和赞同；supported 表示已经受到支撑或赞助。","originQuery":"support","page":43},{"id":"p44r06b","word":"championed","pair":"supported","meaning":"支持","origin":"Championed 意思是“支持”，是因为 champion 原指代表一方出战的斗士。它经古法语来自晚期拉丁语 campio（战士），与 campus（战场）有关。斗士替某人或某项事业站出来战斗，后来 champion 便转作动词，表示公开捍卫、积极推动；championed 即“曾大力支持、倡导”。","originQuery":"champion","page":43},{"id":"p44r07a","word":"counterparts","pair":"parallels","meaning":"对应物","origin":"counterparts 意思是“对应物”，是因为它原指契约中与另一份相配的副本。它经法语 contrepartie 形成，counter-“相对、对应”，part“部分、份”。两份文件分属双方却内容相应，由此扩大为两个体系中地位、作用相当的人或物，所以 counterpart 就是“对应的人或事物”。","originQuery":"counterpart","page":43},{"id":"p44r07b","word":"parallels","pair":"counterparts","meaning":"对应物","origin":"Parallels 意思是“对应物”，是因为 parallel 的希腊语字面概念是“彼此并排”。它来自 parallelos，由 para-（在旁边）和 allelos（彼此）构成，原指两条始终等距、不相交的线。两个事物若在不同环境中并排呈现相似位置、结构或作用，就互为 parallel，因此复数 parallels 可指对应事物。","originQuery":"parallel","page":43},{"id":"p44r08a","word":"obsolete","pair":"outmoded","meaning":"过时的","origin":"Obsolete 意思是“过时的”，是因为它的拉丁语原义是“用旧了、磨损了”。它来自 obsoletus，是 obsolescere（逐渐失去使用、衰落）的过去分词。物品长期使用会破旧并被淘汰，制度或技术也会因新事物出现而不再适用；因此 obsolete 表示已废弃、过时的。相关词 obsolescence 是“淘汰、过时”。","originQuery":"obsolete","page":43},{"id":"p44r08b","word":"outmoded","pair":"obsolete","meaning":"过时的","origin":"Outmoded 意思是“过时的”，是因为它由 out-（超出、不再处于）和 mode（流行方式、样式）构成，可理解为“已经出了当前模式”。mode 来自拉丁语 modus（尺度、方式）。一种做法或款式若不再符合当下通行的方式，就显得陈旧，因此 outmoded 表示不合时代、已过时的。","originQuery":"outmoded","page":43},{"id":"p44r09a","word":"improbable","pair":"unlikely","meaning":"不大可能","origin":"Improbable 意思是“不大可能”，是因为它表示“难以被证明或认可为真的”。im- 是否定前缀，probable 来自拉丁语 probabilis（可信的、可赞同的），其词根 probare 是“检验、证明”。某种结果若经不起证据检验，就不值得相信会发生；因此 improbable 从“不可信”发展为发生概率很低。","originQuery":"improbable","page":43},{"id":"p44r09b","word":"unlikely","pair":"improbable","meaning":"不大可能","origin":"Unlikely 意思是“不大可能”，是因为它由 un-（不）和 likely（可能的）构成。likely 源自古英语 gelic（相似、合适），与 like 同源；某事“看起来像会发生”便是 likely。加否定前缀后，就是不符合预期迹象、看起来不会发生，因此表示不太可能的。","originQuery":"unlikely","page":43},{"id":"p44r10a","word":"experimental","pair":"innovative","meaning":"创新的","origin":"Experimental 意思是“创新的”，是因为它表示“通过试验来探索”。experiment 来自拉丁语 experimentum（试验、经验证明），源于 experiri（尝试、检验）；-al 构成形容词。尚未成为常规的方法需要先试做和检验，所以 experimental 从“试验性的”可引申为探索新方法、具有创新性，但并不保证成熟有效。","originQuery":"experimental","page":43},{"id":"p44r10b","word":"innovative","pair":"experimental","meaning":"创新的","origin":"Innovative 意思是“创新的”，是因为 innovate 的拉丁语构词表示“使之更新”。它来自 innovare，由 in-（进入、使成）和 novus（新的）构成；-ive 表示具有这种作用或倾向。把新思想、新方法引入既有事物，使其变成新的形态，就是创新，因此 innovative 表示富有新意、能带来革新的。相关词 novelty 也含“新”的概念。","originQuery":"innovative","page":43},{"id":"p45r01a","word":"combine","pair":"meld","meaning":"融合","origin":"Combine 意思是“融合”，是因为它的词源字面概念是“把两个东西联结在一起”。它来自晚期拉丁语 combinare，由 com-（共同）和 bini（两个一组）构成。原本强调成对连接，后来泛指不同成分合到同一整体中；当各部分不仅并置而且相互结合时，便可译为融合。","originQuery":"combine","page":44},{"id":"p45r01b","word":"meld","pair":"combine","meaning":"融合","origin":"Meld 意思是“融合”，是因为现代动词 meld 表示把不同部分混合成一个整体。它在二十世纪由 melt（熔化）与 weld（焊接）影响形成的可能性较大，也可能受到牌戏术语 meld 的推动，具体来源并不完全确定。无论来源如何，语义都集中在界限逐渐消失、各部分融为一体。","originQuery":"meld","page":44},{"id":"p45r02a","word":"revival","pair":"renaissance","meaning":"复兴","origin":"Revival 意思是“复兴”，是因为它表示“重新获得生命”。re- 是“再次”，vive 来自拉丁语 vivere（生活），-al 构成事件名词。已经衰弱、沉寂或停止的事物若再次活跃，就像重新活过来；因此 revival 可指艺术、经济、传统或宗教活动的恢复兴盛。相关词 revive 是“复苏、使复兴”。","originQuery":"revival","page":44},{"id":"p45r02b","word":"renaissance","pair":"revival","meaning":"复兴","origin":"Renaissance 意思是“复兴”，是因为它的法语字面义就是“重生”。re- 表示“再次”，naissance 表示“出生”，源自拉丁语 nasci（出生）。这个词特指欧洲文艺复兴时，古典文化仿佛重新获得生命；后来也泛指某种艺术、思想或行业在衰落后重新繁荣，因此译为复兴。","originQuery":"renaissance","page":44},{"id":"p45r03a","word":"discrepancies","pair":"incongruities","meaning":"不一致","origin":"Discrepancies 意思是“不一致”，是因为 discrepancy 的拉丁语核心是“声音不协调”。它来自 discrepantia，源于 discrepare：dis-（分开、不一致）加 crepare（发出声响）。两个声音不合拍，后来比喻说法、数字或事实彼此对不上；因此 discrepancies 指各项之间的差异、矛盾或不一致之处。","originQuery":"discrepancy","page":44},{"id":"p45r03b","word":"incongruities","pair":"discrepancies","meaning":"不一致","origin":"Incongruities 意思是“不一致”，是因为 incongruity 表示“彼此不契合”。in- 表否定，congruity 来自拉丁语 congruere（相遇、协调、一致），其中 con- 有“共同”意味。各部分若无法协调地合在一起，就显得不相称或矛盾；因此 incongruities 指不协调、不合逻辑或不一致之处。","originQuery":"incongruity","page":44},{"id":"p45r04a","word":"ceded","pair":"left","meaning":"让与","origin":"Ceded 意思是“让与”，是因为 cede 来自拉丁语 cedere“退让、让路”。一个人从位置退开，就把空间让给别人；用于权利、领土或控制权时，便是正式交出。ceded 是其过去式，表示某物已经被“割让、转让”。","originQuery":"cede","page":44},{"id":"p45r04b","word":"left","pair":"ceded","meaning":"让与","origin":"Left 在这里意思是“让与、留下”，来自 leave 的过去式，而不是“左边”的 left。leave 源自古英语 læfan“留下、遗留”。一个人离开时把财产留给别人，或主动让出某物，接受者就获得了它；因此 leave something to someone 可表示“把某物留给、交由”。","originQuery":"left","page":44},{"id":"p45r05a","word":"simplicity","pair":"intelligibility","meaning":"简洁明了","origin":"Simplicity 意思是“简洁明了”，是因为它来自 simple，即“单一、不复杂”。simple 经法语来自拉丁语 simplex，通常与“一”和“折叠”相关，可理解为“单层、不多重”。没有多余层次或装饰，结构便容易看清；加 -ity 后，simplicity 表示简单、朴素的性质，在表达上就是简洁明了。","originQuery":"simplicity","page":44},{"id":"p45r05b","word":"intelligibility","pair":"simplicity","meaning":"简洁明了","origin":"Intelligibility 意思是“简洁明了”，是因为它直接表示“能够被理解的性质”。intelligible 来自拉丁语 intelligere（理解、辨识），通常分析为 inter-（在……之间）和 legere（选择、读），即从信息中辨出意义。加 -ibility 后，词义落在可理解性；表达若清楚易懂，就具有 intelligibility，但它不一定单独强调篇幅简短。","originQuery":"intelligibility","page":44},{"id":"p45r06a","word":"assured","pair":"settled","meaning":"自信的","origin":"Assured 意思是“自信的”，是因为 assure 原指“使确定、使安全”。它经法语来自拉丁语 securus（安全、无忧），并受 sure 影响。一个人若对结果感到确定，内心就不会犹疑；因此 assured 从“得到保证的”发展为举止镇定、确信自己能力的，即自信的。相关词 assurance 既可指保证，也可指自信。","originQuery":"assured","page":44},{"id":"p45r06b","word":"settled","pair":"assured","meaning":"自信的","origin":"Settled 意思是“自信的”，是因为 settle 的核心是“安置稳当、使不再动摇”。它与 seat（座位）有历史联系，早期表示使某人坐下或固定居所。事情尘埃落定，或人的心绪不再摇摆，就进入稳定确定的状态；因此 settled 在特定语境中可表示安定、笃定，不过它通常不直接等同于外显的自信。","originQuery":"settled","page":44},{"id":"p45r07a","word":"transitory","pair":"temporary","meaning":"短暂的","origin":"Transitory 意思是“短暂的”，是因为它的词源核心是“从这里经过”。它来自晚期拉丁语 transitorius，源于 transire：trans-（越过）加 ire（走）。只是在途中经过的事物不会久留，于是“过渡、经过”发展为持续时间短、很快消逝，因此 transitory 表示暂时的、短暂的。相关词 transit 是“通过、运输”。","originQuery":"transitory","page":44},{"id":"p45r07b","word":"temporary","pair":"transitory","meaning":"短暂的","origin":"Temporary 意思是“短暂的”，是因为它来自拉丁语 temporarius（限于一段时间的），其词根 tempus 表示“时间”。与永久存在相对，某物若只在特定时段内有效，时间一到就结束，便是 temporary。因此它表示临时的、短期的；相关词 contemporary 的核心也是“同一时间”。","originQuery":"temporary","page":44},{"id":"p45r08a","word":"render","pair":"reproduce","meaning":"再现","origin":"Render 意思是“再现”，是因为它原本表示“交还、呈交”，后来发展为“把某物以某种形式呈现出来”。它经古法语 rendre 来自通俗拉丁语 rendere，受拉丁语 reddere（归还）影响。艺术家把所观察的对象“呈交”为图像或文字，就形成表现、描绘的意义，因此 render 可表示再现。","originQuery":"render","page":44},{"id":"p45r08b","word":"reproduce","pair":"render","meaning":"再现","origin":"Reproduce 意思是“再现”，是因为它由 re-（再次）和 produce（产生、呈现）构成，字面概念是“重新产生”。produce 来自拉丁语 producere，由 pro-（向前）和 ducere（引导）组成。把原有的声音、图像、文本或状态再次制造出来，就使原物重现，因此 reproduce 表示复制、再现；在生物语境中也指繁殖。","originQuery":"reproduce","page":44},{"id":"p45r09a","word":"mediated","pair":"influenced","meaning":"受影响","origin":"Mediated 意思是“受到影响、经由中介而发生”，是因为原形 mediate 来自拉丁语 medius“中间的”。站在两方中间传递、调解或促成作用，就是 mediate；因此 mediated 可表示某种结果并非直接产生，而是经某因素传导、调节或影响而形成。","originQuery":"mediate","page":44},{"id":"p45r09b","word":"influenced","pair":"mediated","meaning":"受影响","origin":"influenced 意思是“受影响”，是因为 influence 原指星辰之力“流入”人间。它来自拉丁语 influere“流入”：in-“进入”，fluere“流”。某种思想或人物的作用像水流进入他人头脑，改变其方向并激发创作，因此 influenced 表示“受到作用或启发”。","originQuery":"influence","page":44},{"id":"p45r10a","word":"catalyst","pair":"factor","meaning":"促成因素","origin":"Catalyst 意思是“促成因素”，是因为它最初是化学术语，来自希腊语 katalysis“溶解、松开”，核心 lyein 表示“松开”。催化剂能加快反应而自身不被耗尽；这一作用后来被比喻为推动变化迅速发生的人或事，因此成为“促成因素”。","originQuery":"catalyst","page":44},{"id":"p45r10b","word":"factor","pair":"catalyst","meaning":"促成因素","origin":"Factor 意思是“促成因素”，是因为它来自拉丁语 factor“做事者、制造者”，核心 facere 是“做、造成”，与 factory 同源。凡是参与“造成”某个结果的条件，都可看作一个 factor；词义遂从行动者扩展为影响结果的要素或原因。","originQuery":"factor","page":44},{"id":"p46r01a","word":"immaterial","pair":"irrelevant","meaning":"不重要的","origin":"Immaterial 意思是“不重要的”，是因为它先表示“不由物质构成”。im-“不”，material 来自拉丁语 materia“材料、物质”。不具有实体的东西被视为无形；法律和论证中，与核心事实没有实质关系的内容也像“没有分量”，于是 immaterial 进一步表示“无关紧要的”。","originQuery":"immaterial","page":45},{"id":"p46r01b","word":"irrelevant","pair":"immaterial","meaning":"不重要的","origin":"Irrelevant 意思是“不重要的、不相关的”，是因为它由否定前缀 ir- 与 relevant“切合当前问题的”构成。relevant 经法语、拉丁语而来，逐渐有“与事情有关”的意思；若信息与正在讨论的问题搭不上关系，就无法影响判断，因此显得无关紧要。","originQuery":"irrelevant","page":45},{"id":"p46r02a","word":"canny","pair":"shrewd","meaning":"精明","origin":"Canny 意思是“精明”，是因为它来自苏格兰和英格兰北部用法，核心与 can“知道、会做”有关，早期有“懂得如何做、谨慎”的意思。知道分寸、善于处理实际事务的人显得机敏而可靠，因此 canny 发展为“精明谨慎的”，有时也含小心算计。","originQuery":"canny","page":45},{"id":"p46r02b","word":"shrewd","pair":"canny","meaning":"精明","origin":"Shrewd 意思是“精明”，是因为它经历了从“恶毒、难对付”到“判断敏锐”的褒义化。它与 shrew“泼妇、鼩鼱”同族，中古英语早期可指邪恶或尖刻。一个难对付的人往往机警、善算计，于是词义逐渐转为有敏锐实际判断力的“精明”。","originQuery":"shrewd","page":45},{"id":"p46r03a","word":"furtive","pair":"covert","meaning":"秘密的","origin":"Furtive 意思是“秘密的、偷偷摸摸的”，是因为它来自拉丁语 furtivus“偷来的、暗中进行的”，而 furtum 是“偷窃”。偷窃必须避人耳目，于是“与偷窃有关”逐渐概括成隐蔽而怕被发现的举止；相关词 furtively 即“偷偷地”。","originQuery":"furtive","page":45},{"id":"p46r03b","word":"covert","pair":"furtive","meaning":"秘密的","origin":"Covert 意思是“秘密的、隐蔽的”，是因为它经古法语 covert 来自 couvrir“覆盖”，与 cover 同源。东西被盖住便看不见；这个具体图景转用于行动或意图，就表示表面不显露、暗中进行，因此 covert operation 是“秘密行动”。","originQuery":"covert","page":45},{"id":"p46r04a","word":"undogmatic","pair":"receptive","meaning":"开放接受的","origin":"Undogmatic 意思是“不武断、开放接受的”，是因为它由 un-“不”与 dogmatic“教条式的”构成。dogma 来自希腊语，指被确立、接受的见解；dogmatic 因而指把观点当成不可质疑的定论。去掉这种僵硬态度，便愿意听取不同意见。","originQuery":"undogmatic","page":45},{"id":"p46r04b","word":"receptive","pair":"undogmatic","meaning":"开放接受的","origin":"Receptive 意思是“愿意接受的、开放接受的”，是因为它来自拉丁语 recipere“接回、接纳”，由 re-“回来”与 capere“拿、取”构成。能够把外来的事物接进来，就是 receptive；用于人时，便指愿意听取新观点或接受建议。","originQuery":"receptive","page":45},{"id":"p46r05a","word":"somnolence","pair":"lethargy","meaning":"嗜睡","origin":"Somnolence 意思是“嗜睡、困倦”，是因为它来自拉丁语 somnolentia“困倦”，核心 somnus 就是“睡眠”，与 insomnia“失眠”中的 somn- 同源。处在睡意不断袭来的状态，就是 somnolence；形容词 somnolent 表示“昏昏欲睡的”。","originQuery":"somnolence","page":45},{"id":"p46r05b","word":"lethargy","pair":"somnolence","meaning":"嗜睡","origin":"Lethargy 意思是“嗜睡、倦怠”，是因为它经拉丁语来自希腊语 lēthargia，早期指伴随健忘、昏睡的病态状态，并与 lēthē“遗忘”有关。意识像沉入遗忘、难以清醒，后来便泛指身体无力、精神迟钝和缺乏行动欲。","originQuery":"lethargy","page":45},{"id":"p46r06a","word":"defraud","pair":"swindle","meaning":"欺骗","origin":"Defraud 意思是“欺骗、诈取”，是因为它来自拉丁语 defraudare“以欺诈夺走”，核心 fraus、fraud- 表示“欺骗、损害”，与 fraud 同源。它强调的不只是说假话，而是借欺骗使别人失去钱财、权利或应得之物。","originQuery":"defraud","page":45},{"id":"p46r06b","word":"swindle","pair":"defraud","meaning":"欺骗","origin":"Swindle 意思是“欺骗、诈骗”，是因为它借自德语 Schwindler“骗子”，相关动词 schwindeln 既有“头晕”也有“行骗”之义。具体语义如何相连并不完全确定；英语保留了“以诡计骗取财物”的核心，因此比一般 deceive 更强调诈骗。","originQuery":"swindle","page":45},{"id":"p46r07a","word":"hybridity","pair":"eclecticism","meaning":"兼收并蓄","origin":"Hybridity 意思是“混合性、兼收并蓄”，是因为它由 hybrid“杂交的、混合的”与 -ity“状态”构成。hybrid 经拉丁语 hybrida 而来，原指不同种类所生的混种；后来扩展到文化、风格或思想，把多种来源融合在一起的状态就是 hybridity。","originQuery":"hybridity","page":45},{"id":"p46r07b","word":"eclecticism","pair":"hybridity","meaning":"兼收并蓄","origin":"Eclecticism 意思是“兼收并蓄”，是因为它来自希腊语 eklegein“挑选出来”：ek-“向外”加 legein“选择、收集”。eclectic 原指不拘泥于单一学派，而从不同体系中选取可用部分；这种择善而取、综合多家的做法就是 eclecticism。","originQuery":"eclecticism","page":45},{"id":"p46r08a","word":"promoter","pair":"champion","meaning":"支持者","origin":"Promoter 意思是“支持者、推动者”，是因为 promote 来自拉丁语 promovere“向前推动”，由 pro-“向前”与 movere“移动”构成，-er 表示执行者。把某项事业向前推、帮助它得到发展或关注的人，就是 promoter。","originQuery":"promoter","page":45},{"id":"p46r08b","word":"champion","pair":"promoter","meaning":"支持者","origin":"Champion 意思是“支持者、拥护者”，是因为它经古法语来自中世纪拉丁语 campio“决斗者、战士”，与 campus“战场”有关。champion 原是替自己或他人在场上作战的人；“为某人而战”转成比喻义，便指公开捍卫并积极支持某项主张的人。","originQuery":"champion","page":45},{"id":"p46r09a","word":"functional","pair":"serviceable","meaning":"实用的","origin":"Functional 意思是“实用的、能发挥作用的”，是因为它来自 function“功能、履行作用”与 -al。function 源于拉丁语 fungi“执行、履行”；某物若真正完成预定任务，而不只讲究外观，就具有 functional 的性质，因此表示“实用的”。","originQuery":"functional","page":45},{"id":"p46r09b","word":"serviceable","pair":"functional","meaning":"实用的","origin":"Serviceable 意思是“实用的、可用的”，是因为它由 service“服务、用途”与 -able“能够……的”构成。能够提供所需服务、完成实际用途的东西，就是 serviceable；它通常不强调精美或最佳，只强调状态尚好、足以派上用场。","originQuery":"serviceable","page":45},{"id":"p46r10a","word":"keen","pair":"impatient","meaning":"渴望的","origin":"keen 意思是“渴望的”，是因为它的早期核心是“锋利、勇猛、有力量”。它来自古英语 cēne“勇敢、强烈”，后来也形容刀刃锐利。欲望若像刀锋一样强而集中，就会表现为热切、迫切；因此 be keen to do 表示“急切想做”。","originQuery":"keen","page":45},{"id":"p46r10b","word":"impatient","pair":"keen","meaning":"渴望的","origin":"impatient 意思是“渴望的”，是因为它由 im-“不能”与 patient“耐心忍受的”构成。patient 来自拉丁语 pati“承受、忍耐”。一个人不能继续忍受等待，就急于立刻行动或得到结果；因此 impatient 既可表示“不耐烦”，也可在 impatient to do 中表示“迫切想做”。","originQuery":"impatient","page":45},{"id":"p47r01a","word":"applauded","pair":"extolled","meaning":"称赞","origin":"Applauded 意思是“受到称赞”，是因为 applaud 的拉丁语字面动作是“朝某人拍手”。它来自 applaudere：ad-“向”，plaudere“拍打、鼓掌”；ad- 在 p 前同化为 ap-。观众拍手表示赞许，于是 applaud 从具体的鼓掌扩展为公开赞扬，applauded 即“被称赞的”。","originQuery":"applaud","page":46},{"id":"p47r01b","word":"extolled","pair":"applauded","meaning":"称赞","origin":"Extolled 意思是“受到称赞”，是因为 extoll 的拉丁语字面义是“高高举起”。它来自 extollere，含 ex-“向上”与 tollere“举起”。在言辞中把某人的优点和地位抬高，就是高度赞颂；因此 extol 比普通 praise 语气更强，extolled 是“被盛赞的”。","originQuery":"extoll","page":46},{"id":"p47r02a","word":"histrionic","pair":"theatrical","meaning":"夸张的","origin":"Histrionic 意思是“夸张做作的”，是因为它来自拉丁语 histrio“演员”，最初只是“与演员或表演有关的”。当表演式的姿态被用于日常情绪表达时，便显得刻意、戏剧化，于是 histrionic 发展出“过分夸张、装腔作势”的贬义。","originQuery":"histrionic","page":46},{"id":"p47r02b","word":"theatrical","pair":"histrionic","meaning":"夸张的","origin":"Theatrical 意思是“夸张的、戏剧性的”，是因为 theater 最终来自希腊语 theatron“观看的场所”。舞台表达为了让远处观众看清，常放大动作、语气和情绪；这种“像舞台表演一样”的特点转用于现实行为，就表示夸张甚至做作。","originQuery":"theatrical","page":46},{"id":"p47r03a","word":"fitting","pair":"apposite","meaning":"恰当的","origin":"Fitting 意思是“恰当的、合适的”，是因为它来自 fit“适合、吻合”。fit 的更早来源并不完全确定，但核心图景是大小或形状能够严密配合；从衣物、零件的“合身、合槽”，自然扩展到言行与场合相配，因此表示“恰当”。","originQuery":"fitting","page":46},{"id":"p47r03b","word":"apposite","pair":"fitting","meaning":"恰当的","origin":"Apposite 意思是“恰当的、贴切的”，是因为它来自拉丁语 appositus“放在旁边、摆到跟前”，即 apponere 的过去分词；ad- 表示“向、靠近”，ponere 表示“放置”。某句话若放在当前论点旁边正好契合，就从“位置相合”发展为“切题、贴切”。","originQuery":"apposite","page":46},{"id":"p47r04a","word":"inept","pair":"unequal","meaning":"不能胜任","origin":"Inept 意思是“不能胜任的、不合适的”，是因为它来自拉丁语 ineptus“不合适、笨拙”，可理解为否定成分 in-“不”加 aptus“合适的”。人若能力或举止与任务要求不相配，就显得笨拙而无法胜任；反义词 apt 表示“合适的、善于的”。","originQuery":"inept","page":46},{"id":"p47r04b","word":"unequal","pair":"inept","meaning":"不能胜任","origin":"Unequal 意思是“不能胜任”，是因为它由 un-“不”与 equal“相等、相称”构成。这里不是单说数量不等，而来自 be unequal to the task 这一用法：人的能力与任务要求“不相称、达不到同等程度”，因此表示无力应付或不能胜任。","originQuery":"unequal","page":46},{"id":"p47r05a","word":"skepticism regarding","pair":"doubt about","meaning":"怀疑","origin":"Skepticism regarding 意思是“对……持怀疑态度”，是因为 skepticism 来自希腊语 skeptesthai“仔细察看、思考”。skeptic 原指不断审视、暂不下定论的人；对某说法继续查验而不立即相信，就形成“怀疑”。regarding 只是引出被怀疑的对象。","originQuery":"skepticism","page":46},{"id":"p47r05b","word":"doubt about","pair":"skepticism regarding","meaning":"怀疑","origin":"Doubt about 意思是“对……怀疑”，是因为 doubt 经古法语来自拉丁语 dubitare“犹豫、不确定”，与 duo“二”所表达的“两种可能之间”有关。心里在两个判断间摇摆，无法确信其一，便是 doubt；about 用来引出怀疑的对象。","originQuery":"doubt","page":46},{"id":"p47r06a","word":"atypical","pair":"exceptional","meaning":"非典型的","origin":"Atypical 意思是“非典型的”，是因为它由希腊来源的 a-“不、没有”与 typical“典型的”构成。type 来自希腊语 typos“印痕、模型”；typical 是符合某一模型或代表性样式，前面加否定成分后，就表示偏离通常模式。","originQuery":"atypical","page":46},{"id":"p47r06b","word":"exceptional","pair":"atypical","meaning":"非典型的","origin":"exceptional 意思是“非典型的”，是因为 exception 原指从一般规则中“取出来”的情况。它最终来自拉丁语 excipere：ex-“向外”，capere“拿取”；-al 构成形容词。被排除在常规模式之外的事物就是例外，因此 exceptional 可表示“异常的”，也可褒义表示“格外优秀”。","originQuery":"exceptional","page":46},{"id":"p47r07a","word":"eliminating","pair":"discontinuing","meaning":"终止","origin":"eliminating 意思是“终止”，是因为 eliminate 的拉丁语核心是“赶出门槛”。它来自 eliminare，核心 limen 是“门槛”，e-/ex- 表示“向外”。把某物逐出门外，就是从范围中移除；后来词义扩大为删去、淘汰或彻底消除。","originQuery":"eliminate","page":46},{"id":"p47r07b","word":"discontinuing","pair":"eliminating","meaning":"终止","origin":"Discontinuing 意思是“终止、中断”，是因为 discontinue 由 dis-“分开、取消”与 continue“连续保持”构成。continue 最终来自拉丁语 continere“连在一起、维持”；把原本连续相接的过程拆开，使它不再延续，就是 discontinue。","originQuery":"discontinue","page":46},{"id":"p47r08a","word":"liberating","pair":"emancipatory","meaning":"解放的","origin":"Liberating 意思是“解放的、使人获得自由的”，是因为原形 liberate 来自拉丁语 liberare“使自由”，核心 liber 是“自由的”。把人从束缚、控制或限制中释放出来，就是 liberate；-ing 形容能产生这种释放效果的事物。","originQuery":"liberate","page":46},{"id":"p47r08b","word":"emancipatory","pair":"liberating","meaning":"解放的","origin":"Emancipatory 意思是“解放的”，是因为它来自 emancipate“使脱离支配”。拉丁语 emancipare 原指依法解除父权或所有权，字面背景与 manus“手”和 capere“取得”构成的 mancipium“控制、所有”有关；脱离他人之“手”，遂泛化为获得自由。","originQuery":"emancipatory","page":46},{"id":"p47r09a","word":"illuminate","pair":"clarify","meaning":"阐明","origin":"Illuminate 意思是“阐明、照亮”，是因为它来自拉丁语 illuminare“使有光”，其中 in- 有“进入、使成为”的作用，lumen 是“光”。灯光照到物体上会让轮廓清楚可见；这一物理意义转用于思想，便指用解释使原本不明白的内容变清楚。","originQuery":"illuminate","page":46},{"id":"p47r09b","word":"clarify","pair":"illuminate","meaning":"阐明","origin":"Clarify 意思是“阐明、弄清”，是因为它经法语来自晚期拉丁语 clarificare“使清楚”，核心 clarus 是“清晰、明亮”，-fy 表示“使成为”。像把浑浊液体变清一样，clarify 用于信息或观点时，就是消除含混，让意思明白。","originQuery":"clarify","page":46},{"id":"p47r10a","word":"sequestered","pair":"unique","meaning":"独有的","origin":"Sequestered 意思是“隔离的、独处的”，是因为 sequester 经法语来自拉丁语 sequestrare，原指把有争议的财物交给中间保管人 sequester。物品因此被从各方手中移开、单独存放；词义后来扩展为把人或地点隔开，使其隐蔽而不受打扰。","originQuery":"sequester","page":46},{"id":"p47r10b","word":"unique","pair":"sequestered","meaning":"独有的","origin":"unique 意思是“独有的”，是因为它来自拉丁语 unicus“唯一的”，核心 unus 就是“一”。同类中只存在一个的事物没有可与之完全相比的旧例，因此 unique 首先表示“独特的”，语境中也可强调前所未见。","originQuery":"unique","page":46},{"id":"p48r01a","word":"exploited","pair":"utilized","meaning":"被利用","origin":"Exploited 意思是“被利用”，是因为 exploit 经古法语 esploit“成果、功绩、收益”而来，最终与拉丁语 explicare“展开、完成”有关。先有“取得成果、发挥用途”，后来发展为利用资源；若这种利用只为自己获利并损害他人，便是“剥削、占便宜”。","originQuery":"exploit","page":47},{"id":"p48r01b","word":"utilized","pair":"exploited","meaning":"被利用","origin":"Utilized 意思是“被利用、被使用”，是因为 utilize 经法语 utiliser 而来，核心拉丁语 utilis 是“有用的”，与 use 同源。把某物的“有用性”真正发挥出来，就是 utilize；变成过去分词 utilized，便表示它已被拿来服务某个目的。","originQuery":"utilize","page":47},{"id":"p48r02a","word":"indolence","pair":"sloth","meaning":"懒惰","origin":"Indolence 意思是“懒惰、懒散”，是因为它来自拉丁语 indolentia“无痛、无感觉”，其中 in- 是“不”，dolere 是“疼痛、悲伤”。从对痛苦无感，词义转向对事情漠不关心、懒得行动，最终成为缺乏勤奋和活力的状态。","originQuery":"indolence","page":47},{"id":"p48r02b","word":"sloth","pair":"indolence","meaning":"懒惰","origin":"Sloth 意思是“懒惰”，是因为它来自古英语 slæwth“迟缓、懒散”，本质上是 slow“慢”的旧派生形式。行动过分缓慢、不愿付出努力，便从“慢”发展为“懒”；在基督教传统中，sloth 还成为七宗罪之一。","originQuery":"sloth","page":47},{"id":"p48r03a","word":"proscribe","pair":"disallow","meaning":"禁止","origin":"Proscribe 意思是“禁止”，是因为它来自拉丁语 proscribere“公开写出”，由 pro-“在前、公开”与 scribere“写”构成。古罗马把被判罪、财产可没收者的名字公开列出，相当于宣布其不受保护；后来遂发展为正式禁止或取缔。","originQuery":"proscribe","page":47},{"id":"p48r03b","word":"disallow","pair":"proscribe","meaning":"禁止","origin":"Disallow 意思是“禁止、不准许”，是因为它由 dis-“否定、取消”与 allow“准许、认可”构成。该词早期还可指“不认可、责备”；当权威不认可某行为或请求时，就不给它生效或进行的许可，因此成为“禁止”。","originQuery":"disallow","page":47},{"id":"p48r04a","word":"speculative","pair":"unsubstantiated","meaning":"缺乏根据的","origin":"speculative 意思是“缺乏根据的”，是因为它来自“观察、思考”而不是已经证实的事实。其核心是拉丁语 speculari“察看、审视”，与 specere“看”有关；-ive 表示具有某种性质。由仔细观察进入理论思考，再指根据有限线索提出可能性，所以 speculative 表示“推测性的”。","originQuery":"speculative","page":47},{"id":"p48r04b","word":"unsubstantiated","pair":"speculative","meaning":"缺乏根据的","origin":"Unsubstantiated 意思是“缺乏根据的、未经证实的”，是因为它由 un-“未”与 substantiate“用证据支持”构成。substance 原指站在表象之下的“实体、根基”；说法若没有事实或证据在下面托住，就未被 substantiated，因而不可靠。","originQuery":"unsubstantiated","page":47},{"id":"p48r05a","word":"sensible","pair":"levelheaded","meaning":"明智的","origin":"Sensible 意思是“明智的”，是因为它来自拉丁语 sensibilis“可以感知的”，核心 sentire 是“感觉、察觉”。能准确感知现实的人通常判断稳妥，于是词义从“有感觉、可感知”发展为“有判断力、合乎实际”，即明智而不冲动。","originQuery":"sensible","page":47},{"id":"p48r05b","word":"levelheaded","pair":"sensible","meaning":"明智的","origin":"Levelheaded 意思是“明智冷静的”，是因为它由 level“水平、平稳”与 headed“具有某种头脑的”构成。头脑像保持水平一样不倾斜、不失衡，可以理解为情绪稳定、不被冲动带偏；因此能作出清醒而实际的判断。","originQuery":"levelheaded","page":47},{"id":"p48r06a","word":"predation","pair":"rapacity","meaning":"掠夺","origin":"Predation 意思是“掠夺、捕食”，是因为它来自拉丁语 praedatio“抢掠”，核心 praeda 是“战利品、猎获物”，与 predator“捕食者、掠夺者”同源。把别的生命或财物当作可夺取的猎物，就是 predation，既可指动物捕食，也可指强势者掠夺。","originQuery":"predation","page":47},{"id":"p48r06b","word":"rapacity","pair":"predation","meaning":"掠夺","origin":"Rapacity 意思是“贪婪掠夺”，是因为它来自拉丁语 rapacitas，核心 rapere 是“猛抓、夺走”，与 rapt、raptor 同源。它不只是想拥有更多，而是有强烈的攫取倾向，甚至不顾他人利益地夺取，因此表示贪得无厌或掠夺性。","originQuery":"rapacity","page":47},{"id":"p48r07a","word":"sole","pair":"exclusive","meaning":"唯一的","origin":"Sole 意思是“唯一的”，是因为这个形容词来自拉丁语 solus“单独、仅有的”，经古法语进入英语。它与表示“鞋底”的另一个 sole 来源不同，不能混作一个词源。某人或某物独自存在、没有第二个，就是 sole。","originQuery":"sole","page":47},{"id":"p48r07b","word":"exclusive","pair":"sole","meaning":"唯一的","origin":"Exclusive 意思是“唯一的、排他的”，是因为它来自拉丁语 excludere“关在外面”：ex-“向外”加 claudere“关闭”。把其他人或可能性都挡在门外，只留下某一个对象，就从“排除”发展出“专属、独有”的意思。","originQuery":"exclusive","page":47},{"id":"p48r08a","word":"ample","pair":"prodigious","meaning":"丰富的，充足的","origin":"Ample 意思是“丰富的、充足的”，是因为它来自拉丁语 amplus“宽广的、大的”，经法语进入英语。空间宽大意味着容纳得多；这个物理尺度转用于数量，便表示不只是勉强够用，而是有宽裕、有余量，因此是“充足的”。","originQuery":"ample","page":47},{"id":"p48r08b","word":"prodigious","pair":"ample","meaning":"丰富的，充足的","origin":"Prodigious 意思是“巨大的、数量惊人的”，是因为它来自拉丁语 prodigiosus“像奇兆一样惊异的”，核心 prodigium 指“异象、奇迹或预兆”。令人惊异到仿佛奇迹的事物往往超出常规尺度，于是词义发展为“异常巨大、数量极多”。","originQuery":"prodigious","page":47},{"id":"p48r09a","word":"interdependent","pair":"symbiotic","meaning":"相互依存","origin":"Interdependent 意思是“相互依存的”，是因为它由 inter-“在彼此之间”、dependent“依赖的”构成。depend 最终来自拉丁语 dependere“悬挂下来”；一个东西若悬系于另一个就离不开它。加上 inter- 后，关系变成双方互相“挂靠”、彼此依赖。","originQuery":"interdependent","page":47},{"id":"p48r09b","word":"symbiotic","pair":"interdependent","meaning":"相互依存","origin":"Symbiotic 意思是“共生的、相互依存的”，是因为它来自希腊语 symbiōsis“共同生活”：syn-/sym-“一起”加 bios“生命、生活”。两个不同生物共同生活并彼此受益，是生物学上的共生；后来也比喻人与组织间互相依赖的关系。","originQuery":"symbiotic","page":47},{"id":"p49r01a","word":"abjuration","pair":"repudiation","meaning":"放弃，拒绝","origin":"Abjuration 意思是“正式放弃、拒绝”，是因为它来自拉丁语 abiurare“宣誓否认”，由 ab-“离开”与 iurare“发誓”构成。它原本不是随口说不要，而是在誓言下郑重否认或舍弃某种信仰、权利；因此带有正式、坚决的放弃意味。","originQuery":"abjuration","page":48},{"id":"p49r01b","word":"repudiation","pair":"abjuration","meaning":"放弃，拒绝","origin":"Repudiation 意思是“拒绝、否认或抛弃”，是因为它来自拉丁语 repudiare“休弃、拒斥”，核心 repudium 指拒绝婚约或离弃关系。词义后来扩展到公开声明某主张、义务或关系不再被承认，因此比普通 refusal 更强烈、正式。","originQuery":"repudiation","page":48},{"id":"p49r02a","word":"abates","pair":"dissipates","meaning":"减弱","origin":"Abates 意思是“减弱、减退”，是因为原形 abate 经古法语 abatre“打倒、击落”而来，其中 battre 是“击打”。把某物打低、压下去，就会使它的力量或程度降低；因此风势、疼痛或愤怒由强变弱时，都可以说 abates。","originQuery":"abate","page":48},{"id":"p49r02b","word":"dissipates","pair":"abates","meaning":"减弱","origin":"dissipates 意思是“减弱”，是因为 dissipate 的拉丁语核心是“向四处分散”。它来自 dissipare：dis-“分开”，sipare 可能与“抛撒”有关。力量或云雾被散到各处后，局部浓度便降低直至消失，因此 dissipating 表示“正在消散、减弱”。","originQuery":"dissipate","page":48},{"id":"p49r03a","word":"contrivance","pair":"pretext","meaning":"借口","origin":"Contrivance 意思是“借口、计策”，是因为它来自 contrive“设法想出、设计”，后者经古法语 controver“发现、发明”进入英语，不能按现代拼写强拆。被刻意设计出来的办法或装置是 contrivance；若它专为掩饰真实动机，就成为人为编出的借口。","originQuery":"contrivance","page":48},{"id":"p49r03b","word":"pretext","pair":"contrivance","meaning":"借口","origin":"Pretext 意思是“借口、托词”，是因为它来自拉丁语 praetextum“摆在前面的掩饰”，核心 praetexere 由 prae-“在前”与 texere“编织”构成。像在真实动机前织一层遮盖，表面理由只负责掩饰，便成为 pretext。","originQuery":"pretext","page":48},{"id":"p49r04a","word":"quiescent","pair":"dormant","meaning":"静止的休眠的","origin":"Quiescent 意思是“静止的、休眠的”，是因为它来自拉丁语 quiescere“休息、安静下来”，核心 quies 是“安静、休息”，与 quiet 有亲缘关系。暂时没有活动但仍可能重新活跃的状态，就是 quiescent，常用于细胞、火山或局势。","originQuery":"quiescent","page":48},{"id":"p49r04b","word":"dormant","pair":"quiescent","meaning":"静止的休眠的","origin":"Dormant 意思是“静止的、休眠的”，是因为它经古法语来自拉丁语 dormire“睡觉”，与 dormitory“宿舍”同源。睡着时外表没有活动，但生命和能力并未消失；因此 dormant 可指暂不生长、运作或爆发而仍有潜能的状态。","originQuery":"dormant","page":48},{"id":"p49r05a","word":"idealization","pair":"romanticization","meaning":"理想化","origin":"Idealization 意思是“理想化”，是因为它由 ideal“理想的、完美典范”与表示过程的 -ization 构成。ideal 最终来自希腊语 idea“形态、观念”。把现实对象按心中的完美形态重新看待，突出优点并淡化缺陷，就是 idealization。","originQuery":"idealization","page":48},{"id":"p49r05b","word":"romanticization","pair":"idealization","meaning":"理想化","origin":"Romanticization 意思是“浪漫化、理想化”，是因为它由 romantic 与 -ization“使成为……的过程”构成。romantic 起初与 romance“传奇故事”有关，后来强调想象、情感和非现实色彩。把真实事物描绘得像传奇般动人而忽略困难，就是 romanticization。","originQuery":"romanticization","page":48},{"id":"p49r06a","word":"antics","pair":"capers","meaning":"滑稽举动","origin":"Antics 意思是“滑稽举动、胡闹”，是因为它最初来自意大利语 antico“古代的”，曾指古罗马遗迹中奇异、夸张的装饰图案。那些怪诞人物形象使 antic 逐渐有“小丑般、古怪的”意思；复数 antics 遂专指惹人发笑或不严肃的举动。","originQuery":"antics","page":48},{"id":"p49r06b","word":"capers","pair":"antics","meaning":"滑稽举动","origin":"Capers 意思是“欢跳、滑稽举动”，是因为单数 caper 经法语、意大利语而来，相关意大利语 capriola 指像山羊一样的跳跃，核心 capra 是“山羊”。山羊式蹦跳轻快又顽皮，于是 caper 从跳跃扩展为嬉闹、搞怪的行为。","originQuery":"caper","page":48},{"id":"p49r07a","word":"undermined","pair":"hampered","meaning":"削弱","origin":"Undermined 意思是“削弱、暗中破坏”，是因为 undermine 原本指在城墙或堡垒下面挖 mine“坑道”。下方支撑被掏空后，上面的建筑会坍塌；这个军事图景转成比喻，便指从根基处逐渐损害权威、信心或力量。","originQuery":"undermine","page":48},{"id":"p49r07b","word":"hampered","pair":"undermined","meaning":"削弱","origin":"Hampered 意思是“妨碍、削弱”，是因为动词 hamper 早期有“使残废、束缚、阻碍”之义，其更深来源并不完全确定，不宜简单解释为装东西的 hamper“篮子”。行动被束缚便难以充分发挥能力，因此 hampered 表示进展或效能受到限制。","originQuery":"hamper","page":48},{"id":"p49r08a","word":"dismissive","pair":"scornful","meaning":"轻蔑的","origin":"Dismissive 意思是“轻蔑的、不屑一顾的”，是因为 dismiss 来自拉丁语 dimittere“送开、放走”，由 dis-“分开”与 mittere“送”构成。把一个观点随手“打发走”、认为不值得认真考虑，就是 dismissive 的态度，因此含有轻视和拒斥意味。","originQuery":"dismissive","page":48},{"id":"p49r08b","word":"scornful","pair":"dismissive","meaning":"轻蔑的","origin":"Scornful 意思是“轻蔑的”，是因为它由 scorn“嘲弄、鄙视”与 -ful“充满……的”构成。scorn 经古法语进入英语，较早就有讥笑、蔑视之义。心里充满这种把别人看低的态度，言语和神情自然表现出不屑。","originQuery":"scornful","page":48},{"id":"p49r09a","word":"inchoate","pair":"incipient","meaning":"初始的，未成形的","origin":"Inchoate 意思是“初始的、未成形的”，是因为它来自拉丁语 inchoatus“已经开始的”，核心 inchoare 是“着手、开始”。它的更深构词并不确定，不能把现代拼写强拆。事情只是刚起头，结构和细节尚未发展完整，便是 inchoate。","originQuery":"inchoate","page":48},{"id":"p49r09b","word":"incipient","pair":"inchoate","meaning":"初始的，未成形的","origin":"Incipient 意思是“初始的、刚出现的”，是因为它来自拉丁语 incipientem“正在开始的”，核心 incipere 可理解为“着手”，由 in-“进入”与 capere“拿、取”构成。刚被拿起来着手的事尚处萌芽阶段，因此还未充分成形。","originQuery":"incipient","page":48},{"id":"p49r10a","word":"ceded","pair":"surrendered","meaning":"屈服于","origin":"ceded 意思是“屈服于”，是因为 cede 来自拉丁语 cedere“退让、让路”。一个人从位置退开，就把空间让给别人；用于权利、领土或控制权时，便是正式交出。ceded 是其过去式，表示某物已经被“割让、转让”。","originQuery":"cede","page":48},{"id":"p49r10b","word":"surrendered","pair":"ceded","meaning":"屈服于","origin":"Surrendered 意思是“屈服、交出”，是因为原形 surrender 经古法语 surrendre 而来，sur- 有“在上、交付”之意，rendre 是“归还、交出”。把控制权、武器或权利交到对方手中，就是停止抵抗；因此 surrendered 表示已经投降或让步。","originQuery":"surrender","page":48},{"id":"p50r01a","word":"banal","pair":"lackluster","meaning":"乏味","origin":"Banal 意思是“乏味、陈腐的”，是因为它来自法语 banal，早期指受领主 ban“公告、管辖权”约束而供大家共同使用的东西。由“公共的、人人都有”发展为“普通、毫无特色”，再带上因重复常见而令人厌倦的意味。","originQuery":"banal","page":49},{"id":"p50r01b","word":"lackluster","pair":"banal","meaning":"乏味","origin":"Lackluster 意思是“乏味的、无光彩的”，是因为它由 lack“缺少”与 luster“光泽、光彩”构成，字面就是“缺少光泽”。物体不发亮会显得暗淡；这一视觉感受转用于表演、作品或表现，便表示缺乏活力、吸引力和平庸无聊。","originQuery":"lackluster","page":49},{"id":"p50r02a","word":"tempered","pair":"mitigated","meaning":"缓和的","origin":"Tempered 意思是“缓和的”，是因为 temper 的早期核心是“按适当比例调和”。它来自拉丁语 temperare“混合、节制、使适中”。把过强的材料掺合调整，会降低其强度；同样，情绪、言辞或政策被 tempered，就是被约束、调到不过度的程度，因此译为“缓和的”。","originQuery":"tempered","page":49},{"id":"p50r02b","word":"mitigated","pair":"tempered","meaning":"缓和的","origin":"Mitigated 意思是“被缓和、减轻的”，是因为原形 mitigate 来自拉丁语 mitigare“使柔和、使温顺”，核心 mitis 是“温和的”。把严厉、疼痛或损害的强度变得温和，就是 mitigate；过去分词 mitigated 因而表示程度已经降低。","originQuery":"mitigate","page":49},{"id":"p50r03a","word":"repudiate","pair":"abjure","meaning":"拒绝否认","origin":"Repudiate 意思是“拒绝、否认”，是因为它来自拉丁语 repudiare“休弃、拒斥”，核心 repudium 曾指解除婚约或离弃关系。由正式断绝关系，词义扩展到公开拒绝接受某项主张、责任或债务，并明确表示不承认。","originQuery":"repudiate","page":49},{"id":"p50r03b","word":"abjure","pair":"repudiate","meaning":"拒绝否认","origin":"Abjure 意思是“郑重拒绝、发誓放弃”，是因为它来自拉丁语 abiurare，由 ab-“离开”与 iurare“发誓”构成。它原指在誓言下否认或舍弃某物，所以不是普通的不喜欢，而是正式、坚决地放弃信仰、主张或行为。","originQuery":"abjure","page":49},{"id":"p50r04a","word":"not antithetical","pair":"not opposed","meaning":"不矛盾的","origin":"Not antithetical 意思是“不矛盾的”，是因为 antithetical 来自希腊语 antithesis“对置”：anti-“相反”加 thesis“放置、命题”。两个观点被摆在相反位置，就彼此对立；前面的 not 否定这种关系，表示二者并非互相排斥，可以同时成立。","originQuery":"antithetical","page":49},{"id":"p50r04b","word":"not opposed","pair":"not antithetical","meaning":"不矛盾的","origin":"Not opposed 意思是“不矛盾、不反对的”，是因为 oppose 来自拉丁语 opponere“放在对面”，由 ob-“对着”与 ponere“放置”构成。被放到彼此对面便形成对抗；加上 not 后，就是没有站在对立面，因而可以相容或至少不反对。","originQuery":"oppose","page":49},{"id":"p50r05a","word":"displace","pair":"supplant","meaning":"取代","origin":"displace 意思是“取代”，是因为它由 dis-“离开、移开”与 place“位置”构成。把某人或某物从原来的位置移走，就会留下空位，常由另一对象占据；因此 displace 既可指“使离开原处”，也可指新技术或人“替代”旧者。","originQuery":"displace","page":49},{"id":"p50r05b","word":"supplant","pair":"displace","meaning":"取代","origin":"Supplant 意思是“取代”，是因为拉丁语 supplantare 原指“从下面绊倒”。它由 sub-“在下”与 planta“脚底”相关成分构成，sub- 在 p 前同化为 sup-。把对手绊倒后占据其位置，就是排挤替代；因此 supplant 带有新事物把旧事物赶走的意味。","originQuery":"supplant","page":49},{"id":"p50r06a","word":"hackneyed","pair":"pedestrian","meaning":"陈腐的","origin":"Hackneyed 意思是“陈腐的、用滥了的”，是因为 hackney 曾指供人租用的普通马匹，后来作动词表示反复役使。租赁马因被许多人骑用而疲惫磨损；这个图景转用于说法或题材，就表示被重复使用到失去新鲜感。","originQuery":"hackneyed","page":49},{"id":"p50r06b","word":"pedestrian","pair":"hackneyed","meaning":"陈腐的","origin":"Pedestrian 意思是“陈腐平庸的”，是因为它来自拉丁语 pedester“步行的”，核心 pes、ped- 是“脚”。步行相对于骑乘或飞驰显得普通缓慢；该词在修辞中又与高扬的诗体相对，指平实散文，后来遂贬为缺乏想象、乏味。","originQuery":"pedestrian","page":49},{"id":"p50r07a","word":"commensurate","pair":"appropriate","meaning":"相称的适合的","origin":"Commensurate 意思是“相称的、适合的”，是因为它来自拉丁语 commensurare“共同衡量”，由 com-“一起”与 mensura“尺度、测量”构成。两样东西若能用同一尺度衡量且比例匹配，就彼此相称；因此报酬可与贡献 commensurate。","originQuery":"commensurate","page":49},{"id":"p50r07b","word":"appropriate","pair":"commensurate","meaning":"相称的适合的","origin":"Appropriate 意思是“相称的、适合的”，是因为它来自拉丁语 appropriare“使成为自己的”，核心 proprius 是“自己的、特有的”。某物若恰好属于那个场合或用途，像是“归到正确位置”，便由“专属”发展出“恰当、适宜”。","originQuery":"appropriate","page":49},{"id":"p50r08a","word":"discretionary","pair":"optional","meaning":"可自行决定的","origin":"Discretionary 意思是“可自行决定的”，是因为它来自 discretion“判断权、裁量”，后者最终源于拉丁语 discernere“分开辨别”。能辨别不同情况，便能自行作判断；不由固定规则强制、留给个人或机构判断的事项，就是 discretionary。","originQuery":"discretionary","page":49},{"id":"p50r08b","word":"optional","pair":"discretionary","meaning":"可自行决定的","origin":"Optional 意思是“可自行选择的、非强制的”，是因为它来自 option“选择”，而 option 源于拉丁语 optare“选择、希望”。如果一件事由当事人选择做或不做，而不是必须完成，它就是 optional；相关词 opt 表示“作出选择”。","originQuery":"optional","page":49},{"id":"p50r09a","word":"endures","pair":"persists","meaning":"持续存在","origin":"Endures 意思是“持续存在、经受住”，是因为原形 endure 经法语来自拉丁语 indurare“使坚硬”，核心 durus 是“坚硬的”，与 durable 同源。能保持坚硬而不被压力摧毁，就能长久承受；因此既可指忍耐，也可指事物延续不消失。","originQuery":"endure","page":49},{"id":"p50r09b","word":"persists","pair":"endures","meaning":"持续存在","origin":"Persists 意思是“持续存在、坚持”，是因为原形 persist 来自拉丁语 persistere“坚定站住”，由 per-“始终、贯穿”与 sistere“站立”构成。面对时间或阻力仍站在原处、不退不散，就从具体姿态发展为继续存在或坚持行动。","originQuery":"persist","page":49},{"id":"p51r01a","word":"scathing","pair":"lacerating","meaning":"尖刻的","origin":"Scathing 意思是“尖刻的、严厉抨击的”，是因为它来自 scathe“伤害、损害”，后者经古诺斯语进入英语。scathing 原本就是“造成伤害的”；言辞若像武器一样刺伤名誉或感情，便成为猛烈而不留情面的批评。","originQuery":"scathing","page":50},{"id":"p51r01b","word":"lacerating","pair":"scathing","meaning":"尖刻的","origin":"Lacerating 意思是“尖刻的、令人痛苦的”，是因为原形 lacerate 来自拉丁语 lacerare“撕裂、割碎”。能把皮肉撕开的动作极其痛苦；转用于批评、羞辱或情绪时，就表示像撕裂伤口一样尖锐、摧折人心。","originQuery":"lacerate","page":50},{"id":"p51r02a","word":"prescient","pair":"foresighted","meaning":"有先见之明的","origin":"Prescient 意思是“有先见之明的”，是因为它来自拉丁语 praescientem“预先知道的”，由 prae-“在前、预先”与 scire“知道”构成。事情发生之前就能看出趋势或结果，仿佛提前拥有知识，因此是有预见性的。","originQuery":"prescient","page":50},{"id":"p51r02b","word":"foresighted","pair":"prescient","meaning":"有先见之明的","origin":"Foresighted 意思是“有先见之明的”，是因为它由 fore-“在前、预先”、sight“看见、眼光”和 -ed 构成。字面可理解为“具有向前看的眼光”；能在行动前看到长远后果并提前准备，就是 foresighted。","originQuery":"foresight","page":50},{"id":"p51r03a","word":"impugn","pair":"dispute","meaning":"质疑","origin":"Impugn 意思是“质疑、抨击”，是因为它来自拉丁语 impugnare“攻击、与……作战”，核心 pugnare 是“战斗”，与 pugnacious“好斗的”同源。对一个说法的真实性或某人的品格发动言语攻击，就是挑战其可信度，因而表示“质疑”。","originQuery":"impugn","page":50},{"id":"p51r03b","word":"dispute","pair":"impugn","meaning":"质疑","origin":"Dispute 意思是“质疑、争论”，是因为它来自拉丁语 disputare“讨论、权衡”，由 dis-“分开”与 putare“思考、估量”构成。把问题拆开来反复推论，若双方得出不同判断，就形成争辩；作动词时也表示挑战某说法的真实性。","originQuery":"dispute","page":50},{"id":"p51r04a","word":"eschew","pair":"avoid","meaning":"避开","origin":"eschew 意思是“避开”，是因为 eschew 经古法语 eschiver 进入英语，早期就表示“躲避、远离”。其更早来源与日耳曼语中“害怕、避开”的词有关。因认为某物有害或不合原则而主动不用它，就是 eschew；eschewing 表示持续回避。","originQuery":"eschew","page":50},{"id":"p51r04b","word":"avoid","pair":"eschew","meaning":"避开","origin":"Avoid 意思是“避开”，是因为它经古法语 esvuidier 而来，原有“使空、清除、离开”的意思，核心 vuide 与 modern French vide“空的”相关。把自己从某个地方或情形中移开、让两者之间空出来，就发展为不接触、躲开。","originQuery":"avoid","page":50},{"id":"p51r05a","word":"precluded","pair":"invalidated","meaning":"排除使无效","origin":"Precluded 意思是“排除、使不可能”，是因为原形 preclude 来自拉丁语 praecludere“预先关闭”，由 prae-“在前、事先”与 claudere“关”构成。若一扇门在行动开始前就被关上，某种可能性便无法实现，因此表示事先阻止或排除。","originQuery":"preclude","page":50},{"id":"p51r05b","word":"invalidated","pair":"precluded","meaning":"排除使无效","origin":"Invalidated 意思是“使无效、推翻”，是因为 invalidate 由 in-“不”与 valid“有效、有力量的”构成；valid 来自拉丁语 valere“强健、有力”。证据或规则一旦被证明不再具有效力，就被 invalidated，即其法律、逻辑或实际作用被取消。","originQuery":"invalidate","page":50},{"id":"p51r06a","word":"venerating","pair":"exalting","meaning":"尊敬崇拜","origin":"Venerating 意思是“尊敬、崇敬”，是因为原形 venerate 来自拉丁语 venerari“敬畏、崇拜”，与 venerable“值得尊敬的”同源。它表达的不是一般喜欢，而是把对象视为地位崇高、值得敬畏，因而给予深切敬意。","originQuery":"venerate","page":50},{"id":"p51r06b","word":"exalting","pair":"venerating","meaning":"尊敬崇拜","origin":"Exalting 意思是“尊崇、颂扬”，是因为原形 exalt 来自拉丁语 exaltare“举高、抬升”，由 ex-“向上、向外”与 altus“高”相关。把人从普通位置“举到高处”，转用于名声和评价，就是高度赞扬、尊崇；也可指使情绪振奋。","originQuery":"exalt","page":50},{"id":"p51r07a","word":"nautical","pair":"maritime","meaning":"航海的","origin":"Nautical 意思是“航海的、船舶的”，是因为它经拉丁语 nauticus 来自希腊语 nautikos，核心 naus 是“船”，与 navigator 在概念上相关。凡涉及船只、水手、海上航行或航海技术的事物，便可称为 nautical。","originQuery":"nautical","page":50},{"id":"p51r07b","word":"maritime","pair":"nautical","meaning":"航海的","origin":"Maritime 意思是“海上的、航海的”，是因为它来自拉丁语 maritimus“属于海的、靠海的”，核心 mare 是“海”。事物若发生在海上、与船运有关，或地理位置临海，就属于 maritime，因此可指航海业、海事活动和沿海地区。","originQuery":"maritime","page":50},{"id":"p51r08a","word":"muddled","pair":"turbid","meaning":"混乱的","origin":"Muddled 意思是“混乱的”，是因为原形 muddle 早期可指把清水弄成 muddy“浑浊的”，其确切更早来源并不确定。水中泥沙搅起后无法看清；这个图景转用于思维、叙述或安排，就表示条理被搅乱、让人分辨不清。","originQuery":"muddle","page":50},{"id":"p51r08b","word":"turbid","pair":"muddled","meaning":"混乱的","origin":"Turbid 意思是“浑浊的、混乱的”，是因为它来自拉丁语 turbidus“混乱、受扰动的”，与 turba“人群、骚动”有关。水被搅动后泥沙翻起而不透明；这一物理状态同样可比喻思路或文字混乱难懂。","originQuery":"turbid","page":50},{"id":"p51r09a","word":"mythical","pair":"enigmatic","meaning":"神秘难解","origin":"Mythical 意思是“神话中的、虚构的”，是因为它由 myth“神话”与 -ical 构成；myth 最终来自希腊语 mythos“故事、传说”。只存在于传说而非现实中的人物或事物，就是 mythical。它本身不等于“神秘难解”，那通常应说 enigmatic。","originQuery":"mythical","page":50},{"id":"p51r09b","word":"enigmatic","pair":"mythical","meaning":"神秘难解","origin":"Enigmatic 意思是“神秘难解的”，是因为它来自希腊语 ainigma“谜语、隐晦的话”，经拉丁语进入英语。像谜语一样只给出模糊线索、不直接显露答案的人或事，就让人难以看透，因此 enigmatic 表示费解而神秘。","originQuery":"enigmatic","page":50},{"id":"p51r10a","word":"enigmatic","pair":"inscrutable","meaning":"难以理解","origin":"Enigmatic 意思是“难以理解的”，是因为它来自希腊语 ainigma“谜语、隐晦表达”，相关动词有“用暗语说话”之意。谜语把真正意思藏在间接线索中；同样，含义、动机或性格若不直接显露，就会显得 enigmatic。","originQuery":"enigmatic","page":50},{"id":"p51r10b","word":"inscrutable","pair":"enigmatic","meaning":"难以理解","origin":"Inscrutable 意思是“难以理解、无法看透的”，是因为它来自晚期拉丁语 inscrutabilis，由 in-“不能”与 scrutari“细查、探究”构成。即使仔细搜索也找不到内在答案，就不是一般的陌生，而是深到无法探明；scrutinize 与它共享“细查”的词根。","originQuery":"inscrutable","page":50}];
